  let paint = null;
  // ノートのハニカム（タブの題名を六角セルに並べる区画）：開いているか・中心にしている親のノート・各ノートのメモの数
  const hive = { open: false, parent: null, stats: new Map(), loading: false };
  // 全体表示でマウスを重ねたマスを浮かせて見せる要素（初めて使うときに作る）とその状態
  let peek = null;
  let peekKey = null;
  let peekTimer = 0;
  // 小さく表示しているときに、マスのコメント（または本文）の1行目を出す吹き出し（縮小時の1行表示）。設定はこの端末に覚える
  const TIPS_PREF = 'hexMemo.lineTips';
  const TIPS_DEFAULT = { show: 'off', last: 'comment-new', when: 'overview', overlap: 'avoid', len: 0 }; // len 0：マスの大きさに合わせる
  let tipsPref = { ...TIPS_DEFAULT };
  let tipLayer = null; // 吹き出しを入れる層（初めて使うときに作る）
  const tipEls = new Map(); // マスのキー → 吹き出しの要素
  let tipsDirty = false; // 並べ直しが要る（マスの出入り・中身の変化）
  let tipsQueued = false;
  let tipsLaidZ = null; // 並べたときの倍率（null：まだ並べていない）
  let tipsSeenZ = null;
  let tipsTimer = 0; // 拡大・縮小が止まるのを待つ
  let tipsStat = { shown: 0, hidden: 0 };
  let tipsLastAt = 0; // 最後に並べた時刻と、かかった時間（ms）
  let tipsCost = 0;
  // 画像とセルの組み合わせ：ハニカムの下に敷く画像の要素（初めて使うときに作る）、一時的に隠している層、位置合わせ中の状態
  let comboImg = null;
  let comboHiddenFor = null;
  let comboAdjust = null; // { layer, before: { x, y, w } }
  let comboGesture = null; // 位置合わせのドラッグ { kind: 'move' | 'resize', corner, id, sx, sy, start, aspect }
  let peekHideTimer = 0;
  let peekPinned = null; // 固定した浮かび上がりのマスのキー（縮小中のクリックが「浮かせて固定」のとき）
  let peekPinCam = null; // 固定したときのカメラ（動かした・拡大縮小したら外す）
  let flashKey = null;
  let flashTimer = 0;
  let spaceHeld = false;
  let pan = null;
  let suppressClick = false;
  let cameraAnim = 0;
  let renderQueued = false;
  let lastSignature = '';
  let lastCenterLabel = '';
  let ready = false; // データ読み込みが終わるまでは描画しない

  // ノート（上段のタブ）。ノートごとに別のハニカム・別の保存ファイルを持つ
  let boards = []; // [{ id, name }]（タブの並び順）
  let currentBoardId = null;
  let boardReadOnly = false; // 表示中のノートを読み込めず、保存を止めている
  let boardsReadOnly = false; // ノート一覧を書き換えられない（追加・名前変更・削除を止める）
  let switchSeq = 0;

  // このメモアプリ（別のメモアプリとして作ったものは、その名前）
  let appName = '六角メモ';
  let appId = null;

  // アプリ全体の設定（本体の settings.json）：タグの登録・関連線の種類・クイック入力。本体から受け取り、変えたら本体へ送る
  let settings = { version: 1, tags: [], linkKinds: [], quickInput: { shortcut: 'CommandOrControl+Alt+Q', place: 'origin', global: true }, templates: [], capture: { shortcut: 'CommandOrControl+Alt+H', sizes: [], last: 280, comment: true }, tray: { enabled: true } };

  // ---- 小物 ----------------------------------------------------------------

  const nowIso = () => new Date().toISOString();

  function uuid() {
    if (typeof crypto.randomUUID === 'function') return crypto.randomUUID();
    const b = crypto.getRandomValues(new Uint8Array(16));
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    const h = [...b].map((x) => x.toString(16).padStart(2, '0')).join('');
    return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
  }

  // 絵文字などを1文字として数える
  const segmenter = typeof Intl.Segmenter === 'function' ? new Intl.Segmenter('ja', { granularity: 'grapheme' }) : null;
  function countChars(text) {
    if (!text) return 0;
    if (!segmenter) return [...text].length;
    let n = 0;
    for (const _ of segmenter.segment(text)) n++;
    return n;
  }

  function formatRelative(iso, now = Date.now()) {
    const t = Date.parse(iso);
    if (Number.isNaN(t)) return '';
    const sec = Math.max(0, now - t) / 1000;
    if (sec < 45) return 'たった今';
    if (sec < 3600) return `${Math.max(1, Math.floor(sec / 60))}分前`;
    if (sec < 86400) return `${Math.floor(sec / 3600)}時間前`;
    if (sec < 86400 * 7) return `${Math.floor(sec / 86400)}日前`;
    const d = new Date(t);
    const md = `${d.getMonth() + 1}月${d.getDate()}日`;
    return d.getFullYear() === new Date(now).getFullYear() ? md : `${d.getFullYear()}年${md}`;
  }

  function formatFull(iso) {
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return '';
    const p = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}/${p(d.getMonth() + 1)}/${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
  }

  const formatCoord = (key) => key.replace(',', ', ');

  function svgIcon(name) {
    const tpl = document.createElement('template');
    tpl.innerHTML = `<svg class="icon icon-${name}" viewBox="0 0 24 24" aria-hidden="true" focusable="false">${ICONS[name]}</svg>`;
    return tpl.content.firstChild;
  }

  function el(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  let toastTimer = 0;
  let toastSeq = 0;
  // 押せる札（削除の「元に戻す」・区画の「戻す」）が出ている時間。短くしたければ両方まとめてここで変える
  const UNDO_TOAST_MS = 8000;
  // action：{ label, run }（任意）。渡すと札にボタンを1つ付ける。押せるのはいちばん新しい札のボタンだけで、
  // 「今押してよいか」「同じ状態か」は run の中で決める（この札の部品は何も判断しない）
  function toast(message, kind = 'info', ms = 2800, opts = null) {
    const action = (opts && opts.action) || null;
    const seq = ++toastSeq;
    let deadline = 0;
    const hide = (after) => {
      clearTimeout(toastTimer);
      deadline = performance.now() + after;
      toastTimer = setTimeout(() => toastEl.classList.remove('is-on'), after);
    };
    if (action) {
      const btn = el('button', 'toast-btn', action.label);
      btn.type = 'button';
      btn.tabIndex = -1;
      btn.addEventListener('pointerdown', (e) => e.preventDefault()); // 書く欄からフォーカスを奪わない（書いている途中でも押せる）
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        // ダブルクリックの2回目は無視（押した直後に同じ場所へ出る次の札のボタンまで押してしまわないように）
        if (e.detail > 1) return;
        if (seq === toastSeq && toastEl.classList.contains('is-on')) action.run();
      });
      // マウスを重ねている間は消さない（指の長押しでは離れたことが伝わらないことがあるので、マウスのときだけ）。
      // 離したら残りの時間から数え直す（少なくとも2秒は残す）
      btn.addEventListener('pointerenter', (e) => {
        if (e.pointerType === 'mouse' && seq === toastSeq) clearTimeout(toastTimer);
      });
      btn.addEventListener('pointerleave', (e) => {
        if (e.pointerType === 'mouse' && seq === toastSeq) hide(Math.max(2000, deadline - performance.now()));
      });
      toastEl.replaceChildren(el('span', 'toast-text', message), btn);
    } else {
      toastEl.textContent = message;
    }
    toastEl.classList.toggle('has-action', !!action);
    toastEl.dataset.kind = kind;
    liftToastAboveBars();
    toastEl.classList.add('is-on');
    hide(ms);
  }
  // 下の操作バー（複数選択・読書モード）は窓の幅によって折り返して高くなるので、札がバーに重ならないよう、
  // 見えているバーの上端より上に出す（バーが無い・低いときは styles.css の位置のまま）
  function liftToastAboveBars() {
    toastEl.style.bottom = '';
    let bottom = 0;
    for (const bar of document.querySelectorAll('#multiBar:not([hidden]), #readBar:not([hidden])')) {
      const r = bar.getBoundingClientRect();
      if (r.height) bottom = Math.max(bottom, Math.ceil(window.innerHeight - r.top + 10));
    }
    if (bottom > parseFloat(getComputedStyle(toastEl).bottom)) toastEl.style.bottom = `${bottom}px`;
  }

  const isTypingTarget = (t) => t instanceof HTMLElement && (t.isContentEditable || t.matches('textarea, input, select'));
  const anyDialogOpen = () => commentDialog.open || confirmDialog.open || $('newAppDialog').open || $('sendTargetDialog').open
    || $('tagDialog').open || $('regionDialog').open || $('linkKindDialog').open || $('quickDialog').open || $('quickAskDialog').open || $('aiTagDialog').open
    || $('tplDialog').open || $('captureDialog').open || $('tagSetDialog').open || $('slideView').open || $('voiceDialog').open || $('exportDialog').open;

  // ---- レコード ------------------------------------------------------------

  function createRecord() {
    const t = nowIso();
    return { text: '', createdAt: t, updatedAt: t, likedLevel: 0, liked: false, bookmarked: false, comments: [] };
  }

  const currentLayer = () => (path.length ? path[path.length - 1].layer : rootLayer);

  // ---- 層：1つのメモの周りに、ハニカムを何枚も重ねられる（第1層・第2層…） ----
  // 第1層は rec.children、重ねた第2層以降は rec.moreLayers（保存形式も同じ）。
  // 道筋 keys の1段は「マスのキー」。第2層以降に入る段は「キー@層の番号」（例 "1,0@2"）
  const MAX_LAYERS = 20; // store.js と同じ上限（第1層を含む）
  const newLayer = () => ({ camera: { x: 0, y: 0, zoom: 1 }, memos: new Map(), regions: [], footprints: {}, trails: {} });
  const recLayers = (rec) => (rec && rec.children ? [rec.children, ...(rec.moreLayers || [])] : []);
  const layerOf = (rec, li) => recLayers(rec)[li] || null;
  const stepOf = (key, li) => (li > 0 ? `${key}@${li + 1}` : key);
  function parseStep(step) {
    const m = /^(.*?)(?:@(\d+))?$/.exec(step);
    return { key: m[1], li: m[2] ? Number(m[2]) - 1 : 0 };
  }
  const layerName = (rec, li) => (layerOf(rec, li) && layerOf(rec, li).name) || `第${li + 1}層`;

  // 空の層を片付ける：後ろの空の層を外す（途中の空の層は、後ろの層の番号を保つために残す）。
  // 第1層だけになってそれも空なら children ごと外す。keep の層（これから入る層）は残す
  function trimLayers(rec, keep = new Set()) {
    const more = rec.moreLayers || [];
    while (more.length && !layerHasContent(more[more.length - 1]) && !keep.has(more[more.length - 1])) more.pop();
    if (more.length) return;
    delete rec.moreLayers;
    if (rec.children && !layerHasContent(rec.children) && !keep.has(rec.children)) delete rec.children;
  }
  const isCenter = (key) => path.length > 0 && key === CENTER_KEY;

  // 表示中の階層のレコード。下の階層の中心 (0,0) は親のメモそのもの
  function getRecord(key) {
    return isCenter(key) ? path[path.length - 1].rec : memos.get(key);
  }

  function ensureRecord(key) {
    let rec = getRecord(key);
    if (!rec) {
      rec = createRecord();
      memos.set(key, rec);
    }
    return rec;
  }

  const hasText = (rec) => !!rec && rec.text.trim() !== '';

  // 関連付けがあるメモは、本文が空でも消さない（書き直している途中で関連が消えないように）
  function isEmptyRecord(rec) {
    return !hasText(rec) && rec.likedLevel === 0 && !rec.bookmarked && rec.comments.length === 0 && !hasChildren(rec)
      && !(rec.images && rec.images.length) && !(rec.urls && rec.urls.length) && !(rec.tags && rec.tags.length)
      && !rec.due && !(rec.progress > 0)
      && !(rec.id && linkIndex.has(rec.id) || (rec.id && dendriteUses(rec.id)));
  }

  const tagsOf = (rec) => (rec && Array.isArray(rec.tags) ? rec.tags : []);

  // ---- 関連付けのデータ ----

  function rebuildLinkIndex() {
    linkIndex = new Map();
    for (const { a, b } of links) {
      if (!linkIndex.has(a)) linkIndex.set(a, new Set());
      if (!linkIndex.has(b)) linkIndex.set(b, new Set());
      linkIndex.get(a).add(b);
      linkIndex.get(b).add(a);
    }
  }

  const linkCount = (rec) => (rec && rec.id && linkIndex.has(rec.id) ? linkIndex.get(rec.id).size : 0);
  const isLinked = (a, b) => !!linkIndex.get(a) && linkIndex.get(a).has(b);

  function ensureId(rec) {
    if (!rec.id) rec.id = uuid();
    return rec.id;
  }

  function addLink(a, b, { kind = null, label = '' } = {}) {
    const link = { a, b, createdAt: nowIso() };
    if (kind) link.kind = kind;
    if (label) link.label = label;
    links.push(link);
    rebuildLinkIndex();
  }

  const findLink = (a, b) => links.find((l) => (l.a === a && l.b === b) || (l.a === b && l.b === a)) || null;

  function removeLink(a, b) {
    links = links.filter((l) => !((l.a === a && l.b === b) || (l.a === b && l.b === a)));
    rebuildLinkIndex();
  }

  // そのメモと、周りに書いたメモ（下の階層）すべての ID
  function subtreeIds(rec, ids = new Set()) {
    if (rec.id) ids.add(rec.id);
    for (const layer of recLayers(rec)) for (const child of layer.memos.values()) subtreeIds(child, ids);
    return ids;
  }

  function countLinksFor(ids) {
    return links.filter((l) => ids.has(l.a) || ids.has(l.b)).length;
  }

  function removeLinksFor(ids) {
    const before = links.length;
    links = links.filter((l) => !ids.has(l.a) && !ids.has(l.b));
    if (links.length !== before) rebuildLinkIndex();
    return before - links.length;
  }

  // ID のメモが、どの階層（道筋 keys）のどのマスにあるか
  function locateById(id) {
    const walk = (layer, keys) => {
      for (const [key, rec] of layer.memos) {
        if (rec.id === id) return { keys, key, rec };
        for (const [li, sub] of recLayers(rec).entries()) {
          const found = walk(sub, [...keys, stepOf(key, li)]);
          if (found) return found;
        }
      }
      return null;
    };
    return walk(rootLayer, []);
  }

  // 画像を組み合わせた層は、メモが無くても中身がある（組み合わせだけで残す）
  function layerHasContent(layer) {
    if (layer.combo || (layer.regions && layer.regions.length)) return true;
    for (const rec of layer.memos.values()) if (!isEmptyRecord(rec)) return true;
    return false;
  }

  const hasChildren = (rec) => recLayers(rec).some(layerHasContent);

  // 周りに書いたメモの数（直下のみ。重ねた層も合わせて）
  function childCount(rec) {
    let n = 0;
    for (const layer of recLayers(rec)) for (const r of layer.memos.values()) if (!isEmptyRecord(r)) n++;
    return n;
  }

  function layerMemoCount(layer) {
    let n = 0;
    for (const r of layer.memos.values()) if (!isEmptyRecord(r)) n++;
    return n;
  }

  // 下の階層すべてのメモの数
  function descendantCount(rec) {
    let n = 0;
    for (const layer of recLayers(rec)) {
      for (const r of layer.memos.values()) {
        if (!isEmptyRecord(r)) n++;
        n += descendantCount(r);
      }
    }
    return n;
  }

  // ノート全体（下の階層も含む）のメモを順にたどる。keys はそのメモがある階層までの道筋
  function forEachMemo(cb, root = rootLayer) {
    const walk = (layer, keys) => {
      for (const [key, rec] of layer.memos) {
        if (!isEmptyRecord(rec)) cb(rec, key, keys);
        for (const [li, sub] of recLayers(rec).entries()) walk(sub, [...keys, stepOf(key, li)]);
      }
    };
    walk(root, []);
  }

  // 保存形式（プレーンなオブジェクト）→ 画面用（Map）。children も同じ形に変換する
  function toLayer(raw) {
    const cam = (raw && raw.camera) || {};
    const zoom = Number(cam.zoom);
    const layer = { camera: { x: Number(cam.x) || 0, y: Number(cam.y) || 0, zoom: Number.isFinite(zoom) ? clampZoom(zoom) : 1 }, memos: new Map() };
    if (raw && typeof raw.name === 'string' && raw.name) layer.name = raw.name;
    const combo = comboFromRaw(raw && raw.combo);
    if (combo) layer.combo = combo;
    // 領域（名前を付けたマスの集まり）。無ければ空の一覧
    layer.regions = Array.isArray(raw && raw.regions) ? raw.regions.map((r) => ({ ...r, keys: [...r.keys] })) : [];
    // 足あと（マスごとの回数）と道（続けて訪れた2マス）
    layer.footprints = raw && raw.footprints && typeof raw.footprints === 'object' ? Object.fromEntries(Object.entries(raw.footprints).map(([k, v]) => [k, { ...v }])) : {};
    layer.trails = raw && raw.trails && typeof raw.trails === 'object' ? { ...raw.trails } : {};
    for (const [key, rec] of Object.entries((raw && raw.memos) || {})) {
      if (rec.children) rec.children = toLayer(rec.children);
      if (Array.isArray(rec.moreLayers)) rec.moreLayers = rec.moreLayers.map(toLayer);
      layer.memos.set(key, rec);
    }
    return layer;
  }

  // 空になったマスは保持しない（編集中のマスは編集終了時に判定する）
  function pruneIfEmpty(key) {
    if (key === editingKey || isCenter(key)) return false;
    const rec = memos.get(key);
    if (rec && isEmptyRecord(rec)) {
      memos.delete(key);
      return true;
    }
    return false;
  }

  function afterRecordChange(key) {
    pruneIfEmpty(key);
    refreshCell(key);
    updateTabCounts();
    scheduleSave();
  }

  // ---- マス要素 ------------------------------------------------------------

  let cellPrototype = null;

  function buildCellPrototype() {
    const cell = el('div', 'cell');
    cell.innerHTML = `
      <div class="hex"><div class="hex-inner"><div class="fp"></div><div class="cover"></div>
        <div class="zone-meta"><span class="meta-coord"></span><span class="meta-sep">·</span><span class="meta-info"></span><span class="meta-seq" hidden></span><button type="button" class="meta-link" data-action="links" tabindex="-1" hidden><span class="meta-link-n"></span></button><button type="button" class="meta-badge meta-copy" data-action="copies" tabindex="-1" hidden><span class="meta-badge-n"></span></button><button type="button" class="meta-badge meta-att" data-action="images" tabindex="-1" hidden><span class="meta-badge-n"></span></button><button type="button" class="meta-badge meta-web" data-action="web" tabindex="-1" hidden><span class="meta-badge-n"></span></button><button type="button" class="meta-badge meta-due hexp" data-action="due" tabindex="-1" hidden><span class="meta-badge-n"></span></button></div>
        <div class="zone-body"><div class="body-text"></div><button type="button" class="body-card" data-action="open-url" tabindex="-1" hidden></button><div class="body-placeholder">メモを書く…</div></div>
        <div class="zone-actions">
          <button type="button" class="act act-comment" data-action="comment"><span class="act-badge"></span></button>
          <button type="button" class="act act-layer" data-action="layer"><span class="act-badge"></span></button>
          <button type="button" class="act act-like" data-action="like"><span class="act-badge"></span></button>
          <button type="button" class="act act-bookmark" data-action="bookmark"></button>
          <button type="button" class="act act-delete" data-action="delete" title="削除" aria-label="メモを削除"></button>
        </div>
        <button type="button" class="zone-tags" data-action="tags" tabindex="-1" title="タグを付ける" aria-label="タグ"></button>
        <button type="button" class="cell-check" data-action="select" tabindex="-1" title="選ぶ（複数選択）" aria-label="このマスを選ぶ"></button>
      </div></div>`;
    for (const btn of cell.querySelectorAll('.act')) btn.prepend(svgIcon(ACTION_ICONS[btn.dataset.action]));
    cell.querySelector('.meta-link').prepend(svgIcon('link'));
    cell.querySelector('.meta-copy').prepend(svgIcon('hexcopy'));
    cell.querySelector('.meta-att').prepend(svgIcon('clip'));
    cell.querySelector('.meta-web').prepend(svgIcon('globe'));
    return cell;
  }

  function createCell() {
    if (!cellPrototype) cellPrototype = buildCellPrototype();
    const node = cellPrototype.cloneNode(true);
    node._refs = {
      coord: node.querySelector('.meta-coord'),
      sep: node.querySelector('.meta-sep'),
      info: node.querySelector('.meta-info'),
      seq: node.querySelector('.meta-seq'),
      link: node.querySelector('.meta-link'),
      linkN: node.querySelector('.meta-link-n'),
      copy: node.querySelector('.meta-copy'),
      copyN: node.querySelector('.meta-copy .meta-badge-n'),
      meta: node.querySelector('.zone-meta'),
      att: node.querySelector('.meta-att'),
      attN: node.querySelector('.meta-att .meta-badge-n'),
      web: node.querySelector('.meta-web'),
      webN: node.querySelector('.meta-web .meta-badge-n'),
      due: node.querySelector('.meta-due'),
      dueN: node.querySelector('.meta-due .meta-badge-n'),
      cover: node.querySelector('.cover'),
      card: node.querySelector('.body-card'),
      body: node.querySelector('.zone-body'),
      text: node.querySelector('.body-text'),
      comment: node.querySelector('.act-comment'),
      commentBadge: node.querySelector('.act-comment .act-badge'),
      layer: node.querySelector('.act-layer'),
      layerBadge: node.querySelector('.act-layer .act-badge'),
      like: node.querySelector('.act-like'),
      likeBadge: node.querySelector('.act-like .act-badge'),
      bookmark: node.querySelector('.act-bookmark'),
      del: node.querySelector('.act-delete'),
      tags: node.querySelector('.zone-tags'),
    };
    return node;
  }

  function placeCell(node) {
    const x = Math.round(node._wx - anchor.x - HEX_W / 2);
    const y = Math.round(node._wy - anchor.y - HEX_H / 2);
    node.style.transform = `translate(${x}px, ${y}px)`;
  }

  function bindCell(node, key) {
    const { q, r } = H.parseKey(key);
    const p = H.hexToPixel(q, r, HEX_SIZE);
    node._key = key;
    node._wx = p.x;
    node._wy = p.y;
    node.dataset.key = key;
    node.classList.toggle('is-origin', q === 0 && r === 0);
    for (const b of node.querySelectorAll('.act.is-pop')) b.classList.remove('is-pop');
    placeCell(node);
    updateCellContent(node);
  }

  function updateCellContent(node) {
    markTipsDirty(); // 1行の吹き出しも中身に合わせる
    const key = node._key;
    const rec = getRecord(key);
    const refs = node._refs;
    const editing = key === editingKey;
    const center = isCenter(key);
    const level = rec ? rec.likedLevel : 0;
    const comments = rec ? rec.comments.length : 0;
    const bookmarked = !!rec && rec.bookmarked;
    const kids = childCount(rec);

    node.classList.toggle('has-record', !!rec && !isEmptyRecord(rec));
    node.classList.toggle('has-text', hasText(rec));
    node.classList.toggle('is-editing', editing);
    node.classList.toggle('is-selected', key === selectedKey && !editing);
    node.classList.toggle('is-cut', !!rec && !!cutSource && cutSource.board === currentBoardId && (cutSource.rec === rec || (!!cutSource.recs && cutSource.recs.includes(rec))));
    const multiN = rec && multiSet.has(rec) ? multiOrder.get(rec) : 0;
    node.classList.toggle('is-multi', !!multiN);
    if (multiN) node.dataset.multiN = String(multiN);
    else delete node.dataset.multiN;
    node.classList.toggle('is-center', center);
    node.classList.toggle('is-bookmarked', bookmarked); // 全体表示の印に使う
    node.classList.toggle('has-kids', kids > 0);
    node.classList.toggle('is-flash', key === flashKey);
    const sideOn = isSideTarget(key, rec);
    node.classList.toggle('is-side-target', sideOn);
    node.dataset.like = String(level);
    const seq = rec && rec.seq;
    node.classList.toggle('is-seq', !!seq);
    node.classList.toggle('is-seq-head', !!seq && !!seq.head);
    node.classList.toggle('is-reading', !!reading && !!rec && rec === reading.rec);
    node.classList.toggle('is-read-set', !!reading && !!reading.set && !!rec && reading.set.has(rec)); // 選んだマスを読んでいるときの、読む順のマス
    const seqSide = !!seq && !!side && side.series === seq.id;
    node.classList.toggle('is-seq-side', seqSide);
    node.classList.toggle('is-seg-hover', !!seq && key === seriesHoverKey);
    refs.seq.hidden = !seq;
    if (seq) {
      refs.seq.textContent = String(seq.n);
      refs.seq.title = `分けて並べた文章の ${seq.n} 番目${seq.head ? '（見出し）' : ''}｜右クリックで全文をサイドバーに${seqSide ? '出すのをやめる' : '表示'}｜マスの右クリック →「ここから読む」で読書モード`;
    }

    // ノート直下の原点のマス：ノートの名前の札（ここのメモが、ノートのハニカムでこのノートの説明・表紙になる）
    const nbOrigin = !center && !path.length && key === '0,0';
    const nbName = nbOrigin ? (boards.find((b) => b.id === currentBoardId) || {}).name || '' : '';
    refs.coord.textContent = center ? '中心' : nbOrigin && nbName ? `📓 ${nbName}` : formatCoord(key);
    refs.coord.classList.toggle('is-notebook', nbOrigin && !!nbName);
    refs.coord.title = nbOrigin && nbName ? `ノート「${nbName}」の原点（0, 0）：ここのメモが、ノートのハニカムでこのノートの説明（と表紙）として出ます` : '';
    renderBodyText(refs.text, rec ? rec.text : '');
    if (editing) updateCounter(node, editor.value);
    else updateMetaTime(node, rec);

    refs.like.dataset.level = String(level);
    refs.like.title = `${LIKE_LABELS[level]}｜右クリックでいいねの一覧${side && side.list === 'likes' ? 'を閉じる' : '（時系列）'}`;
    refs.like.setAttribute('aria-label', `いいね（現在：${LIKE_LABELS[level]}）`);
    refs.like.setAttribute('aria-pressed', String(level > 0));
    refs.likeBadge.textContent = level >= 2 ? String(level) : '';

    refs.bookmark.classList.toggle('is-on', bookmarked);
    const bookmarkLabel = bookmarked ? 'ブックマーク済み' : 'ブックマーク';
    refs.bookmark.title = `${bookmarkLabel}｜右クリックでブックマークの一覧${side && side.list === 'bookmarks' ? 'を閉じる' : '（時系列）'}`;
    refs.bookmark.setAttribute('aria-label', bookmarkLabel);
    refs.bookmark.setAttribute('aria-pressed', String(bookmarked));

    const nLinks = linkCount(rec);
    refs.link.hidden = nLinks === 0;
    refs.linkN.textContent = nLinks ? String(nLinks) : '';
    refs.link.title = `関連するメモ（${nLinks}件）を見る｜右クリックでサイドバー${sideOn && side.tab === 'links' ? 'を閉じる' : 'に表示'}`;
    refs.link.classList.toggle('is-side', sideOn && side.tab === 'links');
    // 区画（写しの作業台）にあるこのメモの写しの数（このマスから写した紙片と、紙片からこのマスへ置いた写し）
    const nCopies = copyCount(rec);
    const copiesOn = !!side && side.list === 'pocket' && !!rec && !!rec.id && side.copiesOf === rec.id;
    refs.copy.hidden = nCopies === 0;
    refs.copyN.textContent = nCopies ? String(nCopies) : '';
    refs.copy.title = `区画に写しが ${nCopies} 枚｜クリックで一覧・右クリックで区画${copiesOn ? 'を閉じる' : 'を開いて光らせる'}`;
    refs.copy.classList.toggle('is-side', copiesOn);
    node.classList.toggle('is-link-source', !!linking && linking.rec === rec);
    node.classList.toggle('is-new-link-target', !!linking && linking.create && key === newLinkTarget);

    refs.commentBadge.textContent = comments ? String(comments) : '';
    const commentLabel = comments ? `コメント（${comments}件）` : 'コメント';
    refs.comment.title = `${commentLabel}｜右クリックでサイドバー${sideOn && side.tab === 'comments' ? 'を閉じる' : 'に表示'}`;
    refs.comment.setAttribute('aria-label', commentLabel);
    refs.comment.classList.toggle('is-side', sideOn && side.tab === 'comments');

    // 中心（親のメモ）の六角形ボタンは「この周りに層を重ねる」。削除は出さない（親の削除は上の階層で行う）
    const nLayers = recLayers(rec).length;
    const combined = !center && recLayers(rec).some((l) => l.combo); // 下の階層に画像を組み合わせてある
    node.classList.toggle('has-combo', combined);
    refs.layer.hidden = center ? nLayers >= MAX_LAYERS : path.length >= MAX_DEPTH;
    refs.del.hidden = center;
    refs.layer.classList.toggle('is-on', center ? nLayers > 1 : kids > 0 || combined);
    refs.layer.classList.toggle('is-stack', center);
    refs.layerBadge.textContent = center ? (nLayers > 1 ? String(nLayers) : '') : kids ? String(kids) : '';
    const layerLabel = center
      ? `この周りに新しい層を重ねる（第${nLayers + 1}層を作る${nLayers > 1 ? `・今 ${nLayers} 層` : ''}）`
      : kids ? `周りのメモを開く（${kids}件${nLayers > 1 ? `・${nLayers} 層` : ''}${combined ? '・画像と組み合わせ' : ''}）`
        : combined ? '画像と組み合わせたセルを開く' : 'このメモを中心にしたハニカムを開く（周りに書く）';
    refs.layer.title = `${layerLabel}｜右クリックでサイドバー${sideOn && side.tab === 'layer' ? 'を閉じる' : 'に一覧'}`;
    refs.layer.setAttribute('aria-label', layerLabel);
    refs.layer.classList.toggle('is-side', sideOn && side.tab === 'layer');

    updateCellMedia(node, rec); // 画像・リンクの印、表紙、リンクのカード
    renderCellTags(node, rec); // 下の三角形のタグ
    renderCellDue(node, rec); // 上の三角形の期限の印
    syncMetaBadges(refs); // 期限の印が決まってから、上の三角形の混み具合をもう一度
    renderCellFootprint(node, key); // 足あと（表示しているときだけ見える）
    // 検索・タグの分布（地図）：当たったマスを色で、ほかを薄く
    const mapColor = searchMap && rec ? searchMap.hits.get(rec) || null : null;
    node.classList.toggle('is-map-hit', !!mapColor);
    if (mapColor) node.style.setProperty('--map-c', mapColor);
    else node.style.removeProperty('--map-c');

    // Tab キーで辿れるのは編集中のマスのボタンだけにする
    const tabIndex = editing ? 0 : -1;
    for (const b of [refs.comment, refs.layer, refs.like, refs.bookmark, refs.del, refs.link, refs.copy, refs.att, refs.web, refs.tags, refs.due]) b.tabIndex = tabIndex;
  }

  // 上の三角形が狭いので、印が2つ以上（または印があって日付が長い）なら更新時刻を省く（マウスを乗せると見える）。
  // 印が5つそろったら（🔗・区画の写し・📎・🌐・期限）、間を詰めて 📎・🌐 の数と期限の日付を省く（はみ出して両端が欠けないように。数はマウスを乗せると見える）
  function syncMetaBadges(refs) {
    const badges = [refs.link, refs.copy, refs.att, refs.web, refs.due].filter((b) => !b.hidden).length;
    const longInfo = [...refs.info.textContent].length > 7; // 「2023年11月15日」のような長い日付
    const crowded = badges >= 2 || (badges >= 1 && longInfo);
    refs.meta.classList.toggle('is-crowded', crowded);
    refs.meta.classList.toggle('is-packed', badges >= 5);
    refs.meta.title = crowded ? refs.info.title : '';
  }

  function updateMetaTime(node, rec = getRecord(node._key)) {
    const refs = node._refs;
    const show = !!rec && !isEmptyRecord(rec);
    refs.info.className = 'meta-info';
    refs.info.textContent = show ? formatRelative(rec.updatedAt) : '';
    refs.info.title = show ? `更新：${formatFull(rec.updatedAt)}` : '';
    refs.sep.hidden = !show;
  }

  function updateCounter(node, text) {
    const n = countChars(text);
    const refs = node._refs;
    refs.info.className = `meta-info${n > TEXT_LIMIT ? ' is-over' : n >= TEXT_WARN ? ' is-warn' : ''}`;
    refs.info.textContent = `${n} / ${TEXT_LIMIT}`;
    refs.info.title = n > TEXT_LIMIT ? `目安の ${TEXT_LIMIT} 字を超えています` : `文字数（目安 ${TEXT_LIMIT} 字）`;
    refs.sep.hidden = false;
  }

  function refreshCell(key) {
    const node = activeCells.get(key);
    if (node) updateCellContent(node);
    if (peekPinned === key) refreshPinnedPeek(key);
  }

  // ---- 描画（仮想化） --------------------------------------------------------

  function requestRender() {
    if (renderQueued) return;
    renderQueued = true;
    requestAnimationFrame(() => {
      renderQueued = false;
      render();
    });
  }

  function measureView() {
    view.w = stage.clientWidth;
    view.h = stage.clientHeight;
    const r = stage.getBoundingClientRect();
    stageLeft = r.left;
    stageRight = r.right;
  }

  function syncStageSize() {
    if (activeTab !== 'grid') return;
    compensateStageShift();
    const w = stage.clientWidth;
    const h = stage.clientHeight;
    if (w === view.w && h === view.h) return;
    view.w = w;
    view.h = h;
    lastSignature = '';
    render();
  }

  function render() {
    if (!ready || activeTab !== 'grid' || view.w === 0 || view.h === 0) return;
    const z = camera.zoom;
    const overview = z < OVERVIEW_BELOW;
    if (overview !== isOverview) setOverview(overview);
    if (peekPinned && peekCameraMoved(camera, peekPinCam)) unpinPeek(); // 動かした・拡大縮小した：固定を外す

    if (Math.abs(camera.x - anchor.x) > REBASE_DISTANCE || Math.abs(camera.y - anchor.y) > REBASE_DISTANCE) {
      anchor.x = Math.round(camera.x);
      anchor.y = Math.round(camera.y);
      tipsDirty = true; // 吹き出しも同じ基準点で並べ直す
      for (const node of activeCells.values()) placeCell(node);
      renderLinks(); // 線も同じ基準点で描き直す
      placeCombo(); // 組み合わせた画像も
    }

    // 画面に映るワールド座標の範囲（縮小するほど広い）
    const rect = {
      left: camera.x - view.w / 2 / z - VIEW_BUFFER,
      top: camera.y - view.h / 2 / z - VIEW_BUFFER,
      right: camera.x + view.w / 2 / z + VIEW_BUFFER,
      bottom: camera.y + view.h / 2 / z + VIEW_BUFFER,
    };
    const b = H.visibleBounds(rect.left, rect.top, rect.right, rect.bottom, HEX_SIZE);
    const signature = `${overview ? 'ov' : 'full'}|${b.rMin},${b.rMax},${b.a2},${b.b2}|${editingKey}`;
    if (signature !== lastSignature) {
      lastSignature = signature;
      reconcile(b, overview ? rect : null);
      tipsDirty = true;
    }

    // 全体表示では小数の位置のまま動かす（背景の模様とずれないように）
    const ox = view.w / 2 - (camera.x - anchor.x) * z;
    const oy = view.h / 2 - (camera.y - anchor.y) * z;
    cellLayer.style.transform = overview
      ? `translate(${ox}px, ${oy}px) scale(${z})`
      : `translate(${Math.round(ox)}px, ${Math.round(oy)}px) scale(${z})`;
    if (overview) updateGridBackground(z);
    if (z !== lastZoom) applyZoomStyles(z);
    syncTips(ox, oy, z);
    if (comboAdjust) placeComboFrame(); // 位置合わせの枠は画面の座標で追いかける

    const c = H.pixelToHex(camera.x, camera.y, HEX_SIZE);
    const label = `${c.q}, ${c.r}`;
    if (label !== lastCenterLabel) {
      lastCenterLabel = label;
      centerCoordEl.textContent = label;
    }
    if (ovWriteKey) placeOvWrite(ovWriteKey);
    if (ovEditKey) placeOvEdit(ovEditKey);
  }

  // ---- 縮小表示 -------------------------------------------------------------

  const gridBg = $('gridBg');
  const zoomLabelEl = $('zoomLabel');
  let isOverview = false;
  let lastZoom = null;

  // ---- 表示倍率の計算 ----
  // DOM にも settings にも触らない（test/zoom.test.js が、この印の間をそのまま取り出して試す）。
  // 倍率は整数の %（Math.round(z * 100)）で比べる（なめらかに動かした後の小数の端数で、登録と合わなくならないように）
  const ZOOM_RANGE = { grid: [4, 150], graph: [20, 250] }; // ハニカム（MIN_ZOOM〜MAX_ZOOM）・関係線のグラフ
  // その画面で使える倍率（%）に収める
  function zoomClampPct(pct, view) {
    const [min, max] = ZOOM_RANGE[view] || ZOOM_RANGE.grid;
    return Math.min(max, Math.max(min, Math.round(pct)));
  }
  // 登録の何番目が今の倍率か（その画面の範囲に収めた値で比べる。無ければ -1。同じ値が2つなら前のほう）
  function zoomPresetIndex(presets, pct, view) {
    return presets.findIndex((p) => zoomClampPct(p, view) === Math.round(pct));
  }
  // 「この倍率で固定する」：今の倍率が登録にあればそのまま、無ければいちばん近い登録（同じだけ離れていれば前のほう）
  function zoomLockTarget(presets, pct, view) {
    const vals = presets.map((p) => zoomClampPct(p, view));
    const now = Math.round(pct);
    if (vals.includes(now)) return now;
    return vals.reduce((best, v) => (Math.abs(v - now) < Math.abs(best - now) ? v : best), vals[0]);
  }
  // 登録の i 番目を押した（Ctrl+Shift+n・メニューのボタン）：{ pct：する倍率, lock：固定（undefined は変えない・null は外す・数はその倍率で固定）}
  // 固定していなければ倍率を変えるだけ。固定中ならその倍率で固定し直す。toggle（キー）で、固定中の倍率と同じ登録をもう一度押したら固定を外す
  function zoomPresetAction(presets, i, lockPct, view, toggle = false) {
    const pct = zoomClampPct(presets[i], view);
    if (lockPct == null) return { pct, lock: undefined };
    if (toggle && Math.round(lockPct) === pct) return { pct, lock: null };
    return { pct, lock: pct };
  }
  // グラフの倍率を k にしても、画面上の点 (mx, my) が動かないカメラ
  function gZoomCam(cam, k, mx, my) {
    return { x: mx - (mx - cam.x) * (k / cam.k), y: my - (my - cam.y) * (k / cam.k), k };
  }
  // グラフの全体表示：丸の範囲 box { cx, cy：真ん中, w, h：余白込みの幅・高さ } を、幅 vw・高さ vh に収めるカメラ。
  // lockK（倍率を固定中）があれば倍率はそのまま、真ん中に寄せるだけ
  function gFitCam(box, vw, vh, kMax, lockK = null) {
    const k = lockK ?? Math.min(kMax, Math.max(0.25, Math.min((vw - 40) / box.w, (vh - 60) / box.h)));
    return { x: vw / 2 - box.cx * k, y: vh / 2 - box.cy * k + 10, k };
  }
  // 全体表示の余白（丸の範囲に足す幅・高さ）：狭い区画では小さくして、丸を大きく見せる
  function gFitPad(vw) {
    return vw < 600 ? { x: 60, y: 50 } : { x: 160, y: 120 };
  }
  // 右の欄（一覧・概観）の自動でたたむ・開く。stageW：グラフの区画の幅、panelW：欄のふだんの幅（一覧 420・概観 320）
  // open：今開いているか、auto：自動でたたんだか、pinned：狭いのに自分で開けたか → 'close' | 'open' | null
  function gPanelAutoStep(stageW, panelW, open, auto, pinned) {
    if (!stageW) return null;
    const narrow = stageW < panelW * 2;
    if (narrow && open && !pinned) return 'close';
    if (!narrow && !open && auto) return 'open';
    return null;
  }
  // ホイールの動き（行・ページ単位も px に）。Shift で縦の回転を横に
  function wheelPanDelta(e, w, h) {
    let dx = e.deltaX;
    let dy = e.deltaY;
    if (e.deltaMode === 1) {
      dx *= 40;
      dy *= 40;
    } else if (e.deltaMode === 2) {
      dx *= w;
      dy *= h;
    }
    if (e.shiftKey && dx === 0) {
      dx = dy;
      dy = 0;
    }
    return { dx, dy };
  }
  // 「このセルを拡大表示」：丸 p（グラフの座標）を見える範囲 v（{ left, top, right, bottom }、画面の座標）の真ん中に、
  // 六角形の半径が画面で R（見える範囲の短いほうの 18%、64〜110px）くらいになる倍率で。lockK（倍率を固定中）があればその倍率のまま真ん中へ
  function gZoomCellCam(p, v, gr, kMin, kMax, lockK = null) {
    const w = Math.max(0, v.right - v.left);
    const h = Math.max(0, v.bottom - v.top);
    const R = Math.min(110, Math.max(64, Math.min(w, h) * 0.18));
    const k = lockK ?? Math.min(kMax, Math.max(kMin, R / gr));
    return { x: v.left + w / 2 - p.x * k, y: v.top + h / 2 - p.y * k, k };
  }
  // 段階の拡大：押すたびに 3 段で寄る。k0：はじめ（1 段目の前）の倍率、kT：寄せきった倍率、step：何段目か（1〜）
  // 倍率の比で等分（k0 × (kT/k0)^(step/3)）。3 段目からは kT のまま。kT が k0 以下なら倍率は k0 のまま（真ん中に寄せるだけ）
  const G_ZOOM_STEPS = 3;
  function gZoomStepK(k0, kT, step) {
    if (!(kT > k0) || !(k0 > 0)) return k0;
    const s = Math.max(0, Math.min(G_ZOOM_STEPS, step));
    return s >= G_ZOOM_STEPS ? kT : k0 * Math.pow(kT / k0, s / G_ZOOM_STEPS);
  }
  // 右クリックのメニューから押したとき、メニューを開いたままにするか。prev：押す前の段（0〜）
  // 1・2 段目は開いたまま（続けて押せる）、3 段目（寄せきった）と、寄せきったあとの「真ん中に」は閉じる
  function gZoomMenuStays(prev) {
    return prev + 1 < G_ZOOM_STEPS;
  }
  // メニューの「このセルを拡大表示」の文字。next：次に押すと何段目か
  function gZoomMenuLabel(next) {
    return next > G_ZOOM_STEPS ? 'このセルを真ん中に（拡大は最大）' : `このセルを拡大表示（${next}/${G_ZOOM_STEPS}）`;
  }
  // 寄ったあとのメニューの置き場所：セル（画面の矩形 a）の右に、入らなければ左に。縦はセルの上端にそろえ、画面の中に
  function gZoomMenuPlace(a, size, view) {
    const PAD = 8;
    const GAP = 10;
    const clamp = (v, lo, hi) => Math.max(lo, Math.min(v, Math.max(lo, hi)));
    const y = clamp(a.top, PAD, view.h - size.h - PAD);
    if (a.right + GAP + size.w <= view.w - PAD) return { x: a.right + GAP, y };
    if (a.left - GAP - size.w >= PAD) return { x: a.left - GAP - size.w, y };
    return { x: clamp(a.left, PAD, view.w - size.w - PAD), y };
  }
  // カメラの途中（t：0〜1、ゆっくり止まる）
  function gCamLerp(a, b, t) {
    const e = 1 - Math.pow(1 - Math.max(0, Math.min(1, t)), 3);
    return { x: a.x + (b.x - a.x) * e, y: a.y + (b.y - a.y) * e, k: a.k + (b.k - a.k) * e };
  }
  // ---- 表示倍率の計算ここまで ----

  // ---- 倍率の登録と固定（右上の「－ 100% ＋」） ----
  // 右上の倍率は、見ている画面に合わせる：ハニカムではハニカムの倍率（camera.zoom）、グラフのタブでは関係線のグラフの倍率（graph.cam.k）。
  // 登録（6つ）は共通、固定は画面ごと。どちらも settings.json の zoom（ほかのウィンドウにも届く）。小窓は固定に従わない
  const OVERVIEW_CLICK_MODES = ['zoom', 'edit', 'pin'];
  const ZOOM_DEFAULT = { presets: [25, 50, 75, 100, 125, 150], lock: { grid: null, graph: null }, overviewClick: 'zoom' };
  const G_ZOOM_MIN = 0.2; // グラフの倍率の範囲（ホイールと同じ）
  const G_ZOOM_MAX = 2.5;
  const zoomMenu = $('zoomMenu');
  const zoomView = () => (activeTab === 'graph' ? 'graph' : 'grid');
  const zoomViewName = (view) => (view === 'graph' ? 'グラフ' : 'ハニカム');
  // 古い本体（settings に zoom が無い）でも動くように、既定で埋めて読む
  function zoomPrefs() {
    const z = settings.zoom || {};
    return {
      presets: Array.isArray(z.presets) && z.presets.length === 6 ? z.presets.slice() : ZOOM_DEFAULT.presets.slice(),
      lock: { ...ZOOM_DEFAULT.lock, ...(z.lock || {}) },
      overviewClick: ['zoom', 'edit', 'pin'].includes(z.overviewClick) ? z.overviewClick : 'zoom', // OVERVIEW_CLICK_MODES と同じ（テストが関数だけ取り出すので書き並べる）
    };
  }
  // 縮小中（全体表示）にメモのマスをクリックしたとき：'zoom'（そこを拡大）・'edit'（拡大して編集）・'pin'（浮かび上がりを固定）
  const overviewClickMode = () => zoomPrefs().overviewClick;
  function setOverviewClickMode(mode) {
    const p = zoomPrefs();
    p.overviewClick = OVERVIEW_CLICK_MODES.includes(mode) ? mode : 'zoom';
    if (p.overviewClick !== 'pin') unpinPeek();
    settings = { ...settings, zoom: p };
    saveSettings({ zoom: p }, { quiet: true });
  }
  // 固定している倍率（%）。固定していない・小窓なら null
  function zoomLockPct(view = zoomView()) {
    if (miniMode) return null;
    const v = zoomPrefs().lock[view];
    return Number.isFinite(v) ? v : null;
  }
  // 固定している倍率（倍。1 が 100%）か null。ハニカムの拡大縮小・グラフの全体表示とホイールは、ここだけを見る
  function lockedZoom(view = zoomView()) {
    const pct = zoomLockPct(view);
    return pct == null ? null : pct / 100;
  }
  const currentZoom = (view = zoomView()) => (view === 'graph' ? graph.cam.k : camera.zoom);

  // 固定中に倍率を変えようとした：倍率を小さく弾ませて、4 秒に1回だけ知らせる
  let zoomToastAt = -Infinity;
  function notifyZoomLocked(view = zoomView()) {
    if (!zoomLabelEl.classList.contains('is-bump')) zoomLabelEl.classList.add('is-bump');
    const pct = zoomLockPct(view);
    if (pct == null || performance.now() - zoomToastAt < 4000) return;
    zoomToastAt = performance.now();
    toast(`${view === 'graph' ? 'グラフの' : ''}倍率を ${pct}% に固定しています（解除は右上の倍率から）`);
  }
  zoomLabelEl.addEventListener('animationend', () => zoomLabelEl.classList.remove('is-bump'));

  // 右上の倍率の表示（数字・固定の印・＋－のボタン）と、開いていればメニューを今の状態に
  let zoomUiKey = '';
  function updateZoomUi() {
    const view = zoomView();
    const pct = Math.round(currentZoom(view) * 100);
    const lock = zoomLockPct(view);
    const key = `${view}|${pct}|${lock}`;
    if (key !== zoomUiKey) {
      zoomUiKey = key;
      const locked = lock != null;
      const what = view === 'graph' ? 'グラフの' : '';
      if (locked) zoomLabelEl.replaceChildren(svgIcon('lock'), document.createTextNode(`${pct}%`));
      else zoomLabelEl.textContent = `${pct}%`;
      zoomLabelEl.setAttribute('aria-label', `${what}表示倍率 ${pct}%${locked ? '（固定中）' : ''}`);
      zoomLabelEl.title = locked
        ? `${what}倍率を ${lock}% で固定中（クリックで倍率の登録と固定・解除）`
        : `${view === 'graph' ? '関係線のグラフの倍率。' : ''}倍率の登録と固定（クリック）／100% に戻す：Ctrl+0`;
      zoomLabelEl.closest('.zoom-ctl').classList.toggle('is-locked', locked);
      for (const [id, verb, keys] of [['zoomIn', '拡大', 'Ctrl++'], ['zoomOut', '縮小', 'Ctrl+-']]) {
        const b = $(id);
        if (locked) b.setAttribute('aria-disabled', 'true');
        else b.removeAttribute('aria-disabled');
        b.title = locked ? `倍率を固定中（${lock}%）。解除は倍率のメニューから`
          : view === 'graph' ? `グラフを${verb}（${keys}／ホイール）` : `${verb}（${keys}／Ctrl+ホイール）`;
      }
    }
    if (zoomMenu.matches(':popover-open')) renderZoomMenu();
  }

  // 倍率のメニュー（右上の倍率を押す）を今の状態に
  function renderZoomMenu() {
    const view = zoomView();
    const p = zoomPrefs();
    const pct = Math.round(currentZoom(view) * 100);
    const lock = zoomLockPct(view);
    const [min, max] = ZOOM_RANGE[view];
    $('zoomMenuTarget').textContent = view === 'graph' ? `関係線のグラフの倍率（${min}%〜${max}%）` : `ハニカムの倍率（${min}%〜${max}%）`;
    const on = zoomPresetIndex(p.presets, pct, view);
    for (const b of zoomMenu.querySelectorAll('[data-zoom-preset]')) {
      const i = Number(b.dataset.zoomPreset);
      const v = zoomClampPct(p.presets[i], view);
      b.textContent = `${v}%`;
      b.setAttribute('aria-pressed', String(i === on));
      b.title = `${v !== p.presets[i] ? `グラフでは ${v}%（登録は ${p.presets[i]}%）。` : ''}${lock != null ? 'この倍率で固定し直す' : 'この倍率にする'}（Ctrl+Shift+${i + 1}）`;
    }
    $('zoomLock').checked = lock != null;
    const st = $('zoomMenuStatus');
    if (lock != null) {
      const off = zoomPresetIndex(p.presets, lock, view) < 0 ? '（登録にない倍率で固定中）' : '';
      st.textContent = view === 'graph'
        ? `グラフを ${lock}% で固定中${off}。ホイールは画面を動かし、＋－・全体では倍率を変えません（位置は動きます）`
        : `ハニカムを ${lock}% で固定中${off}。ホイール・ピンチ・＋－・全体・ジャンプでは倍率を変えません（位置は動きます）`;
    } else {
      st.textContent = `いまは ${pct}%。登録の倍率を押すと、その倍率にします`;
    }
    const zoomWarn = $('zoomMenuWarn');
    zoomWarn.hidden = !(view === 'grid' && lock != null && lock < OVERVIEW_BELOW * 100);
    zoomWarn.textContent = settings.overviewViewOnly === true
      ? '50% 未満では全体表示になり、新しい書き込みは止まります（1回のクリックは、下の「メモのクリック」のまま）'
      : '50% 未満では全体表示のままです。空いたマスをクリックすると一行で書けます。メモのあるマスはダブルクリックで本文を直せます（「見るだけ」で止められます）。1回のクリックは、下の「メモのクリック」に従います';
    $('overviewViewOnly').checked = settings.overviewViewOnly === true;
    $('zoomOverviewClickRow').hidden = view !== 'grid';
    if (document.activeElement !== $('zoomOverviewClick')) $('zoomOverviewClick').value = p.overviewClick;
    // 書いている途中の枠は書き換えない
    for (const input of zoomMenu.querySelectorAll('[data-zoom-slot]')) {
      if (document.activeElement !== input) input.value = String(p.presets[Number(input.dataset.zoomSlot)]);
    }
  }

  function openZoomMenu(anchorEl = zoomLabelEl) {
    renderZoomMenu();
    const r = anchorEl.getBoundingClientRect();
    const visible = r.width > 0 && r.bottom > 0;
    showPopoverAt(zoomMenu, visible ? { x: r.left + r.width / 2 - 180, y: r.bottom + 8 } : { x: innerWidth / 2 - 180, y: 90 });
  }

  // 固定を変えて settings.json に保存する（pct が null なら外す）。先に手元の settings を変え、すぐに効かせる
  function setZoomLock(view, pct) {
    const p = zoomPrefs();
    p.lock[view] = pct == null ? null : zoomClampPct(pct, view);
    settings = { ...settings, zoom: p };
    zoomUiKey = '';
    updateZoomUi();
    saveSettings({ zoom: p }, { quiet: true });
  }
  function setZoomPresets(presets) {
    const p = zoomPrefs();
    p.presets = presets;
    settings = { ...settings, zoom: p };
    updateZoomUi();
    saveSettings({ zoom: p }, { quiet: true });
  }

  // その画面の倍率を pct（%）にする（固定はもう決めてある前提）
  function zoomToPct(view, pct) {
    if (view === 'graph') gZoomTo(pct / 100);
    else animateCameraTo(camera.x, camera.y, null, pct / 100);
  }

  // 登録の i 番目（0〜5）。toggle はキー（Ctrl+Shift+n）から：固定中の倍率と同じなら固定を外す
  function applyZoomPreset(i, { toggle = false } = {}) {
    const view = zoomView();
    const act = zoomPresetAction(zoomPrefs().presets, i, zoomLockPct(view), view, toggle);
    if (act.lock === null) {
      setZoomLock(view, null);
      toast('倍率の固定を解除しました');
      return;
    }
    if (act.lock !== undefined) setZoomLock(view, act.lock);
    zoomToPct(view, act.pct);
    if (toggle && act.lock !== undefined) toast(`${zoomViewName(view)}を ${act.pct}% で固定しました（同じキーでもう一度押すと解除）`);
  }

  // 「この倍率で固定する」：今の倍率が登録になければ、いちばん近い登録へ動かしてから固定
  function toggleZoomLock(on) {
    const view = zoomView();
    if (!on) {
      setZoomLock(view, null);
      toast('倍率の固定を解除しました');
      return;
    }
    const pct = zoomLockTarget(zoomPrefs().presets, currentZoom(view) * 100, view);
    setZoomLock(view, pct);
    zoomToPct(view, pct);
  }

  // ほかのウィンドウ（や保存の返事）で固定が変わった：表示中の画面の固定が新しくなったら、その倍率へ動かす
  function applyZoomSettings(prev) {
    const before = prev && prev.zoom && prev.zoom.lock ? prev.zoom.lock : ZOOM_DEFAULT.lock;
    const view = zoomView();
    const lock = zoomLockPct(view);
    zoomUiKey = '';
    if (ready && !miniMode && lock != null && lock !== before[view] && Math.round(currentZoom(view) * 100) !== lock) zoomToPct(view, lock);
    updateZoomUi();
  }

  // 階層・ノートを切り替えた（その階層の倍率を読み込んだ）後：ハニカムを固定中なら、その倍率にする（保存される）
  function enforceGridZoomLock() {
    const lz = lockedZoom('grid');
    if (lz == null || Math.round(camera.zoom * 100) === Math.round(lz * 100)) return;
    camera.zoom = lz;
    scheduleSave('camera');
  }

  // ハニカムの倍率を 50% 未満で固定していると全体表示のままで、書き始められない。そのときだけ知らせる（固定は破らない）
  const OVERVIEW_LOCKED_MSG = '倍率を 50% 未満で固定しているため、書き始められません（右上の倍率から解除）';
  function warnOverviewLocked() {
    if (!isOverview || lockedZoom('grid') == null) return false;
    toast(OVERVIEW_LOCKED_MSG, 'warn');
    return true;
  }

  function setOverview(on) {
    isOverview = on;
    if (!on) {
      hidePeek();
      hideOvMark();
      if (ovWriteKey) closeOvWrite({ commit: true }); // 拡大したときは、書きかけの一行を置いてから閉じる
      if (ovEditKey) closeOvEdit({ commit: true });
      cancelOvZoom();
    }
    if (on) endEdit(); // ふつうの編集欄は閉じる。ドラッグ中の移動はやめない（縮小中でも動かせる）
    stage.classList.toggle('is-overview', on);
    gridBg.hidden = !on;
    lastSignature = '';
    syncOverviewEditClass();
  }

  // 全体表示で足した操作（紙片・棚を置く、空いたマスに書く、メモの本文を直す、関連線）を使うか。
  // 「全体表示は見るだけ」が入っているとき、または読み取り専用のときは、今までの動きのまま
  function overviewWrites() {
    return isOverview && settings.overviewViewOnly !== true && activeTab === 'grid' && !boardReadOnly;
  }
  function syncOverviewEditClass() {
    stage.classList.toggle('is-ov-edit', overviewWrites());
  }

  // ---- 全体表示の操作（計算だけ） ----
  // DOM にも settings にも触らない（test/overview-edit.test.js が、この印の間を取り出して試す）。
  // 紙片を離したとき：全体表示でハニカムの上なら写しを置く（紙片は動かさない）。見るだけ、または盤の上なら今までの並べ替え。
  function slipDropAction({ honey, honeyKey, boardTarget, viewOnly, overview }) {
    if (overview && viewOnly !== true && honey && honeyKey) return { kind: 'place-copy', key: honeyKey };
    if (boardTarget) return { kind: 'reorder', target: boardTarget };
    return { kind: 'cancel' };
  }
  // 棚のメモを離したとき。見るだけの全体表示では何もしない（今までどおり）。それ以外は近い空いたマスへ置く。
  function shelfDropAction({ overview, viewOnly, key }) {
    if (overview && viewOnly === true) return { kind: 'ignore' };
    if (!key) return { kind: 'ignore' };
    return { kind: 'place', key };
  }
  // 空いたマスをクリックしたとき。見るだけ・メモのあるマス・中心は、今までどおり拡大。それ以外は一行で書く
  function emptyOverviewClick({ overview, viewOnly, filled, center }) {
    if (!(overview && viewOnly !== true) || filled || center) return 'zoom';
    return 'write';
  }
  // 全体表示で、メモから線を引き始める操作。Alt+左ドラッグ、または右ドラッグ。見るだけ・空のマスは無し
  function overviewLinkGesture({ overview, viewOnly, button, alt, fromMemo }) {
    if (!(overview && viewOnly !== true) || !fromMemo) return 'none';
    if (button === 0 && alt) return 'alt-drag';
    if (button === 2) return 'right-drag';
    return 'none';
  }
  // 線を空いたマスで離したとき。見るだけ・メモのあるマス・中心・読み取り専用は、今までの動き。それ以外は一行で書いて線も引く
  function emptyLinkRelease({ viewOnly, filled, center, linking, readOnly }) {
    if (!linking || filled || center || readOnly || viewOnly === true) return 'reject';
    return 'write';
  }
  // メモのあるマスの本文。1回のクリックは拡大を少し待つ（2回押し・メニュー・Enter・F2 は編集）。
  // 見るだけ・空・中心・読み取り専用は、今までどおり拡大
  function overviewFilledAction({ overview, viewOnly, filled, center, readOnly, gesture }) {
    const can = overview && viewOnly !== true && filled && !center && readOnly !== true;
    if (!can) return 'zoom';
    if (gesture === 'dblclick' || gesture === 'menu' || gesture === 'key') return 'edit';
    return 'wait';
  }
  // 直した本文。空（空白だけ）や、元と同じ文はメモを消さず残す
  function overviewEditResult(original, next) {
    const text = String(next == null ? '' : next);
    if (!text.trim() || text === String(original == null ? '' : original)) return { kind: 'keep' };
    return { kind: 'save', text };
  }
  // ---- 全体表示の操作（計算だけ）ここまで ----

  // 全体表示の落とし先・空いたマスの印。空のマスは DOM に置かないので、影は1枚だけ浮かべる
  let ovMark = null;
  function ensureOvMark() {
    if (ovMark) return ovMark;
    const el = document.createElement('div');
    el.className = 'ov-mark';
    el.hidden = true;
    el.setAttribute('aria-hidden', 'true');
    el.innerHTML = '<svg class="ov-mark-hex" viewBox="0 0 100 116" preserveAspectRatio="none"><polygon points="50,3 97,30 97,86 50,113 3,86 3,30" vector-effect="non-scaling-stroke"/></svg><div class="ov-mark-plus">＋</div><div class="ov-mark-label"></div>';
    stage.append(el);
    ovMark = { el, plus: el.querySelector('.ov-mark-plus'), label: el.querySelector('.ov-mark-label'), key: null, mode: '' };
    return ovMark;
  }
  function hideOvMark() {
    if (!ovMark || ovMark.el.hidden) return;
    ovMark.el.hidden = true;
    ovMark.key = null;
    ovMark.mode = '';
  }
  function showOvMark(key, mode, labelText) {
    if (!key) {
      hideOvMark();
      return;
    }
    const m = ensureOvMark();
    const { q, r } = H.parseKey(key);
    const p = H.hexToPixel(q, r, HEX_SIZE);
    const z = camera.zoom;
    const w = HEX_W * z;
    const h = HEX_H * z;
    const cx = view.w / 2 + (p.x - camera.x) * z;
    const cy = view.h / 2 + (p.y - camera.y) * z;
    m.el.hidden = false;
    m.el.style.width = `${w}px`;
    m.el.style.height = `${h}px`;
    m.el.style.left = `${cx - w / 2}px`;
    m.el.style.top = `${cy - h / 2}px`;
    m.el.classList.toggle('is-drop', mode === 'drop');
    m.el.classList.toggle('is-plus', mode === 'plus');
    m.plus.hidden = mode !== 'plus';
    m.label.hidden = mode !== 'drop';
    if (mode === 'drop') m.label.textContent = labelText || `ここに置く（${formatCoord(key)}）`;
    m.key = key;
    m.mode = mode;
  }
  // ポインターのマスが埋まっていれば、置くときと同じ近い空いたマス
  function overviewDropKey(clientX, clientY) {
    return nearestEmptyKey(currentLayer(), keyAt(clientX, clientY), { avoidCenter: path.length > 0 });
  }

  // 全体表示で、空いたマスに一行だけ書く（空のマスは DOM に無いので、入力欄は1つだけ浮かべる）
  let ovWriteKey = null;
  let ovLinkDraft = null; // 空いたマスで線を離したあと、Enter でメモと線を一緒に置く { source, kind, label, reverse, key }
  function placeOvWrite(key) {
    const box = $('ovWrite');
    if (!box) return;
    const { q, r } = H.parseKey(key);
    const p = H.hexToPixel(q, r, HEX_SIZE);
    const z = camera.zoom;
    const w = Math.max(220, Math.min(320, view.w - 16));
    const cx = view.w / 2 + (p.x - camera.x) * z;
    const cy = view.h / 2 + (p.y - camera.y) * z;
    box.style.width = `${w}px`;
    box.style.left = `${Math.max(8, Math.min(view.w - w - 8, cx - w / 2))}px`;
    box.style.top = `${Math.max(8, Math.min(view.h - 64, cy + HEX_H * z * 0.42))}px`;
  }
  function openOvWrite(key, opts) {
    const forLink = !!(opts && opts.forLink);
    if (!key) return;
    if (forLink) {
      if (boardReadOnly || settings.overviewViewOnly === true) return;
    } else if (!overviewWrites()) return;
    const rec = getRecord(key);
    if ((rec && !isEmptyRecord(rec)) || isCenter(key)) return;
    ovWriteKey = key;
    hideOvMark();
    const box = $('ovWrite');
    const input = $('ovWriteInput');
    if (!box || !input) {
      ovWriteKey = null;
      return;
    }
    box.hidden = false;
    placeOvWrite(key);
    input.value = '';
    input.placeholder = forLink ? '一行で書く（線も引く）' : '一行で書く';
    requestAnimationFrame(() => input.focus());
  }
  function closeOvWrite(opts) {
    const box = $('ovWrite');
    const input = $('ovWriteInput');
    const key = ovWriteKey;
    const draft = ovLinkDraft;
    const commit = !!(opts && opts.commit);
    ovWriteKey = null;
    ovLinkDraft = null;
    if (box) box.hidden = true;
    if (input) input.placeholder = '一行で書く';
    // 拡大や「見るだけ」へ切り替えた途中でも、書きかけは置く（overviewWrites は見ない）
    if (!commit || !key || !input || boardReadOnly) return;
    const text = input.value.trim().slice(0, TEXT_LIMIT);
    if (!text) return;
    const cur = getRecord(key);
    if ((cur && !isEmptyRecord(cur)) || isCenter(key)) return;
    undoCheckpointBeforeDelete();
    const rec = ensureRecord(key);
    rec.text = text;
    rec.updatedAt = nowIso();
    noteEdit(key, rec);
    if (draft && draft.key === key && draft.source) {
      const a = ensureId(draft.source);
      const b = ensureId(rec);
      const extra = { kind: draft.kind || null, label: draft.label || '' };
      const from = draft.reverse ? b : a;
      const to = draft.reverse ? a : b;
      if (!isLinked(from, to)) addLink(from, to, extra);
    }
    scheduleSave();
    undoCheckpoint();
    updateTabCounts();
    if (draft) renderLinks();
    refreshCell(key); // ふつうの倍率では空のマスが既にあるので、本文をその場で出す
    invalidateLayout(); // 全体表示は空のマスを描かないので、置いたメモを出すために並べ直す
    requestAnimationFrame(() => flashCell(key));
    if (draft) toast(showLinkLines ? 'メモと関連線を置きました' : 'メモと関連線を置きました（線は隠しています。Ctrl+Shift+L で表示）');
  }

  // 全体表示で、メモのあるマスの本文を直す（倍率に関係なく読める大きさ。空のマスは DOM に無いので、欄は1つ）
  const OV_EDIT_CLICK_MS = 500; // 1回のクリックの拡大は、ダブルクリックと分かるまで待つ
  let ovEditKey = null;
  let ovZoomTimer = 0;
  function cancelOvZoom() {
    clearTimeout(ovZoomTimer);
    ovZoomTimer = 0;
  }
  function scheduleOvZoom(clientX, clientY, target) {
    cancelOvZoom();
    // 待っている間に倍率が変わっても、押したときの「メモのクリック」で決める
    const mode = overviewClickMode();
    const cell = mode !== 'zoom' && target ? overviewMemoCell(target) : null;
    const key = cell ? cell._key : null;
    ovZoomTimer = setTimeout(() => {
      ovZoomTimer = 0;
      if (!isOverview || ovEditKey || ovWriteKey) return;
      const node = key && activeCells.get(key);
      if (node && mode === 'pin') pinPeek(node);
      else if (node && mode === 'edit') editFromOverview(key);
      else zoomInAt(clientX, clientY);
    }, OV_EDIT_CLICK_MS);
  }
  function placeOvEdit(key) {
    const box = $('ovEdit');
    if (!box) return;
    const { q, r } = H.parseKey(key);
    const p = H.hexToPixel(q, r, HEX_SIZE);
    const z = camera.zoom;
    const w = Math.max(280, Math.min(420, view.w - 16));
    const h = Math.min(320, Math.max(180, Math.round(view.h * 0.42)));
    const cx = view.w / 2 + (p.x - camera.x) * z;
    const cy = view.h / 2 + (p.y - camera.y) * z;
    let top = cy + HEX_H * z * 0.35;
    if (top + h > view.h - 8) top = cy - HEX_H * z * 0.35 - h;
    box.style.width = `${w}px`;
    box.style.height = `${h}px`;
    box.style.left = `${Math.max(8, Math.min(view.w - w - 8, cx - w / 2))}px`;
    box.style.top = `${Math.max(8, Math.min(view.h - h - 8, top))}px`;
  }
  function openOvEdit(key) {
    if (!overviewWrites() || !key || isCenter(key)) return;
    const rec = getRecord(key);
    if (!rec || isEmptyRecord(rec)) return;
    if (ovEditKey === key) {
      const again = $('ovEditInput');
      if (again) again.focus();
      return;
    }
    if (ovEditKey) closeOvEdit({ commit: true });
    if (ovWriteKey) closeOvWrite({ commit: true });
    cancelOvZoom();
    hideOvMark();
    ovEditKey = key;
    const box = $('ovEdit');
    const input = $('ovEditInput');
    if (!box || !input) {
      ovEditKey = null;
      return;
    }
    box.hidden = false;
    placeOvEdit(key);
    input.value = rec.text || '';
    selectCell(key);
    requestAnimationFrame(() => {
      input.focus();
      const end = input.value.length;
      input.setSelectionRange(end, end);
    });
  }
  function closeOvEdit(opts) {
    const box = $('ovEdit');
    const input = $('ovEditInput');
    const key = ovEditKey;
    const commit = !!(opts && opts.commit);
    ovEditKey = null;
    if (box) box.hidden = true;
    if (!commit || !key || !input || boardReadOnly) return;
    const rec = getRecord(key);
    if (!rec || isEmptyRecord(rec)) return;
    const result = overviewEditResult(rec.text || '', input.value);
    if (result.kind !== 'save') return;
    undoCheckpointBeforeDelete();
    rec.text = result.text;
    rec.updatedAt = nowIso();
    noteEdit(key, rec);
    scheduleSave();
    undoCheckpoint();
    refreshCell(key);
  }
  function tryOverviewEditKey() {
    if (activeTab !== 'grid' || !selectedKey) return false;
    const rec = getRecord(selectedKey);
    const act = overviewFilledAction({
      overview: isOverview,
      viewOnly: settings.overviewViewOnly === true,
      filled: !!(rec && !isEmptyRecord(rec)),
      center: isCenter(selectedKey),
      readOnly: boardReadOnly,
      gesture: 'key',
    });
    if (act !== 'edit') return false;
    openOvEdit(selectedKey);
    return true;
  }
  {
    const ovEditInput = $('ovEditInput');
    const ovEditBox = $('ovEdit');
    if (ovEditInput && ovEditBox) {
      ovEditInput.addEventListener('keydown', (e) => {
        if (e.isComposing || e.keyCode === 229) return;
        if (e.key === 'Escape') {
          e.preventDefault();
          e.stopPropagation();
          closeOvEdit({ commit: false });
        } else if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
          e.preventDefault();
          e.stopPropagation();
          closeOvEdit({ commit: true });
        }
      });
      ovEditInput.addEventListener('blur', () => {
        if (ovEditKey) closeOvEdit({ commit: true });
      });
      ovEditBox.addEventListener('pointerdown', (e) => {
        e.stopPropagation();
        if (e.target !== ovEditInput) e.preventDefault();
      });
      ovEditBox.addEventListener('click', (e) => e.stopPropagation());
    }
  }
  document.addEventListener('pointerdown', (e) => {
    if (!ovEditKey) return;
    if (e.target.closest && e.target.closest('#ovEdit')) return;
    closeOvEdit({ commit: true });
  }, true);
  {
    const ovWriteInput = $('ovWriteInput');
    const ovWriteBox = $('ovWrite');
    if (ovWriteInput && ovWriteBox) {
      ovWriteInput.addEventListener('keydown', (e) => {
        if (e.isComposing || e.keyCode === 229) return;
        if (e.key !== 'Enter' && e.key !== 'Escape') return;
        e.preventDefault();
        e.stopPropagation();
        closeOvWrite({ commit: e.key === 'Enter' });
      });
      ovWriteInput.addEventListener('blur', () => {
        if (ovWriteKey) closeOvWrite({ commit: true });
      });
      ovWriteBox.addEventListener('pointerdown', (e) => {
        e.stopPropagation();
        if (e.target !== ovWriteInput) e.preventDefault(); // ヒントを押しても、入力を終わらせない
      });
      ovWriteBox.addEventListener('click', (e) => e.stopPropagation());
    }
  }

  // 空のマスを背景の模様として描く（1枚＝横1マス × 縦2段で繰り返す）
  function buildGridPattern() {
    const W = H.SQRT3 * HEX_SIZE;
    const T = 3 * HEX_SIZE;
    const r = HEX_SIZE - HEX_GAP / H.SQRT3; // マスの隙間ぶん小さく
    const hex = (cx, cy) => [0, 1, 2, 3, 4, 5].map((i) => {
      const a = (Math.PI / 180) * (60 * i - 90);
      return `${(cx + r * Math.cos(a)).toFixed(2)},${(cy + r * Math.sin(a)).toFixed(2)}`;
    }).join(' ');
    const polys = [[0, 0], [W, 0], [0, T], [W, T], [W / 2, T / 2]]
      .map(([x, y]) => `<polygon points="${hex(x, y)}" vector-effect="non-scaling-stroke"/>`).join('');
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W.toFixed(2)} ${T}" preserveAspectRatio="none">`
      + `<g fill="#0f141b" stroke="#1d2530" stroke-width="1">${polys}</g></svg>`;
    gridBg.style.backgroundImage = `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
  }

  function updateGridBackground(z) {
    const W = H.SQRT3 * HEX_SIZE * z;
    const T = 3 * HEX_SIZE * z;
    const mod = (a, n) => ((a % n) + n) % n;
    gridBg.style.backgroundSize = `${W}px ${T}px`;
    gridBg.style.backgroundPosition = `${mod(view.w / 2 - camera.x * z, W)}px ${mod(view.h / 2 - camera.y * z, T)}px`;
  }

  // 全体表示の文字は、縮小しても読める大きさ（画面上で約 10px）にする
  function applyZoomStyles(z) {
    lastZoom = z;
    stage.style.setProperty('--inv-z', (1 / z).toFixed(4)); // 領域の名前・関連線のラベルを、縮小しても読める大きさに
    const font = Math.min(44, Math.max(14, 10 / z));
    stage.style.setProperty('--ov-font', `${font.toFixed(1)}px`);
    stage.style.setProperty('--ov-lines', String(overviewLines(Math.max(1, Math.floor(150 / (font * 1.25))), textLines.honey))); // 選んだ文字量より多くは出さない
    stage.style.setProperty('--ov-bw', `${Math.min(10, 1.5 / z).toFixed(2)}px`);
    stage.classList.toggle('is-tiny', z < TINY_BELOW);
    // 引くほど空のマスの模様を薄くして、メモのあるマスを目立たせる
    gridBg.style.opacity = String(Math.min(1, Math.max(0.3, (z - 0.04) / 0.3)).toFixed(2));
    updateZoomUi();
  }

  // 画面上の点 (clientX, clientY) を動かさずに倍率を変える（Ctrl+ホイール・ピンチ）
  function zoomAt(clientX, clientY, factor) {
    if (lockedZoom('grid') != null) {
      notifyZoomLocked('grid'); // ピンチで一緒に動かす分（panBy）はそのまま効く
      return;
    }
    const z0 = camera.zoom;
    const z1 = clampZoom(z0 * factor);
    if (z1 === z0) return;
    stopCameraAnimation();
    const r = stage.getBoundingClientRect();
    const sx = clientX - r.left - view.w / 2;
    const sy = clientY - r.top - view.h / 2;
    const wx = camera.x + sx / z0;
    const wy = camera.y + sy / z0;
    camera.zoom = z1;
    camera.x = wx - sx / z1;
    camera.y = wy - sy / z1;
    requestRender();
    scheduleSave('camera');
  }

  // ボタン・キー操作：画面の中央を基準に、なめらかに拡大縮小。グラフのタブではグラフの倍率を（ハニカムに切り替えない）
  function zoomBy(factor) {
    if (activeTab === 'graph') {
      gZoomBy(factor);
      return;
    }
    if (activeTab !== 'grid') setTab('grid');
    if (lockedZoom('grid') != null) {
      notifyZoomLocked('grid');
      return;
    }
    animateCameraTo(camera.x, camera.y, null, clampZoom(camera.zoom * factor));
  }

  function zoomReset() {
    if (activeTab === 'graph') {
      gZoomTo(1);
      return;
    }
    if (activeTab !== 'grid') setTab('grid');
    if (lockedZoom('grid') != null && Math.round(lockedZoom('grid') * 100) !== 100) {
      notifyZoomLocked('grid');
      return;
    }
    animateCameraTo(camera.x, camera.y, null, 1);
  }

  // この階層のメモがすべて画面に入るように縮小する（100% より大きくはしない）。
  // グラフのタブではグラフの「全体」と同じ。倍率を固定中は、真ん中に寄せるだけ
  function fitAll() {
    if (activeTab === 'graph') {
      gFit(graph.layout === 'flow');
      return;
    }
    if (activeTab !== 'grid') setTab('grid');
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    const add = (key) => {
      const { q, r } = H.parseKey(key);
      const p = H.hexToPixel(q, r, HEX_SIZE);
      minX = Math.min(minX, p.x);
      maxX = Math.max(maxX, p.x);
      minY = Math.min(minY, p.y);
      maxY = Math.max(maxY, p.y);
    };
    for (const [key, rec] of memos) if (!isEmptyRecord(rec)) add(key);
    if (path.length) add(CENTER_KEY);
    if (minX === Infinity) {
      animateCameraTo(0, 0, null, 1);
      toast('この階層にはまだメモがありません');
      return;
    }
    const w = maxX - minX + HEX_W * 1.3;
    const h = maxY - minY + HEX_H * 1.3;
    const z = clampZoom(Math.min(view.w / w, view.h / h, 1));
    animateCameraTo((minX + maxX) / 2, (minY + maxY) / 2, null, z);
  }

  // 表示範囲のマスだけ DOM に置き、範囲外になった要素は使い回す。
  // 全体表示（overviewRect あり）では、メモのあるマスだけを置く
  function reconcile(bounds, overviewRect = null) {
    const needed = new Set();
    if (overviewRect) {
      const pad = HEX_SIZE;
      const inRect = (key) => {
        const { q, r } = H.parseKey(key);
        const p = H.hexToPixel(q, r, HEX_SIZE);
        return p.x >= overviewRect.left - pad && p.x <= overviewRect.right + pad && p.y >= overviewRect.top - pad && p.y <= overviewRect.bottom + pad;
      };
      for (const [key, rec] of memos) if (!isEmptyRecord(rec) && inRect(key)) needed.add(key);
      if (path.length && inRect(CENTER_KEY)) needed.add(CENTER_KEY);
      // ドラッグ中の落とし先は、空いたマスでも描く（縮小中でも、どこに置くか見えるように）
      if (drag && drag.target) needed.add(drag.target);
    } else {
      H.forEachInBounds(bounds, (q, r) => needed.add(H.keyOf(q, r)));
    }
    if (editingKey) needed.add(editingKey); // 編集中のマスは画面外でも外さない

    for (const [key, node] of activeCells) {
      if (needed.has(key)) continue;
      activeCells.delete(key);
      node.remove();
      freeCells.push(node);
    }

    const frag = document.createDocumentFragment();
    for (const key of needed) {
      if (activeCells.has(key)) continue;
      const node = freeCells.pop() || createCell();
      bindCell(node, key);
      activeCells.set(key, node);
      frag.appendChild(node);
    }
    cellLayer.appendChild(frag);
  }

  function invalidateLayout() {
    lastSignature = '';
    requestRender();
  }

  // ---- カメラ --------------------------------------------------------------

  function stopCameraAnimation() {
    if (!cameraAnim) return;
    cancelAnimationFrame(cameraAnim);
    cameraAnim = 0;
  }

  // dx, dy は画面上の移動量（px）。縮小中は同じ操作でより遠くまで動く
  function panBy(dx, dy) {
    if (!dx && !dy) return;
    stopCameraAnimation();
    camera.x += dx / camera.zoom;
    camera.y += dy / camera.zoom;
    requestRender();
    scheduleSave('camera');
  }

  // (x, y) を画面の中央へ。zoom を渡すと倍率も一緒に変える
  // 倍率を固定中（ハニカム）は、どこから呼ばれても倍率は固定した値のまま（位置だけ動かす）。ここが倍率の固定の関所
  function animateCameraTo(x, y, onDone, zoom = camera.zoom) {
    stopCameraAnimation();
    const lz = lockedZoom('grid');
    if (lz != null && Math.round(zoom * 100) !== Math.round(lz * 100) && Math.round(zoom * 100) !== Math.round(camera.zoom * 100)) notifyZoomLocked('grid');
    const z1 = clampZoom(lz ?? zoom);
    const finish = () => {
      cameraAnim = 0;
      camera.x = x;
      camera.y = y;
      camera.zoom = z1;
      render();
      scheduleSave('camera');
      if (onDone) onDone();
    };

    let sx = camera.x;
    let sy = camera.y;
    const z0 = camera.zoom;
    const dist = Math.hypot(x - sx, y - sy);
    if ((dist < 1 && Math.abs(z1 - z0) < 1e-4) || matchMedia('(prefers-reduced-motion: reduce)').matches) {
      finish();
      return;
    }
    // 遠すぎる移動は手前までワープしてから流す
    const maxTravel = (Math.max(view.w, view.h, 800) / Math.min(z0, z1)) * 1.5;
    if (dist > maxTravel) {
      const k = maxTravel / dist;
      sx = x - (x - sx) * k;
      sy = y - (y - sy) * k;
    }

    const duration = 480;
    const t0 = performance.now();
    const step = (t) => {
      const p = Math.min(1, (t - t0) / duration);
      if (p >= 1) {
        finish();
        return;
      }
      const e = p < 0.5 ? 4 * p * p * p : 1 - (-2 * p + 2) ** 3 / 2;
      camera.x = sx + (x - sx) * e;
      camera.y = sy + (y - sy) * e;
      camera.zoom = z0 * (z1 / z0) ** e; // 倍率は比で補間すると自然に見える
      render();
      cameraAnim = requestAnimationFrame(step);
    };
    cameraAnim = requestAnimationFrame(step);
  }

  function goToOrigin() {
    if (activeTab !== 'grid') setTab('grid');
    animateCameraTo(0, 0);
  }

  function flashCell(key) {
    clearTimeout(flashTimer);
    const prev = flashKey;
    flashKey = key;
    if (prev && prev !== key) refreshCell(prev);
    const node = activeCells.get(key);
    if (node) {
      node.classList.remove('is-flash');
      void node.offsetWidth; // アニメーションを最初から再生させる
      node.classList.add('is-flash');
    }
    flashTimer = setTimeout(() => {
      flashKey = null;
      refreshCell(key);
    }, FLASH_MS);
  }

  // keys：そのメモがある階層までの道筋（ノート直下なら空）
  function jumpTo(key, keys = []) {
    const pos = H.parseKey(key);
    if (!pos) return;
    if (hive.open) closeHive(); // ノートのハニカムの下にあるハニカムへ
    setTab('grid');
    if (!setPath(keys)) return;
    const p = H.hexToPixel(pos.q, pos.r, HEX_SIZE);
    // 全体表示のままだと読めないので、100% に戻してから光らせる
    animateCameraTo(p.x, p.y, () => {
      flashCell(key);
      recordVisit(key);
    }, camera.zoom < OVERVIEW_BELOW ? 1 : camera.zoom);
  }

  // ---- 階層（メモを中心に開いたハニカム） ---------------------------------------

  const crumbsEl = $('crumbs');

  // このメモを中心 (0,0) にした下の階層へ入る。周りのマスに書いたメモは、このメモの children に入る
  function enterLayer(key) {
    if (isCenter(key) || path.length >= MAX_DEPTH) return;
    endEdit(); // 先に編集を閉じる（空のマスが消えても、この後で作り直す）
    recordVisit(key);
    const rec = ensureRecord(key);
    if (!rec.children) rec.children = newLayer();
    setPath([...path.map((p) => p.step), key], 'in');
  }

  // 今開いているメモ（中心）の周りに、新しい層を重ねて入る
  function addLayer() {
    const top = path[path.length - 1];
    if (!top) return;
    const n = recLayers(top.rec).length;
    if (n >= MAX_LAYERS) {
      toast(`1つのメモに重ねられる層は ${MAX_LAYERS} 層までです`, 'warn');
      return;
    }
    endEdit();
    if (!top.rec.children) top.rec.children = newLayer();
    top.rec.moreLayers = [...(top.rec.moreLayers || []), newLayer()];
    const li = recLayers(top.rec).length - 1;
    setPath([...path.slice(0, -1).map((p) => p.step), stepOf(top.key, li)], 'in');
    toast(`「${recordLabel(top.rec, top.key)}」の周りに第${li + 1}層を重ねました（左上の層の切り替えで行き来できます）`, 'info', 4000);
  }

  // 今開いているメモの別の層へ
  function switchLayer(li) {
    const top = path[path.length - 1];
    if (!top || li === top.li || !layerOf(top.rec, li)) return;
    setPath([...path.slice(0, -1).map((p) => p.step), stepOf(top.key, li)], li > top.li ? 'in' : 'out');
  }

  // depth 段目の階層へ戻る（0 = ノート直下）。戻った先で、いま出てきたマスを光らせる
  function goToDepth(depth) {
    if (depth < 0 || depth >= path.length) return;
    const from = path[depth].key;
    setPath(path.slice(0, depth).map((p) => p.step), 'out');
    flashCell(from);
  }

  function setPath(keys, direction = null) {
    endEdit();
    let common = 0;
    while (common < path.length && common < keys.length && path[common].step === keys[common]) common++;
    // 行き先を先に確かめる（途中のメモ・層が無ければ移動しない）
    const next = path.slice(0, common);
    let layer = common ? next[common - 1].layer : rootLayer;
    for (let i = common; i < keys.length; i++) {
      const { key, li } = parseStep(keys[i]);
      const rec = layer && layer.memos.get(key);
      const sub = rec && layerOf(rec, li);
      if (!sub) return false;
      next.push({ key, li, rec, layer: sub, step: keys[i] });
      layer = sub;
    }
    cleanupLeftLayers(common, new Set(next.map((p) => p.layer)));
    path = next;
    activateLayer(direction);
    return true;
  }

  // 抜ける階層が空なら片付ける（何も書かずに戻ったとき、空の children や空のメモを残さない）
  function cleanupLeftLayers(depth, keep = new Set()) {
    for (let i = path.length - 1; i >= depth; i--) {
      const { key, rec } = path[i];
      trimLayers(rec, keep);
      const parent = i === 0 ? rootLayer : path[i - 1].layer;
      if (parent && parent.memos.get(key) === rec && isEmptyRecord(rec)) parent.memos.delete(key);
    }
  }

  function activateLayer(direction) {
    hidePeek();
    if (reading) stopReading({ quiet: true });
    const layer = currentLayer();
    endDrag();
    selectedKey = null; // 選択は階層ごと（切り取りは階層をまたいで有効）
    resetMulti();
    memos = layer.memos;
    camera = layer.camera;
    enforceGridZoomLock(); // 倍率を固定中なら、この階層もその倍率で
    stopCameraAnimation();
    clearTimeout(flashTimer);
    flashKey = null;
    anchor.x = Math.round(camera.x);
    anchor.y = Math.round(camera.y);
    for (const node of activeCells.values()) {
      placeCell(node);
      updateCellContent(node);
    }
    lastSignature = '';
    if (activeTab === 'grid') {
      measureView();
      render();
    }
    renderLinks();
    renderCrumbs();
    if (side && side.series) renderSide(); // 全文の文章が、表示中の階層にあるかどうかが変わる
    if (direction) {
      stage.classList.remove('layer-in', 'layer-out');
      void stage.offsetWidth;
      stage.classList.add(direction === 'in' ? 'layer-in' : 'layer-out');
    }
  }

  stage.addEventListener('animationend', (e) => {
    if (e.target === stage) stage.classList.remove('layer-in', 'layer-out');
  });

  function recordLabel(rec, key, max = 14) {
    const line = (rec.text.split('\n').find((l) => l.trim()) || '').trim();
    if (!line) return `（${formatCoord(key)}）`;
    const chars = [...line];
    return chars.length > max ? `${chars.slice(0, max).join('')}…` : line;
  }

  function renderCrumbs() {
    renderCombo(); // 階層・表示が変わったら、組み合わせた画像も合わせる
    crumbsEl.hidden = !path.length || activeTab !== 'grid';
    if (!path.length) {
      crumbsEl.replaceChildren();
      return;
    }
    const up = el('button', 'crumb-up');
    up.type = 'button';
    up.dataset.depth = String(path.length - 1);
    up.title = '上の階層へ（Alt+↑）';
    up.setAttribute('aria-label', '上の階層へ');
    up.append(svgIcon('up'));

    const items = [{ label: currentBoard() ? currentBoard().name : 'ノート' },
      // 途中の段が重ねた層なら層の名前を添える（今いる層はタブで示すので、最後の段には付けない＝層を切り替えてもタブの位置が動かない）
      ...path.map((p, i) => ({ label: p.li > 0 && i < path.length - 1 ? `${recordLabel(p.rec, p.key)}（${layerName(p.rec, p.li)}）` : recordLabel(p.rec, p.key) }))];
    const list = el('ol', 'crumb-list');
    items.forEach((item, depth) => {
      const li = el('li');
      if (depth === items.length - 1) {
        const cur = el('span', 'crumb is-current', item.label);
        cur.setAttribute('aria-current', 'location');
        li.append(cur);
      } else {
        const b = el('button', 'crumb', item.label);
        b.type = 'button';
        b.dataset.depth = String(depth);
        li.append(b);
      }
      list.append(li);
    });
    crumbsEl.replaceChildren(up, list, buildLayerTabs());
  }

  // 今開いているメモの層（第1層・第2層…）の切り替え。＋で新しい層を重ねる
  function buildLayerTabs() {
    const top = path[path.length - 1];
    const box = el('div', 'layer-tabs');
    box.setAttribute('role', 'tablist');
    box.setAttribute('aria-label', 'このメモの周りの層');
    recLayers(top.rec).forEach((layer, li) => {
      const b = el('button', 'layer-tab', layerName(top.rec, li));
      b.type = 'button';
      b.dataset.layer = String(li);
      b.setAttribute('role', 'tab');
      b.setAttribute('aria-selected', String(li === top.li));
      const n = layerMemoCount(layer);
      if (layer.combo) b.prepend(svgIcon('image')); // 画像と組み合わせた層
      if (n) b.append(el('span', 'layer-tab-n', String(n)));
      b.title = `${layerName(top.rec, li)}（メモ ${n} 件${layer.combo ? '・画像と組み合わせ' : ''}）｜ダブルクリックで名前を変更・右クリックでメニュー`;
      box.append(b);
    });
    if (recLayers(top.rec).length < MAX_LAYERS) {
      const add = el('button', 'layer-add');
      add.type = 'button';
      add.dataset.cmd = 'add-layer';
      add.title = 'この周りに新しい層を重ねる（中心のマスの六角形ボタンでも）';
      add.setAttribute('aria-label', '新しい層を重ねる');
      add.append(svgIcon('plus'));
      box.append(add);
    }
    return box;
  }

  crumbsEl.addEventListener('click', (e) => {
    if (e.target.closest('.layer-rename')) return;
    const b = e.target.closest('button[data-depth]');
    if (b) {
      goToDepth(Number(b.dataset.depth));
      return;
    }
    const tab = e.target.closest('button[data-layer]');
    if (tab) {
      switchLayer(Number(tab.dataset.layer));
      return;
    }
    if (e.target.closest('[data-cmd="add-layer"]')) addLayer();
  });
  crumbsEl.addEventListener('dblclick', (e) => {
    const tab = e.target.closest('button[data-layer]');
    if (tab) renameLayer(Number(tab.dataset.layer));
  });
  crumbsEl.addEventListener('contextmenu', (e) => {
    const tab = e.target.closest('button[data-layer]');
    if (!tab) return;
    e.preventDefault();
    layerMenuIndex = Number(tab.dataset.layer);
    const top = path[path.length - 1];
    layerMenu.querySelector('[data-cmd="delete"]').disabled = recLayers(top.rec).length < 2;
    showPopoverAt(layerMenu, { x: e.clientX, y: e.clientY });
  });

  // 層のメニュー（名前を変更・この層を削除）
  const layerMenu = $('layerMenu');
  let layerMenuIndex = 0;
  layerMenu.addEventListener('mousedown', (e) => e.preventDefault());
  layerMenu.addEventListener('click', (e) => {
    const btn = e.target.closest('button[data-cmd]');
    if (!btn || btn.disabled) return;
    layerMenu.hidePopover();
    if (btn.dataset.cmd === 'rename') renameLayer(layerMenuIndex);
    else if (btn.dataset.cmd === 'delete') deleteLayer(layerMenuIndex);
  });

  function renameLayer(li) {
    const top = path[path.length - 1];
    const layer = top && layerOf(top.rec, li);
    const tab = crumbsEl.querySelector(`button[data-layer="${li}"]`);
    if (!layer || !tab) return;
    const input = document.createElement('input');
    input.className = 'layer-rename';
    input.value = layer.name || '';
    input.placeholder = `第${li + 1}層`;
    input.maxLength = 20;
    input.spellcheck = false;
    input.setAttribute('aria-label', '層の名前');
    tab.replaceWith(input);
    input.focus();
    input.select();
    let done = false;
    const finish = (commit) => {
      if (done) return;
      done = true;
      if (commit) {
        const name = [...input.value.replace(/\s+/g, ' ').trim()].slice(0, 20).join('');
        if (name) layer.name = name;
        else delete layer.name;
        if (layerHasContent(layer)) scheduleSave();
      }
      renderCrumbs();
    };
    input.addEventListener('keydown', (e) => {
      e.stopPropagation();
      if (e.isComposing || e.keyCode === 229) return;
      if (e.key === 'Enter') {
        e.preventDefault();
        finish(true);
      } else if (e.key === 'Escape') {
        e.preventDefault();
        finish(false);
      }
    });
    input.addEventListener('blur', () => finish(true));
  }

  // 層を削除する（中のメモと、その周りのメモも）。後ろの層の番号は1つずつ繰り上がる
  async function deleteLayer(li) {
    const top = path[path.length - 1];
    const layers = recLayers(top.rec);
    const layer = layers[li];
    if (!layer || layers.length < 2) return;
    let count = 0;
    const ids = new Set();
    for (const r of layer.memos.values()) {
      if (isEmptyRecord(r)) continue;
      count += 1 + descendantCount(r);
      subtreeIds(r, ids);
    }
    const nLinks = countLinksFor(ids);
    const ok = await confirmAction({
      title: `「${layerName(top.rec, li)}」を削除しますか？`,
      message: `${count ? `この層のメモ ${count} 件（周りに書いたメモを含む）が削除されます。` : 'この層にはメモがありません。'}`
        + `${nLinks ? `関連付け ${nLinks} 件も解除されます。` : ''}${li < layers.length - 1 ? '後ろの層の番号は1つずつ繰り上がります。' : ''}${count ? 'メモはゴミ箱に移します（戻すと棚に入ります。Ctrl+Z でもすぐ元に戻せます）。' : ''}`,
      confirmLabel: '層を削除',
    });
    if (!ok) return;
    endEdit();
    const gone = `${recordLabel(top.rec, top.key, 12)} の${layerName(top.rec, li)}（削除した層）`;
    for (const r of layer.memos.values()) if (!isEmptyRecord(r)) trashRecord(r, { toShelf: true, where: gone });
    if (removeLinksFor(ids)) renderLinks();
    const rest = layers.filter((_, i) => i !== li);
    top.rec.children = rest[0];
    if (rest.length > 1) top.rec.moreLayers = rest.slice(1);
    else delete top.rec.moreLayers;
    // 今いる層の番号を付け直して、同じ層（削除した層にいたなら1つ前の層）を開き直す
    const cur = top.li === li ? Math.max(0, li - 1) : top.li > li ? top.li - 1 : top.li;
    const steps = [...path.slice(0, -1).map((p) => p.step), stepOf(top.key, cur)];
    path[path.length - 1] = { ...top, step: '' }; // 開き直させる
    setPath(steps, top.li === li ? 'out' : null);
    updateTabCounts();
    scheduleSave();
    toast('層を削除しました');
  }

  // ---- 編集 ----------------------------------------------------------------

  const editor = document.createElement('textarea');
  editor.className = 'editor';
  editor.placeholder = 'メモを書く…';
  editor.spellcheck = false;
  editor.setAttribute('aria-label', 'メモ本文');

  function startEdit(key) {
    if (editingKey === key) {
      editor.focus({ preventScroll: true });
      return;
    }
    if (editingKey) endEdit();
    const node = activeCells.get(key);
    if (!node) return;

    selectCell(key);
    editingKey = key;
    const rec = getRecord(key);
    recordVisit(key);
    editor.value = rec ? rec.text : '';
    node._refs.body.appendChild(editor);
    updateCellContent(node);
    editor.focus({ preventScroll: true });
    const end = editor.value.length;
    editor.setSelectionRange(end, end);
    editor.scrollTop = editor.scrollHeight;
    invalidateLayout();
  }

  function endEdit() {
    if (ovEditKey) closeOvEdit({ commit: true });
    const key = editingKey;
    if (!key) return;
    editingKey = null;
    editor.remove();
    if (newLinkedDraft) settleNewLinkedDraft(key);
    if (pruneIfEmpty(key)) {
      updateTabCounts();
      scheduleSave();
    }
    refreshCell(key);
    if (isCenter(key)) renderCrumbs(); // 親のメモの本文が変わった
    invalidateLayout();
  }

  editor.addEventListener('input', () => {
    const key = editingKey;
    if (!key) return;
    const rec = getRecord(key) || (editor.value ? ensureRecord(key) : null);
    if (!rec) return;
    rec.text = editor.value;
    rec.updatedAt = nowIso();
    noteEdit(key, rec);
    const node = activeCells.get(key);
    if (node) {
      node._refs.text.textContent = rec.text;
      node._refs.text._text = null; // 表示に戻したとき、リンクを付け直す
      node.classList.toggle('has-text', hasText(rec));
      node.classList.toggle('has-record', !isEmptyRecord(rec));
      updateCounter(node, rec.text);
    }
    scheduleSave();
  });

  // ---- 選択・コピー・切り取り・貼り付け --------------------------------------------

  function selectCell(key) {
    const prev = selectedKey;
    selectedKey = key;
    if (prev && prev !== key) refreshCell(prev);
    if (key) refreshCell(key);
    if (prev !== key && links.length) renderLinks(); // 選んだメモの関連を強調
    if (prev !== key) followSeries(key);
  }

  function clearSelection() {
    if (selectMode) setSelectMode(false);
    clearMulti();
    selectCell(null);
  }

  function refreshAllCells() {
    for (const node of activeCells.values()) updateCellContent(node);
  }

  // 保存形式と同じ形（children も含む）にする。クリップボードにもこの形で載せる
  function serializeRecord(rec) {
    const round = (n) => Math.round(n * 100) / 100;
    const out = {
      text: rec.text,
      createdAt: rec.createdAt,
      updatedAt: rec.updatedAt,
      likedLevel: rec.likedLevel,
      liked: rec.likedLevel > 0,
      bookmarked: rec.bookmarked,
      comments: rec.comments.map(serializeComment),
    };
    if (rec.id) out.id = rec.id;
    if (rec.tags && rec.tags.length) out.tags = [...rec.tags];
    if (rec.due) out.due = rec.due;
    if (rec.progress > 0) out.progress = rec.progress;
    if (rec.seq) out.seq = { ...rec.seq };
    if (rec.likedLevel > 0 && rec.likedAt) out.likedAt = rec.likedAt;
    if (rec.bookmarked && rec.bookmarkedAt) out.bookmarkedAt = rec.bookmarkedAt;
    if (rec.images && rec.images.length) {
      out.images = rec.images.map((img) => ({ ...img }));
      if (rec.cover) out.cover = rec.cover;
    }
    if (rec.urls && rec.urls.length) out.urls = rec.urls.map((u) => ({ ...u, ...(u.snapshot ? { snapshot: { ...u.snapshot } } : {}) }));
    if (hasChildren(rec)) {
      // 第1層は children、重ねた層は moreLayers。後ろの空の層は書かない（途中の空の層は番号を保つために書く）
      const layers = recLayers(rec);
      let last = layers.length - 1;
      while (last > 0 && !layerHasContent(layers[last])) last--;
      const layerOut = (layer) => {
        const memosOut = {};
        for (const [k, child] of layer.memos) if (!isEmptyRecord(child)) memosOut[k] = serializeRecord(child);
        return {
          camera: serializeCamera(layer.camera), memos: memosOut, ...(layer.name ? { name: layer.name } : {}), ...(layer.combo ? { combo: serializeCombo(layer.combo) } : {}),
          ...(layer.regions && layer.regions.length ? { regions: layer.regions.map(serializeRegion) } : {}),
          ...(layer.footprints && Object.keys(layer.footprints).length ? { footprints: { ...layer.footprints } } : {}),
          ...(layer.trails && Object.keys(layer.trails).length ? { trails: { ...layer.trails } } : {}),
        };
      };
      out.children = layerOut(layers[0]);
      if (last > 0) out.moreLayers = layers.slice(1, last + 1).map(layerOut);
    }
    return out;
  }

  const serializeComment = (c) => ({ id: c.id, text: c.text, createdAt: c.createdAt, ...(c.parentId ? { parentId: c.parentId } : {}) });
  const serializeRegion = (r) => ({ id: r.id, name: r.name, keys: [...r.keys], ...(r.color ? { color: r.color } : {}) });
  const serializeDendrite = (d) => ({ id: d.id, name: d.name, steps: [...d.steps], ...(d.color ? { color: d.color } : {}), ...(d.parentId ? { parentId: d.parentId, at: d.at || 0 } : {}) });

  // ノート直下だけが持つもの（棚・Dendritic Extension・日ごとの活動・ゴミ箱・グラフの並び・区画）を、読み込んだ保存形式から画面用の階層に付ける。
  // 渡した store とは配列を共有しない（2つのウィンドウを合わせた内容や元に戻すの記録をそのまま渡されても、
  // 棚のコメントを足したときに、覚えておいた「前の内容」まで一緒に書き換わらないように）
  function attachRootExtras(root, store) {
    root.shelf = Array.isArray(store && store.shelf) ? store.shelf.map((r) => {
      const rec = structuredClone(r);
      if (rec.children) rec.children = toLayer(rec.children);
      if (Array.isArray(rec.moreLayers)) rec.moreLayers = rec.moreLayers.map(toLayer);
      return rec;
    }) : [];
    root.dendrites = Array.isArray(store && store.dendrites) ? store.dendrites.map((d) => ({ ...d, steps: [...d.steps] })) : [];
    // ゴミ箱は保存形式のまま持つ（戻すときに画面用にする）。30 日たったものは捨てる
    const trashLimit = Date.now() - TRASH_DAYS * 86400000;
    root.trash = Array.isArray(store && store.trash) ? store.trash.filter((t) => t && t.rec && Date.parse(t.deletedAt) >= trashLimit) : [];
    root.graphLayouts = Array.isArray(store && store.graphLayouts) ? store.graphLayouts.map((g) => structuredClone(g)) : [];
    // 配置ヒント（AI が書いた、メモの大まかな置き場所）。保存された内容をそのまま持つ（読み直し・元に戻すのたびに作り直す）
    root.layoutHints = store && store.layoutHints ? structuredClone(store.layoutHints) : null;
    // 区画（写しの作業台）は保存形式のまま持つ（紙片は周りのメモを持たないので、画面用に変えるものが無い）
    root.pockets = Array.isArray(store && store.pockets) ? store.pockets.map((x) => structuredClone(x)) : [];
    root.activity = store && store.activity && typeof store.activity === 'object' ? Object.fromEntries(Object.entries(store.activity).map(([k, v]) => [k, { ...v }])) : {};
  }
  const serializeLink = ({ a, b, createdAt, kind, label }) => ({ a, b, createdAt, ...(kind ? { kind } : {}), ...(label ? { label } : {}) });

  function serializeCamera(c) {
    const round = (n) => Math.round(n * 100) / 100;
    const out = { x: round(c.x), y: round(c.y) };
    // 倍率は 0.01% 単位で残す（表示の「8%」などが起動し直しても変わらないように）
    if (c.zoom && Math.abs(c.zoom - 1) > 1e-4) out.zoom = Math.round(c.zoom * 10000) / 10000;
    return out;
  }

  // 切り取ったメモが今どこにあるか（ドラッグ等で動いていても、レコードそのもので探す）
  function locateRecord(target) {
    const walk = (layer) => {
      for (const [key, rec] of layer.memos) {
        if (rec === target) return { layer, key };
        for (const sub of recLayers(rec)) {
          const found = walk(sub);
          if (found) return found;
        }
      }
      return null;
    };
    return walk(rootLayer);
  }

  async function copyCell(key, { cut = false } = {}) {
    const rec = getRecord(key);
    if (!api || !rec || isEmptyRecord(rec)) return;
    if (cut && isCenter(key)) {
      toast('中心（親のメモ）は切り取れません。上の階層で操作してください', 'warn');
      return;
    }
    const nonce = uuid();
    try {
      await ipc(api.writeClip({ v: 1, nonce, cut, record: serializeRecord(rec) }));
    } catch (err) {
      toast(`コピーできませんでした：${err.message}`, 'error', 5000);
      return;
    }
    cutSource = cut ? { nonce, board: currentBoardId, rec } : null;
    refreshAllCells();
    toast(cut ? '切り取りました。移動先のマスを選んで Ctrl+V（右クリック →「貼り付け」）' : 'コピーしました');
  }

  function clearCut() {
    if (!cutSource) return;
    cutSource = null;
    refreshAllCells();
  }

  // クリップボードのマス（保存形式）から、画面用のレコードを作る。
  // 複製は別のメモなので ID を外す（関連付けは引き継がない）
  function recordFromClip(raw) {
    const stripIds = (r) => {
      delete r.id;
      delete r.seq; // 複製は文章の並びの一部ではない
      for (const layer of [r.children, ...(Array.isArray(r.moreLayers) ? r.moreLayers : [])]) {
        if (layer) for (const child of Object.values(layer.memos || {})) stripIds(child);
      }
    };
    stripIds(raw);
    const t = nowIso();
    const rec = { ...raw, createdAt: t, updatedAt: t, comments: raw.comments || [] };
    if (raw.children) rec.children = toLayer(raw.children);
    else delete rec.children;
    if (raw.children && Array.isArray(raw.moreLayers) && raw.moreLayers.length) rec.moreLayers = raw.moreLayers.map(toLayer);
    else delete rec.moreLayers;
    return rec;
  }

  async function pasteAt(key) {
    if (!api || !key) return;
    let clip;
    try {
      clip = await ipc(api.readClip());
    } catch (err) {
      toast(`貼り付けできませんでした：${err.message}`, 'error', 5000);
      return;
    }
    // 画像（スクリーンショット・コピーした画像ファイル）は、そのマスに添付する（中心なら親のメモに）
    if (clip.image) {
      const name = clip.image.name || '画像.png';
      const ext = ((/\.(\w+)$/.exec(name) || [])[1] || 'png').toLowerCase();
      const type = { jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp' }[ext] || 'image/png';
      attachImagesToKey(key, [new File([clip.image.data], name, { type })]);
      return;
    }
    if (!clip.cell && !clip.text) {
      toast('クリップボードが空です', 'warn');
      return;
    }
    // URL だけを貼り付けたら、上書きせずにリンクとして付ける（マスへのリンクは本文に入れる）
    if (!clip.cell) {
      const kind = U.classifyPasted(clip.text);
      if (kind === 'web') {
        addUrlToKey(key, clip.text.trim());
        return;
      }
      if (kind === 'memo') {
        addMemoLinkToKey(key, clip.text.trim());
        return;
      }
    }
    if (isCenter(key)) {
      toast('中心（親のメモ）には貼り付けられません', 'warn');
      return;
    }
    if (clip.missing) toast(`画像など ${clip.missing} 件を取り込めませんでした（コピー元のメモアプリのデータが見つかりません）`, 'warn', 5000);
    if (clip.cells && clip.cells.length > 1) {
      pasteMany(key, clip.cells, { offsets: clip.offsets || null, nonce: clip.cell ? clip.cell.nonce : '', cut: !!clip.cell && clip.cell.cut });
      return;
    }

    // 切り取ったメモ（このノートの中）なら移動する
    const sameCut = !!clip.cell && !!cutSource && clip.cell.nonce === cutSource.nonce;
    const moving = sameCut && cutSource.board === currentBoardId;
    const from = moving ? locateRecord(cutSource.rec) : null; // 見つからなければ（削除済み）コピーとして貼る
    if (moving && from && from.layer === currentLayer() && from.key === key) {
      clearCut(); // 元の場所に貼り付けた
      return;
    }
    if (moving && from && path.some((p) => p.rec === cutSource.rec)) {
      toast('メモを、そのメモ自身の周り（下の階層）には移動できません', 'warn', 4000);
      return;
    }

    const existing = memos.get(key);
    if (existing && !isEmptyRecord(existing)) {
      const inner = descendantCount(existing);
      const nLinks = countLinksFor(subtreeIds(existing));
      const ok = await confirmAction({
        title: 'このマスに上書きしますか？',
        message: `マス（${formatCoord(key)}）のメモ${inner ? `（周りのメモ ${inner} 件を含む）` : ''}は、貼り付ける内容に置き換わります。`
          + `${nLinks ? `関連付け ${nLinks} 件も解除されます。` : ''}置き換わるメモはゴミ箱に移します（Ctrl+Z でもすぐ元に戻せます）。`,
        confirmLabel: '上書きして貼り付け',
      });
      if (!ok) return;
    }
    if (editingKey === key) endEdit();
    if (existing && !(moving && from && existing === cutSource.rec)) {
      if (!isEmptyRecord(existing)) trashRecord(existing, { keys: curKeys(), key });
      removeLinksFor(subtreeIds(existing));
    }

    let rec;
    if (moving && from) {
      rec = cutSource.rec;
      from.layer.memos.delete(from.key);
      cutSource = null;
    } else if (clip.cell) {
      rec = recordFromClip(clip.cell.record);
      if (clip.cell.cut && !moving) {
        toast('切り取り元が別のノート（またはアプリ）のため、コピーとして貼り付けました。元のメモは残っています', 'info', 5000);
      }
      if (sameCut) cutSource = null;
    } else {
      rec = createRecord();
      rec.text = clip.text;
      if ([...clip.text].length > TEXT_LIMIT) {
        setTimeout(() => toast('長い文章は Ctrl+Shift+V（右クリック →「分けて貼り付け」）で、マスに分けて帯のように並べられます', 'info', 5000), 400);
      }
    }
    memos.set(key, rec);
    selectCell(key);
    refreshAllCells();
    renderLinks();
    updateTabCounts();
    scheduleSave();
    flashCell(key);
  }

  // 中心からその周（ring）のマスへの差 { dq, dr }。右上から時計回り
  function ringOffsets(ring) {
    const cells = [];
    for (let dq = -ring; dq <= ring; dq++) {
      for (let dr = Math.max(-ring, -dq - ring); dr <= Math.min(ring, -dq + ring); dr++) {
        if (H.hexDistance({ q: 0, r: 0 }, { q: dq, r: dr }) !== ring) continue;
        const p = H.hexToPixel(dq, dr, 1);
        cells.push({ dq, dr, angle: (Math.atan2(p.x, -p.y) + 2 * Math.PI) % (2 * Math.PI) });
      }
    }
    return cells.sort((a, b) => a.angle - b.angle);
  }

  // 複数のマスを貼り付ける。
  // ・並び（offsets）があれば、選んだマスを左上にして同じ形で置く。重なるときは、形を保てる近くの場所へずらす
  // ・並びが無い（まとめてコピーしたコメント）か、形を保てる場所が無ければ、選んだマスから近い順（周ごとに右上から時計回り）に
  //   空いているマスへ1件ずつ置く。メモのあるマスは上書きせずに飛ばす
  // ・このノートで切り取ったマスなら、同じメモ（ID・関連・通し番号もそのまま）を移動する
  function pasteMany(key, raws, { offsets = null, nonce = '', cut = false } = {}) {
    const sameCut = cut && !!cutSource && !!cutSource.recs && cutSource.nonce === nonce;
    const sources = sameCut && cutSource.board === currentBoardId ? cutSource.recs : [];
    const moving = sources.length === raws.length && sources.every((r) => locateRecord(r));
    if (moving && sources.some((r) => path.some((p) => p.rec === r))) {
      toast('メモを、そのメモ自身の周り（下の階層）には移動できません', 'warn', 4000);
      return;
    }
    const vacated = new Set(moving ? sources : []);
    const free = (k) => {
      if (isCenter(k) || k === editingKey) return false;
      const ex = memos.get(k);
      return !ex || isEmptyRecord(ex) || vacated.has(ex);
    };
    const start = H.parseKey(key);
    let targets = null;
    let shifted = false;
    if (offsets && offsets.length === raws.length) {
      for (let ring = 0; !targets && ring <= 12; ring++) {
        for (const { dq, dr } of ringOffsets(ring)) {
          const ks = offsets.map((o) => H.keyOf(start.q + dq + o.dq, start.r + dr + o.dr));
          if (ks.every(free)) {
            targets = ks;
            shifted = ring > 0;
            break;
          }
        }
      }
    }
    const scattered = !targets;
    if (!targets) {
      targets = [];
      for (let ring = 0; targets.length < raws.length && ring <= 40; ring++) {
        for (const { dq, dr } of ringOffsets(ring)) {
          const k = H.keyOf(start.q + dq, start.r + dr);
          if (!free(k)) continue;
          targets.push(k);
          if (targets.length >= raws.length) break;
        }
      }
    }
    if (!targets.length) return;
    if (moving && targets.length < sources.length) {
      toast('まとめて移動できるだけの空いているマスが近くにありません', 'warn', 4000); // 元のメモはそのまま
      return;
    }
    let placed;
    if (moving) {
      for (const r of sources) {
        const from = locateRecord(r);
        if (from) from.layer.memos.delete(from.key);
      }
      placed = sources.slice(0, targets.length);
      targets.forEach((k, i) => memos.set(k, placed[i]));
      cutSource = null;
    } else {
      placed = targets.map((k, i) => {
        const rec = recordFromClip(raws[i]);
        memos.set(k, rec);
        return rec;
      });
      if (sameCut) {
        cutSource = null;
        toast('切り取り元が別のノート（またはアプリ）のため、コピーとして貼り付けました。元のメモは残っています', 'info', 5000);
      }
    }
    selectCell(targets[0]);
    if (offsets) setMulti(placed); // 貼り付けたマスを選んだ状態に（そのまま移動・コピーし直せる）
    refreshAllCells();
    renderLinks();
    updateTabCounts();
    scheduleSave();
    flashCell(targets[0]);
    if (!offsets) {
      const skipped = targets[0] !== key;
      toast(`${targets.length} 件を、${skipped ? '選んだマスの周りの' : '選んだマスとその周りの'}空いているマスに貼り付けました${skipped ? '（選んだマスにはメモがあるため）' : ''}`, 'info', 4000);
      return;
    }
    const verb = moving ? '移動しました' : '貼り付けました';
    toast(scattered ? `${targets.length} 件を、選んだマスの周りの空いているマスに${verb}（同じ並びで置ける場所が無かったため）`
      : `${targets.length} 件を、並びを保って${verb}${shifted ? '（メモと重ならない近くの場所へずらしました）' : ''}`, 'info', 4000);
  }

  // ---- 長文を分けて並べる（帯）と読書モード ----------------------------------------------
  // 貼り付けた長文を段落・文の区切りでマスの大きさに分け、選んだマスから左から右へ帯のように並べる。
  // 行の端では2行分の空白をあけて次の行へ（分け方・並べ方は ribbon.js）。
  // 分けたマスには通し番号 rec.seq = { id, n, head? } を付け、読書モードはこの順に進む

  const RB = window.HexRibbon;
  const SEQ_MAX = 2000; // 1回に並べるマスの上限
  const READ_POS_PREF = 'hexMemo.readPos';
  let reading = null; // { id, rec, key }

  // 表示中の（または指定した）階層にある、その文章のマス（番号順）
  function seriesCells(id, layerMemos = memos) {
    return [...layerMemos].filter(([, r]) => r.seq && r.seq.id === id && !isEmptyRecord(r)).sort((a, b) => a[1].seq.n - b[1].seq.n);
  }

  function seriesIndexOf(id, n) {
    const list = seriesCells(id);
    const i = list.findIndex(([, r]) => r.seq.n >= n);
    return (i < 0 ? list.length - 1 : i) + 1;
  }

  // 画面の幅に1行が収まるマスの数（100% 表示で）
  function ribbonPerLine(width = view.w) {
    const w = Math.max(width, 320);
    return Math.max(3, Math.min(10, Math.floor((w - 60) / (H.SQRT3 * HEX_SIZE))));
  }

  const cellFree = (k) => {
    if (isCenter(k) || k === editingKey) return false;
    const r = memos.get(k);
    return !r || isEmptyRecord(r);
  };

  async function splitPasteAt(key) {
    if (!api || !key) return;
    if (isCenter(key)) {
      toast('中心（親のメモ）には並べられません。周りのマスを選んでください', 'warn');
      return;
    }
    let clip;
    try {
      clip = await ipc(api.readClip());
    } catch (err) {
      toast(`貼り付けできませんでした：${err.message}`, 'error', 5000);
      return;
    }
    const text = clip.text || (clip.cells ? clip.cells.map((r) => r.text).join('\n\n') : clip.cell ? clip.cell.record.text : '');
    if (!text || !text.trim()) {
      toast('クリップボードに文章がありません', 'warn');
      return;
    }
    const chunks = RB.splitText(text).slice(0, SEQ_MAX);
    if (chunks.length < 2) {
      toast('分けるほど長くないので、ふつうに貼り付けました');
      pasteAt(key);
      return;
    }
    endEdit();
    const perLine = ribbonPerLine(stageWidthWithSide()); // 全文を左のサイドバーに出すので、その分を除いた幅で
    const pos = RB.layout(chunks, perLine);
    const start = H.parseKey(key);
    const keysAt = (q0, r0) => pos.map((p) => {
      const a = RB.toAxial(p, q0, r0);
      return H.keyOf(a.q, a.r);
    });
    let q0 = start.q;
    let r0 = start.r;
    let keys = keysAt(q0, r0);
    let moved = false;
    if (!keys.every(cellFree)) {
      // メモと重なるときは、並べ始める横の位置はそのままに、メモの下の空いたところへずらす（上書きしない）
      let maxR = path.length ? 0 : -Infinity;
      for (const [k, r] of memos) if (!isEmptyRecord(r)) maxR = Math.max(maxR, H.parseKey(k).r);
      const x0 = start.q + start.r / 2;
      r0 = Math.max(start.r, maxR + RB.LINE_STEP);
      for (let tries = 0; tries < 60; tries++, r0 += RB.LINE_STEP) {
        q0 = Math.round(x0 - r0 / 2);
        keys = keysAt(q0, r0);
        if (keys.every(cellFree)) break;
      }
      if (!keys.every(cellFree)) {
        toast('並べる場所が見つかりませんでした', 'error');
        return;
      }
      moved = true;
    }
    const id = uuid().replace(/-/g, '').slice(0, 10);
    chunks.forEach((ch, i) => {
      const rec = createRecord();
      rec.text = ch.text;
      rec.seq = { id, n: i + 1, ...(ch.head ? { head: true } : {}), ...(ch.para ? { para: true } : {}) };
      memos.set(keys[i], rec);
    });
    selectCell(keys[0]);
    openSeriesSide(id); // 全文を左に出し、選んでいるマスの部分を強調する
    refreshAllCells();
    updateTabCounts();
    scheduleSave();
    // 最初の行が見えるように
    const first = keys.filter((k, i) => pos[i].dr === 0).map((k) => { const a = H.parseKey(k); return H.hexToPixel(a.q, a.r, HEX_SIZE); });
    const cx = (Math.min(...first.map((p) => p.x)) + Math.max(...first.map((p) => p.x))) / 2;
    animateCameraTo(cx, first[0].y, () => flashCell(keys[0]), camera.zoom < OVERVIEW_BELOW ? 1 : camera.zoom);
    toast(`${chunks.length} マスに分けて、1行 ${perLine} マスで並べました${moved ? '（メモと重ならない場所へずらしました）' : ''}。全文は左のサイドバーに（右クリック →「ここから読む」で読書モード）`, 'info', 6000);
  }

  // この文章（分けて並べたマス）をまとめて削除
  async function deleteSeries(key) {
    const rec = getRecord(key);
    if (!rec || !rec.seq) return;
    const list = seriesCells(rec.seq.id);
    const ids = new Set();
    let inner = 0;
    for (const [, r] of list) {
      subtreeIds(r, ids);
      inner += descendantCount(r);
    }
    const nLinks = countLinksFor(ids);
    const ok = await confirmAction({
      title: 'この文章をまとめて削除しますか？',
      message: `分けて並べた ${list.length} マスを削除します。${inner ? `周りに書いたメモ ${inner} 件も一緒に削除されます。` : ''}`
        + `${nLinks ? `関連付け ${nLinks} 件も解除されます。` : ''}ゴミ箱に移します（30 日間は戻せます。削除した直後なら、画面下の札の［元に戻す］か Ctrl+Z ですぐ戻せます）。`,
      confirmLabel: `${list.length} マスを削除`,
    });
    if (!ok) return;
    if (reading && reading.id === rec.seq.id) stopReading({ quiet: true });
    endEdit();
    undoCheckpointBeforeDelete();
    for (const [k, r] of list) {
      trashRecord(r, { keys: curKeys(), key: k });
      memos.delete(k);
    }
    if (removeLinksFor(ids)) renderLinks();
    clearSelection();
    refreshAllCells();
    updateTabCounts();
    scheduleSave();
    toastDeleted(list.length, list.length === 1 ? list[0][0] : null);
  }

  // ---- 読書モード ----

  function readPositions() {
    try {
      const v = JSON.parse(localStorage.getItem(READ_POS_PREF) || '{}');
      return v && typeof v === 'object' ? v : {};
    } catch {
      return {};
    }
  }
  const readPosOf = (id) => Number(readPositions()[`${currentBoardId}:${id}`]) || 0;
  function saveReadPos(id, n) {
    try {
      const all = readPositions();
      delete all[`${currentBoardId}:${id}`];
      all[`${currentBoardId}:${id}`] = n;
      const keys = Object.keys(all);
      for (const k of keys.slice(0, Math.max(0, keys.length - 300))) delete all[k]; // 古いものから捨てる
      localStorage.setItem(READ_POS_PREF, JSON.stringify(all));
    } catch {
      // しおりを残せなくても読める
    }
  }

  function startReading(key, { resume = false } = {}) {
    const rec = getRecord(key);
    if (!rec || !rec.seq) return;
    endEdit();
    if (linking) cancelLinking();
    reading = { id: rec.seq.id, rec: null, key: null };
    showReadingUi();
    goReading(resume && readPosOf(rec.seq.id) ? readPosOf(rec.seq.id) : rec.seq.n, { first: true });
  }

  // 選んだマス（複数選択）を、選んだ順に読む。startKey を指定するとそのマスから
  function startReadingSelection(startKey = null) {
    const list = multiEntries();
    if (!list.length) return;
    const i = startKey ? list.findIndex(([k]) => k === startKey) : 0;
    startReadingRecs(list.map(([, r]) => r), Math.max(0, i));
  }

  // レコードの列を、その順に読む（複数選択・Dendritic Extension）
  function startReadingRecs(recs, startIndex = 0) {
    if (!recs.length) return;
    endEdit();
    if (linking) cancelLinking();
    reading = { id: null, recs, set: new Set(recs), rec: null, key: null };
    showReadingUi();
    const list = readingList();
    const i = list.findIndex(([, r]) => r === recs[startIndex]);
    goReadingAt(Math.max(0, i), { first: true });
  }

  function showReadingUi() {
    stage.classList.add('is-reading');
    document.body.classList.add('is-reading'); // 案内（トースト）を下の操作バーの上に出す
    $('readBar').hidden = false;
    updateMultiBar();
  }

  // 読む順のマス [[key, rec]]：分けて並べた文章は番号順、選んだマスを読むときは選んだ順
  function readingList() {
    if (!reading) return [];
    if (!reading.recs) return seriesCells(reading.id);
    const where = new Map();
    for (const [k, r] of memos) where.set(r, k);
    return reading.recs.map((r) => [where.get(r), r]).filter(([k, r]) => k && !isEmptyRecord(r));
  }

  function stopReading({ quiet = false } = {}) {
    if (!reading) return;
    const last = reading.key;
    reading = null;
    stage.classList.remove('is-reading');
    document.body.classList.remove('is-reading');
    $('readBar').hidden = true;
    updateMultiBar();
    if (quiet) return;
    if (last && memos.has(last) && !selectMode) selectCell(last); // 選択モードでは青い枠を付けない（選んだ印とまぎれる）
    refreshAllCells();
  }

  function cellOnScreen(key) {
    const { q, r } = H.parseKey(key);
    const p = H.hexToPixel(q, r, HEX_SIZE);
    const z = camera.zoom;
    const sx = (p.x - camera.x) * z + view.w / 2;
    const sy = (p.y - camera.y) * z + view.h / 2;
    const mx = (HEX_W / 2) * z;
    const my = (HEX_H / 2) * z;
    return sx - mx >= 0 && sx + mx <= view.w && sy - my >= 0 && sy + my <= view.h - 70; // 下の操作バーの分をあける
  }

  // 分けて並べた文章の n 番目（そのマスが無ければ次のマス）へ
  function goReading(n, opts) {
    if (!reading) return;
    const list = readingList();
    let i = list.findIndex(([, r]) => r.seq && r.seq.n >= n);
    if (i < 0) i = list.length - 1;
    goReadingAt(i, opts);
  }

  // 読む順の i 番目へ
  function goReadingAt(i, { first = false } = {}) {
    if (!reading) return;
    const list = readingList();
    if (!list.length) {
      stopReading({ quiet: true });
      toast(reading && reading.recs ? '読めるマスがありません' : '読める文章がありません', 'warn');
      return;
    }
    i = Math.max(0, Math.min(i, list.length - 1));
    const [key, rec] = list[i];
    const prevRow = reading.key ? H.parseKey(reading.key).r : null;
    reading.key = key;
    reading.rec = rec;
    recordVisit(key);
    if (!reading.recs) saveReadPos(reading.id, rec.seq.n);
    followSeries(key);
    updateReadActions();
    // 行が変わったとき（と最初）は、その行が見えるように画面を送る。行の中では印だけが進む。
    // 選んだマスを読むときは、そのマスを真ん中へ
    const { q, r } = H.parseKey(key);
    if (first || prevRow !== r || !cellOnScreen(key)) {
      const p = H.hexToPixel(q, r, HEX_SIZE);
      let cx = p.x;
      if (!reading.recs) {
        const row = list.filter(([k]) => H.parseKey(k).r === r).map(([k]) => { const a = H.parseKey(k); return H.hexToPixel(a.q, a.r, HEX_SIZE).x; });
        cx = (Math.min(...row) + Math.max(...row)) / 2;
      }
      animateCameraTo(cx, p.y + HEX_SIZE * 0.4, null, camera.zoom < OVERVIEW_BELOW ? 1 : camera.zoom);
    }
    refreshAllCells();
    // 下の操作バー：何番目か・今いる見出し（選んだマスなら、その件数）・進み具合
    const head = reading.recs ? null : [...list.slice(0, i + 1)].reverse().find(([, x]) => x.seq.head);
    $('readPos').textContent = `${i + 1} / ${list.length}`;
    $('readTitle').textContent = reading.recs ? `選んだ ${list.length} マスを選んだ順に` : head ? head[1].text.split('\n')[0] : '';
    $('readProgress').style.width = `${((i + 1) / list.length) * 100}%`;
    $('readPrev').disabled = i === 0;
    $('readNext').disabled = i === list.length - 1;
  }

  function stepReading(d) {
    if (!reading) return;
    const list = readingList();
    const i = list.findIndex(([, r]) => r === reading.rec);
    const j = i + d;
    if (j < 0 || j >= list.length) {
      toast(d > 0 ? '最後まで読みました（Esc で終わる）' : 'ここが最初です');
      return;
    }
    goReadingAt(j);
  }

  function handleReadingKey(e) {
    if (e.ctrlKey || e.metaKey || e.altKey) return false;
    const next = ['ArrowRight', 'ArrowDown', 'PageDown', 'Enter'].includes(e.key) || (e.key === ' ' && !e.shiftKey);
    const prev = ['ArrowLeft', 'ArrowUp', 'PageUp'].includes(e.key) || (e.key === ' ' && e.shiftKey);
    if (next) stepReading(1);
    else if (prev) stepReading(-1);
    else if (e.key === 'Home') goReadingAt(0);
    else if (e.key === 'End') goReadingAt(Number.MAX_SAFE_INTEGER);
    else if (e.key === 'Escape') stopReading();
    else if (!e.shiftKey && ['KeyL', 'KeyB', 'KeyC'].includes(e.code)) {
      if (!e.repeat) readAct({ KeyL: 'like', KeyB: 'bookmark', KeyC: 'comment' }[e.code]);
    } else return false;
    e.preventDefault();
    return true;
  }

  // 操作バーの → のそばの いいね・ブックマーク・コメント：今読んでいるマスに付ける（マスの下のボタンと同じ）
  function readAct(kind) {
    if (!reading || !reading.key) return;
    if (kind === 'comment') openComments(reading.key);
    else handleAction(kind, reading.key, $(kind === 'like' ? 'readLike' : 'readBookmark'));
    updateReadActions();
  }

  // 今読んでいるマスの いいね（段階）・ブックマーク・コメント数をボタンに出す
  function updateReadActions() {
    const rec = reading && reading.key ? getRecord(reading.key) : null;
    const level = rec ? rec.likedLevel : 0;
    const like = $('readLike');
    like.dataset.like = String(level);
    like.setAttribute('aria-pressed', String(level > 0));
    like.querySelector('.read-act-n').textContent = level > 1 ? `×${level}` : '';
    like.title = `${level ? LIKE_LABELS[level] : 'いいね'}（L）｜押すたびに いいね → ×2 → ×3 → なし`;
    const marked = !!rec && rec.bookmarked;
    const bookmark = $('readBookmark');
    bookmark.setAttribute('aria-pressed', String(marked));
    bookmark.title = marked ? 'ブックマークを外す（B）' : 'ブックマークする（B）';
    const n = rec ? rec.comments.length : 0;
    const comment = $('readComment');
    comment.querySelector('.read-act-n').textContent = n ? String(n) : '';
    comment.title = n ? `コメント ${n} 件を見る・書く（C）` : 'コメントを書く（C）';
  }

  $('readActs').addEventListener('mousedown', (e) => e.preventDefault()); // ボタンにフォーカスを移さない（Space・Enter は読み進めるキーのまま）
  $('readLike').addEventListener('click', () => readAct('like'));
  $('readBookmark').addEventListener('click', () => readAct('bookmark'));
  $('readComment').addEventListener('click', () => readAct('comment'));

  $('readPrev').addEventListener('click', () => stepReading(-1));
  $('readNext').addEventListener('click', () => stepReading(1));
  $('readExit').addEventListener('click', () => stopReading());

  // マスの右クリックメニュー
  const cellMenu = $('cellMenu');
  let cellMenuKey = null;

  function openCellMenu(key, pos) {
    cellMenuKey = key;
    const rec = getRecord(key);
    const filled = !!rec && !isEmptyRecord(rec);
    cellMenu.querySelector('[data-cmd="copy"]').disabled = !filled;
    cellMenu.querySelector('[data-cmd="cut"]').disabled = !filled || isCenter(key);
    cellMenu.querySelector('[data-cmd="paste"]').disabled = isCenter(key);
    cellMenu.querySelector('[data-cmd="split-paste"]').disabled = isCenter(key);
    cellMenu.querySelector('[data-cmd="pocket"]').disabled = !filled || isCenter(key) || boardReadOnly || !slipable(rec);
    cellMenu.querySelector('[data-cmd="select"]').hidden = !filled || isCenter(key);
    // この関係線のグラフ：関連線でつながる相手がいるときだけ押せる（いなければ理由を title に）
    const graphBtn = $('cellMenuGraph');
    const graphTarget = graphOpenTarget(rec);
    graphBtn.disabled = !graphTarget;
    graphBtn.title = graphTarget ? 'このメモと関係線でつながるメモだけのグラフを、グラフの区画に表示する' : (filled ? 'このメモには、関係線でつながる相手がありません' : '空のマスには関係線がありません');
    const seq = rec && rec.seq;
    for (const n of cellMenu.querySelectorAll('[data-seq-only]')) n.hidden = !seq;
    if (seq) {
      const saved = readPosOf(seq.id);
      const total = seriesCells(seq.id).length;
      const resume = cellMenu.querySelector('[data-cmd="read-resume"]');
      resume.hidden = !saved || saved === seq.n;
      resume.querySelector('span').textContent = `続きから読む（${seriesIndexOf(seq.id, saved)} / ${total}）`;
      cellMenu.querySelector('[data-cmd="delete-seq"] span').textContent = `この文章をまとめて削除（${total} マス）…`;
    }
    // 画像と組み合わせる：画像のあるメモだけ。組み合わせた階層があれば「開く」、中心のマスなら今いる階層に組み合わせる
    const combine = cellMenu.querySelector('[data-cmd="combine"]');
    const comboLayer = rec && !isCenter(key) ? recLayers(rec).find((l) => l.combo) : null;
    combine.hidden = !rec || !imagesOf(rec).length || (isCenter(key) ? !!currentLayer().combo : path.length >= MAX_DEPTH);
    combine.querySelector('span').textContent = comboLayer ? '画像と組み合わせたセルを開く'
      : isCenter(key) ? 'この階層に画像を組み合わせる（セルの下に敷く）' : '画像と組み合わせる（画像の上のセルに書く）';
    cellMenu.querySelector('[data-cmd="delete"]').disabled = !filled || isCenter(key);
    cellMenu.querySelector('[data-cmd="tags"] span').textContent = rec && tagsOf(rec).length ? `タグ（${tagsOf(rec).map((t) => `#${t}`).join(' ')}）…` : 'タグを付ける…';
    const region = regionOf(key);
    cellMenu.querySelector('[data-cmd="region"] span').textContent = region ? `領域「${region.name}」…` : multiEntries().length ? `選んだ ${multiEntries().length} マスを領域にする…` : '領域を作る（マスを選んで名前を付ける）…';
    cellMenu.querySelector('[data-cmd="due"] span').textContent = rec && rec.due ? `期限（${dueLabel(rec.due)}${isDone(rec) ? '・完了' : ''}）…` : '期限を付ける…';
    cellMenu.querySelector('[data-cmd="shelve"]').disabled = !filled || isCenter(key);
    cellMenu.querySelector('[data-cmd="dend"]').disabled = !filled;
    const inDends = rec && rec.id ? dendsOf().filter((d) => d.steps.includes(rec.id)) : [];
    cellMenu.querySelector('[data-cmd="dend"] span').textContent = inDends.length ? `Dendritic Extension（${inDends.map((d) => d.name).join('・')}）…` : 'Dendritic Extension…';
    cellMenu.querySelector('[data-cmd="link"]').disabled = !filled;
    const linkFrom = cellMenu.querySelector('[data-cmd="link-from"]');
    linkFrom.hidden = !(filled && overviewWrites());
    const editHere = cellMenu.querySelector('[data-cmd="edit-here"]');
    if (editHere) editHere.hidden = !(filled && overviewWrites() && !isCenter(key));
    cellMenu.querySelector('[data-cmd="link-create"]').disabled = !filled;
    cellMenu.querySelector('[data-cmd="copy-link"]').disabled = !filled;
    cellMenu.querySelector('[data-cmd="send"]').disabled = !filled;
    const sendReg = cellMenu.querySelector('[data-cmd="send-register"]');
    sendReg.disabled = !filled;
    syncSendItem(sendReg, 'memo', rec && rec.id, ['このマスを送り先に登録（この下へ送れるように）', '送り先の登録を外す']);
    cellMenu.querySelector('[data-cmd="send"]').hidden = !hasSendApi();
    const nLinks = linkCount(rec);
    const listBtn = cellMenu.querySelector('[data-cmd="links"]');
    listBtn.disabled = nLinks === 0;
    listBtn.querySelector('span').textContent = nLinks ? `関連するメモ（${nLinks}件）` : '関連するメモ';
    renderCellMenuTemplates();
    showPopoverAt(cellMenu, pos);
  }

  cellMenu.addEventListener('mousedown', (e) => e.preventDefault());
  cellMenu.addEventListener('click', (e) => {
    const btn = e.target.closest('button[data-cmd]');
    if (!btn || btn.disabled) return;
    const key = cellMenuKey;
    cellMenu.hidePopover();
    const cmd = btn.dataset.cmd;
    if (cmd === 'copy') copyCell(key);
    else if (cmd === 'cut') copyCell(key, { cut: true });
    else if (cmd === 'paste') pasteAt(key);
    else if (cmd === 'split-paste') splitPasteAt(key);
    else if (cmd === 'pocket') copyMemosToPocket([[key, getRecord(key)]]);
    else if (cmd === 'select') {
      setSelectMode(true);
      if (!multiSet.has(getRecord(key))) toggleMulti(key);
    }
    else if (cmd === 'series-side') {
      const rec = getRecord(key);
      if (rec && rec.seq) openSeriesSide(rec.seq.id);
    }
    else if (cmd === 'read') startReading(key);
    else if (cmd === 'read-resume') startReading(key, { resume: true });
    else if (cmd === 'delete-seq') deleteSeries(key);
    else if (cmd === 'edit-here') openOvEdit(key);
    else if (cmd === 'link-from') startLinking(key);
    else if (cmd === 'link') startLinking(key);
    else if (cmd === 'link-create') startLinking(key, getRecord(key), { create: true });
    else if (cmd === 'links') openLinkList(key, { x: e.clientX, y: e.clientY });
    else if (cmd === 'tags') openTagMenu(key, { x: e.clientX, y: e.clientY });
    else if (cmd === 'tag-buttons') openCellTagButtons([[key, getRecord(key)]], { x: e.clientX, y: e.clientY });
    else if (cmd === 'voice') openVoice({ key });
    else if (cmd === 'due') openDueMenu(key, { x: e.clientX, y: e.clientY });
    else if (cmd === 'tpl-more') openTplMenu(key, { x: e.clientX, y: e.clientY });
    else if (cmd === 'shelve') {
      if (shelveKey(key)) toast('棚へ移しました（右上の「棚」から置き直せます）', 'info', 3500);
    } else if (cmd === 'graph-open') openLinkGraph(getRecord(key));
    else if (cmd === 'dend') openDendMenu(key, { x: e.clientX, y: e.clientY });
    else if (cmd === 'region') {
      const r = regionOf(key);
      if (r) openRegionMenu(r.id, { x: e.clientX, y: e.clientY });
      else if (multiEntries().length) createRegionFromMulti(key);
      else {
        setSelectMode(true);
        if (selectableRec(key)) toggleMulti(key);
        toast('領域にするマスを選んで（クリック・なぞる）、下の「領域に名前」を押してください', 'info', 4500);
      }
    }
    else if (cmd === 'copy-link') copyMemoLink(key);
    else if (cmd === 'send') openSendMenu([[key, getRecord(key)]], { x: e.clientX, y: e.clientY });
    else if (cmd === 'send-register') toggleSendCell(key);
    else if (cmd === 'attach-image') {
      cellImageKey = key;
      $('cellImageInput').click();
    } else if (cmd === 'combine') {
      const rec = getRecord(key);
      if (rec) combineImage(rec, rec.cover);
    } else if (cmd === 'add-url') {
      openSide(key, 'web');
      revealCell(key);
      $('sideUrlInput').focus();
    }
    else if (cmd === 'side') {
      const rec = getRecord(key);
      openSide(key, rec && !rec.comments.length && childCount(rec) ? 'layer' : 'comments');
      revealCell(key);
    }
    else if (cmd === 'delete') deleteMemo(key);
  });

  stage.addEventListener('contextmenu', (e) => {
    if (ovLinkDrag || ovLinkSuppressMenu) {
      e.preventDefault();
      e.stopImmediatePropagation(); // 右ドラッグで線を引いている間は、マスのメニューを出さない
      return;
    }
    const cell = e.target.closest('.cell');
    if (!cell && clearOnEmptyContext(e)) return;
    if (!cell || e.target.closest('.editor')) return; // 本文の入力欄はふつうの右クリックメニュー
    e.preventDefault();
    if (linking) cancelLinking();
    if (editingKey && editingKey !== cell._key) endEdit();
    if ((multi.length > 1 || selectMode) && multiSet.has(getRecord(cell._key)) && !e.target.closest('button[data-action], .meta-seq')) {
      openMultiMenu(cell._key, { x: e.clientX, y: e.clientY }); // 選んだマスの右クリック：選んだマスのメニュー
      return;
    }
    const shownSeries = side && side.series; // 選ぶと別の文章の全文に切り替わるので、先に覚えておく
    selectCell(cell._key);
    // 分けて並べたマスの番号：全文をサイドバーに（もう一度で閉じる）
    const seqRec = e.target.closest('.meta-seq') && getRecord(cell._key);
    if (seqRec && seqRec.seq) {
      if (shownSeries === seqRec.seq.id) closeSide();
      else {
        openSeriesSide(seqRec.seq.id);
        revealCell(cell._key);
      }
      return;
    }
    if (e.target.closest('button[data-action="copies"]')) {
      const rec = getRecord(cell._key);
      if (rec && rec.id && side && side.list === 'pocket' && side.copiesOf === rec.id) closeSide(); // もう一度右クリックで閉じる
      else if (rec) showCopiesInPocket(rec);
      return;
    }
    const act = e.target.closest('button[data-action="comment"], button[data-action="layer"], button[data-action="links"], button[data-action="like"], button[data-action="bookmark"], button[data-action="images"], button[data-action="web"]');
    if (act) {
      const tab = { comment: 'comments', layer: 'layer', links: 'links', like: 'likes', bookmark: 'bookmarks', images: 'images', web: 'web' }[act.dataset.action];
      if (isSideShowing(cell._key, tab)) {
        closeSide(); // もう一度右クリックで閉じる
        return;
      }
      openSide(cell._key, tab);
      revealCell(cell._key);
      return;
    }
    openCellMenu(cell._key, { x: e.clientX, y: e.clientY });
  });

  // マスの無いところ（隙間・縮小中の空いたところ）の右クリック：選んでいるマス（強調）と関連付けの途中をやめる。
  // 書いている途中・選択モード・ほかが受けた右クリック（位置合わせの枠など）は今までどおり。返り値：やめたら true
  function clearOnEmptyContext(e) {
    if (e.defaultPrevented || editingKey || selectMode) return false;
    if (e.target.closest && e.target.closest('.editor, .combo-frame, button, input, textarea')) return false;
    if (!selectedKey && !linking) return false;
    e.preventDefault();
    if (linking) cancelLinking();
    if (selectedKey) clearSelection();
    return true;
  }

  // ---- 関連付け（線・関連付け先の選択・一覧） ---------------------------------------
  // 同じ階層にある関連は、マスの隙間（六角形の辺）をたどる線で結ぶ。
  // 別の階層の相手は、マスの 🔗 の数と一覧で分かる

  const SVG_NS = 'http://www.w3.org/2000/svg';
  const LINK_STUB = 18; // 線の端：隙間の角からマスの中へ少し入ったところに印を付ける
  const LINES_PREF = 'hexMemo.showLinkLines';
  const linkLayer = document.createElementNS(SVG_NS, 'svg');
  linkLayer.classList.add('link-layer');
  linkLayer.setAttribute('aria-hidden', 'true');
  cellLayer.prepend(linkLayer);
  const linkDefs = document.createElementNS(SVG_NS, 'defs'); // 向きのある種類の矢印
  linkLayer.append(linkDefs);
  let rubber = null; // 関連付け先を選んでいる間、元のメモからポインター（相手の候補）まで伸びる線
  let rubberFrom = null; // 元のメモのこの階層でのキー（別の階層にいるときは null）
  let rubberTo = null; // 経路を描いている相手のキー
  let pointerWorld = null;
  let showLinkLines = readLinePref();

  function readLinePref() {
    try {
      return localStorage.getItem(LINES_PREF) !== '0';
    } catch {
      return true;
    }
  }

  function layerPositions() {
    const pos = new Map();
    for (const [key, rec] of memos) if (rec.id) pos.set(rec.id, key);
    if (path.length && path[path.length - 1].rec.id) pos.set(path[path.length - 1].rec.id, CENTER_KEY);
    return pos;
  }

  // 2つのマスを隙間でつなぐ線の点（cells レイヤー基準）。両端はマスの中へ少し入れる
  function linkRoutePoints(keyA, keyB) {
    const a = H.parseKey(keyA);
    const b = H.parseKey(keyB);
    const route = H.gapRoute(a, b);
    if (!route) return null;
    const pts = route.map((v) => H.vertexToPixel(v.i, v.j, HEX_SIZE));
    const into = (p, cell) => {
      const c = H.hexToPixel(cell.q, cell.r, HEX_SIZE);
      return { x: p.x + ((c.x - p.x) * LINK_STUB) / HEX_SIZE, y: p.y + ((c.y - p.y) * LINK_STUB) / HEX_SIZE };
    };
    pts.unshift(into(pts[0], a));
    pts.push(into(pts[pts.length - 1], b));
    return pts.map((p) => ({ x: p.x - anchor.x, y: p.y - anchor.y }));
  }

  const pointsAttr = (pts) => pts.map((p) => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');

  function linkEnd(p) {
    const dot = document.createElementNS(SVG_NS, 'circle');
    dot.setAttribute('class', 'link-end');
    dot.setAttribute('cx', p.x.toFixed(1));
    dot.setAttribute('cy', p.y.toFixed(1));
    dot.setAttribute('r', '6');
    return dot;
  }

  function renderLinks() {
    renderRegions(); // 領域の枠も同じ基準点で
    renderDendrites(); // 順路（Dendritic Extension）の線と番号
    renderTrails(); // 足あとの道
    renderTemplateGhost(); // 定型を貼る前の影
    const frag = document.createDocumentFragment();
    const pos = layerPositions();
    const focus = focusLinkId();
    if (showLinkLines) {
      const focused = [];
      links.forEach((l, i) => {
        const ka = pos.get(l.a);
        const kb = pos.get(l.b);
        if (!ka || !kb) return;
        const pts = linkRoutePoints(ka, kb);
        if (!pts) return;
        const isFocus = !!focus && (l.a === focus || l.b === focus);
        const g = document.createElementNS(SVG_NS, 'g');
        g.setAttribute('class', `link${isFocus ? ' is-focus' : ''}${l.kind ? ' has-kind' : ''}`);
        g.dataset.a = ka;
        g.dataset.b = kb;
        g.dataset.i = String(i);
        const color = linkColor(l);
        if (color) g.style.setProperty('--link-c', color);
        const points = pointsAttr(pts);
        const hit = document.createElementNS(SVG_NS, 'polyline'); // 太い透明な線：クリックで編集
        hit.setAttribute('class', 'link-hit');
        hit.setAttribute('points', points);
        const line = document.createElementNS(SVG_NS, 'polyline');
        line.setAttribute('class', 'link-line');
        line.setAttribute('points', points);
        const directed = !!(kindOf(l.kind) && kindOf(l.kind).directed);
        if (directed && showLinkArrows) line.setAttribute('marker-end', `url(#lk-arrow-${l.kind})`);
        g.append(hit, line, linkEnd(pts[0]));
        if (!(directed && showLinkArrows)) g.append(linkEnd(pts[pts.length - 1]));
        if (l.label) {
          const m = polylineMid(pts);
          const text = document.createElementNS(SVG_NS, 'text');
          text.setAttribute('class', 'link-label');
          text.setAttribute('x', m.x.toFixed(1));
          text.setAttribute('y', m.y.toFixed(1));
          text.textContent = l.label;
          g.append(text);
        }
        if (isFocus) focused.push(g); // 同じ隙間を通る線があっても、強調した線を上に
        else frag.append(g);
      });
      // 同じページ（URL）を含むマスどうしは、自動の関連として点線で結ぶ
      for (const [ka, kb] of autoPairsInLayer()) {
        const pts = linkRoutePoints(ka, kb);
        if (!pts) continue;
        const g = document.createElementNS(SVG_NS, 'g');
        g.setAttribute('class', 'link is-auto');
        g.dataset.a = ka;
        g.dataset.b = kb;
        const line = document.createElementNS(SVG_NS, 'polyline');
        line.setAttribute('class', 'link-line');
        line.setAttribute('points', pointsAttr(pts));
        g.append(line);
        frag.prepend(g);
      }
      frag.append(...focused);
    }
    rubber = null;
    rubberTo = null;
    rubberFrom = linking ? pos.get(linking.rec.id) || null : null;
    if (linking) {
      rubber = document.createElementNS(SVG_NS, 'polyline');
      rubber.setAttribute('class', 'link-rubber');
      const color = linkColor({ kind: linking.kind });
      if (color) rubber.style.setProperty('--link-c', color);
      frag.append(rubber);
      updateRubber();
    }
    linkLayer.replaceChildren(linkDefs, frag);
    linkLayer.classList.toggle('has-focus', showLinkLines && !!focus && linkIndex.has(focus));
    if (activeTab === 'graph') requestGraphRender();
  }
  const showLinkArrows = true;

  function updateLinkToggle() {
    const btn = $('linkToggle');
    btn.setAttribute('aria-pressed', String(showLinkLines));
    btn.title = `関連付けの線を${showLinkLines ? '隠す' : '表示する'}（Ctrl+Shift+L）`;
  }

  function setShowLinkLines(on) {
    showLinkLines = on;
    try {
      localStorage.setItem(LINES_PREF, on ? '1' : '0');
    } catch {
      // 保存できなくても、この起動中は切り替わる
    }
    updateLinkToggle();
    renderLinks();
    toast(on ? '関連付けの線を表示しました' : '関連付けの線を隠しました（関連は 🔗 から確認できます）');
  }

  // 強調する関連：関連付けの途中ならその元、そうでなければ選択中のメモ
  function focusLinkId() {
    if (linking) return linking.rec.id;
    const rec = selectedKey ? getRecord(selectedKey) : null;
    return rec && rec.id ? rec.id : null;
  }

  // 相手の候補（メモのあるマス）の上では、関連付けたときと同じ隙間の経路を点線で見せる。
  // それ以外では、元のメモの中心からポインターへまっすぐ
  function updateRubber() {
    if (!rubber || !linking) return;
    if (!rubberFrom || !pointerWorld) {
      rubber.setAttribute('visibility', 'hidden');
      return;
    }
    rubber.removeAttribute('visibility');
    const h = H.pixelToHex(pointerWorld.x, pointerWorld.y, HEX_SIZE);
    const key = H.keyOf(h.q, h.r);
    const rec = key !== rubberFrom ? getRecord(key) : null;
    if (linking.create) {
      // 新しいメモを置く：空いたマス（中心は除く）の上で、置いたときの隙間の経路を見せる
      const ok = key !== rubberFrom && !isCenter(key) && !(rec && !isEmptyRecord(rec));
      markNewLinkTarget(ok ? key : null);
      if (ok) {
        if (rubberTo === key) return;
        rubberTo = key;
        rubber.classList.add('is-route');
        rubber.setAttribute('points', pointsAttr(linkRoutePoints(rubberFrom, key)));
        return;
      }
    } else if (rec && !isEmptyRecord(rec)) {
      if (rubberTo === key) return;
      rubberTo = key;
      rubber.classList.add('is-route');
      rubber.setAttribute('points', pointsAttr(linkRoutePoints(rubberFrom, key)));
      return;
    }
    rubberTo = null;
    rubber.classList.remove('is-route');
    const { q, r } = H.parseKey(rubberFrom);
    const c = H.hexToPixel(q, r, HEX_SIZE);
    rubber.setAttribute('points', pointsAttr([
      { x: c.x - anchor.x, y: c.y - anchor.y },
      { x: pointerWorld.x - anchor.x, y: pointerWorld.y - anchor.y },
    ]));
  }

  function worldAt(clientX, clientY) {
    const r = stage.getBoundingClientRect();
    const z = camera.zoom;
    return { x: camera.x + (clientX - r.left - view.w / 2) / z, y: camera.y + (clientY - r.top - view.h / 2) / z };
  }

  function keyAt(clientX, clientY) {
    return H.screenToKey(clientX, clientY, camera, view, stage.getBoundingClientRect(), HEX_SIZE);
  }

  stage.addEventListener('pointermove', (e) => {
    if (!linking) return;
    pointerWorld = worldAt(e.clientX, e.clientY);
    updateRubber();
    syncLinkLanding(e.clientX, e.clientY);
  });

  const linkBanner = $('linkBanner');

  // create：相手を選ぶ代わりに、空いたマスを選んで「関連付けのある新しいメモ」を置く（置いたらすぐ書ける）
  function startLinking(key, rec = getRecord(key), { kind = null, create = false } = {}) {
    if (!rec || isEmptyRecord(rec)) {
      toast('メモのあるマスから関連付けてください', 'warn');
      return;
    }
    endEdit();
    endDrag();
    ensureId(rec);
    linking = { rec, kind: kind && kindOf(kind) ? kind : null, create, reverse: false };
    pointerWorld = null;
    stage.classList.add('is-linking');
    stage.classList.toggle('is-linking-create', create);
    $('linkBannerText').textContent = create
      ? `「${recordLabel(rec, key, 16)}」と関連付けのある新しいメモを置く、空いたマスをクリック（種類・ラベルは先に選べます。ほかの階層へ移動して置くこともできます）`
      : `「${recordLabel(rec, key, 16)}」と関連付けるメモをクリック。空いたマスで離すと、そこに新しいメモを一行で書けます（種類・ラベルは先に選べます）`;
    $('linkLabelInput').value = '';
    renderLinkKindPalette();
    linkBanner.hidden = false;
    refreshAllCells();
    renderLinks();
  }

  function cancelLinking() {
    if (!linking) return;
    linking = null;
    markNewLinkTarget(null);
    stage.classList.remove('is-linking', 'is-linking-create');
    linkBanner.hidden = true;
    if (ovMark && ovMark.mode === 'drop' && !shelfPlacing) hideOvMark();
    refreshAllCells();
    renderLinks();
  }

  // 新しいメモを置ける空いたマスに印（ポインターを重ねている間）
  function markNewLinkTarget(key) {
    if (newLinkTarget === key) return;
    if (newLinkTarget) activeCells.get(newLinkTarget)?.classList.remove('is-new-link-target');
    newLinkTarget = key;
    if (key) activeCells.get(key)?.classList.add('is-new-link-target');
  }

  // 置いた新しいメモ：何も書かずに離れたら、メモも線も残さない
  let newLinkedDraft = null; // { rec, layer, a, b }
  // 続けて作る：置いた新しいメモを書いているとき、Tab でそのメモから次を、Shift+Tab で同じ元からもう1つ（種類・ラベル・向きは同じ）
  let chainCreate = null; // { rec, source, kind, label, reverse }

  function continueLinkedChain(sameSource) {
    const c = chainCreate;
    const key = editingKey;
    const rec = key && getRecord(key);
    if (!c || !rec || rec !== c.rec) return;
    if (!hasText(rec)) {
      toast('本文を書いてから続けてください（やめるときは Esc）', 'warn', 2500);
      return;
    }
    endEdit();
    const from = sameSource ? c.source : rec;
    startLinking(keyInView(from), from, { kind: c.kind, create: true });
    if (!linking) return;
    linking.reverse = c.reverse;
    $('linkLabelInput').value = c.label;
    renderLinkKindPalette();
    toast(sameSource ? `「${recordLabel(from, '?', 12)}」から、もう1つ置くマスをクリック` : '今書いたメモから、次のメモを置くマスをクリック', 'info', 2500);
  }

  function completeNewLinked(key) {
    const source = linking.rec;
    if (isCenter(key)) {
      toast('中心のマスには置けません。周りの空いたマスをクリックしてください（やめるときは Esc）', 'warn');
      return;
    }
    const here = getRecord(key);
    if (here === source) {
      cancelLinking();
      return;
    }
    if (here && !isEmptyRecord(here)) {
      toast('空いたマスをクリックしてください（メモのあるマスとつなぐときは「関連付ける…」。やめるときは Esc）', 'warn');
      return;
    }
    const extra = { kind: linking.kind || null, label: $('linkLabelInput').value.replace(/\s+/g, ' ').trim() };
    const reverse = linking.reverse && !!(kindOf(extra.kind) && kindOf(extra.kind).directed);
    cancelLinking();
    const rec = ensureRecord(key);
    const a = ensureId(source);
    const b = ensureId(rec);
    if (reverse) addLink(b, a, extra);
    else addLink(a, b, extra);
    newLinkedDraft = { rec, layer: currentLayer(), a: reverse ? b : a, b: reverse ? a : b };
    chainCreate = { rec, source, kind: extra.kind, label: extra.label, reverse };
    refreshAllCells();
    renderLinks();
    updateTabCounts();
    scheduleSave();
    startEdit(key);
    flashCell(key);
    toast(`「${kindName(extra.kind) || '関連'}」の線でつないだ新しいメモです。本文を書いてください。Tab で続けてこのメモから次を、Shift+Tab で同じ元からもう1つ（何も書かずに離れると消えます）`, 'info', 5000);
  }

  // 置いた新しいメモの最初の編集が終わったとき：何も書いていなければ、メモと線を片付ける
  function settleNewLinkedDraft(key) {
    const d = newLinkedDraft;
    if (!d) return;
    newLinkedDraft = null;
    const rec = memos.get(key);
    if (rec !== d.rec || d.layer !== currentLayer()) return;
    if (!isEmptyRecord({ ...rec, id: null })) return; // 本文・コメント・タグなど何かあれば残す
    removeLink(d.a, d.b);
    if (isEmptyRecord(rec)) {
      memos.delete(key);
      refreshAllCells(); // 元のメモの 🔗 の数も戻す
      renderLinks();
      updateTabCounts();
      scheduleSave();
      toast('何も書かなかったので、新しいメモと線は取りやめました', 'info', 2500);
    }
  }

  function completeLinking(key) {
    const target = getRecord(key);
    const source = linking.rec;
    if (!target || isEmptyRecord(target)) {
      if (beginLinkedWrite(key)) return;
      toast('メモのあるマスをクリックしてください（やめるときは Esc）', 'warn');
      return;
    }
    if (target === source) {
      cancelLinking();
      return;
    }
    const a = ensureId(source);
    const b = ensureId(target);
    const extra = { kind: linking.kind || null, label: $('linkLabelInput').value.replace(/\s+/g, ' ').trim() };
    cancelLinking();
    if (isLinked(a, b)) {
      toast('すでに関連付けられています');
      return;
    }
    addLink(a, b, extra);
    refreshAllCells();
    renderLinks();
    scheduleSave();
    selectCell(key);
    flashCell(key);
    toast(showLinkLines ? '関連付けました' : '関連付けました（線は隠しています。Ctrl+Shift+L で表示）');
  }

  // 線を空いたマスで離した：同じ一行入力を出し、Enter でメモと線を1手で置く。Esc は何も作らない
  function beginLinkedWrite(key) {
    if (!linking || linking.create) return false;
    const rec = getRecord(key);
    const act = emptyLinkRelease({
      viewOnly: settings.overviewViewOnly === true,
      filled: !!(rec && !isEmptyRecord(rec)),
      center: isCenter(key),
      linking: true,
      readOnly: boardReadOnly,
    });
    if (act !== 'write') return false;
    const source = linking.rec;
    const kind = linking.kind || null;
    const label = $('linkLabelInput').value.replace(/\s+/g, ' ').trim();
    const reverse = !!(linking.reverse && kindOf(kind) && kindOf(kind).directed);
    cancelLinking();
    ovLinkDraft = { source, kind, label, reverse, key };
    openOvWrite(key, { forLink: true });
    if (ovWriteKey !== key) {
      ovLinkDraft = null;
      return false;
    }
    return true;
  }
  function syncLinkLanding(clientX, clientY) {
    const blocked = !linking || linking.create || ovWriteKey || boardReadOnly || settings.overviewViewOnly === true;
    if (blocked) {
      if (ovMark && ovMark.mode === 'drop' && !shelfPlacing && !(pocketDrag && pocketDrag.honey)) hideOvMark();
      return;
    }
    const key = keyAt(clientX, clientY);
    const rec = getRecord(key);
    const act = emptyLinkRelease({
      viewOnly: false,
      filled: !!(rec && !isEmptyRecord(rec)),
      center: isCenter(key),
      linking: true,
      readOnly: false,
    });
    if (act === 'write') showOvMark(key, 'drop', `ここに書く（${formatCoord(key)}）`);
    else if (ovMark && ovMark.mode === 'drop' && !shelfPlacing && !(pocketDrag && pocketDrag.honey)) hideOvMark();
  }

  $('linkCancel').addEventListener('click', cancelLinking);

  // 関連するメモの一覧（マスの 🔗 から）
  const linkMenu = $('linkMenu');
  const linkList = $('linkList');
  let linkMenuKey = null;

  // その ID のメモの場所を、今いる階層から見た言葉で
  function describeLocation(found) {
    const here = path.map((p) => p.step).join('|');
    if (found.keys.join('|') === here) return `この階層（${formatCoord(found.key)}）`;
    if (path.length && found.rec === path[path.length - 1].rec) return 'この階層の中心';
    const labels = pathLabels(found.keys);
    return labels.length ? `${labels.join(' › ')} の周り` : `ノート直下（${formatCoord(found.key)}）`;
  }

  function openLinkList(key, pos) {
    const rec = getRecord(key);
    if (!rec || !rec.id) return;
    linkMenuKey = key;
    const rows = [];
    for (const otherId of linkIndex.get(rec.id) || []) {
      const found = locateById(otherId);
      if (!found) continue;
      const row = el('div', 'link-row');
      const go = el('button', 'link-go');
      go.type = 'button';
      go.dataset.id = otherId;
      go.append(el('span', 'link-text', recordLabel(found.rec, found.key, 22)), el('span', 'link-where', describeLocation(found)));
      const link = findLink(rec.id, otherId);
      if (link && (link.kind || link.label)) {
        const k = el('span', 'link-kind-tag');
        const color = linkColor(link);
        if (color) k.style.setProperty('--kind-c', color);
        const directed = !!(kindOf(link.kind) && kindOf(link.kind).directed);
        const dir = directed ? (link.a === rec.id ? '→ ' : '← ') : '';
        k.append(el('span', 'tag-dot'), document.createTextNode(`${dir}${[kindName(link.kind), link.label].filter(Boolean).join('：')}`));
        go.append(k);
      }
      const edit = el('button', 'icon-btn link-edit');
      edit.type = 'button';
      edit.dataset.edit = otherId;
      edit.title = '線の種類・ラベルを変える';
      edit.setAttribute('aria-label', '線の種類・ラベルを変える');
      edit.append(svgIcon('edit'));
      const remove = el('button', 'icon-btn link-remove');
      remove.type = 'button';
      remove.dataset.id = otherId;
      remove.title = '関連を解除';
      remove.setAttribute('aria-label', '関連を解除');
      remove.append(svgIcon('close'));
      row.append(go, edit, remove);
      rows.push(row);
    }
    linkList.replaceChildren(...(rows.length ? rows : [el('div', 'menu-empty', '関連するメモはありません')]));
    $('linkMenuHead').replaceChildren(document.createTextNode('関連するメモ'), el('strong', '', recordLabel(rec, key, 20)));
    showPopoverAt(linkMenu, pos);
  }

  linkMenu.addEventListener('mousedown', (e) => e.preventDefault());
  linkMenu.addEventListener('click', (e) => {
    const key = linkMenuKey;
    const rec = key && getRecord(key);
    const edit = e.target.closest('.link-edit');
    if (edit && rec) {
      const link = findLink(rec.id, edit.dataset.edit);
      linkMenu.hidePopover();
      if (link) openLinkEditor(link, { x: e.clientX, y: e.clientY }, rec.id);
      return;
    }
    const remove = e.target.closest('.link-remove');
    if (remove && rec) {
      removeLink(rec.id, remove.dataset.id);
      pruneIfEmpty(key);
      refreshAllCells();
      renderLinks();
      scheduleSave();
      if (linkCount(rec)) openLinkList(key, { x: parseFloat(linkMenu.style.left), y: parseFloat(linkMenu.style.top) });
      else linkMenu.hidePopover();
      return;
    }
    const go = e.target.closest('.link-go');
    if (go) {
      linkMenu.hidePopover();
      const found = locateById(go.dataset.id);
      if (found) jumpTo(found.key, found.keys);
      return;
    }
    if (e.target.closest('[data-cmd="link-graph"]')) {
      linkMenu.hidePopover();
      openLinkGraph(rec);
      return;
    }
    if (e.target.closest('[data-cmd="link-new"]')) {
      linkMenu.hidePopover();
      startLinking(key);
    }
  });

  // ---- 複数選択 ------------------------------------------------------------------
  // Ctrl+クリックで1つずつ足す（外す）、Shift+クリックで範囲、空いているところ（または Shift を押して）からドラッグで囲む、
  // Ctrl+A でこの階層のメモをすべて。選んだ順に番号が付き、この順で読める（読書モード）。コピー・切り取りは並びを保つ

  function setMulti(recs) {
    multi = recs;
    multiSet = new Set(recs);
    multiOrder = new Map(recs.map((r, i) => [r, i + 1]));
    refreshAllCells();
    updateMultiBar();
  }

  function clearMulti() {
    if (!multi.length) return;
    setMulti([]);
  }

  // 階層・ノートが変わったときなど（マスの描き直しはそちらで）
  function resetMulti() {
    multi = [];
    multiSet = new Set();
    multiOrder = new Map();
    multiAnchor = null;
    paint = null;
    if (selectMode) {
      selectMode = false;
      stage.classList.remove('is-selecting');
      $('selectBtn').setAttribute('aria-pressed', 'false');
    }
    updateMultiBar();
  }

  // 選択モードに入る・終える（終えると選んだ印も消える）
  let selectHinted = false;
  function setSelectMode(on) {
    if (selectMode === on) return;
    selectMode = on;
    stage.classList.toggle('is-selecting', on);
    $('selectBtn').setAttribute('aria-pressed', String(on));
    if (on) {
      endEdit();
      hidePeek();
      selectHinted = false;
      // 1つだけ選んでいた（コピーなどの対象の）マスの青い枠は、選んだ印とまぎれるので外す
      selectCell(null);
    } else {
      paint = null;
      multiAnchor = null;
      if (multi.length) setMulti([]);
    }
    updateMultiBar();
  }

  // 選んだマス [[key, rec]]（選んだ順。この階層にあるメモだけ）
  function multiEntries() {
    if (!multi.length) return [];
    const where = new Map();
    for (const [k, r] of memos) where.set(r, k);
    return multi.map((r) => [where.get(r), r]).filter(([k, r]) => k && !isCenter(k) && !isEmptyRecord(r));
  }

  // 位置の順（上の行から、行の中は左から）
  function byPosition(a, b) {
    const pa = H.parseKey(a);
    const pb = H.parseKey(b);
    return pa.r - pb.r || (pa.q + pa.r / 2) - (pb.q + pb.r / 2);
  }

  const selectableRec = (key) => {
    const rec = memos.get(key);
    return rec && !isEmptyRecord(rec) && !isCenter(key) ? rec : null;
  };

  function toggleMulti(key) {
    const rec = selectableRec(key);
    if (!rec) return;
    const list = multi.slice();
    // 1つだけ選んでいたマスがあれば、それも含めて選び始める（選択モードでは、押したマスだけ）
    const cur = !selectMode && selectedKey && selectedKey !== key ? selectableRec(selectedKey) : null;
    if (!list.length && cur) list.push(cur);
    const i = list.indexOf(rec);
    if (i >= 0) list.splice(i, 1);
    else list.push(rec);
    multiAnchor = key;
    if (!selectMode) selectCell(key);
    setMulti(list);
  }

  // Shift+クリック：起点のマスからそのマスまでの四角の中のメモ（位置の順）
  function rangeMulti(key) {
    const anchor = multiAnchor && selectableRec(multiAnchor) ? multiAnchor : selectedKey;
    if (!anchor || anchor === key || !selectableRec(anchor)) {
      toggleMulti(key);
      return;
    }
    const a = H.parseKey(anchor);
    const b = H.parseKey(key);
    const pa = H.hexToPixel(a.q, a.r, HEX_SIZE);
    const pb = H.hexToPixel(b.q, b.r, HEX_SIZE);
    const pad = HEX_SIZE * 0.5;
    const box = { x0: Math.min(pa.x, pb.x) - pad, x1: Math.max(pa.x, pb.x) + pad, y0: Math.min(pa.y, pb.y) - pad, y1: Math.max(pa.y, pb.y) + pad };
    const hits = [...memos].filter(([k]) => {
      if (!selectableRec(k)) return false;
      const c = H.parseKey(k);
      const p = H.hexToPixel(c.q, c.r, HEX_SIZE);
      return p.x >= box.x0 && p.x <= box.x1 && p.y >= box.y0 && p.y <= box.y1;
    }).sort(([x], [y]) => byPosition(x, y)).map(([, r]) => r);
    if (!selectMode) selectCell(key);
    setMulti(hits);
  }

  function selectAllMemos() {
    if (reading) return;
    endEdit();
    const all = [...memos].filter(([k]) => selectableRec(k)).sort(([x], [y]) => byPosition(x, y)).map(([, r]) => r);
    if (!all.length) return;
    multiAnchor = null;
    setMulti(all);
    toast(`この階層のメモ ${all.length} 件を選びました（Esc で解除）`);
  }

  // 選んだマスをまとめてコピー・切り取り（ほかのアプリには本文を空行で区切って）。1つだけならふつうのコピー
  async function copyMulti({ cut = false } = {}) {
    const list = multiEntries();
    if (!api || !list.length) return;
    if (list.length === 1) {
      copyCell(list[0][0], { cut });
      return;
    }
    if (list.length > 200) {
      toast('まとめてコピーできるのは 200 マスまでです', 'warn');
      return;
    }
    const topLeft = list.map(([k]) => k).sort(byPosition)[0];
    const a = H.parseKey(topLeft);
    const offsets = list.map(([k]) => {
      const p = H.parseKey(k);
      return { dq: p.q - a.q, dr: p.r - a.r };
    });
    const records = list.map(([, r]) => serializeRecord(r));
    const nonce = uuid();
    try {
      await ipc(api.writeClip({ v: 1, nonce, cut, record: records[0], records, offsets, text: list.map(([, r]) => r.text).join('\n\n') }));
    } catch (err) {
      toast(`コピーできませんでした：${err.message}`, 'error', 5000);
      return;
    }
    cutSource = cut ? { nonce, board: currentBoardId, rec: list[0][1], recs: list.map(([, r]) => r) } : null;
    if (cut) {
      // 切り取ったマスは、切り取りの印で示す。選択モードも終えて、次のクリックで移動先を選べるように
      if (selectMode) setSelectMode(false);
      else clearMulti();
    }
    refreshAllCells();
    toast(cut ? `${list.length} マスを切り取りました。移動先のマス（左上になる）を右クリック →「貼り付け」（または選んで Ctrl+V）`
      : `${list.length} マスをコピーしました。貼り付け先のマス（左上になる）を右クリック →「貼り付け」（または選んで Ctrl+V）で、同じ並びで貼り付けます`, 'info', 5000);
  }

  async function deleteMulti() {
    const list = multiEntries();
    if (!list.length) return;
    if (list.length === 1) {
      deleteMemo(list[0][0]);
      return;
    }
    const ids = new Set();
    let inner = 0;
    for (const [, r] of list) {
      subtreeIds(r, ids);
      inner += descendantCount(r);
    }
    const nLinks = countLinksFor(ids);
    const ok = await confirmAction({
      title: `選んだ ${list.length} マスのメモを削除しますか？`,
      message: '本文・いいね・ブックマーク・コメントをすべて削除します。'
        + `${inner ? `周りに書いたメモ ${inner} 件も一緒に削除されます。` : ''}`
        + `${nLinks ? `関連付け ${nLinks} 件も解除されます。` : ''}ゴミ箱に移します（30 日間は戻せます。削除した直後なら、画面下の札の［元に戻す］か Ctrl+Z ですぐ戻せます）。`,
      confirmLabel: `${list.length} マスを削除`,
    });
    if (!ok) return;
    endEdit();
    if (reading && reading.set && list.some(([, r]) => reading.set.has(r))) stopReading({ quiet: true });
    undoCheckpointBeforeDelete();
    for (const [k, r] of list) {
      if (cutSource && (cutSource.rec === r || (cutSource.recs && cutSource.recs.includes(r)))) cutSource = null;
      trashRecord(r, { keys: curKeys(), key: k });
      memos.delete(k);
    }
    removeLinksFor(ids);
    multiAnchor = null;
    setMulti([]);
    selectCell(null);
    renderLinks();
    updateTabCounts();
    scheduleSave();
    toastDeleted(list.length, null);
  }

  // 下の操作バー：選んだ件数と、読む・コピー・切り取り・削除・解除（読書モード中と一覧の表示では隠す）
  function updateMultiBar() {
    const n = multi.length ? multiEntries().length : 0;
    const show = (n > 0 || selectMode) && !reading && activeTab === 'grid';
    $('multiBar').hidden = !show;
    document.body.classList.toggle('has-multi', show);
    if (show) {
      $('multiCount').textContent = n ? `${n} マスを選択中` : '選択モード';
      $('multiHint').hidden = n > 0; // まだ何も選んでいないときの案内
      for (const b of $('multiBar').querySelectorAll('[data-multi="read"], [data-multi="copy"], [data-multi="send"], [data-multi="cut"], [data-multi="delete"], [data-multi="region"], [data-multi="dend"], [data-multi="shelve"], [data-multi="tpl"], [data-multi="tag-buttons"]')) b.disabled = n === 0;
      $('multiBar').querySelector('[data-multi="send"]').hidden = !hasSendApi();
      $('multiBar').querySelector('[data-multi="pocket"]').disabled = n === 0 || boardReadOnly;
    }
    // 札が出ている間にバー（複数選択・読書モード）が出入りしたら、札の高さを合わせ直す
    if (toastEl.classList.contains('is-on')) liftToastAboveBars();
  }

  function runMulti(cmd, key = null, pos = null) {
    if (cmd === 'send') {
      const at = pos || (() => {
        const r = $('multiBar').getBoundingClientRect();
        return { x: r.left + r.width / 2, y: r.top - 8 };
      })();
      openSendMenu(multiEntries(), at);
      return;
    }
    if (cmd === 'read') startReadingSelection();
    else if (cmd === 'region') createRegionFromMulti();
    else if (cmd === 'dend') createDendriteFromMulti();
    else if (cmd === 'shelve') shelveMulti();
    else if (cmd === 'pocket') copyMemosToPocket(multiEntries()); // 選んだ順に、区画の上から詰める
    else if (cmd === 'tag-buttons') openCellTagButtons(multiEntries(), pos || tagButtonsPos());
    else if (cmd === 'export') openExport({ kind: 'keys', keys: multiEntries().map(([k]) => k) });
    else if (cmd === 'tpl') createTemplateFromMulti(key);
    else if (cmd === 'read-here') startReadingSelection(key);
    else if (cmd === 'copy') copyMulti();
    else if (cmd === 'cut') copyMulti({ cut: true });
    else if (cmd === 'delete') deleteMulti();
    else if (cmd === 'clear') clearSelection();
    else if (cmd === 'all') {
      setSelectMode(true);
      selectAllMemos();
    } else if (cmd === 'done') {
      setSelectMode(false);
      clearMulti();
    }
  }

  const multiMenu = $('multiMenu');
  let multiMenuKey = null;
  function openMultiMenu(key, pos) {
    multiMenuKey = key;
    const n = multiEntries().length;
    const i = multiEntries().findIndex(([k]) => k === key);
    multiMenu.querySelector('[data-multi="read-here"] span').textContent = `ここから読む（選んだ順の ${i + 1} 番目から）`;
    multiMenu.querySelector('[data-multi="copy"] span').textContent = `選んだ ${n} マスをコピー`;
    multiMenu.querySelector('[data-multi="cut"] span').textContent = `選んだ ${n} マスを切り取り（移動）`;
    multiMenu.querySelector('[data-multi="send"] span').textContent = `選んだ ${n} マスをコピーして送る…`;
    multiMenu.querySelector('[data-multi="send"]').hidden = !hasSendApi();
    multiMenu.querySelector('[data-multi="delete"] span').textContent = `選んだ ${n} マスを削除…`;
    showPopoverAt(multiMenu, pos);
  }
  multiMenu.addEventListener('mousedown', (e) => e.preventDefault());
  multiMenu.addEventListener('click', (e) => {
    const b = e.target.closest('button[data-multi]');
    if (!b) return;
    multiMenu.hidePopover();
    runMulti(b.dataset.multi, multiMenuKey, { x: e.clientX, y: e.clientY });
  });
  $('multiBar').addEventListener('mousedown', (e) => e.preventDefault());
  $('multiBar').addEventListener('click', (e) => {
    const b = e.target.closest('button[data-multi]');
    if (!b) return;
    const r = b.getBoundingClientRect();
    runMulti(b.dataset.multi, null, { x: r.left, y: r.top - 8 });
  });

  // 空いているところからドラッグして四角で囲む（Ctrl・Shift を押していれば、今の選択に足す）
  function updateMarquee() {
    const m = marquee;
    const s = stage.getBoundingClientRect();
    const x0 = Math.min(m.x, m.cx) - s.left;
    const x1 = Math.max(m.x, m.cx) - s.left;
    const y0 = Math.min(m.y, m.cy) - s.top;
    const y1 = Math.max(m.y, m.cy) - s.top;
    Object.assign(m.el.style, { left: `${x0}px`, top: `${y0}px`, width: `${x1 - x0}px`, height: `${y1 - y0}px` });
    const z = camera.zoom;
    const hits = [...memos].filter(([k]) => {
      if (!selectableRec(k)) return false;
      const c = H.parseKey(k);
      const p = H.hexToPixel(c.q, c.r, HEX_SIZE);
      const sx = (p.x - camera.x) * z + view.w / 2;
      const sy = (p.y - camera.y) * z + view.h / 2;
      return sx >= x0 && sx <= x1 && sy >= y0 && sy <= y1;
    }).sort(([a], [b]) => byPosition(a, b)).map(([, r]) => r);
    const keep = m.base.filter((r) => !hits.includes(r));
    const next = [...keep, ...hits];
    if (next.length !== multi.length || next.some((r, i) => r !== multi[i])) setMulti(next);
  }

  function endMarquee() {
    const m = marquee;
    marquee = null;
    if (!m || !m.active) return;
    m.el.remove();
    stage.classList.remove('is-marquee');
    if (stage.hasPointerCapture(m.pointerId)) stage.releasePointerCapture(m.pointerId);
    multiAnchor = null;
    // 囲んだ後は選択モードに（続けてクリック・なぞって足したり外したりできる）
    if (multi.length) setSelectMode(true);
  }

  stage.addEventListener('pointermove', (e) => {
    const m = marquee;
    if (!m || e.pointerId !== m.pointerId) return;
    if (!(e.buttons & 1)) {
      endMarquee();
      return;
    }
    if (!m.active) {
      if (Math.hypot(e.clientX - m.x, e.clientY - m.y) <= DRAG_THRESHOLD) return;
      m.active = true;
      suppressClick = true; // 離したときのクリック（本文の編集）にしない
      if (editingKey) endEdit();
      hidePeek();
      m.base = m.additive ? multi.slice() : [];
      m.el = el('div', 'marquee');
      stage.append(m.el);
      stage.classList.add('is-marquee');
      stage.setPointerCapture(e.pointerId);
    }
    m.cx = e.clientX;
    m.cy = e.clientY;
    updateMarquee();
  });
  stage.addEventListener('pointerup', (e) => {
    if (marquee && e.pointerId === marquee.pointerId) endMarquee();
  });
  stage.addEventListener('pointercancel', () => endMarquee());

  // 選択モードでメモの上からなぞる：通ったメモを、通った順に選ぶ（選んであるメモから始めたら外していく）
  function paintAt(key) {
    const p = paint;
    if (!p || p.seen.has(key)) return;
    p.seen.add(key);
    const rec = selectableRec(key);
    if (!rec) return;
    const has = multiSet.has(rec);
    if (p.remove && has) setMulti(multi.filter((r) => r !== rec));
    else if (!p.remove && !has) setMulti([...multi, rec]);
  }
  stage.addEventListener('pointermove', (e) => {
    const p = paint;
    if (!p || e.pointerId !== p.pointerId) return;
    if (!(e.buttons & 1)) {
      paint = null;
      return;
    }
    if (!p.active) {
      if (Math.hypot(e.clientX - p.x, e.clientY - p.y) <= DRAG_THRESHOLD) return;
      p.active = true;
      suppressClick = true; // 離したときのクリックで、最後のマスを選び直さない
      hidePeek();
      stage.setPointerCapture(e.pointerId);
      stage.classList.add('is-painting');
      paintAt(p.start);
    }
    paintAt(keyAt(e.clientX, e.clientY));
  });
  const endPaint = (e) => {
    if (!paint || (e && e.pointerId !== paint.pointerId)) return;
    const p = paint;
    paint = null;
    if (!p.active) return;
    stage.classList.remove('is-painting');
    if (stage.hasPointerCapture(p.pointerId)) stage.releasePointerCapture(p.pointerId);
  };
  stage.addEventListener('pointerup', endPaint);
  stage.addEventListener('pointercancel', () => endPaint());
  $('selectBtn').addEventListener('click', () => {
    if (selectMode) {
      setSelectMode(false);
      clearMulti();
    } else setSelectMode(true);
  });

  // ---- ドラッグでマスを移動 --------------------------------------------------------
  // 空のマスへ落とすと移動、メモのあるマスへ落とすと入れ替え。画面の端では自動でスクロールする

  const DRAG_THRESHOLD = 6;
  const EDGE_PAN = 48;

  function startDrag(e) {
    const key = dragCandidate.key;
    dragCandidate = null;
    if (editingKey) endEdit();
    const src = activeCells.get(key);
    if (!src || !getRecord(key)) return;
    hidePeek(); // 縮小中の浮かび上がり（プレビュー）は、ドラッグの間は出さない
    const ghost = src.cloneNode(true);
    ghost.classList.remove('is-editing', 'is-selected', 'is-flash', 'is-drop-target');
    ghost.classList.add('drag-ghost');
    stage.appendChild(ghost);
    drag = { key, ghost, pointerId: e.pointerId, target: null, mode: null, x: e.clientX, y: e.clientY, raf: 0 };
    stage.setPointerCapture(e.pointerId);
    stage.classList.add('is-dragging');
    src.classList.add('is-drag-source');
    suppressClick = true;
    selectCell(key);
    updateDrag();
    drag.raf = requestAnimationFrame(dragFrame);
  }

  // ドラッグ中の写し（ゴースト）の大きさ。縮小するほど小さくなるが、全体表示では見失わない大きさを下限にする
  function dragGhostScale(z) {
    return Math.max(0.9 * z, isOverview ? 0.3 : 0);
  }

  function updateDrag() {
    const r = stage.getBoundingClientRect();
    const sx = drag.x - r.left;
    const sy = drag.y - r.top;
    const z = camera.zoom;
    drag.ghost.style.transform = `translate(${Math.round(sx - HEX_W / 2)}px, ${Math.round(sy - HEX_H / 2)}px) scale(${dragGhostScale(z)})`;
    const h = H.pixelToHex(camera.x + (sx - view.w / 2) / z, camera.y + (sy - view.h / 2) / z, HEX_SIZE);
    setDropTarget(H.keyOf(h.q, h.r));
  }

  function setDropTarget(key) {
    if (drag.target === key) return;
    const old = drag.target && activeCells.get(drag.target);
    if (old) old.classList.remove('is-drop-target', 'is-drop-swap', 'is-drop-invalid');
    drag.target = key;
    if (isOverview && !activeCells.has(key)) {
      // 全体表示では空いたマスを描いていない：落とし先のマスだけ描き足す（前の落とし先は外れる）
      lastSignature = '';
      render();
    }
    const rec = memos.get(key);
    drag.mode = key === drag.key ? 'same' : isCenter(key) ? 'invalid' : rec && !isEmptyRecord(rec) ? 'swap' : 'move';
    const node = activeCells.get(key);
    if (node && drag.mode !== 'same') {
      node.classList.add('is-drop-target');
      node.classList.toggle('is-drop-swap', drag.mode === 'swap');
      node.classList.toggle('is-drop-invalid', drag.mode === 'invalid');
    }
  }

  // 画面の端に近いほど速くスクロールし、落とし先も追いかける
  function dragFrame() {
    if (!drag) return;
    const r = stage.getBoundingClientRect();
    const speed = (d) => (d < EDGE_PAN ? Math.round(((EDGE_PAN - d) / EDGE_PAN) * 18) : 0);
    const dx = speed(r.right - drag.x) - speed(drag.x - r.left);
    const dy = speed(r.bottom - drag.y) - speed(drag.y - r.top);
    if (dx || dy) {
      camera.x += dx / camera.zoom;
      camera.y += dy / camera.zoom;
      render();
      scheduleSave('camera');
    }
    updateDrag();
    drag.raf = requestAnimationFrame(dragFrame);
  }

  function endDrag() {
    if (!drag) return null;
    const d = drag;
    drag = null;
    if (isOverview) lastSignature = ''; // 描き足した落とし先（空いたマス）を、次の描画で外す
    cancelAnimationFrame(d.raf);
    d.ghost.remove();
    stage.classList.remove('is-dragging');
    if (stage.hasPointerCapture(d.pointerId)) stage.releasePointerCapture(d.pointerId);
    for (const node of cellLayer.querySelectorAll('.is-drag-source, .is-drop-target')) {
      node.classList.remove('is-drag-source', 'is-drop-target', 'is-drop-swap', 'is-drop-invalid');
    }
    return d;
  }

  function finishDrag() {
    const d = endDrag();
    if (!d || !d.target || d.mode === 'same' || d.mode === 'invalid') {
      if (d) render();
      return;
    }
    const a = memos.get(d.key);
    if (!a) return;
    const b = memos.get(d.target);
    memos.delete(d.key);
    if (d.mode === 'swap') memos.set(d.key, b);
    memos.set(d.target, a);
    selectCell(d.target);
    refreshCell(d.key);
    refreshCell(d.target);
    renderLinks(); // 関連の線もついてくる（ID で結び付いている）
    render(); // 全体表示：描き足した空いたマスを外し、動かした先を描く
    scheduleSave();
  }

  // ---- アクション ----------------------------------------------------------

  function pop(btn) {
    btn.classList.remove('is-pop');
    void btn.offsetWidth;
    btn.classList.add('is-pop');
  }

  function handleAction(action, key, btn) {
    if (action === 'select') {
      // マスの上の丸：選択モードにして、このマスを選ぶ（外す）
      setSelectMode(true);
      toggleMulti(key);
      return;
    }
    if (action === 'like') {
      const rec = ensureRecord(key);
      rec.likedLevel = (rec.likedLevel + 1) % 4; // 0 → 1 → 2 → 3 → 0
      rec.liked = rec.likedLevel > 0;
      if (rec.liked) rec.likedAt = nowIso(); // 段階を上げたときも「いいねした時刻」
      else delete rec.likedAt;
      afterRecordChange(key);
      pop(btn);
    } else if (action === 'bookmark') {
      const rec = ensureRecord(key);
      rec.bookmarked = !rec.bookmarked;
      if (rec.bookmarked) rec.bookmarkedAt = nowIso();
      else delete rec.bookmarkedAt;
      afterRecordChange(key);
      pop(btn);
    } else if (action === 'comment') {
      openComments(key);
    } else if (action === 'layer') {
      if (isCenter(key)) addLayer(); // 中心の六角形：同じメモの周りに層を重ねる
      else enterLayer(key);
    } else if (action === 'links') {
      const r = btn.getBoundingClientRect();
      selectCell(key);
      openLinkList(key, { x: r.left, y: r.bottom + 4 });
    } else if (action === 'copies') {
      // 区画の写しの印：区画の紙片の一覧と「区画にもう1枚写す」
      const r = btn.getBoundingClientRect();
      selectCell(key);
      openCopyList(key, { x: r.left, y: r.bottom + 4 });
    } else if (action === 'images' || action === 'web') {
      // 画像（📎）・リンク（🌐）の印：サイドバーで見る（もう一度押すと閉じる）
      if (isSideShowing(key, action)) closeSide();
      else {
        openSide(key, action);
        revealCell(key);
      }
    } else if (action === 'open-url') {
      const u = urlsOf(getRecord(key))[0];
      if (u) openAnyUrl(u.url);
    } else if (action === 'due') {
      stepProgress(getRecord(key) || ensureRecord(key));
    } else if (action === 'tags') {
      const r = btn.getBoundingClientRect();
      if (!editingKey || editingKey !== key) selectCell(key);
      openTagMenu(key, { x: r.left + r.width / 2 - 120, y: r.bottom + 4 });
    } else if (action === 'delete') {
      deleteMemo(key);
    }
  }

  async function deleteMemo(key) {
    const rec = memos.get(key);
    if (!rec || isCenter(key)) return;
    const inner = descendantCount(rec);
    const ids = subtreeIds(rec);
    const nLinks = countLinksFor(ids);
    const media = [imagesOf(rec).length ? `画像 ${imagesOf(rec).length} 枚` : '', urlsOf(rec).length ? `リンク ${urlsOf(rec).length} 件` : ''].filter(Boolean).join('・');
    const ok = await confirmAction({
      title: 'このメモを削除しますか？',
      message: `マス（${formatCoord(key)}）の本文・いいね・ブックマーク・コメントをすべて削除します。`
        + `${media ? `添付した${media}も外れます。` : ''}`
        + `${inner ? `周りに書いたメモ ${inner} 件も一緒に削除されます。` : ''}`
        + `${nLinks ? `関連付け ${nLinks} 件も解除されます。` : ''}ゴミ箱に移します（30 日間は戻せます。削除した直後なら、画面下の札の［元に戻す］か Ctrl+Z ですぐ戻せます）。`,
    });
    if (!ok) {
      if (editingKey === key) editor.focus({ preventScroll: true });
      return;
    }
    if (editingKey === key) {
      editingKey = null;
      editor.remove();
      invalidateLayout();
    }
    if (cutSource && (cutSource.rec === rec || (cutSource.recs && cutSource.recs.includes(rec)))) cutSource = null;
    undoCheckpointBeforeDelete();
    trashRecord(rec, { keys: curKeys(), key });
    memos.delete(key);
    if (removeLinksFor(ids)) refreshAllCells(); // 相手のマスの 🔗 の数も変わる
    else refreshCell(key);
    renderLinks();
    updateTabCounts();
    scheduleSave();
    toastDeleted(1, key);
  }

  // ---- 元に戻す・やり直す（ノートごと） ----------------------------------------------
  // 中身が変わるたびに少し待って「その時点の内容」を覚え（続けて入力した分は1回にまとめる）、Ctrl+Z でひとつ前の内容に戻す。
  // 表示位置・足あと・日ごとの活動は戻さない。ほかのウィンドウの変更を読み込んだら、それより前には戻さない（あちらの変更を消さないように）
  const UNDO_MAX = 60;
  const undoBoards = new Map(); // ノートの ID → { undo: [{ json, sig }], redo: [...], base: { json, sig } }
  let undoTimer = 0;
  let undoApplying = false;

  const UNDO_SKIP = new Set(['camera', 'footprints', 'trails', 'activity']);
  const undoSig = (data) => JSON.stringify(data, (k, v) => {
    if (UNDO_SKIP.has(k)) return undefined;
    if (v && typeof v === 'object' && !Array.isArray(v)) return Object.fromEntries(Object.keys(v).sort().map((x) => [x, v[x]]));
    return v;
  });
  function undoSnap() {
    const data = serialize();
    return { json: JSON.stringify(data), sig: undoSig(data) };
  }
  function undoState() {
    if (!currentBoardId || !ready) return null;
    let st = undoBoards.get(currentBoardId);
    if (!st) {
      st = { undo: [], redo: [], base: undoSnap() };
      undoBoards.set(currentBoardId, st);
    }
    return st;
  }
  // 今の内容を起点にする。keep：覚えていた起点と同じ内容なら、履歴はそのまま
  function resetUndo({ keep = false } = {}) {
    clearTimeout(undoTimer);
    undoTimer = 0;
    if (!currentBoardId || !ready) return;
    const snap = undoSnap();
    const st = undoBoards.get(currentBoardId);
    if (keep && st && st.base.sig === snap.sig) return;
    undoBoards.set(currentBoardId, { undo: [], redo: [], base: snap });
  }
  // 見た目の変わらない変更（ID を付けるなど）：元に戻す履歴にしない
  function undoAbsorb() {
    clearTimeout(undoTimer);
    undoTimer = 0;
    const st = undoState();
    if (st) st.base = undoSnap();
  }
  function scheduleUndoCheckpoint() {
    if (undoApplying || !ready) return;
    clearTimeout(undoTimer);
    undoTimer = setTimeout(undoCheckpoint, 600);
  }
  function undoCheckpoint() {
    clearTimeout(undoTimer);
    undoTimer = 0;
    const st = undoState();
    if (!st) return;
    const snap = undoSnap();
    if (snap.sig === st.base.sig) return;
    st.undo.push(st.base);
    if (st.undo.length > UNDO_MAX) st.undo.shift();
    st.redo = [];
    st.base = snap;
  }
  // 戻せたら true（削除の札が、戻ったあとに自分の札を出すのに使う。ほかの呼び出しは戻り値を見ない）
  function applyUndo(dir) {
    if (!ready || !currentBoardId || boardReadOnly || activeTab === 'list') return false;
    if (editingKey) endEdit();
    if (slipEdit) saveSlipEdit({ by: 'interrupt' }); // 紙片の書きかけを保存してから戻す（直した分が1手で戻る）
    if (undoTimer) undoCheckpoint(); // まだ覚えていない変更を先に
    const st = undoState();
    if (!st) return false;
    const from = dir === 'undo' ? st.undo : st.redo;
    if (!from.length) {
      toast(dir === 'undo' ? 'これ以上は元に戻せません' : 'やり直せる操作はありません', 'info', 1800);
      return false;
    }
    const target = from.pop();
    (dir === 'undo' ? st.redo : st.undo).push(st.base);
    st.base = target;
    const data = JSON.parse(target.json);
    const now = serialize();
    for (const k of ['footprints', 'trails', 'activity']) { // 足あと・活動は今のまま
      if (now[k]) data[k] = now[k];
      else delete data[k];
    }
    undoApplying = true;
    try {
      applyRemoteStore(data);
    } finally {
      undoApplying = false;
    }
    if (shelfTagMenu.matches(':popover-open')) shelfTagMenu.hidePopover();
    updateTrashCount();
    if (activeTab === 'graph') requestGraphRender();
    if (canSave()) scheduleSave();
    clearTimeout(undoTimer); // 戻した内容そのものは、新しい履歴にしない
    undoTimer = 0;
    st.base = undoSnap();
    toast(dir === 'undo' ? `元に戻しました（Ctrl+Y でやり直し）` : 'やり直しました', 'info', 1600);
    return true;
  }

  // ---- 削除の札（［元に戻す］→［やり直す］→ …） ----
  // 中身は左上メニューの「元に戻す」「やり直す」と同じ。ただし押したときに、札を出したあと何も変わっていない
  // （元に戻すの起点が同じ）ときだけ効く。違えば案内の札にして何もしない（黙ってほかの変更まで戻さないように）。
  // 削除の前に呼ぶ：直前の入力（600ms 以内）が削除と1つの履歴にまとまらないように（区画に写す・外すの前にも呼ぶ）
  function undoCheckpointBeforeDelete() {
    if (undoTimer) undoCheckpoint();
  }
  // 削除の後に呼ぶ（scheduleSave の後）：削除をその場で1回分の履歴にして、札を出す
  function toastDeleted(count, key) {
    const before = undoState();
    const base0 = before && before.base;
    undoCheckpoint();
    updateTrashCount();
    const text = count > 1 ? `${count} マスのメモをゴミ箱に移しました` : 'メモをゴミ箱に移しました';
    const st = undoState();
    // 中身が変わらなかった削除（空のマスを消したなど）は履歴が増えないので、ボタンを付けない（押すと1つ前の変更まで戻ってしまうため）
    if (!st || boardReadOnly || st.base === base0) {
      toast(text, 'info', 3000);
      return;
    }
    offerUndoToast('undo', { text, count, key, keys: curKeys().join('|'), boardId: currentBoardId, mark: st.base });
  }
  function offerUndoToast(dir, ctx) {
    toast(ctx.text, 'info', UNDO_TOAST_MS, { action: { label: dir === 'undo' ? '元に戻す' : 'やり直す', run: () => runUndoToast(dir, ctx) } });
  }
  function runUndoToast(dir, ctx) {
    const changed = dir === 'undo'
      ? 'ほかの変更があるので、この札からは戻せません。ゴミ箱（左上メニュー）から戻せます'
      : 'ほかの変更があるので、この札からはやり直せません。もう一度削除してください';
    if (currentBoardId !== ctx.boardId) {
      toast(dir === 'undo' ? '別のノートに切り替えたので、この札からは戻せません。ゴミ箱（左上メニュー）から戻せます' : '別のノートに切り替えたので、この札からはやり直せません', 'warn', 5000);
      return;
    }
    if (boardReadOnly) {
      toast('読み取り専用のノートなので、この札からは戻せません', 'warn', 5000);
      return;
    }
    // いいね・ブックマーク・グラフのタブにいても、そのまま戻す（左上メニューの「元に戻す」と同じ）
    // 照合は2段：書きかけを確定する前に一度（変換中の文字を打ち切らないように）、確定したあとにもう一度
    if (undoTimer) undoCheckpoint();
    let st = undoState();
    if (!st || st.base !== ctx.mark) {
      toast(changed, 'warn', 6000);
      return;
    }
    if (editingKey) endEdit();
    if (slipEdit) saveSlipEdit({ by: 'interrupt' });
    if (undoTimer) undoCheckpoint();
    st = undoState();
    if (!st || st.base !== ctx.mark || !applyUndo(dir)) {
      toast(changed, 'warn', 6000);
      return;
    }
    // 1マスを戻したときだけ、戻ったマスを光らせる（画面は動かさない）
    if (dir === 'undo' && ctx.count === 1 && activeTab === 'grid' && curKeys().join('|') === ctx.keys && memos.has(ctx.key)) flashCell(ctx.key);
    const text = dir === 'undo' ? (ctx.count > 1 ? `${ctx.count} マスを戻しました` : '戻しました') : 'やり直しました';
    const next = undoState();
    if (next) offerUndoToast(dir === 'undo' ? 'redo' : 'undo', { ...ctx, text, mark: next.base });
  }

  // ---- 今日の1枚（毎日、見直すメモを浮かび上がらせる） ---------------------------------------
  // その日・そのノートで決まった数を、いいね・ブックマーク・書いてからの日数などで重みを付けて選ぶ（2週間以内に出したものは避ける）。
  // 選んだメモ・出した記録はこのブラウザ（アプリ）に覚える。設定（枚数・対象・起動時）は settings.json
  const TODAY_PREF = 'hexMemo.today.';
  const TODAY_AVOID_DAYS = 14;
  const TODAY_SOURCE_LABELS = { mixed: 'いいね・ブックマーク・古いメモを混ぜて', liked: 'いいねしたメモ', bookmarked: 'ブックマークしたメモ', old: 'しばらく前に書いたメモ', all: 'すべてのメモから' };
  const todaySettings = () => ({ count: 1, source: 'mixed', startup: false, aiCount: 20, ...(settings.today || {}) });
  let todayStartupDone = false;

  function readTodayState() {
    try {
      return JSON.parse(localStorage.getItem(TODAY_PREF + currentBoardId) || '{}') || {};
    } catch {
      return {};
    }
  }
  function writeTodayState(st) {
    try {
      localStorage.setItem(TODAY_PREF + currentBoardId, JSON.stringify(st));
    } catch {
      // 覚えられなくても、その場では出せる
    }
  }

  function todayWeight(rec, source, now) {
    const age = Math.max(0, (now - Date.parse(rec.updatedAt || rec.createdAt)) / DAY_MS);
    const like = rec.likedLevel || 0;
    if (source === 'liked') return like;
    if (source === 'bookmarked') return rec.bookmarked ? 1 : 0;
    if (source === 'old') return age >= 14 ? Math.min(age, 720) / 30 : 0;
    if (source === 'all') return 1;
    return 1 + like * 1.5 + (rec.bookmarked ? 1.5 : 0) + Math.min(age, 720) / 60; // 混ぜて
  }
  function todayCandidates(exclude = new Set()) {
    const src = todaySettings().source;
    const now = Date.now();
    const out = [];
    forEachMemo((rec, key, keys) => {
      if (!hasText(rec) || (rec.id && exclude.has(rec.id))) return;
      const w = todayWeight(rec, src, now);
      if (w > 0) out.push({ rec, key, keys, w });
    });
    return out;
  }
  // 日付から決まる乱数（同じ日・同じノートなら同じ順）
  function seededRandom(text) {
    let h = 2166136261;
    for (const ch of text) h = Math.imul(h ^ ch.codePointAt(0), 16777619);
    return () => {
      h += 0x6d2b79f5;
      let t = h;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function weightedPick(list, n, rand) {
    const pool = list.slice();
    const out = [];
    while (out.length < n && pool.length) {
      const total = pool.reduce((sum, x) => sum + x.w, 0);
      let r = rand() * total;
      let i = 0;
      while (i < pool.length - 1 && r >= pool[i].w) {
        r -= pool[i].w;
        i++;
      }
      out.push(pool.splice(i, 1)[0]);
    }
    return out;
  }

  // 今日の分 [{ rec, key, keys }]。足りなければ選び足す（reroll：全部選び直す、replace：その ID だけ別のメモに）
  function todayPicks({ reroll = false, replace = null } = {}) {
    const day = localDay();
    const st = readTodayState();
    const { count } = todaySettings();
    const recent = (st.history || []).filter((h) => h && h.day && (Date.parse(day) - Date.parse(h.day)) / DAY_MS < TODAY_AVOID_DAYS);
    let ids = st.day === day && !reroll ? (st.ids || []).filter((id) => id !== replace) : [];
    ids = ids.filter((id) => {
      const f = locateById(id);
      return f && hasText(f.rec);
    }).slice(0, count);
    let changed = false;
    if (ids.length < count) {
      const avoid = new Set([...ids, ...recent.map((h) => h.id), ...(replace ? [replace] : []), ...(reroll ? st.ids || [] : [])]);
      let cands = todayCandidates(avoid);
      if (cands.length < count - ids.length) cands = todayCandidates(new Set([...ids, ...(replace ? [replace] : [])])); // 足りなければ、最近出したものも
      const rand = seededRandom(`${day}|${currentBoardId}|${reroll || replace ? Date.now() : ''}|${ids.length}`);
      for (const c of weightedPick(cands, count - ids.length, rand)) {
        if (!c.rec.id) changed = true;
        ids.push(ensureId(c.rec));
      }
    }
    if (changed) { // 選んだメモに ID を付けた：保存する（元に戻す履歴にはしない）
      scheduleSave();
      undoAbsorb();
    }
    const history = [...recent.filter((h) => !(h.day === day && !ids.includes(h.id))), ...ids.filter((id) => !recent.some((h) => h.id === id && h.day === day)).map((id) => ({ id, day }))].slice(-500);
    writeTodayState({ ...st, day, ids, history });
    return ids.map((id) => locateById(id)).filter(Boolean);
  }

  function updateTodayBadge() {
    const b = $('todayBtn');
    if (!b || !currentBoardId) return;
    const st = readTodayState();
    const unseen = st.seenDay !== localDay();
    b.querySelector('.btn-badge').textContent = unseen ? String(todaySettings().count) : '';
    b.classList.toggle('has-new', unseen);
    b.title = unseen ? `今日の1枚：まだ見ていない ${todaySettings().count} 枚（サイドバーで見る）` : '今日の1枚（見直すメモ）';
  }

  function openToday() {
    showSide({ list: 'today' });
    $('todayBtn').setAttribute('aria-pressed', 'true');
  }
  function toggleToday() {
    if (side && side.list === 'today') closeSide();
    else openToday();
  }
  // 起動したとき（そのノートでその日はじめて）に開く
  function maybeOpenTodayOnStart() {
    if (todayStartupDone) return;
    todayStartupDone = true;
    if (!todaySettings().startup || readTodayState().seenDay === localDay()) return;
    setTimeout(() => {
      if (!side) openToday();
    }, 600);
  }

  let todayItems = [];
  function renderSideToday() {
    $('sideFilter').hidden = true;
    $('sideHistoryCtl').hidden = true;
    const ts = todaySettings();
    $('todayCount').value = String(ts.count);
    $('todaySource').value = ts.source;
    $('todayStartup').checked = !!ts.startup;
    $('todayAiN').textContent = String(ts.aiCount);
    todayItems = todayPicks();
    const st = readTodayState();
    if (st.seenDay !== localDay()) {
      writeTodayState({ ...st, seenDay: localDay() });
      updateTodayBadge();
    }
    $('sideListSub').textContent = todayItems.length ? `${localDay()} の ${todayItems.length} 枚（${TODAY_SOURCE_LABELS[ts.source]}）` : '';
    const ul = el('ul', 'side-list today-list');
    todayItems.forEach((f, i) => {
      const { rec, key, keys } = f;
      const li = el('li', 'side-item today-item');
      const go = el('button', 'side-item-go');
      go.type = 'button';
      go.dataset.key = key;
      go.dataset.path = keys.join('|');
      go.title = 'ハニカムでこのマスへ移動';
      const meta = el('span', 'side-item-meta');
      const time = el('span', 'card-time', `書いたのは ${formatRelative(rec.createdAt)}`);
      time.title = formatFull(rec.createdAt);
      meta.append(el('span', 'side-dir is-where', locationLabel(keys, key)), time);
      go.append(meta, el('span', 'side-item-text today-text', rec.text.trim()));
      const foot = el('div', 'side-item-foot');
      foot.append(...stateChips(rec, { comments: true }));
      for (const name of tagsOf(rec)) {
        const c = el('span', 'chip chip-tag is-small');
        c.style.setProperty('--tag-c', tagColor(name));
        c.append(el('span', 'tag-dot'), document.createTextNode(tagLabel(name)));
        foot.append(c);
      }
      const acts = el('div', 'shelf-acts');
      const slides = el('button', 'btn small', 'スライドで');
      slides.type = 'button';
      slides.dataset.todaySlide = String(i);
      const other = el('button', 'btn small', '別の1枚に');
      other.type = 'button';
      other.dataset.todayReplace = rec.id || '';
      other.title = 'このメモの代わりに、別のメモを選ぶ';
      acts.append(slides, other);
      li.append(go, foot, acts);
      ul.append(li);
    });
    $('sideListItems').replaceChildren(ul);
    const empty = $('sideListEmpty');
    empty.hidden = todayItems.length > 0;
    empty.textContent = ts.source === 'all' ? 'まだ本文のあるメモがありません。' : `「${TODAY_SOURCE_LABELS[ts.source]}」に当たるメモがありません。上の「対象」を変えてみてください。`;
  }

  function todaySlides(start = 0) {
    const items = todayItems.map((f, i) => ({ rec: f.rec, key: f.key, keys: f.keys, group: `今日の1枚 ${i + 1} / ${todayItems.length}` }));
    openSlides({ title: `今日の1枚（${localDay()}）`, items, start });
  }

  // AI への依頼文：メモ1件分（場所・日付・いいね・タグ・本文・つながり・最近のコメント）
  function memoForAi(f, i) {
    const { rec, key, keys } = f;
    const marks = [locationLabel(keys, key), `作成 ${formatFull(rec.createdAt)}`, rec.likedLevel ? LIKE_LABELS[rec.likedLevel] : '', rec.bookmarked ? 'ブックマーク' : '', ...tagsOf(rec).map((t) => `#${t}`)].filter(Boolean);
    const lines = [`[${i}] （${marks.join('／')}）`, rec.text.trim()];
    for (const id of [...(rec.id ? linkIndex.get(rec.id) || [] : [])].slice(0, 6)) {
      const o = locateById(id);
      const l = o && findLink(rec.id, id);
      if (o) lines.push(`　つながり：${[kindName(l && l.kind) || '関連', l && l.label].filter(Boolean).join('：')} ─ ${recordLabel(o.rec, o.key, 40)}`);
    }
    for (const c of rec.comments.slice(-3)) lines.push(`　コメント：${[...c.text.replace(/\s+/g, ' ')].slice(0, 120).join('')}`);
    return lines.join('\n');
  }
  function todayAiPrompt(mode) {
    const board = currentBoard();
    const name = board ? board.name : 'ノート';
    const ts = todaySettings();
    let list;
    let head;
    if (mode === 'today') {
      list = todayItems;
      head = [
        `以下は、メモアプリ「六角メモ」のノート「${name}」から、今日見直すメモとして選んだ ${list.length} 件です。`,
        'それぞれについて、次の3つを短く教えてください。',
        '1. 今の私にとっての意味・価値',
        '2. 次に取れる具体的な行動（あれば）',
        '3. ほかのメモ（下の一覧の中）とのつながりや、まとめられそうなもの',
        '最後に、今日いちばん見直す価値が高いものを1つ選び、その理由を書いてください。',
      ];
    } else {
      list = weightedPick(todayCandidates(), ts.aiCount, seededRandom(`${localDay()}|${currentBoardId}|ai`)).map(({ rec, key, keys }) => ({ rec, key, keys }));
      head = [
        `以下は、メモアプリ「六角メモ」のノート「${name}」のメモから、見直す候補として選んだ ${list.length} 件です（${TODAY_SOURCE_LABELS[ts.source]}、いいね・ブックマーク・書いてからの日数で重みを付けています）。`,
        `この中から、今日見直すとよいメモを ${ts.count} 件選んでください。`,
        '答えの最初に、選んだメモの番号（[3] のように）を並べてください。そのうえで選んだそれぞれについて、',
        '1. 選んだ理由',
        '2. 今の私にとっての意味・価値と、次に取れる具体的な行動',
        'を短く書いてください。似ている・つながるメモがあれば、まとめ方も提案してください。',
      ];
    }
    if (!list.length) return null;
    return `${head.join('\n')}\n\n${list.map((f, i) => memoForAi(f, i + 1)).join('\n\n---\n\n')}\n`;
  }

  $('todayBtn').addEventListener('click', toggleToday);
  $('todayCount').addEventListener('change', (e) => saveSettings({ today: { count: Number(e.target.value) } }, { quiet: true }));
  $('todaySource').addEventListener('change', (e) => {
    const st = readTodayState();
    writeTodayState({ ...st, ids: [] }); // 対象が変わったら選び直す
    saveSettings({ today: { source: e.target.value } }, { quiet: true });
  });
  $('todayStartup').addEventListener('change', (e) => saveSettings({ today: { startup: e.target.checked } }, { quiet: true }));
  $('todaySlides').addEventListener('click', () => todaySlides(0));
  $('todayReroll').addEventListener('click', () => {
    todayPicks({ reroll: true });
    renderSide();
  });
  $('todayAi').addEventListener('click', () => {
    const text = todayAiPrompt('today');
    if (text) copyPlainText(text, '依頼文をコピーしました。Claude・ChatGPT などに貼り付けて送ってください');
  });
  $('todayAiPick').addEventListener('click', () => {
    const text = todayAiPrompt('pick');
    if (text) copyPlainText(text, `候補 ${todaySettings().aiCount} 件の依頼文をコピーしました。AI に貼り付けて送ってください`);
    else toast('候補になるメモがありません', 'warn');
  });
  $('sideListItems').addEventListener('click', (e) => {
    if (!side || side.list !== 'today') return;
    const sl = e.target.closest('[data-today-slide]');
    const rp = e.target.closest('[data-today-replace]');
    if (sl) todaySlides(Number(sl.dataset.todaySlide));
    else if (rp && rp.dataset.todayReplace) {
      todayPicks({ replace: rp.dataset.todayReplace });
      renderSide();
    }
  });

  // ---- 音声で入力 -------------------------------------------------------------------------
  // 方法は3つ：ブラウザの音声認識（話すとそのまま文字に）／録音して文字起こし（変換しやすい WAV・16kHz・モノラルで保存し、
  // Whisper などの文字起こし（txt・srt・vtt・json）を読み込む。デスクトップ版は変換コマンドで自動でも）／OS の音声入力の案内。
  // 文字は欄に溜めて直せる。書き込む先：新しいメモ・選んでいるマスに書き足す・未配置の棚
  const V = window.HexVoice;
  const voiceDialog = $('voiceDialog');
  const SpeechRec = window.SpeechRecognition || window.webkitSpeechRecognition || null;
  const voiceSettings = () => ({ method: 'browser', lang: 'ja-JP', command: '', auto: true, place: 'new', ...(settings.voice || {}) });
  const voice = { target: null, method: 'browser', on: false, rec: null, base: '', final: '', media: null, stream: null, chunks: [], wav: null, seconds: 0, ac: null, raf: 0, started: 0, tick: 0 };
  const platformName = () => {
    const ua = navigator.userAgent || '';
    if (/iPad|iPhone|iPod/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1)) return 'ios';
    if (/Android/.test(ua)) return 'android';
    if (/Mac/.test(navigator.platform || ua)) return 'mac';
    if (/Win/.test(navigator.platform || ua)) return 'win';
    return 'other';
  };
  const radioValue = (name) => (document.querySelector(`input[name="${name}"]:checked`) || {}).value;
  const setRadio = (name, value) => {
    for (const r of document.querySelectorAll(`input[name="${name}"]`)) r.checked = r.value === value;
  };

  function openVoice({ key = null, shelf = false } = {}) {
    if (!ready || anyDialogOpen()) return;
    const vs = voiceSettings();
    const k = key || (activeTab === 'grid' ? editingKey || selectedKey : null);
    if (editingKey) endEdit();
    voice.target = shelf ? { kind: 'shelf' } : k ? { kind: 'cell', key: k, keys: curKeys() } : null;
    voice.method = vs.method === 'browser' && !SpeechRec ? 'record' : vs.method;
    setRadio('voiceMethod', voice.method);
    const filled = voice.target && voice.target.kind === 'cell' && getRecord(voice.target.key) && hasText(getRecord(voice.target.key));
    setRadio('voicePlace', shelf ? 'shelf' : key && filled ? 'append' : vs.place === 'append' && !filled ? 'new' : vs.place);
    for (const r of document.querySelectorAll('input[name="voicePlace"][value="append"]')) r.disabled = !filled;
    $('voiceText').value = '';
    $('voiceCmd').value = vs.command;
    $('voiceAuto').checked = !!vs.auto;
    $('voiceError').hidden = true;
    voice.wav = null;
    renderVoiceMethod();
    setVoiceStatus('');
    voiceDialog.showModal();
  }

  function renderVoiceMethod() {
    const m = voice.method;
    const hint = $('voiceMethodHint');
    const browserOk = !!SpeechRec;
    for (const r of document.querySelectorAll('input[name="voiceMethod"][value="browser"]')) r.disabled = !browserOk;
    if (m === 'browser') {
      hint.textContent = browserOk
        ? `「はじめる」を押して話すと、下の欄に文字が入ります（言語：${voiceSettings().lang}）。${isWeb ? '' : 'デスクトップ版では、認識のサービスにつながらず使えないことがあります。そのときは「録音して文字起こし」か「OS の音声入力」を。'}`
        : 'このブラウザ（アプリ）では使えません。「録音して文字起こし」か「OS の音声入力」を使ってください。';
    } else if (m === 'record') {
      hint.textContent = `録音して、文字起こしソフト（Whisper など）がそのまま読める WAV（16kHz・モノラル・16bit）で保存できます。文字起こしの結果（.txt・.srt・.vtt・Whisper の .json）を「文字起こしを読み込む」で入れます。${isWeb ? '' : '下の変換コマンドを設定すると、止めたあとすぐ文字起こしします。'}`;
    } else {
      const p = platformName();
      hint.textContent = p === 'win' ? '「はじめる」で下の欄に入ってから、Windows キー＋H を押すと Windows の音声入力が始まります。'
        : p === 'mac' ? '「はじめる」で下の欄に入ってから、Fn（地球儀）キーを2回押すと Mac の音声入力が始まります（システム設定 → キーボード → 音声入力をオンに）。'
          : p === 'ios' ? '下の欄をタップして、キーボードのマイクのボタンを押すと音声入力できます。'
            : p === 'android' ? '下の欄をタップして、キーボードのマイクのボタンを押すと音声入力できます。'
              : '下の欄に入ってから、OS の音声入力を使ってください。';
    }
    $('voiceFileRow').hidden = m !== 'record';
    $('voiceCmdBox').hidden = m !== 'record' || isWeb;
    $('voiceStart').textContent = m === 'record' ? '● 録音をはじめる' : m === 'os' ? '欄に入る' : '● 話しはじめる';
    $('voiceStart').disabled = voice.on || (m === 'browser' && !browserOk);
    $('voiceStop').disabled = !voice.on;
    $('voiceStop').hidden = m === 'os';
    $('voiceSaveWav').disabled = !voice.wav;
    $('voiceRunCmd').disabled = !voice.wav || !$('voiceCmd').value.trim() || !api || !api.transcribeVoice;
  }

  function setVoiceStatus(text, kind = '') {
    const el0 = $('voiceStatus');
    el0.textContent = text;
    el0.dataset.kind = kind;
  }
  function appendVoiceText(text) {
    const t = String(text || '').trim();
    if (!t) return;
    const ta = $('voiceText');
    ta.value = ta.value.trim() ? `${ta.value.replace(/\s+$/, '')}\n${t}` : t;
  }

  async function startVoice() {
    $('voiceError').hidden = true;
    if (voice.method === 'os') {
      const ta = $('voiceText');
      ta.focus();
      ta.setSelectionRange(ta.value.length, ta.value.length);
      return;
    }
    if (voice.method === 'browser') {
      const rec = new SpeechRec();
      rec.lang = voiceSettings().lang;
      rec.continuous = true;
      rec.interimResults = true;
      voice.base = $('voiceText').value.trim() ? `${$('voiceText').value.replace(/\s+$/, '')}\n` : '';
      voice.final = '';
      rec.onresult = (e) => {
        let interim = '';
        for (let i = e.resultIndex; i < e.results.length; i++) {
          const r = e.results[i];
          if (r.isFinal) voice.final += r[0].transcript;
          else interim += r[0].transcript;
        }
        $('voiceText').value = voice.base + voice.final + interim;
      };
      rec.onerror = (e) => {
        const msg = { 'not-allowed': 'マイクを使う許可がありません（ブラウザ・OS の設定でマイクを許可してください）', 'service-not-allowed': 'マイクを使う許可がありません', network: '音声認識のサービスにつながりません（この画面では使えないかもしれません。「録音して文字起こし」か「OS の音声入力」を）', 'audio-capture': 'マイクが見つかりません', 'no-speech': '' }[e.error];
        if (msg === '') return; // 黙っていただけ：続ける
        voice.on = false;
        showVoiceError(msg || `音声認識が止まりました（${e.error}）`);
      };
      rec.onend = () => {
        if (voice.on && voice.rec === rec) {
          voice.base = $('voiceText').value.trim() ? `${$('voiceText').value.replace(/\s+$/, '')}\n` : ''; // 区切りで止まったら続ける
          voice.final = '';
          try {
            rec.start();
            return;
          } catch {
            // 続けられなければ止める
          }
        }
        stopVoice();
      };
      voice.rec = rec;
      voice.on = true;
      try {
        rec.start();
      } catch (err) {
        voice.on = false;
        showVoiceError(`音声認識を始められませんでした：${err.message}`);
        return;
      }
      setVoiceStatus('聞いています…（止めるときは「止める」）', 'on');
      renderVoiceMethod();
      return;
    }
    // 録音
    try {
      voice.stream = await navigator.mediaDevices.getUserMedia({ audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true } });
    } catch (err) {
      showVoiceError(`マイクを使えません：${err.name === 'NotAllowedError' ? '許可がありません（ブラウザ・OS の設定でマイクを許可してください）' : err.message}`);
      return;
    }
    voice.chunks = [];
    voice.wav = null;
    const mr = new MediaRecorder(voice.stream);
    mr.ondataavailable = (e) => {
      if (e.data && e.data.size) voice.chunks.push(e.data);
    };
    mr.onstop = () => finishRecording(mr.mimeType);
    voice.media = mr;
    mr.start(500);
    voice.on = true;
    voice.started = performance.now();
    // 音の大きさの目安と、経過時間
    try {
      voice.ac = new (window.AudioContext || window.webkitAudioContext)();
      const an = voice.ac.createAnalyser();
      an.fftSize = 512;
      voice.ac.createMediaStreamSource(voice.stream).connect(an);
      const data = new Uint8Array(an.fftSize);
      const loop = () => {
        an.getByteTimeDomainData(data);
        let peak = 0;
        for (const v of data) peak = Math.max(peak, Math.abs(v - 128));
        $('voiceLevel').style.width = `${Math.min(100, (peak / 128) * 160)}%`;
        voice.raf = requestAnimationFrame(loop);
      };
      loop();
    } catch {
      // 目安が出せなくても録音は続ける
    }
    voice.tick = setInterval(() => {
      const s = Math.floor((performance.now() - voice.started) / 1000);
      setVoiceStatus(`録音中 ${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`, 'on');
    }, 250);
    setVoiceStatus('録音中 0:00', 'on');
    renderVoiceMethod();
  }

  function releaseMic() {
    clearInterval(voice.tick);
    cancelAnimationFrame(voice.raf);
    $('voiceLevel').style.width = '0';
    if (voice.stream) for (const t of voice.stream.getTracks()) t.stop();
    voice.stream = null;
    if (voice.ac) voice.ac.close().catch(() => {});
    voice.ac = null;
  }

  function stopVoice() {
    const wasOn = voice.on;
    voice.on = false;
    if (voice.rec) {
      const r = voice.rec;
      voice.rec = null;
      try {
        r.stop();
      } catch {
        // もう止まっている
      }
      if (wasOn) setVoiceStatus('止めました。下の欄で直してから「書き込む」');
    }
    if (voice.media && voice.media.state !== 'inactive') voice.media.stop(); // → finishRecording
    else releaseMic();
    renderVoiceMethod();
  }

  // 録音を WAV（16kHz・モノラル・16bit）に
  async function finishRecording(type) {
    releaseMic();
    voice.media = null;
    if (!voice.chunks.length) return;
    setVoiceStatus('録音をまとめています…');
    try {
      const buf = await new Blob(voice.chunks, { type: type || 'audio/webm' }).arrayBuffer();
      const ac = new (window.AudioContext || window.webkitAudioContext)();
      const audio = await ac.decodeAudioData(buf);
      const chans = [];
      for (let c = 0; c < audio.numberOfChannels; c++) chans.push(audio.getChannelData(c));
      const rate = Math.min(V.WAV_RATE, audio.sampleRate);
      voice.wav = V.encodeWav(V.downsample(V.toMono(chans), audio.sampleRate, rate), rate);
      voice.seconds = audio.duration;
      ac.close().catch(() => {});
      setVoiceStatus(`録音 ${Math.round(voice.seconds)} 秒（WAV ${Math.ceil(voice.wav.length / 1024)} KB）`);
      renderVoiceMethod();
      if (!isWeb && voiceSettings().auto && $('voiceCmd').value.trim() && api && api.transcribeVoice) runVoiceCommand();
    } catch (err) {
      showVoiceError(`録音をまとめられませんでした：${err.message}`);
    }
  }

  async function runVoiceCommand() {
    if (!voice.wav || !api || !api.transcribeVoice) return;
    const command = $('voiceCmd').value.trim();
    if (!command) return;
    setVoiceStatus('文字起こし中…（長い録音では数分かかります）', 'busy');
    $('voiceRunCmd').disabled = true;
    try {
      // 本体は保存したコマンドを使う（初めてのコマンドは、本体が確かめてから動かす）
      if (command !== voiceSettings().command) await saveSettings({ voice: { command } }, { quiet: true });
      const res = await ipc(api.transcribeVoice({ bytes: voice.wav }));
      appendVoiceText(res.text);
      setVoiceStatus(res.text ? `文字起こしを入れました（${res.from}）` : '文字起こしの結果が空でした');
    } catch (err) {
      showVoiceError(err.message);
      setVoiceStatus('');
    }
    renderVoiceMethod();
  }

  function showVoiceError(msg) {
    const e = $('voiceError');
    e.textContent = msg;
    e.hidden = false;
    renderVoiceMethod();
  }

  function voiceFileName() {
    const d = new Date();
    return `voice-${localDay(d).replace(/-/g, '')}-${pad2(d.getHours())}${pad2(d.getMinutes())}${pad2(d.getSeconds())}.wav`;
  }

  // 書き込む：新しいメモ（選んでいるマス・その近く・原点の近く）／選んでいるマスに書き足す／棚
  function commitVoice() {
    const text = $('voiceText').value.trim();
    if (!text) {
      showVoiceError('文字がありません。話すか、録音の文字起こしを読み込むか、欄に書いてください');
      return;
    }
    const place = radioValue('voicePlace') || 'new';
    stopVoice();
    const vs = voiceSettings();
    if (vs.method !== voice.method || vs.place !== place) saveSettings({ voice: { method: voice.method, place } }, { quiet: true });
    voiceDialog.close();
    if (place === 'shelf') {
      addToShelf(text);
      toast('棚に置きました（右上の「棚」から置き場所を決められます）', 'info', 3000);
      return;
    }
    if (activeTab !== 'grid') setTab('grid');
    const t = voice.target && voice.target.kind === 'cell' && voice.target.keys.join('|') === curKeys().join('|') ? voice.target.key : selectedKey;
    if (place === 'append') {
      const rec = t && getRecord(t);
      if (!rec) {
        toast('書き足すマスが見つからないので、新しいメモにしました', 'warn', 3000);
      } else {
        rec.text = hasText(rec) ? `${rec.text.replace(/\s+$/, '')}\n${text}` : text;
        rec.updatedAt = nowIso();
        afterRecordChange(t);
        revealCell(t);
        flashCell(t);
        toast('音声の文字を書き足しました', 'info', 2000);
        return;
      }
    }
    const here = t && !isCenter(t) ? getRecord(t) : null;
    const key = t && !isCenter(t) && !(here && !isEmptyRecord(here)) ? t : nearestEmptyKey(currentLayer(), t || '0,0', { avoidCenter: path.length > 0 });
    if (!key) {
      toast('空いたマスが見つかりません', 'warn');
      return;
    }
    const rec = ensureRecord(key);
    rec.text = text;
    rec.updatedAt = nowIso();
    afterRecordChange(key);
    selectCell(key);
    revealCell(key);
    flashCell(key);
    toast(`新しいメモを ${formatCoord(key)} に書きました`, 'info', 2500);
  }

  for (const r of document.querySelectorAll('input[name="voiceMethod"]')) {
    r.addEventListener('change', () => {
      if (voice.on) stopVoice();
      voice.method = r.value;
      $('voiceError').hidden = true;
      renderVoiceMethod();
    });
  }
  $('voiceStart').addEventListener('click', startVoice);
  $('voiceStop').addEventListener('click', stopVoice);
  $('voiceSaveWav').addEventListener('click', async () => {
    if (!voice.wav || !api || !api.saveBinaryFile) return;
    try {
      const res = await ipc(api.saveBinaryFile({ name: voiceFileName(), bytes: voice.wav, type: 'audio/wav', filters: [{ name: 'WAV（16kHz・モノラル）', extensions: ['wav'] }] }));
      if (!res.canceled) toast(`録音を保存しました：${res.path}（Whisper などで文字起こしして「文字起こしを読み込む」）`, 'info', 6000);
    } catch (err) {
      showVoiceError(`保存できませんでした：${err.message}`);
    }
  });
  $('voiceImport').addEventListener('click', async () => {
    if (!api || !api.openTextFile) return;
    try {
      const res = await ipc(api.openTextFile({ filters: [{ name: '文字起こし（txt・srt・vtt・json）', extensions: ['txt', 'srt', 'vtt', 'json'] }, { name: 'すべてのファイル', extensions: ['*'] }] }));
      if (res.canceled) return;
      const text = V.parseTranscript(res.text, res.path || '');
      appendVoiceText(text);
      setVoiceStatus(text ? `文字起こしを読み込みました（${String(res.path || '').split(/[\\/]/).pop()}）` : '読み込んだファイルに文字がありませんでした');
    } catch (err) {
      showVoiceError(`読み込めませんでした：${err.message}`);
    }
  });
  $('voiceRunCmd').addEventListener('click', runVoiceCommand);
  $('voiceCmd').addEventListener('input', renderVoiceMethod);
  $('voiceCmd').addEventListener('change', (e) => saveSettings({ voice: { command: e.target.value } }, { quiet: true }));
  $('voiceAuto').addEventListener('change', (e) => saveSettings({ voice: { auto: e.target.checked } }, { quiet: true }));
  $('voiceOk').addEventListener('click', commitVoice);
  $('voiceCancel').addEventListener('click', () => voiceDialog.close());
  $('voiceText').addEventListener('keydown', (e) => {
    if (e.isComposing || e.keyCode === 229) return;
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      commitVoice();
    }
  });
  voiceDialog.addEventListener('close', () => {
    stopVoice();
    releaseMic();
  });
  $('shelfVoice').addEventListener('click', () => openVoice({ shelf: true }));

  // ---- ゴミ箱（削除したメモ。ノートごと・30 日） -------------------------------------------
  // 削除したメモは、周りに書いたメモ・そのとき外した関連付けと一緒に、保存形式のままゴミ箱に入れる。
  // 「元の場所に戻す」（埋まっていれば近くの空いたマス。階層が無ければ棚）・「棚に戻す」・「完全に削除」
  const TRASH_DAYS = 30;
  const trashOf = () => rootLayer.trash || (rootLayer.trash = []);
  const newTrashId = () => `t${uuid().replace(/-/g, '').slice(0, 16)}`;
  const curKeys = () => path.map((p) => p.step);

  // rec をゴミ箱へ（消す前に呼ぶ。関連付けを外す前に、一緒に覚える）。toShelf：戻すときは棚へ
  function trashRecord(rec, { keys = null, key = null, toShelf = false, where = '' } = {}) {
    if (!rec || isEmptyRecord({ ...rec, id: null })) return; // 中身の無いメモは入れない
    const ids = subtreeIds(rec);
    const entry = { id: newTrashId(), deletedAt: nowIso(), rec: serializeRecord(rec) };
    if (toShelf || !keys) entry.from = 'shelf';
    else {
      entry.from = 'cell';
      entry.keys = [...keys];
      entry.key = key;
    }
    entry.where = where || (entry.from === 'cell' ? locationLabel(keys, key) : '未配置の棚');
    const ls = links.filter((l) => ids.has(l.a) || ids.has(l.b)).map(serializeLink);
    if (ls.length) entry.links = ls;
    const list = trashOf();
    list.unshift(entry);
    if (list.length > 500) list.length = 500;
  }

  function updateTrashCount() {
    const b = $('appMenu') && $('appMenu').querySelector('[data-cmd="trash"] .menu-n');
    if (b) b.textContent = trashOf().length ? `${trashOf().length} 件` : '';
  }

  // 保存形式のメモ → 画面用（周りの層も）
  function recFromStored(raw) {
    const rec = structuredClone(raw);
    if (rec.children) rec.children = toLayer(rec.children);
    if (Array.isArray(rec.moreLayers)) rec.moreLayers = rec.moreLayers.map(toLayer);
    return rec;
  }

  function liveIds() {
    const ids = new Set();
    forEachMemo((r) => {
      if (r.id) ids.add(r.id);
    });
    for (const r of shelfOf()) subtreeIds(r, ids);
    return ids;
  }

  function restoreFromTrash(entry, { toShelf = false } = {}) {
    const i = trashOf().indexOf(entry);
    if (i < 0) return;
    const rec = recFromStored(entry.rec);
    // 同じ ID のメモがもうあれば（元に戻すなどで）、戻すほうの ID を外す
    const live = liveIds();
    const walk = (r) => {
      if (r.id && live.has(r.id)) delete r.id;
      for (const layer of recLayers(r)) for (const c of layer.memos.values()) walk(c);
    };
    walk(rec);
    let placed = null; // { keys, key }
    let note = '';
    if (!toShelf && entry.from === 'cell') {
      const layer = layerAt(entry.keys || []);
      if (layer) {
        const nested = (entry.keys || []).length > 0;
        const here = layer.memos.get(entry.key);
        const free = !(here && !isEmptyRecord(here)) && !(nested && entry.key === CENTER_KEY);
        const key = free ? entry.key : nearestEmptyKey(layer, entry.key, { avoidCenter: nested });
        if (key) {
          layer.memos.set(key, rec);
          placed = { keys: entry.keys || [], key };
          if (key !== entry.key) note = '（元のマスは埋まっていたので、近くの空いたマスに）';
        }
      } else note = '（元の階層が無いので、棚に）';
    }
    if (!placed) shelfOf().unshift(rec);
    // 関連付け：両端があるものだけ付け直す
    const ids = liveIds();
    let relinked = 0;
    for (const l of entry.links || []) {
      if (!ids.has(l.a) || !ids.has(l.b) || isLinked(l.a, l.b)) continue;
      links.push({ ...l });
      relinked++;
    }
    if (relinked) rebuildLinkIndex();
    trashOf().splice(i, 1);
    refreshAllCells();
    renderLinks();
    updateTabCounts();
    updateShelfCount();
    updateTrashCount();
    scheduleSave();
    const where = placed ? locationLabel(placed.keys, placed.key) : '未配置の棚';
    toast(`${where} に戻しました${note}${relinked ? `・関連付け ${relinked} 件も` : ''}`, 'info', 3500);
    if (placed && placed.keys.join('|') === curKeys().join('|') && activeTab === 'grid') flashCell(placed.key);
  }

  function openTrash() {
    showSide({ list: 'trash' });
  }

  function renderSideTrash() {
    $('sideFilter').hidden = true;
    $('sideHistoryCtl').hidden = true;
    const list = trashOf();
    $('sideListSub').textContent = list.length ? `${list.length} 件（削除してから ${TRASH_DAYS} 日たつと消えます）` : '';
    $('sideTrashEmpty').disabled = !list.length;
    const countKids = (r) => {
      let n = 0;
      for (const layer of [r.children, ...(r.moreLayers || [])]) {
        if (!layer || !layer.memos) continue;
        for (const c of Object.values(layer.memos)) n += 1 + countKids(c);
      }
      return n;
    };
    const ul = el('ul', 'side-list trash-list');
    list.forEach((t, i) => {
      const li = el('li', 'side-item trash-item');
      const go = el('div', 'side-item-go');
      const meta = el('span', 'side-item-meta');
      const time = el('span', 'card-time', `削除 ${formatRelative(t.deletedAt)}`);
      time.title = formatFull(t.deletedAt);
      meta.append(el('span', 'side-dir is-where', t.where || (t.from === 'shelf' ? '未配置の棚' : '')), time);
      const text = (t.rec.text || '').trim();
      go.append(meta, el('span', `side-item-text${text ? '' : ' is-empty'}`, text || '（本文なし）'));
      const foot = el('div', 'side-item-foot');
      const chip = (label) => foot.append(el('span', 'chip', label));
      if (t.rec.comments && t.rec.comments.length) chip(`コメント ${t.rec.comments.length}`);
      const kids = countKids(t.rec);
      if (kids) chip(`周りのメモ ${kids}`);
      if (t.links && t.links.length) chip(`関連 ${t.links.length}`);
      for (const name of Array.isArray(t.rec.tags) ? t.rec.tags : []) {
        const c = el('span', 'chip chip-tag is-small');
        c.style.setProperty('--tag-c', tagColor(name));
        c.append(el('span', 'tag-dot'), document.createTextNode(tagLabel(name)));
        foot.append(c);
      }
      const acts = el('div', 'shelf-acts');
      const back = el('button', 'btn small btn-primary', t.from === 'cell' ? '元の場所に戻す' : '棚に戻す');
      back.type = 'button';
      back.dataset.trashRestore = String(i);
      acts.append(back);
      if (t.from === 'cell') {
        const shelf = el('button', 'btn small', '棚に戻す');
        shelf.type = 'button';
        shelf.dataset.trashShelf = String(i);
        acts.append(shelf);
      }
      const del = el('button', 'btn small btn-danger', '完全に削除');
      del.type = 'button';
      del.dataset.trashDel = String(i);
      acts.append(del);
      li.append(go, foot, acts);
      ul.append(li);
    });
    $('sideListItems').replaceChildren(ul);
    const empty = $('sideListEmpty');
    empty.hidden = list.length > 0;
    empty.textContent = 'ゴミ箱は空です。削除したメモはここに入り、30 日間は戻せます（Ctrl+Z でも、すぐ前の操作を元に戻せます）。';
  }

  $('sideListItems').addEventListener('click', async (e) => {
    if (!side || side.list !== 'trash') return;
    const b = e.target.closest('[data-trash-restore], [data-trash-shelf], [data-trash-del]');
    if (!b) return;
    const entry = trashOf()[Number(b.dataset.trashRestore ?? b.dataset.trashShelf ?? b.dataset.trashDel)];
    if (!entry) return;
    if (b.dataset.trashDel !== undefined) {
      const ok = await confirmAction({ title: 'ゴミ箱から完全に削除しますか？', message: `「${(entry.rec.text || '').trim().slice(0, 20) || '（本文なし）'}」を完全に削除します。Ctrl+Z ですぐ前の操作なら元に戻せます。`, confirmLabel: '完全に削除' });
      if (!ok) return;
      const i = trashOf().indexOf(entry);
      if (i >= 0) trashOf().splice(i, 1);
      updateTrashCount();
      scheduleSave();
      return;
    }
    restoreFromTrash(entry, { toShelf: b.dataset.trashShelf !== undefined });
  });
  $('sideTrashEmpty').addEventListener('click', async () => {
    const n = trashOf().length;
    if (!n) return;
    const ok = await confirmAction({ title: 'ゴミ箱を空にしますか？', message: `ゴミ箱の ${n} 件を完全に削除します。Ctrl+Z ですぐ前の操作なら元に戻せます。`, confirmLabel: '空にする' });
    if (!ok) return;
    trashOf().length = 0;
    updateTrashCount();
    scheduleSave();
  });

  // ふつうの文章としてクリップボードへ（AI への依頼文・Markdown など）。できなければ選べる欄に出す
  async function copyPlainText(text, done = 'コピーしました', { quietFail = false } = {}) {
    try {
      await navigator.clipboard.writeText(text);
      toast(done, 'info', 3500);
      return true;
    } catch {
      const ta = el('textarea');
      ta.value = text;
      ta.style.cssText = 'position:fixed;left:-9999px;top:0;opacity:0';
      document.body.append(ta);
      ta.select();
      let ok = false;
      try {
        ok = document.execCommand('copy');
      } catch {
        ok = false;
      }
      ta.remove();
      if (ok || !quietFail) toast(ok ? done : 'コピーできませんでした', ok ? 'info' : 'error', 3500);
      return ok;
    }
  }

  // ---- スライド：メモを1枚ずつ大きく見せる（関係線のまとまり・Dendritic Extension） ------------------
  // items：[{ rec, key, keys, group（上の小さな見出し）, section（一覧の見出し。無ければ group）, color（見出しと縁の色）,
  //   rels：[{ dir, kind, color, who, rec }], choices：[{ label, color, go: () => void }], choicesLabel }]
  // 表紙：{ cover: true, group, head, sub, tree：[{ label, note, color, depth, at（押すとその枚へ） }] }
  const slideView = $('slideView');
  const slide = { title: '', items: [], i: 0, outline: false, onEnter: null, play: false, timer: 0 };
  const SLIDE_SEC_KEY = 'hexMemo.slideSec';
  try {
    const sec = localStorage.getItem(SLIDE_SEC_KEY);
    if (sec && [...$('slideSec').options].some((o) => o.value === sec)) $('slideSec').value = sec;
  } catch {
    // 覚えていなければ既定の秒数
  }

  function openSlides({ title, items, start = 0, onEnter = null }) {
    if (!items.length) return;
    slide.title = title;
    slide.items = items;
    slide.i = Math.min(Math.max(0, start), items.length - 1);
    slide.onEnter = onEnter;
    $('slideTitle').textContent = title;
    if (!slideView.open) slideView.showModal();
    renderSlideOutline();
    renderSlide();
    $('slideCard').focus({ preventScroll: true });
  }

  function renderSlideOutline() {
    const ol = $('slideOutline');
    ol.hidden = !slide.outline;
    $('slideOutlineBtn').setAttribute('aria-pressed', String(slide.outline));
    if (!slide.outline) return;
    let group = null;
    const rows = [];
    slide.items.forEach((it, i) => {
      const sec = it.section || it.group;
      if (sec && sec !== group) {
        group = sec;
        const h = el('li', 'slide-outline-group', group);
        if (it.color) h.style.setProperty('--c', it.color);
        rows.push(h);
      }
      const li = el('li', `slide-outline-item${i === slide.i ? ' is-current' : ''}`);
      if (it.depth) li.style.setProperty('--depth', String(it.depth));
      const b = el('button', '', `${i + 1}. ${it.cover ? '表紙' : recordLabel(it.rec, it.key || '?', 30)}`);
      b.type = 'button';
      b.dataset.slideAt = String(i);
      li.append(b);
      rows.push(li);
    });
    ol.replaceChildren(...rows);
    const cur = ol.querySelector('.is-current');
    if (cur) cur.scrollIntoView({ block: 'nearest' });
  }

  function renderSlide() {
    const it = slide.items[slide.i];
    if (!it) return;
    const { rec } = it;
    const n = slide.items.length;
    $('slidePos').textContent = `${slide.i + 1} / ${n}`;
    $('slideProgress').style.width = `${((slide.i + 1) / n) * 100}%`;
    $('slidePrev').disabled = slide.i === 0;
    $('slideNext').disabled = slide.i === n - 1;
    $('slideJump').disabled = !rec;
    const card = $('slideCard');
    if (it.color) slideView.style.setProperty('--c', it.color); // 見出し・上の縁・進み具合の色
    else slideView.style.removeProperty('--c');
    const parts = [];
    if (it.group) parts.push(el('div', 'slide-group', it.group));
    if (it.cover) {
      card.className = `slide-card is-cover${it.color ? ' has-color' : ''}`;
      parts.push(el('h2', 'slide-head', it.head));
      if (it.sub) parts.push(el('p', 'slide-cover-sub', it.sub));
      const ul = el('ul', 'slide-tree');
      for (const t of it.tree || []) {
        const li = el('li', 'slide-tree-item');
        li.style.setProperty('--depth', String(t.depth || 0));
        if (t.color) li.style.setProperty('--c', t.color);
        const b = el('button', 'slide-tree-go');
        b.type = 'button';
        if (t.at >= 0) b.dataset.slideAt = String(t.at);
        else b.disabled = true;
        b.append(el('span', 'tag-dot'), el('span', 'slide-tree-name', t.label), el('span', 'slide-tree-note', t.note || ''));
        li.append(b);
        ul.append(li);
      }
      parts.push(ul);
      card.replaceChildren(...parts);
      card.scrollTop = 0;
      renderSlideOutline();
      if (!slideView.contains(document.activeElement) || document.activeElement === document.body) card.focus({ preventScroll: true });
      scheduleSlidePlay();
      return;
    }
    const text = hasText(rec) ? rec.text.replace(/\s+$/, '') : '（本文なし）';
    const [first, ...rest] = text.split('\n');
    const len = [...text].length;
    card.className = `slide-card${len <= 40 ? ' is-short' : len <= 160 ? ' is-mid' : ''}${hasText(rec) ? '' : ' is-empty'}${it.color ? ' has-color' : ''}`;
    parts.push(el('h2', 'slide-head', first));
    const body = rest.join('\n').replace(/^\n+/, '');
    if (body.trim()) parts.push(el('div', 'slide-text', body));
    const meta = el('div', 'slide-meta');
    meta.append(el('span', 'slide-where', it.key ? locationLabel(it.keys || [], it.key) : '未配置'));
    for (const name of tagsOf(rec)) {
      const c = el('span', 'chip chip-tag is-small');
      c.style.setProperty('--tag-c', tagColor(name));
      c.append(el('span', 'tag-dot'), document.createTextNode(tagLabel(name)));
      meta.append(c);
    }
    if (rec.likedLevel > 0) meta.append(el('span', 'chip', `♥ ${LIKE_LABELS[rec.likedLevel]}`));
    if (rec.comments.length) meta.append(el('span', 'chip', `コメント ${rec.comments.length}`));
    parts.push(meta);
    if (it.rels && it.rels.length) {
      const row = el('div', 'slide-rels');
      for (const r of it.rels) {
        const b = el('button', 'g-item-rel');
        b.type = 'button';
        b.style.setProperty('--c', r.color);
        b.title = '相手のメモへ';
        const target = slide.items.findIndex((x) => x.rec === r.rec);
        if (target >= 0) b.dataset.slideAt = String(target);
        else b.disabled = true;
        b.append(el('span', 'g-item-rel-dir', r.dir), el('span', 'g-item-rel-kind', r.kind), el('span', 'g-item-rel-who', r.who));
        row.append(b);
      }
      parts.push(row);
    }
    if (it.choices && it.choices.length) {
      const row = el('div', 'slide-choices');
      row.append(el('span', 'slide-choices-label', it.choicesLabel || 'ここから枝が分かれます：'));
      it.choices.forEach((c, ci) => {
        const b = el('button', 'btn small slide-choice', c.label);
        b.type = 'button';
        b.dataset.slideChoice = String(ci);
        if (c.color) b.style.setProperty('--c', c.color);
        row.append(b);
      });
      parts.push(row);
    }
    card.replaceChildren(...parts);
    card.scrollTop = 0;
    renderSlideOutline();
    // 押したボタンが描き直しで消えても、キー（← → Enter）が効き続けるように
    if (!slideView.contains(document.activeElement) || document.activeElement === document.body) card.focus({ preventScroll: true });
    scheduleSlidePlay();
  }

  // 自動で進む（P）：決めた秒数ごとに次の1枚へ。最後まで来たら止まる。手で動かしたら、そこから数え直す
  function scheduleSlidePlay() {
    clearTimeout(slide.timer);
    $('slidePlay').setAttribute('aria-pressed', String(slide.play));
    $('slidePlay').textContent = slide.play ? '❚❚ 止める' : '▶ 自動で進む';
    if (!slide.play || !slideView.open) return;
    if (slide.i >= slide.items.length - 1) {
      slide.play = false;
      $('slidePlay').setAttribute('aria-pressed', 'false');
      $('slidePlay').textContent = '▶ 自動で進む';
      return;
    }
    slide.timer = setTimeout(() => slideGo(slide.i + 1), (Number($('slideSec').value) || 8) * 1000);
  }
  function toggleSlidePlay() {
    slide.play = !slide.play;
    if (slide.play && slide.i >= slide.items.length - 1) slide.i = 0;
    renderSlide();
  }

  function slideGo(i) {
    if (i < 0 || i >= slide.items.length || i === slide.i) return;
    slide.i = i;
    renderSlide();
  }

  function slideJump() {
    const it = slide.items[slide.i];
    if (!it || !it.rec) return;
    slideView.close();
    const found = locatePath(it.rec);
    if (found) jumpTo(found.key, found.keys);
    else toast('このメモはハニカムにありません', 'warn');
  }

  $('slidePrev').addEventListener('click', () => slideGo(slide.i - 1));
  $('slideNext').addEventListener('click', () => slideGo(slide.i + 1));
  $('slideClose').addEventListener('click', () => slideView.close());
  $('slidePlay').addEventListener('click', toggleSlidePlay);
  $('slideSec').addEventListener('change', () => {
    try {
      localStorage.setItem(SLIDE_SEC_KEY, $('slideSec').value);
    } catch {
      // 覚えられなくても使える
    }
    scheduleSlidePlay();
    $('slideCard').focus({ preventScroll: true });
  });
  $('slideJump').addEventListener('click', slideJump);
  $('slideOutlineBtn').addEventListener('click', () => {
    slide.outline = !slide.outline;
    renderSlideOutline();
  });
  slideView.addEventListener('click', (e) => {
    const at = e.target.closest('[data-slide-at]');
    if (at) {
      slideGo(Number(at.dataset.slideAt));
      return;
    }
    const choice = e.target.closest('[data-slide-choice]');
    const it = slide.items[slide.i];
    if (choice && it && it.choices) it.choices[Number(choice.dataset.slideChoice)].go();
  });
  slideView.addEventListener('keydown', (e) => {
    if (e.ctrlKey || e.metaKey || e.altKey || isTypingTarget(e.target)) return;
    const k = e.key;
    let handled = true;
    if (k === 'ArrowRight' || k === 'PageDown' || (k === ' ' && !e.shiftKey)) slideGo(slide.i + 1);
    else if (k === 'ArrowLeft' || k === 'PageUp' || (k === ' ' && e.shiftKey)) slideGo(slide.i - 1);
    else if (k === 'Home') slideGo(0);
    else if (k === 'End') slideGo(slide.items.length - 1);
    else if (k === 'o' || k === 'O') {
      slide.outline = !slide.outline;
      renderSlideOutline();
    } else if (k === 'p' || k === 'P') toggleSlidePlay();
    else if (k === 'Enter' && !e.target.closest('button, select')) slideJump();
    else if (/^[1-9]$/.test(k)) { // 枝の選択
      const it = slide.items[slide.i];
      const c = it && it.choices && it.choices[Number(k) - 1];
      if (c) c.go();
      else handled = false;
    } else handled = false;
    if (handled) e.preventDefault();
  });
  slideView.addEventListener('close', () => {
    slide.items = [];
    slide.play = false;
    clearTimeout(slide.timer);
  });

  // ---- 確認ダイアログ --------------------------------------------------------

  function confirmAction({ title, message, confirmLabel = '削除する', danger = true }) {
    return new Promise((resolve) => {
      confirmTitle.textContent = title;
      confirmMessage.textContent = message;
      confirmOk.textContent = confirmLabel;
      confirmOk.className = `btn ${danger ? 'btn-danger' : 'btn-primary'}`;
      confirmDialog.returnValue = '';
      confirmDialog.addEventListener('close', () => resolve(confirmDialog.returnValue === 'ok'), { once: true });
      confirmDialog.showModal();
      confirmCancel.focus(); // 誤操作を避けるため既定はキャンセル
    });
  }

  confirmDialog.addEventListener('click', (e) => {
    const btn = e.target.closest('button[data-value]');
    if (btn) confirmDialog.close(btn.dataset.value);
  });
  closeOnBackdrop(confirmDialog);

  // 背景（::backdrop）のクリックで閉じる。ダイアログ内から外へドラッグした場合は閉じない
  function closeOnBackdrop(dialog) {
    let downOnBackdrop = false;
    dialog.addEventListener('pointerdown', (e) => {
      downOnBackdrop = e.target === dialog;
    });
    dialog.addEventListener('click', (e) => {
      if (downOnBackdrop && e.target === dialog) dialog.close('cancel');
      downOnBackdrop = false;
    });
  }

  // ---- コメント ------------------------------------------------------------

  function openComments(key) {
    commentKey = key;
    commentInput.value = '';
    renderComments();
    updateComposer();
    commentDialog.showModal();
    commentInput.focus();
  }

  function renderComments() {
    const key = commentKey;
    if (!key) return;
    const rec = getRecord(key);
    const list = rec ? rec.comments : [];
    commentCoordEl.textContent = isCenter(key) ? '（中心）' : `（${formatCoord(key)}）`;
    commentQuote.textContent = hasText(rec) ? rec.text : '（本文なし）';
    commentQuote.classList.toggle('is-empty', !hasText(rec));
    commentThread.replaceChildren(...buildCommentTree(list, { replyable: true }));
    commentThread.hidden = list.length === 0;
    commentEmpty.hidden = list.length > 0;
  }

  // コメントのツリー：parentId で返信をぶら下げる。たたんだ返信は collapsedComments に覚える（この起動中だけ）
  const collapsedComments = new Set();
  let replyTo = null; // 返信先 { where: 'side' | 'dialog', id }

  function commentChildren(list) {
    const ids = new Set(list.map((c) => c.id));
    const kids = new Map();
    const roots = [];
    for (const c of list) {
      if (c.parentId && ids.has(c.parentId) && c.parentId !== c.id) {
        if (!kids.has(c.parentId)) kids.set(c.parentId, []);
        kids.get(c.parentId).push(c);
      } else roots.push(c);
    }
    return { roots, kids };
  }

  // 返信を含めた数
  function countReplies(id, kids) {
    let n = 0;
    for (const c of kids.get(id) || []) n += 1 + countReplies(c.id, kids);
    return n;
  }

  // ツリーの順（親の次に返信）に並べたコメント
  function commentsInTreeOrder(list) {
    const { roots, kids } = commentChildren(list);
    const out = [];
    const walk = (c) => {
      out.push(c);
      for (const k of kids.get(c.id) || []) walk(k);
    };
    for (const r of roots) walk(r);
    return out;
  }

  // list のコメントをツリーの li にする（decorate で li ごとの飾り付け）
  function buildCommentTree(list, { replyable = false, decorate = null } = {}) {
    const { roots, kids } = commentChildren(list);
    const build = (c, depth) => {
      const replies = kids.get(c.id) || [];
      const li = buildCommentItem(c, { replyable, depth, replies: countReplies(c.id, kids), collapsed: collapsedComments.has(c.id) });
      if (decorate) decorate(li, c);
      if (replies.length) {
        const ol = el('ol', 'comment-replies');
        ol.hidden = collapsedComments.has(c.id);
        ol.append(...replies.map((k) => build(k, depth + 1)));
        li.append(ol);
      }
      return li;
    };
    return roots.map((c) => build(c, 0));
  }

  function buildCommentItem(c, { replyable = false, depth = 0, replies = 0, collapsed = false } = {}) {
    const li = el('li', `comment${depth ? ' is-reply' : ''}`);
    const avatar = el('div', 'comment-avatar');
    avatar.append(svgIcon('hex'));
    const main = el('div', 'comment-main');
    const time = el('time', 'comment-time', formatRelative(c.createdAt));
    time.dateTime = c.createdAt;
    time.title = formatFull(c.createdAt);
    const reply = el('button', 'icon-btn comment-reply');
    reply.type = 'button';
    reply.dataset.commentId = c.id;
    reply.title = 'このコメントに返信';
    reply.setAttribute('aria-label', 'このコメントに返信');
    reply.append(svgIcon('reply'));
    reply.hidden = !replyable;
    const fold = el('button', 'comment-fold');
    fold.type = 'button';
    fold.dataset.commentId = c.id;
    fold.dataset.fold = '1';
    fold.hidden = replies === 0;
    fold.setAttribute('aria-expanded', String(!collapsed));
    fold.title = collapsed ? '返信を開く' : '返信をたたむ';
    fold.append(svgIcon('chevron'), document.createTextNode(`返信 ${replies}`));
    const copy = el('button', 'icon-btn comment-copy');
    copy.type = 'button';
    copy.dataset.commentId = c.id;
    copy.title = 'コメントをコピー（マスを選んで Ctrl+V で、メモとして貼り付けられます）';
    copy.setAttribute('aria-label', 'コメントをコピー');
    copy.append(svgIcon('copy'));
    const del = el('button', 'icon-btn comment-delete');
    del.type = 'button';
    del.dataset.commentId = c.id;
    del.title = 'コメントを削除';
    del.setAttribute('aria-label', 'コメントを削除');
    del.append(svgIcon('trash'));
    const meta = el('div', 'comment-meta');
    meta.append(time, fold, reply, copy, del);
    main.append(el('p', 'comment-text', c.text), meta);
    li.dataset.commentId = c.id;
    li.append(avatar, main);
    return li;
  }

  // 返信先の表示の文（コメントの最初の行を 24 文字まで）
  function replyToLabel(c) {
    const line = (c.text.split('\n').find((l) => l.trim()) || '').trim();
    return `返信先：${[...line].length > 24 ? `${[...line].slice(0, 24).join('')}…` : line}`;
  }

  // 返信先の表示（投稿欄の上）。where：'side'（サイドバー）か 'dialog'（コメントの窓）
  function setReplyTo(where, id) {
    replyTo = id ? { where, id } : null;
    const box = $(where === 'side' ? 'sideReplyTo' : 'commentReplyTo');
    const input = where === 'side' ? sideInput : commentInput;
    const rec = where === 'side' ? sideRecord() : getRecord(commentKey);
    const c = id && rec ? rec.comments.find((x) => x.id === id) : null;
    box.hidden = !c;
    if (c) {
      box.querySelector('.reply-to-text').textContent = replyToLabel(c);
      collapsedComments.delete(c.id); // 返信すると開く
      input.focus();
    }
    input.placeholder = c ? '返信を書く…' : 'コメントを書く…';
  }

  // コメントを消すときの確認（コメントの窓・サイドバー・棚・区画の紙片で同じ文）。replies：付け替える返信の数
  function confirmDeleteComment(replies) {
    return confirmAction({ title: 'コメントを削除しますか？', message: `${replies ? `返信 ${replies} 件は、このコメントの親（無ければいちばん上）に付け替えます。` : ''}Ctrl+Z で元に戻せます。` });
  }

  // 削除するコメントの返信は、その親（無ければいちばん上）へ付け替える
  function removeComment(rec, id) {
    const gone = rec.comments.find((c) => c.id === id);
    if (!gone) return false;
    for (const c of rec.comments) {
      if (c.parentId !== id) continue;
      if (gone.parentId) c.parentId = gone.parentId;
      else delete c.parentId;
    }
    rec.comments = rec.comments.filter((c) => c.id !== id);
    if (replyTo && replyTo.id === id) setReplyTo(replyTo.where, null);
    return true;
  }

  // コメントを「マスの中身」としてコピーする（貼り付けるとそのコメントの本文のメモになる。ほかのアプリには本文だけ）。
  // 複数なら、貼り付けたときに選んだマスとその周りの空いているマスへ1件ずつ並ぶ
  async function copyComments(list) {
    if (!api || !list.length) return false;
    const t = nowIso();
    const records = list.map((c) => ({ text: c.text, createdAt: t, updatedAt: t, likedLevel: 0, liked: false, bookmarked: false, comments: [] }));
    const payload = { v: 1, nonce: uuid(), cut: false, record: records[0] };
    if (records.length > 1) {
      payload.records = records;
      payload.text = list.map((c) => c.text).join('\n\n');
    }
    try {
      await ipc(api.writeClip(payload));
    } catch (err) {
      toast(`コピーできませんでした：${err.message}`, 'error', 5000);
      return false;
    }
    if (cutSource) {
      cutSource = null; // クリップボードの中身が変わったので、切り取りは取りやめ
      refreshAllCells();
    }
    toast(list.length > 1
      ? `コメント ${list.length} 件をコピーしました。マスを選んで Ctrl+V で、そのマスと周りの空いているマスに1件ずつ貼り付けます`
      : 'コメントをコピーしました。貼り付けたいマスを選んで Ctrl+V（右クリック →「貼り付け」）', 'info', 4500);
    return true;
  }

  function updateComposer() {
    const text = commentInput.value.trim();
    const n = countChars(text);
    commentCounter.textContent = `${n} / ${TEXT_LIMIT}`;
    commentCounter.className = `counter${n > TEXT_LIMIT ? ' is-over' : n >= TEXT_WARN ? ' is-warn' : ''}`;
    commentPost.disabled = n === 0 || n > TEXT_LIMIT;
  }

  function postComment() {
    const key = commentKey;
    const text = commentInput.value.trim();
    if (!key || !text || countChars(text) > TEXT_LIMIT) return;
    const rec = ensureRecord(key);
    const parent = replyTo && replyTo.where === 'dialog' && rec.comments.some((c) => c.id === replyTo.id) ? replyTo.id : null;
    rec.comments.push({ id: uuid(), text, createdAt: nowIso(), ...(parent ? { parentId: parent } : {}) });
    if (parent) setReplyTo('dialog', null);
    commentInput.value = '';
    updateComposer();
    renderComments();
    commentThread.scrollTop = commentThread.scrollHeight;
    afterRecordChange(key);
    commentInput.focus();
  }

  commentInput.addEventListener('input', updateComposer);
  commentInput.addEventListener('keydown', (e) => {
    if (e.isComposing || e.keyCode === 229) return;
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey || e.shiftKey)) {
      e.preventDefault();
      postComment();
    }
  });
  $('commentReplyTo').querySelector('.reply-to-cancel').addEventListener('click', () => setReplyTo('dialog', null));
  commentPost.addEventListener('click', postComment);
  $('commentClose').addEventListener('click', () => commentDialog.close());
  closeOnBackdrop(commentDialog);

  commentThread.addEventListener('click', async (e) => {
    const copy = e.target.closest('.comment-copy');
    if (copy) {
      const rec = getRecord(commentKey);
      const c = rec && rec.comments.find((x) => x.id === copy.dataset.commentId);
      if (c) copyComments([c]);
      return;
    }
    const reply = e.target.closest('.comment-reply');
    if (reply) {
      setReplyTo('dialog', replyTo && replyTo.where === 'dialog' && replyTo.id === reply.dataset.commentId ? null : reply.dataset.commentId);
      return;
    }
    const fold = e.target.closest('.comment-fold');
    if (fold) {
      if (collapsedComments.has(fold.dataset.commentId)) collapsedComments.delete(fold.dataset.commentId);
      else collapsedComments.add(fold.dataset.commentId);
      renderComments();
      return;
    }
    const btn = e.target.closest('.comment-delete');
    if (!btn) return;
    const key = commentKey;
    const id = btn.dataset.commentId;
    const rec = getRecord(key);
    const replies = rec ? countReplies(id, commentChildren(rec.comments).kids) : 0;
    const ok = await confirmDeleteComment(replies);
    if (ok && rec && key === commentKey) {
      removeComment(rec, id);
      afterRecordChange(key);
      renderComments();
    }
    commentInput.focus();
  });

  // Esc はまずコメントを閉じ、編集中ならそのまま本文の編集に戻る（次の Esc で編集終了）
  commentDialog.addEventListener('close', () => {
    commentKey = null;
    if (replyTo && replyTo.where === 'dialog') setReplyTo('dialog', null);
    if (editingKey) editor.focus({ preventScroll: true });
  });

  // ---- サイドバー（マスのコメント・周りのメモを左側で見る） -----------------------------
  // コメントボタン・六角形ボタンを右クリックで開く。ハニカムを動かしたり別の階層へ移っても、
  // 同じメモを表示し続ける（メモが動いても、レコードそのもので追いかける）

  const sidePanel = $('sidePanel');
  const sideThread = $('sideThread');
  const sideLayerList = $('sideLayerList');
  const sideLinkList = $('sideLinkList');
  const sideInput = $('sideInput');
  const sideCounter = $('sideCounter');
  const sidePost = $('sidePost');
  const sideHistory = []; // サイドバーの中で周りのメモへ移ったときの戻り先
  let sideWhere = null; // 表示中のメモの場所 { keys, key }（マスへ移動・階層を開くのに使う）
  let sideRenderQueued = false;
  const RING1_DIRS = { '1,-1': '右上', '1,0': '右', '0,1': '右下', '-1,1': '左下', '-1,0': '左', '0,-1': '左上' };

  let closedDraft = null; // 閉じたときの書きかけのコメント { target, text }

  const isListTab = (tab) => tab === 'likes' || tab === 'bookmarks';

  // サイドバーがそのマスのその内容（コメント／周りのメモ／関連）を表示中か。
  // いいね・ブックマークの一覧はノート全体の一覧なので、どのマスのボタンからでも同じ一覧
  function isSideShowing(key, tab) {
    if (isListTab(tab)) return !!side && side.list === tab;
    return !!side && !side.list && !side.series && side.tab === tab && isSideTarget(key, getRecord(key));
  }

  function sameSideTarget(a, b) {
    if (a.list || b.list || a.series || b.series) return false;
    return a.rec ? a.rec === b.rec : !b.rec && a.layer === b.layer && a.key === b.key;
  }

  function isSideTarget(key, rec) {
    if (!side || side.list || side.series) return false;
    if (side.rec) return side.rec === rec;
    return side.layer === currentLayer() && side.key === key;
  }

  // そのレコードの場所（ノート直下からの道筋 keys と、その階層でのキー）。見つからなければ null
  function locatePath(target) {
    const walk = (layer, keys) => {
      for (const [key, rec] of layer.memos) {
        if (rec === target) return { keys, key };
        for (const [li, sub] of recLayers(rec).entries()) {
          const found = walk(sub, [...keys, stepOf(key, li)]);
          if (found) return found;
        }
      }
      return null;
    };
    return walk(rootLayer, []);
  }

  // その階層までの道筋（ノート直下なら []）。もう無い階層なら null
  function locateLayer(target) {
    if (target === rootLayer) return [];
    const walk = (layer, keys) => {
      for (const [key, rec] of layer.memos) {
        for (const [li, sub] of recLayers(rec).entries()) {
          if (sub === target) return [...keys, stepOf(key, li)];
          const found = walk(sub, [...keys, stepOf(key, li)]);
          if (found) return found;
        }
      }
      return null;
    };
    return walk(rootLayer, []);
  }

  // 表示中の階層でのキー（中心の親メモも含む）。この階層に無ければ null
  function keyInView(rec) {
    if (path.length && path[path.length - 1].rec === rec) return CENTER_KEY;
    for (const [k, r] of memos) if (r === rec) return k;
    return null;
  }

  // ---- 関係線のグラフを開く（マスの右クリック・左上のメニューから） ----
  // 開けるメモ（関係線でつながる相手がいる）なら rec、いなければ null。サイドバーの「この関係線のグラフ」と同じ決まり
  function graphOpenTarget(rec) {
    return rec && rec.id && !isEmptyRecord(rec) && linkGroup(rec.id).size >= 2 ? rec : null;
  }
  // 左上のメニュー：サイドバーで見ているメモに関係線があれば、そのメモのグラフ。無ければ「グラフ」のタブ（この階層の関係線ぜんぶ）
  function appMenuGraphChoice() {
    const rec = graphOpenTarget(sideRecord());
    return rec ? { rec, label: `この関係線のグラフを表示（${recordLabel(rec, side.key, 12)}）` } : { rec: null, label: '関係線のグラフを表示（この階層のぜんぶ）' };
  }
  function syncAppMenuGraph() {
    $('appMenuGraphLabel').textContent = appMenuGraphChoice().label;
  }
  function openGraphFromAppMenu() {
    const { rec } = appMenuGraphChoice();
    if (rec) openLinkGraph(rec);
    else {
      if (graph.focus) closeLinkGraph();
      setTab('graph');
    }
  }
  function sideRecord() {
    if (!side || side.list || side.series) return null;
    if (!side.rec) {
      const r = side.layer.memos.get(side.key);
      if (r && !isEmptyRecord(r)) side.rec = r; // 空きマスに書き込まれたら、そのメモを追いかける
    }
    return side.rec;
  }

  function openSide(key, tab) {
    const push = !!side && side.list === 'pocket'; // 区画（写しの作業台）から開いたときは、← で区画へ戻れるように
    if (isListTab(tab)) {
      // 右クリックしたマスのメモが一覧にあれば、そこを示す
      const r = getRecord(key);
      showSide({ list: tab, filter: 0, focus: r && !isEmptyRecord(r) ? r : null, scrollToFocus: true }, { push });
      return;
    }
    const rec = getRecord(key);
    const same = side && rec && side.rec === rec;
    // 中心のマスは親のメモそのもの（空でもそのレコードを追う。中心のキーには書き込まない）
    const keep = rec && (!isEmptyRecord(rec) || isCenter(key));
    showSide({ rec: keep ? rec : null, layer: currentLayer(), key, tab }, { keepDraft: same, push });
  }

  function showSide(target, { push = false, keepDraft = false } = {}) {
    if (slipEdit) saveSlipEdit({ by: 'interrupt' }); // 区画の紙片を直している途中なら先に保存（空なら前の文のまま）
    cancelPocketDrag();
    sidePicked = null;
    if (push && side) {
      if (!side.list && !side.series && sideInput.value) side.draft = sideInput.value; // ← で戻ったときに書きかけを戻す
      sideHistory.push(side);
    }
    else if (!push) sideHistory.length = 0;
    const draft = closedDraft && sameSideTarget(closedDraft.target, target) ? closedDraft.text : '';
    closedDraft = null;
    side = target;
    if (!keepDraft) {
      sideInput.value = draft;
      updateSideComposer();
    }
    sidePanel.hidden = false;
    syncStageSize(); // すぐに幅を反映（続けて revealCell が正しい幅で計算できるように）
    $('sideListView').scrollTop = 0;
    $('sideSeriesText').scrollTop = 0;
    $('sideSeriesImages').scrollTop = 0;
    renderSide();
    $('sideBody').scrollTop = 0;
    refreshAllCells();
  }

  function closeSide() {
    if (!side) return;
    if (slipEdit) saveSlipEdit({ by: 'interrupt' });
    cancelPocketDrag();
    if (side.list === 'search') {
      $('searchBtn').setAttribute('aria-pressed', 'false');
      if (searchMap) clearSearchMap();
    }
    if (side.list === 'due') $('dueBtn').setAttribute('aria-pressed', 'false');
    if (side.list === 'shelf') $('shelfBtn').setAttribute('aria-pressed', 'false');
    if (side.list === 'pocket') $('pocketBtn').setAttribute('aria-pressed', 'false');
    if (side.list === 'today') $('todayBtn').setAttribute('aria-pressed', 'false');
    if (side.list === 'stats') $('statsBtn').setAttribute('aria-pressed', 'false');
    if (shelfPlacing) cancelShelfPlacing();
    if (tplPlacing) cancelTemplatePlacing();
    if (replyTo && replyTo.where === 'side') setReplyTo('side', null);
    closedDraft = !side.list && !side.series && sideInput.value.trim() ? { target: side, text: sideInput.value } : null;
    side = null;
    sideWhere = null;
    seriesWhere = null;
    seriesHoverKey = null;
    sidePicked = null;
    pocketPicked = null;
    hidePocketMenus();
    sideHistory.length = 0;
    sidePanel.hidden = true;
    $('historyBtn').setAttribute('aria-pressed', 'false');
    if (hive.open) renderHive(); // ノートの全体を出していたセルの印を消す
    syncStageSize();
    refreshAllCells();
  }

  function requestSideRender() {
    if (!side || sideRenderQueued) return;
    sideRenderQueued = true;
    requestAnimationFrame(renderSide);
  }

  function stateChips(rec, { comments = false, links = true } = {}) {
    const chips = [];
    const chip = (cls, icon, text) => {
      const c = el('span', `chip ${cls}`);
      c.append(svgIcon(icon), document.createTextNode(text));
      chips.push(c);
    };
    if (rec.likedLevel > 0) chip(`chip-like-${rec.likedLevel}`, 'heart', LIKE_LABELS[rec.likedLevel]);
    if (rec.bookmarked) chip('chip-bookmark', 'bookmark', 'ブックマーク');
    if (comments && rec.comments.length) chip('chip-comment', 'comment', `コメント ${rec.comments.length}`);
    if (links && linkCount(rec)) chip('chip-link', 'link', `関連 ${linkCount(rec)}`);
    if (imagesOf(rec).length) chip('chip-image', 'clip', `画像 ${imagesOf(rec).length}`);
    if (urlsOf(rec).length) chip('chip-web', 'globe', `リンク ${urlsOf(rec).length}`);
    return chips;
  }

  // ノート直下（q, r）／ A › B の周り（q, r）
  function locationLabel(keys, key, root = rootLayer) {
    const labels = pathLabels(keys, root);
    return labels.length ? `${labels.join(' › ')} の周り（${formatCoord(key)}）` : `ノート直下（${formatCoord(key)}）`;
  }

  // 道筋 keys の階層（無ければ null）
  function layerAt(keys) {
    let layer = rootLayer;
    for (const step of keys) {
      const { key, li } = parseStep(step);
      const r = layer.memos.get(key);
      const sub = r && layerOf(r, li);
      if (!sub) return null;
      layer = sub;
    }
    return layer;
  }

  function renderSide() {
    sideRenderQueued = false;
    if (!side) return;
    const listMode = !!side.list;
    const seriesMode = !!side.series;
    const listTitle = side.list === 'history' ? (side.sort === 'updated' ? 'メモの更新履歴' : 'メモの作成履歴')
      : side.list === 'overview' ? 'ノートの全体'
        : side.list === 'search' ? '検索'
          : side.list === 'due' ? '期限'
            : side.list === 'shelf' ? '未配置の棚'
              : side.list === 'trash' ? 'ゴミ箱'
                : side.list === 'today' ? '今日の1枚'
              : side.list === 'dendrites' ? 'Dendritic Extensions'
                : side.list === 'stats' ? '足あとと統計'
                  : side.list === 'pocket' ? '区画'
                  : side.list === 'likes' ? 'いいねしたメモ' : 'ブックマークしたメモ';
    $('sideTitle').textContent = seriesMode ? '分けて貼り付けた文章（全文）' : listMode ? listTitle : 'メモの詳細';
    $('historyBtn').setAttribute('aria-pressed', String(side.list === 'history'));
    $('shelfBtn').setAttribute('aria-pressed', String(side.list === 'shelf'));
    $('pocketBtn').setAttribute('aria-pressed', String(side.list === 'pocket'));
    $('sideListView').hidden = !listMode;
    $('sideSeriesView').hidden = !seriesMode;
    if (!seriesMode) seriesWhere = null;
    if (listMode || seriesMode) {
      $('sideBack').hidden = sideHistory.length === 0;
      $('sideGone').hidden = true;
      for (const id of ['sideMemo', 'sideTabs', 'sideBody', 'sideComposer']) $(id).hidden = true;
      sideWhere = null;
      if (seriesMode) renderSideSeries();
      else renderSideList();
      return;
    }
    const rec = sideRecord();
    const found = rec ? locatePath(rec) : null;
    const layerKeys = rec ? null : locateLayer(side.layer);
    const gone = rec ? !found : !layerKeys;
    const commentsTab = side.tab === 'comments';

    $('sideBack').hidden = sideHistory.length === 0;
    $('sideGone').hidden = !gone;
    for (const id of ['sideMemo', 'sideTabs', 'sideBody']) $(id).hidden = gone;
    $('sideComposer').hidden = gone || !commentsTab;
    if (gone) {
      sideWhere = null;
      $('sideGone').textContent = rec ? 'このメモは削除されました。' : 'このマスは表示できなくなりました。';
      return;
    }
    sideWhere = found || { keys: layerKeys, key: side.key };
    const { keys, key } = sideWhere;

    // メモ（場所・本文・状態）
    const where = $('sideWhere');
    const labels = pathLabels(keys);
    where.classList.toggle('is-layer', labels.length > 0);
    where.replaceChildren(svgIcon(labels.length ? 'layers' : 'hex'), el('span', '', locationLabel(keys, key)));
    where.title = where.textContent;
    const quote = $('sideQuote');
    quote.textContent = hasText(rec) ? rec.text : rec ? '（本文なし）' : '（まだメモのないマス）';
    quote.classList.toggle('is-empty', !hasText(rec));
    $('sideStates').replaceChildren(...(rec ? stateChips(rec) : []));
    renderSideTags(rec);
    renderSideDue(rec);

    // タブ
    const nComments = rec ? rec.comments.length : 0;
    const nKids = childCount(rec);
    $('sideCommentCount').textContent = `(${nComments})`;
    $('sideLayerCount').textContent = `(${nKids})`;
    $('sideLinkCount').textContent = `(${rec ? linkCount(rec) : 0})`;
    $('sideImageCount').textContent = `(${imagesOf(rec).length})`;
    $('sideWebCount').textContent = `(${urlsOf(rec).length})`;
    for (const tab of document.querySelectorAll('.side-tab')) {
      const on = tab.dataset.sideTab === side.tab;
      tab.setAttribute('aria-selected', String(on));
      tab.tabIndex = on ? 0 : -1;
    }
    $('sideComments').hidden = side.tab !== 'comments';
    $('sideLayer').hidden = side.tab !== 'layer';
    $('sideLinks').hidden = side.tab !== 'links';
    $('sideImages').hidden = side.tab !== 'images';
    $('sideWeb').hidden = side.tab !== 'web';

    if (commentsTab) {
      const list = rec ? rec.comments : [];
      if (sidePicked && !list.some((c) => c.id === sidePicked)) sidePicked = null;
      sideThread.replaceChildren(...buildCommentTree(list, {
        replyable: true,
        decorate: (li, c) => {
          li.title = 'クリックで選ぶ（Ctrl+C でコピー）・右クリックでメニュー';
          li.classList.toggle('is-picked', c.id === sidePicked);
        },
      }));
      if (replyTo && replyTo.where === 'side' && !list.some((c) => c.id === replyTo.id)) setReplyTo('side', null);
      sideThread.hidden = list.length === 0;
      $('sideThreadEmpty').hidden = list.length > 0;
      $('sideCopyAll').hidden = list.length < 2;
      $('sideCopyAll').lastChild.textContent = `すべてのコメントをコピー（${list.length}件）`;
    } else if (side.tab === 'links') {
      // 関連するメモ（別の階層にあっても）。場所は「今いる階層」ではなくノート直下からの道筋で示す
      const ids = rec && rec.id ? [...(linkIndex.get(rec.id) || [])] : [];
      const items = ids.map((id) => ({ id, found: locateById(id) })).filter((x) => x.found);
      sideLinkList.replaceChildren(...items.map(({ id, found }) => {
        const link = findLink(rec.id, id);
        const extra = [];
        if (link && (link.kind || link.label)) {
          const k = el('span', 'chip chip-kind');
          const color = linkColor(link);
          if (color) k.style.setProperty('--kind-c', color);
          const directed = !!(kindOf(link.kind) && kindOf(link.kind).directed);
          const dir = directed ? (link.a === rec.id ? '→ ' : '← ') : '';
          k.append(el('span', 'tag-dot'), document.createTextNode(`${dir}${[kindName(link.kind), link.label].filter(Boolean).join('：')}`));
          k.title = directed ? (link.a === rec.id ? 'このメモから相手へ' : '相手からこのメモへ') : '';
          extra.push(k);
        }
        const edit = el('button', 'chip chip-edit side-mini');
        edit.type = 'button';
        edit.dataset.linkEdit = id;
        edit.title = '線の種類・ラベルを変える';
        edit.append(svgIcon('edit'), document.createTextNode('線'));
        extra.push(edit);
        return buildSideItem(found.rec, found.key, found.keys, {
          label: locationLabel(found.keys, found.key), labelClass: 'side-dir is-link', coord: false, unlinkId: id, extra,
        });
      }));
      sideLinkList.hidden = items.length === 0;
      $('sideLinkEmpty').hidden = items.length > 0;
      $('sideNewLink').disabled = !rec || isEmptyRecord(rec);
      renderSideSuggest(rec);
      const group = rec && rec.id && items.length ? linkGroup(rec.id) : null;
      $('sideLinkGraph').hidden = !group || group.size < 2;
      if (group) $('sideLinkGraph').lastChild.textContent = `この関係線のグラフ（${group.size} 件・本文の一覧つき）`;
      renderSideAuto(rec);
    } else if (side.tab === 'images') {
      renderSideImages(rec);
    } else if (side.tab === 'web') {
      renderSideWeb(rec);
    } else {
      // 層ごとに（第1層、重ねた第2層…）、近い周から右上を起点に時計回り
      const layers = recLayers(rec);
      const kids = [];
      const nodes = [];
      layers.forEach((layer, li) => {
        const list = [...layer.memos].filter(([, r]) => !isEmptyRecord(r)).map(([k, r]) => {
          const pos = H.parseKey(k);
          const p = H.hexToPixel(pos.q, pos.r, 1);
          return { k, r, li, ring: H.hexDistance(pos, { q: 0, r: 0 }), angle: (Math.atan2(p.x, -p.y) + 2 * Math.PI) % (2 * Math.PI) };
        }).sort((a, b) => a.ring - b.ring || a.angle - b.angle);
        if (layers.length > 1) {
          const head = el('li', 'side-layer-head');
          const open = el('button', 'side-layer-open', `${layerName(rec, li)}（${list.length}件）`);
          open.type = 'button';
          open.dataset.openLayer = String(li);
          open.title = 'この層を開く';
          head.append(open);
          nodes.push(head);
        }
        for (const it of list) {
          kids.push(it);
          nodes.push(buildSideItem(it.r, it.k, [...keys, stepOf(key, li)], { label: it.ring === 1 ? RING1_DIRS[it.k] : `${it.ring}周目` }));
        }
      });
      sideLayerList.replaceChildren(...nodes);
      sideLayerList.hidden = kids.length === 0;
      $('sideLayerEmpty').hidden = kids.length > 0;
      $('sideOpenLayer').textContent = nKids ? 'この周りのハニカムを開く' : 'このメモを中心にしたハニカムを開く（周りに書く）';
      $('sideOpenLayer').prepend(svgIcon('hex'));
      $('sideCopyAllKids').hidden = kids.length < 2;
      $('sideCopyAllKids').lastChild.textContent = `すべての周りのメモをコピー（${kids.length}件）`;
    }
  }

  // ---- サイドバー：分けて貼り付けた文章の全文 ----
  // 分けたマスを番号順につなぎ直して全文を見せ、選んでいる（読書モードでは読んでいる）マスの部分を強調する。
  // 部分にマウスを乗せるとそのマスが光り、クリックでそのマスへ。マスにマウスを乗せると、全文のその部分が光る

  let lastSeriesTab = 'text'; // 全文のサイドバーで最後に見ていたタブ（全文／画像）
  function openSeriesSide(id) {
    showSide({ series: id, scroll: 'jump', seriesTab: lastSeriesTab });
  }

  // 全文を左に出したときのハニカムの幅（まだ出していなければ、出した場合の幅を測る）
  function stageWidthWithSide() {
    if (!sidePanel.hidden) return view.w;
    sidePanel.hidden = false;
    const w = stage.clientWidth;
    sidePanel.hidden = true;
    return w || view.w;
  }

  // その文章のマスがある階層：表示中の階層にあればそこ、無ければノート全体から探す
  function seriesPlace(id) {
    const here = seriesCells(id);
    if (here.length) return { keys: path.map((p) => p.step), list: here, here: true };
    let keys = null;
    forEachMemo((rec, key, at) => {
      if (!keys && rec.seq && rec.seq.id === id) keys = at;
    });
    const layer = keys && layerAt(keys);
    return layer ? { keys, list: seriesCells(id, layer.memos), here: false } : null;
  }

  // 番号順のマスを段落にまとめる。段落の区切りは seq.para で（この印が無い古い文章は、行の途中で次の行へ移ったところ）
  function seriesParagraphs(list) {
    if (!list.length) return [];
    const hasPara = list.some(([, r]) => r.seq.para);
    const rowOf = (k) => H.parseKey(k).r;
    const rowSize = new Map();
    for (const [k] of list) rowSize.set(rowOf(k), (rowSize.get(rowOf(k)) || 0) + 1);
    const full = Math.max(...rowSize.values());
    const paras = [];
    list.forEach(([key, rec], i) => {
      const prev = list[i - 1];
      const start = !prev || rec.seq.head || prev[1].seq.head
        || (hasPara ? !!rec.seq.para : rowOf(prev[0]) !== rowOf(key) && rowSize.get(rowOf(prev[0])) < full);
      if (start) paras.push({ head: !!rec.seq.head, items: [] });
      paras[paras.length - 1].items.push({ key, rec });
    });
    return paras;
  }

  const seriesText = (paras) => paras
    .map((p) => p.items.map((it, i) => (i ? RB.seam(p.items[i - 1].rec.text, it.rec.text) : '') + it.rec.text).join(''))
    .join('\n\n');

  // 全文の部分に付ける印：そのマスのいいね・ブックマーク・コメント・周りのメモ・関連・画像・リンク。
  // count はそのマスでの数（いいねは段階）。いいね・ブックマーク以外は、印を押すとその内容をサイドバーに出す
  const SEG_MARKS = [
    { kind: 'like', icon: 'heart', label: 'いいね', count: (r) => r.likedLevel },
    { kind: 'bookmark', icon: 'bookmark', label: 'ブックマーク', count: (r) => (r.bookmarked ? 1 : 0) },
    { kind: 'comments', icon: 'comment', label: 'コメント', count: (r) => r.comments.length },
    { kind: 'layer', icon: 'hex', label: '周りのメモ', short: '周り', count: (r) => childCount(r) },
    { kind: 'links', icon: 'link', label: '関連するメモ', short: '関連', count: (r) => linkCount(r) },
    { kind: 'images', icon: 'clip', label: '画像', count: (r) => imagesOf(r).length },
    { kind: 'web', icon: 'globe', label: 'リンク', count: (r) => urlsOf(r).length },
  ];

  function segMarks(rec) {
    const marks = [];
    for (const m of SEG_MARKS) {
      const n = m.count(rec);
      if (!n) continue;
      const b = el('button', `seg-mark mark-${m.kind}${m.kind === 'like' ? ` mark-like-${n}` : ''}`);
      b.type = 'button';
      b.dataset.mark = m.kind;
      b.append(svgIcon(m.icon));
      if (m.kind === 'like') {
        if (n > 1) b.append(el('span', 'seg-mark-n', `×${n}`));
        b.title = `${LIKE_LABELS[n]}（このマスへ）`;
      } else if (m.kind === 'bookmark') {
        b.title = 'ブックマーク（このマスへ）';
      } else {
        b.append(el('span', 'seg-mark-n', String(n)));
        const recent = m.kind === 'comments'
          ? `：${rec.comments.slice(-3).map((c) => `「${[...c.text.replace(/\s+/g, ' ')].slice(0, 30).join('')}${[...c.text].length > 30 ? '…' : ''}」`).join(' ')}` : '';
        b.title = `${m.label} ${n} ${m.kind === 'images' ? '枚' : '件'}${recent}｜クリックでサイドバーに表示（← で全文に戻る）`;
      }
      marks.push(b);
    }
    if (!marks.length) return null;
    const box = el('span', 'seg-marks');
    box.append(...marks);
    return box;
  }

  // 全文の上の集計（いいね・コメントなどのある部分の数）。押すと、今の部分の次にある、その印の部分へ移る
  function renderSeriesStats(list) {
    const chips = [];
    for (const m of SEG_MARKS) {
      const parts = list.filter(([, r]) => m.count(r) > 0);
      if (!parts.length) continue;
      const total = m.kind === 'like' || m.kind === 'bookmark' ? parts.length : parts.reduce((a, [, r]) => a + m.count(r), 0);
      const top = m.kind === 'like' ? Math.max(...parts.map(([, r]) => r.likedLevel)) : 0;
      const cls = { like: `chip-like-${top}`, bookmark: 'chip-bookmark', comments: 'chip-comment', layer: 'chip-layer', links: 'chip-link', images: 'chip-image', web: 'chip-web' }[m.kind];
      const b = el('button', `chip ${cls} series-jump`);
      b.type = 'button';
      b.dataset.jump = m.kind;
      b.append(svgIcon(m.icon), document.createTextNode(`${m.short || m.label} ${total}`));
      b.title = `${m.label}のある部分へ順に移動（${parts.length} か所）`;
      chips.push(b);
    }
    $('sideSeriesStats').replaceChildren(...chips);
    $('sideSeriesStats').hidden = chips.length === 0;
  }

  // 今の部分の次にある（最後まで行けば最初から）、その印の部分へ
  function jumpSeriesMark(kind) {
    const m = SEG_MARKS.find((x) => x.kind === kind);
    const list = seriesWhere ? seriesWhere.list : [];
    if (!m || !list.length) return;
    const key = seriesCurrentKey();
    const i = key ? list.findIndex(([k]) => k === key) : -1;
    for (let d = 1; d <= list.length; d++) {
      const [k, r] = list[(i + d + list.length) % list.length];
      if (m.count(r) > 0) {
        goSeriesSeg(k);
        return;
      }
    }
  }

  // 部分の印（コメント・周りのメモ・関連・画像・リンク）→ そのマスのその内容をサイドバーに。← で全文に戻る
  function openSeriesMark(key, kind) {
    if (kind === 'like' || kind === 'bookmark') {
      goSeriesSeg(key);
      return;
    }
    const where = seriesWhere;
    const item = where && where.list.find(([k]) => k === key);
    const layer = item && layerAt(where.keys);
    if (!layer) return;
    if (where.here && !reading) selectCell(key); // 全文に戻ったとき、その部分を示す
    side.scroll = 'jump';
    showSide({ rec: item[1], layer, key, tab: kind }, { push: true });
    if (where.here) revealCell(key);
  }

  function renderSideSeries() {
    const place = seriesPlace(side.series);
    seriesWhere = place;
    const list = place ? place.list : [];
    if (seriesHoverKey && !(place && place.here && list.some(([k]) => k === seriesHoverKey))) setSeriesHover(null);
    const tab = side.seriesTab === 'images' ? 'images' : 'text';
    $('sideSeriesEmpty').hidden = list.length > 0;
    $('sideSeriesBar').hidden = list.length === 0;
    $('sideSeriesTabs').hidden = list.length === 0;
    $('sideSeriesText').hidden = list.length === 0 || tab !== 'text';
    $('sideSeriesImages').hidden = list.length === 0 || tab !== 'images';
    for (const b of $('sideSeriesTabs').querySelectorAll('[data-series-tab]')) b.setAttribute('aria-selected', String(b.dataset.seriesTab === tab));
    $('sideSeriesImageCount').textContent = `(${list.reduce((a, [, r]) => a + imagesOf(r).length, 0)})`;
    renderSeriesStats(list);
    if (!list.length) {
      $('sideSeriesSub').textContent = '';
      $('sideSeriesText').replaceChildren();
      return;
    }
    if (tab === 'images') renderSeriesImages(list);
    const paras = seriesParagraphs(list);
    const chars = countChars(seriesText(paras));
    const labels = pathLabels(place.keys);
    const where = labels.length ? `${labels.join(' › ')} の周り` : 'ノート直下';
    $('sideSeriesSub').textContent = `${list.length} マス・${chars.toLocaleString()} 字｜${where}${place.here ? '' : '（部分をクリックで移動）'}`;
    const box = $('sideSeriesText');
    if (tab === 'text') box.replaceChildren(...paras.map((p) => {
      const block = el(p.head ? 'h3' : 'p', p.head ? 'series-head' : 'series-para');
      p.items.forEach((it, i) => {
        if (i) block.append(document.createTextNode(RB.seam(p.items[i - 1].rec.text, it.rec.text)));
        const seg = el('span', 'seg');
        seg.dataset.key = it.key;
        seg.dataset.n = String(it.rec.seq.n);
        seg.title = `${it.rec.seq.n} 番目のマス（${formatCoord(it.key)}）｜クリックでこのマスへ`;
        const num = el('span', 'seg-n', String(it.rec.seq.n));
        num.setAttribute('aria-hidden', 'true');
        // 番号と印（いいね・コメントなど）は部分の頭にまとめる（行の端で離れて、次の部分の印に見えないように）
        const lead = el('span', 'seg-lead');
        const marks = segMarks(it.rec);
        lead.append(num, ...(marks ? [marks] : []));
        seg.append(lead, document.createTextNode(it.rec.text));
        if (it.rec.likedLevel > 0) seg.dataset.like = String(it.rec.likedLevel); // いいねした部分は、蛍光ペンのように色を付ける
        block.append(seg);
      });
      return block;
    }));
    const scroll = side.scroll || null;
    side.scroll = null;
    markSeriesCurrent({ scroll });
  }

  // 強調する部分のマス：読書モードなら読んでいるマス、そうでなければ選んでいるマス（その文章のマスのときだけ）
  function seriesCurrentKey() {
    if (!side || !side.series || !seriesWhere || !seriesWhere.here) return null;
    const key = reading && reading.id === side.series ? reading.key : selectedKey;
    const rec = key && !isCenter(key) ? memos.get(key) : null;
    return rec && rec.seq && rec.seq.id === side.series ? key : null;
  }

  const segOf = (key) => (key ? $('sideSeriesText').querySelector(`.seg[data-key="${CSS.escape(key)}"]`) : null);

  // scroll：'jump'（すぐ）／'smooth'（すばやくなめらかに）で、その部分がサイドバーの真ん中あたりに来るように全文を送る。
  // 画像のタブでは、今のマスの画像のまとまりを強調して、真ん中あたりへ送る
  function markSeriesCurrent({ scroll = null } = {}) {
    const box = $('sideSeriesText');
    for (const seg of box.querySelectorAll('.seg.is-current')) seg.classList.remove('is-current');
    const list = seriesWhere ? seriesWhere.list : [];
    const key = seriesCurrentKey();
    const cur = segOf(key);
    if (cur) cur.classList.add('is-current');
    box.classList.toggle('has-current', !!cur);
    const imgBox = $('sideSeriesImages');
    let group = null;
    for (const g of imgBox.querySelectorAll('.series-img-group')) {
      const on = !!key && g.dataset.key === key;
      g.classList.toggle('is-current', on);
      if (on) group = g;
    }
    imgBox.classList.toggle('has-current', !!group);
    if (side && side.seriesTab === 'images') {
      if (group && scroll) scrollSegIntoView(group, scroll, imgBox);
      const i = key ? list.findIndex(([k]) => k === key) : -1;
      $('sideSeriesPos').textContent = i >= 0 ? `${i + 1} / ${list.length} マス目${group ? '' : '（画像なし）'}` : 'マスを選ぶと、その画像を強調します';
      $('sideSeriesPrev').disabled = i === 0 || !list.length;
      $('sideSeriesNext').disabled = i === list.length - 1 || !list.length;
      return;
    }
    const i = key ? list.findIndex(([k]) => k === key) : -1;
    $('sideSeriesPos').textContent = i >= 0 ? `${i + 1} / ${list.length} マス目` : 'マスを選ぶと、その部分を強調します';
    $('sideSeriesPrev').disabled = i === 0 || !list.length;
    $('sideSeriesNext').disabled = i === list.length - 1 || !list.length;
    if (cur && scroll) scrollSegIntoView(cur, scroll);
  }

  // 選んでいる部分は、いつもサイドバーの真ん中あたり（ほぼ定位置）に置き、行のほうを動かす。
  // 最後の部分も真ん中まで上げられるよう、全文の後ろに高さの半分の余白を付ける（最初の部分は上の端のまま）
  function scrollSegIntoView(seg, how, box = $('sideSeriesText')) {
    box.style.setProperty('--series-tail', `${Math.round(box.clientHeight / 2)}px`);
    const b = box.getBoundingClientRect();
    const r = seg.getBoundingClientRect();
    // 部分の中ほどを真ん中に。とても長い部分は、頭が上から 1 割のところに来るように
    const offset = r.height > b.height * 0.7 ? b.height * 0.1 : (b.height - r.height) / 2;
    const smooth = how === 'smooth' && !matchMedia('(prefers-reduced-motion: reduce)').matches;
    scrollSeriesTo(box.scrollTop + (r.top - b.top) - offset, smooth, box);
  }

  // すばやいスクロール（ブラウザのなめらかなスクロールより短く、離れているほど少しだけ長く）。新しい移動が来たら切り替える
  let seriesScrollFrame = 0;
  function scrollSeriesTo(target, smooth, box = $('sideSeriesText')) {
    cancelAnimationFrame(seriesScrollFrame);
    const to = Math.round(Math.max(0, Math.min(target, box.scrollHeight - box.clientHeight)));
    const from = box.scrollTop;
    if (!smooth || Math.abs(to - from) < 2) {
      box.scrollTop = to;
      return;
    }
    const t0 = performance.now();
    const dur = Math.min(240, 120 + Math.abs(to - from) * 0.12);
    const step = (now) => {
      const k = Math.min(1, (now - t0) / dur);
      box.scrollTop = from + (to - from) * (1 - (1 - k) ** 3); // 早く動き出して、ゆっくり止まる
      if (k < 1) seriesScrollFrame = requestAnimationFrame(step);
    };
    seriesScrollFrame = requestAnimationFrame(step);
  }

  // 文章のマスの画像 [{ key, rec, img }]（読む順）。マスが別の階層にあるときは key なし
  function seriesImageEntries(id) {
    const place = seriesPlace(id);
    return place ? place.list.flatMap(([key, rec]) => imagesOf(rec).map((img) => ({ key: place.here ? key : null, rec, img }))) : [];
  }

  // 画像のタブ：画像のあるマスごとに、番号・本文の頭・画像の一覧（読む順）
  function renderSeriesImages(list) {
    const box = $('sideSeriesImages');
    const groups = list.filter(([, r]) => imagesOf(r).length);
    const firstLine = (rec) => (rec.text.split('\n').find((l) => l.trim()) || '').trim();
    const sig = groups.map(([k, r]) => `${k}#${r.seq.n}:${firstLine(r).slice(0, 60)}:${imagesOf(r).map((i) => `${i.id}:${i.file}:${i.caption || ''}`).join(',')}`).join('|');
    if (box._sig === sig) return; // 中身が同じなら作り直さない（画像を読み直さない）
    box._sig = sig;
    if (!groups.length) {
      box.replaceChildren(el('p', 'thread-empty', 'この文章のマスには、まだ画像がありません。マスを選んで画像を Ctrl+V で貼り付けたり、マスへドロップしたりすると添付できます。'));
      return;
    }
    box.replaceChildren(...groups.map(([key, rec]) => {
      const sec = el('section', 'series-img-group');
      sec.dataset.key = key;
      const head = el('button', 'series-img-head');
      head.type = 'button';
      head.dataset.go = key;
      head.title = `${rec.seq.n} 番目のマス（${formatCoord(key)}）へ`;
      const n = el('span', 'seg-n', String(rec.seq.n));
      head.append(n, el('span', 'series-img-text', firstLine(rec) || '（本文なし）'), el('span', 'series-img-count', `画像 ${imagesOf(rec).length}`));
      const ul = el('ul', 'side-images series-img-grid');
      ul.append(...imagesOf(rec).map((img) => {
        const li = el('li', 'side-image');
        li.dataset.key = key;
        li.dataset.id = img.id;
        const open = el('button', 'side-image-open');
        open.type = 'button';
        open.title = `${img.caption || img.name || '画像'}（クリックで大きく表示。← → でこの文章の画像を順に見られます）`;
        const pic = el('img');
        pic.src = attUrl(img.thumb || img.file);
        pic.alt = img.caption || img.name || '';
        pic.loading = 'lazy';
        pic.decoding = 'async';
        open.append(pic);
        li.append(open, el('span', 'side-image-cap', img.caption || img.name || ''));
        return li;
      }));
      sec.append(head, ul);
      return sec;
    }));
  }

  {
    const imgBox = $('sideSeriesImages');
    imgBox.addEventListener('wheel', () => cancelAnimationFrame(seriesScrollFrame), { passive: true });
    imgBox.addEventListener('click', (e) => {
      if (!side || !side.series) return;
      const go = e.target.closest('[data-go]');
      if (go) {
        goSeriesSeg(go.dataset.go);
        return;
      }
      const item = e.target.closest('.side-image');
      const entry = item && seriesWhere && seriesWhere.list.find(([k]) => k === item.dataset.key);
      if (!entry) return;
      // そのマスへ移って（読書モードならそこまで進んで）、画像を大きく。窓の ← → でこの文章の画像を順に
      goSeriesSeg(item.dataset.key);
      openViewer(entry[1], item.dataset.id, { series: side.series });
    });
    $('sideSeriesTabs').addEventListener('click', (e) => {
      const b = e.target.closest('[data-series-tab]');
      if (!b || !side || !side.series || (side.seriesTab || 'text') === b.dataset.seriesTab) return;
      side.seriesTab = b.dataset.seriesTab;
      lastSeriesTab = side.seriesTab;
      side.scroll = 'jump';
      renderSide();
    });
  }

  // マスを選んだ（読書モードで進んだ）とき：全文の強調を追いかける。別の分けた文章のマスなら、その全文に切り替える
  function followSeries(key) {
    if (!side || !side.series) return;
    const rec = key && !isCenter(key) ? getRecord(key) : null;
    if (rec && rec.seq && rec.seq.id !== side.series) {
      side.series = rec.seq.id;
      side.scroll = 'jump';
      $('sideSeriesText').scrollTop = 0;
      $('sideSeriesImages').scrollTop = 0;
      renderSide();
      refreshAllCells();
      return;
    }
    markSeriesCurrent({ scroll: 'smooth' });
  }

  // 全文の部分 → そのマスへ（読書モードならそこまで進む。別の階層にあれば、その階層を開く）
  function goSeriesSeg(key) {
    if (!seriesWhere) return;
    const rec = seriesWhere.list.find(([k]) => k === key);
    if (!rec) return;
    if (!seriesWhere.here) {
      jumpTo(key, seriesWhere.keys);
      selectCell(key);
      return;
    }
    if (reading && reading.id === side.series) {
      goReading(rec[1].seq.n);
      return;
    }
    if (activeTab !== 'grid') setTab('grid');
    selectCell(key);
    const { q, r } = H.parseKey(key);
    const p = H.hexToPixel(q, r, HEX_SIZE);
    if (camera.zoom >= OVERVIEW_BELOW && cellOnScreen(key)) flashCell(key);
    else animateCameraTo(p.x, p.y, () => flashCell(key), camera.zoom < OVERVIEW_BELOW ? 1 : camera.zoom);
  }

  function stepSeries(d) {
    const list = seriesWhere ? seriesWhere.list : [];
    if (!list.length) return;
    const key = seriesCurrentKey();
    const i = key ? list.findIndex(([k]) => k === key) : -1;
    const j = i < 0 ? (d > 0 ? 0 : list.length - 1) : i + d;
    if (j >= 0 && j < list.length) goSeriesSeg(list[j][0]);
  }

  // 全文の部分とマスの対応を、マウスを乗せている間だけ両方に示す
  function setSeriesHover(key, { fromCell = false } = {}) {
    if (key === seriesHoverKey && !fromCell) return;
    const prev = seriesHoverKey;
    seriesHoverKey = fromCell ? null : key;
    if (prev && prev !== seriesHoverKey) refreshCell(prev);
    if (seriesHoverKey) refreshCell(seriesHoverKey);
    const box = $('sideSeriesText');
    for (const seg of box.querySelectorAll('.seg.is-hover')) seg.classList.remove('is-hover');
    if (fromCell && key) {
      const seg = segOf(key);
      if (seg) seg.classList.add('is-hover');
    }
  }

  async function copySeriesText() {
    const list = seriesWhere ? seriesWhere.list : [];
    if (!api || !list.length) return;
    const text = seriesText(seriesParagraphs(list));
    const t = nowIso();
    try {
      await ipc(api.writeClip({ v: 1, nonce: uuid(), cut: false, text, record: { text, createdAt: t, updatedAt: t, likedLevel: 0, liked: false, bookmarked: false, comments: [] } }));
    } catch (err) {
      toast(`コピーできませんでした：${err.message}`, 'error', 5000);
      return;
    }
    if (cutSource) {
      cutSource = null; // クリップボードの中身が変わったので、切り取りは取りやめ
      refreshAllCells();
    }
    toast(`全文（${countChars(text).toLocaleString()} 字）をコピーしました。ほかのアプリにも貼り付けられます（マスで Ctrl+Shift+V なら、もう一度分けて並べます）`, 'info', 4500);
  }

  {
    const box = $('sideSeriesText');
    box.addEventListener('click', (e) => {
      const seg = e.target.closest('.seg');
      if (!seg || !side || !side.series) return;
      const mark = e.target.closest('[data-mark]');
      if (mark) {
        openSeriesMark(seg.dataset.key, mark.dataset.mark);
        return;
      }
      const sel = window.getSelection();
      if (sel && !sel.isCollapsed && sel.toString().trim()) return; // 文字を範囲選択したとき（コピーしたい）は移動しない
      goSeriesSeg(seg.dataset.key);
    });
    box.addEventListener('pointerover', (e) => {
      const seg = e.target.closest('.seg');
      setSeriesHover(seg && seriesWhere && seriesWhere.here ? seg.dataset.key : null);
    });
    box.addEventListener('pointerleave', () => setSeriesHover(null));
    box.addEventListener('wheel', () => cancelAnimationFrame(seriesScrollFrame), { passive: true }); // 自分でスクロールしたら、そちらを優先
    $('sideSeriesPrev').addEventListener('click', () => stepSeries(-1));
    $('sideSeriesNext').addEventListener('click', () => stepSeries(1));
    $('sideSeriesCopy').addEventListener('click', copySeriesText);
    $('sideSeriesStats').addEventListener('click', (e) => {
      const b = e.target.closest('[data-jump]');
      if (b && side && side.series) jumpSeriesMark(b.dataset.jump);
    });
    // マスにマウスを乗せると、全文のその部分が光る
    let hoverCellKey = null;
    stage.addEventListener('pointerover', (e) => {
      if (!side || !side.series) return;
      const cell = e.target.closest('.cell');
      const key = cell ? cell._key : null;
      if (key === hoverCellKey) return;
      hoverCellKey = key;
      const rec = key && !isCenter(key) && seriesWhere && seriesWhere.here ? memos.get(key) : null;
      setSeriesHover(rec && rec.seq && rec.seq.id === side.series ? key : null, { fromCell: true });
    });
    stage.addEventListener('pointerleave', () => {
      hoverCellKey = null;
      if (side && side.series) setSeriesHover(null, { fromCell: true });
    });
  }

  // サイドバーの一覧の1件（周りのメモ・関連するメモ）。path はそのメモがある階層までの道筋
  // いいね・ブックマークしたメモの一覧（ノート全体・下の階層も含む）。付けた時刻の新しい順に、日ごとの見出しで区切る。
  // 時刻の記録がない（この機能より前に付けた）ものは最後に、更新の新しい順で並べる
  function renderSideList() {
    $('sideListMore').hidden = true;
    $('sideSearchCtl').hidden = side.list !== 'search';
    $('sideDueCtl').hidden = side.list !== 'due';
    $('sideShelfCtl').hidden = side.list !== 'shelf';
    $('sideTrashCtl').hidden = side.list !== 'trash';
    $('sideTodayCtl').hidden = side.list !== 'today';
    $('sideDendCtl').hidden = side.list !== 'dendrites';
    $('sideStatsCtl').hidden = side.list !== 'stats';
    $('sidePocketCtl').hidden = side.list !== 'pocket';
    if (side.list === 'pocket') {
      renderSidePocket();
      return;
    }
    if (side.list === 'search') {
      renderSideSearch();
      return;
    }
    if (side.list === 'due') {
      renderSideDueList();
      return;
    }
    if (side.list === 'shelf') {
      renderSideShelf();
      return;
    }
    if (side.list === 'trash') {
      renderSideTrash();
      return;
    }
    if (side.list === 'today') {
      renderSideToday();
      return;
    }
    if (side.list === 'dendrites') {
      renderSideDendrites();
      return;
    }
    if (side.list === 'stats') {
      renderSideStats();
      return;
    }
    if (side.list === 'history') {
      renderSideHistory();
      return;
    }
    if (side.list === 'overview') {
      renderSideOverview();
      return;
    }
    $('sideHistoryCtl').hidden = true;
    const likes = side.list === 'likes';
    const word = likes ? 'いいね' : 'ブックマーク';
    const timed = [];
    const untimed = [];
    forEachMemo((rec, key, keys) => {
      const on = likes ? rec.likedLevel > 0 && (!side.filter || rec.likedLevel === side.filter) : rec.bookmarked;
      if (!on) return;
      const at = likes ? rec.likedAt : rec.bookmarkedAt;
      (at ? timed : untimed).push({ rec, key, keys, at });
    });
    const t = (iso) => Date.parse(iso) || 0;
    timed.sort((a, b) => t(b.at) - t(a.at));
    untimed.sort((a, b) => t(b.rec.updatedAt) - t(a.rec.updatedAt));
    const total = timed.length + untimed.length;

    $('sideFilter').hidden = !likes;
    for (const b of $('sideFilter').querySelectorAll('button')) b.setAttribute('aria-pressed', String(Number(b.dataset.filter) === (side.filter || 0)));
    $('sideListSub').textContent = total ? `${word}した新しい順・${total} 件（下の階層のメモも含む）` : '';

    const frag = document.createDocumentFragment();
    let group = null;
    let ul = null;
    const add = ({ rec, key, keys, at }, label) => {
      if (label !== group) {
        group = label;
        frag.append(el('h3', 'side-day', label));
        ul = el('ul', 'side-list');
        frag.append(ul);
      }
      const li = buildSideItem(rec, key, keys, {
        label: locationLabel(keys, key), labelClass: 'side-dir is-where', coord: false,
        time: at ? { text: `${word} ${formatRelative(at)}`, title: `${word}：${formatFull(at)}` } : null,
        unmark: likes ? 'like' : 'bookmark',
      });
      if (side.focus && rec === side.focus) li.classList.add('is-current');
      ul.append(li);
    };
    for (const it of timed) add(it, dayLabel(it.at));
    for (const it of untimed) add(it, 'それ以前（付けた日時の記録なし）');
    $('sideListItems').replaceChildren(frag);
    const empty = $('sideListEmpty');
    empty.hidden = total > 0;
    empty.textContent = likes && side.filter ? `いいね ×${side.filter} のメモはまだありません。` : `まだ${word}したメモはありません。`;

    // 開いたときは、右クリックしたマスのメモが見えるように（一覧の中だけをスクロール）
    if (side.scrollToFocus) {
      side.scrollToFocus = false;
      const cur = $('sideListItems').querySelector('.side-item.is-current');
      const view = $('sideListView');
      if (cur) {
        const r = cur.getBoundingClientRect();
        const v = view.getBoundingClientRect();
        if (r.top < v.top + 40 || r.bottom > v.bottom) view.scrollTop += r.top - v.top - 48;
      }
    }
  }

  // ---- サイドバー：ノート（ファイル）ごとのメモの作成履歴 ----
  // ノート直下と下の階層のメモを、作った（または更新した）新しい順に日ごとに並べる。開いているノートは今の内容で
  // （書くとすぐ反映）、ほかのノートは保存されている内容を読み込んで見せる。分けて貼り付けた長文のマスは1件にまとめる
  const HISTORY_PAGE = 200;
  const historyLoc = (keys, key) => `${keys.join('|')}#${key}`;
  let historyBoardsSig = '';

  function openHistory(boardId = currentBoardId, { sort = 'created' } = {}) {
    showSide({ list: 'history', board: boardId, sort, limit: HISTORY_PAGE, focusLoc: null, peek: null });
    if (boardId !== currentBoardId) loadHistoryBoard();
  }

  function toggleHistory() {
    if (side && side.list === 'history') closeSide();
    else openHistory();
  }

  // ほかのノートの保存されている中身を読む（読み終わる前に閉じたり別のノートを選んだりしたら捨てる）
  async function loadHistoryBoard() {
    const target = side;
    const id = target.board;
    target.peek = { id, loading: true };
    renderSide();
    let peek;
    try {
      const res = await ipc(api.peekBoard(id));
      peek = { id, root: toLayer(res.store) };
    } catch (err) {
      peek = { id, error: err.message };
    }
    if (side !== target || target.board !== id) return;
    target.peek = peek;
    renderSide();
  }

  // タブの順に、子ノートは字下げして
  function boardsInTreeOrder() {
    const out = [];
    const walk = (parentId, depth) => {
      for (const b of siblingBoards(parentId)) {
        out.push({ b, depth });
        walk(b.id, depth + 1);
      }
    };
    walk(null, 0);
    return out;
  }

  function renderHistoryBoards() {
    const list = boardsInTreeOrder();
    const sig = JSON.stringify([currentBoardId, list.map(({ b, depth }) => [b.id, b.name, depth])]);
    const select = $('sideHistoryBoard');
    if (sig !== historyBoardsSig) {
      // 選択肢は変わったときだけ作り直す（開いている選択肢が、書くたびに閉じないように）
      historyBoardsSig = sig;
      select.replaceChildren(...list.map(({ b, depth }) => {
        const o = el('option', '', `${'　'.repeat(depth)}${depth ? '└ ' : ''}${b.name}${b.id === currentBoardId ? '（開いているノート）' : ''}`);
        o.value = b.id;
        return o;
      }));
    }
    select.value = side.board;
  }

  function renderSideHistory() {
    $('sideFilter').hidden = true;
    $('sideHistoryCtl').hidden = false;
    for (const b of $('sideHistorySort').querySelectorAll('button')) b.setAttribute('aria-pressed', String(b.dataset.sort === side.sort));
    renderHistoryBoards();
    const own = side.board === currentBoardId;
    const peek = side.peek && side.peek.id === side.board ? side.peek : null;
    const root = own ? rootLayer : peek && peek.root;
    const board = boardById(side.board);
    const empty = $('sideListEmpty');
    if (!root) {
      $('sideListSub').textContent = '';
      $('sideListItems').replaceChildren();
      empty.hidden = false;
      empty.textContent = !board ? 'このノートは見つかりません（削除されました）。'
        : peek && peek.error ? `このノートを読み込めませんでした：${peek.error}` : '読み込んでいます…';
      return;
    }

    // メモを集める（分けて貼り付けた長文は、同じ階層の同じ文章を1件に）
    const t = (iso) => Date.parse(iso) || 0;
    const entries = [];
    const series = new Map();
    forEachMemo((rec, key, keys) => {
      if (rec.seq) {
        const id = `${keys.join('|')}#${rec.seq.id}`;
        const g = series.get(id);
        if (g) {
          g.count++;
          if (rec.seq.n < g.rec.seq.n) Object.assign(g, { rec, key });
          if (t(rec.createdAt) < t(g.created)) g.created = rec.createdAt;
          if (t(rec.updatedAt) > t(g.updated)) g.updated = rec.updatedAt;
          return;
        }
        const e = { rec, key, keys, count: 1, seq: rec.seq.id, created: rec.createdAt, updated: rec.updatedAt };
        series.set(id, e);
        entries.push(e);
        return;
      }
      entries.push({ rec, key, keys, count: 1, created: rec.createdAt, updated: rec.updatedAt });
    }, root);
    const by = side.sort === 'updated' ? 'updated' : 'created';
    entries.sort((a, b) => t(b[by]) - t(a[by]));

    const word = by === 'created' ? '作成' : '更新';
    const name = board ? board.name : 'ノート';
    $('sideListSub').textContent = entries.length
      ? `「${name}」のメモ ${entries.length} 件を${word}の新しい順に（下の階層も含む${series.size ? '。分けて貼り付けた長文は1件にまとめています' : ''}）${own ? '' : '。保存されている内容を表示しています'}`
      : '';
    const clock = (iso) => {
      const d = new Date(iso);
      return Number.isNaN(d.getTime()) ? '' : d.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
    };

    const frag = document.createDocumentFragment();
    let group = null;
    let ul = null;
    let focused = null;
    for (const e of entries.slice(0, side.limit)) {
      const at = e[by];
      const label = dayLabel(at);
      if (label !== group) {
        group = label;
        frag.append(el('h3', 'side-day', label));
        ul = el('ul', 'side-list');
        frag.append(ul);
      }
      const extra = [];
      if (e.seq) {
        const c = el(own ? 'button' : 'span', `chip chip-series${own ? ' side-mini' : ''}`);
        c.append(svgIcon('layers'), document.createTextNode(`長文 ${e.count} マス`));
        if (own) {
          c.type = 'button';
          c.title = '分けて貼り付けた文章の全文をサイドバーで見る（← で履歴に戻る）';
          Object.assign(c.dataset, { series: e.seq, key: e.key, path: e.keys.join('|') });
        } else c.title = `分けて貼り付けた文章（${e.count} マス）`;
        extra.push(c);
      }
      const li = buildSideItem(e.rec, e.key, e.keys, {
        label: locationLabel(e.keys, e.key, root), labelClass: 'side-dir is-where', coord: false,
        time: { text: `${word} ${clock(at)}`, title: `作成：${formatFull(e.created)}\n更新：${formatFull(e.updated)}` },
        board: own ? null : side.board, extra,
      });
      if (side.focusLoc === historyLoc(e.keys, e.key)) {
        li.classList.add('is-current');
        focused = li;
      }
      ul.append(li);
    }
    $('sideListItems').replaceChildren(frag);
    const rest = entries.length - side.limit;
    $('sideListMore').hidden = rest <= 0;
    $('sideListMore').textContent = `もっと見る（残り ${rest} 件）`;
    empty.hidden = entries.length > 0;
    empty.textContent = 'このノートにはまだメモがありません。';
    if (side.scrollToFocus && focused) {
      side.scrollToFocus = false;
      const view = $('sideListView');
      const r = focused.getBoundingClientRect();
      const v = view.getBoundingClientRect();
      if (r.top < v.top + 40 || r.bottom > v.bottom) view.scrollTop += r.top - v.top - 48;
    }
  }

  // ほかのノートのメモ → そのノートを開いて（履歴は開いたまま）、そのマスへ
  async function goToBoardMemo(boardId, key, keys) {
    await switchBoard(boardId);
    if (currentBoardId !== boardId) return;
    if (side && (side.list === 'history' || side.list === 'overview')) {
      side.focusLoc = historyLoc(keys, key);
      side.scrollToFocus = true;
      renderSide();
    }
    jumpTo(key, keys);
  }

  // 履歴の「長文 N マス」→ その文章のある階層へ移って、全文をサイドバーに（← で履歴に戻る）
  function openSeriesFromHistory(id, key, keys) {
    jumpTo(key, keys);
    selectCell(key);
    showSide({ series: id, scroll: 'jump' }, { push: true });
  }

  // ---- サイドバー：ノートの全体 ----
  // ノートの顔（原点のメモ）・ミニマップ（ノート直下のメモの並び）・原点から近い順の一覧・数。
  // 開いているノートは今の内容で、ほかのノートは保存されている内容を読んで見せる（作成履歴と同じ読み方）
  function openOverview(boardId = currentBoardId) {
    showSide({ list: 'overview', board: boardId, limit: 120, focusLoc: null, peek: null });
    if (boardId !== currentBoardId) loadHistoryBoard();
    if (hive.open) renderHive();
  }

  // ノートのハニカムのセルの右クリック：そのノートの全体（もう一度で閉じる）
  function toggleOverview(boardId) {
    if (side && side.list === 'overview' && side.board === boardId) closeSide();
    else openOverview(boardId);
  }

  const OV_RING_DIRS = { '1,-1': '右上', '1,0': '右', '0,1': '右下', '-1,1': '左下', '-1,0': '左', '0,-1': '左上' };

  function renderSideOverview() {
    $('sideFilter').hidden = true;
    $('sideHistoryCtl').hidden = true;
    const board = boardById(side.board);
    const own = side.board === currentBoardId;
    const peek = side.peek && side.peek.id === side.board ? side.peek : null;
    const root = own ? rootLayer : peek && peek.root;
    const empty = $('sideListEmpty');
    if (!board || !root) {
      $('sideListSub').textContent = board ? boardPath(board.id).map((b) => b.name).join(' › ') : '';
      $('sideListItems').replaceChildren();
      empty.hidden = false;
      empty.textContent = !board ? 'このノートは見つかりません（削除されました）。'
        : peek && peek.error ? `このノートを読み込めませんでした：${peek.error}` : '読み込んでいます…';
      return;
    }

    // 数
    let count = 0;
    let liked = 0;
    let marked = 0;
    let images = 0;
    forEachMemo((rec) => {
      count++;
      if (rec.likedLevel > 0) liked++;
      if (rec.bookmarked) marked++;
      images += imagesOf(rec).length;
    }, root);
    const kids = siblingBoards(board.id).length;
    const parts = [`メモ ${count}（下の階層も含む）`, liked ? `いいね ${liked}` : '', marked ? `ブックマーク ${marked}` : '', images ? `画像 ${images}` : '', kids ? `子ノート ${kids}` : ''].filter(Boolean);
    $('sideListSub').textContent = `${boardPath(board.id).map((b) => b.name).join(' › ')}｜${parts.join('・')}${own ? '' : '｜保存されている内容'}`;

    const frag = document.createDocumentFragment();
    // 開く・メニュー
    const actions = el('div', 'overview-actions');
    const openBtn = el('button', `btn ${own ? '' : 'btn-primary '}overview-open`, own ? '開いているノートです' : 'このノートを開く');
    openBtn.type = 'button';
    openBtn.dataset.overviewOpen = '1';
    openBtn.disabled = own && !hive.open;
    if (own && hive.open) openBtn.textContent = 'このノートのハニカムへ';
    // 区画（写しの作業台）にノートの顔（ノート名・原点のメモの1行目・表紙）を写す
    const faceBtn = el('button', 'btn overview-pocket', '顔を区画に写す');
    faceBtn.type = 'button';
    faceBtn.dataset.overviewPocket = '1';
    faceBtn.title = 'このノートの名前と原点のメモの1行目（表紙があれば表紙）を、写しとして区画に入れる';
    faceBtn.disabled = boardReadOnly;
    const menuBtn = el('button', 'btn overview-menu', 'メニュー…');
    menuBtn.type = 'button';
    menuBtn.dataset.overviewMenu = '1';
    menuBtn.title = '名前の変更・子ノートの作成・並べ替え・削除など';
    actions.append(openBtn, faceBtn, menuBtn);
    frag.append(actions);

    // 原点のメモ（ノートの説明・表紙）
    frag.append(el('h3', 'side-day', '原点のメモ（ノートの説明・表紙）'));
    const origin = root.memos.get('0,0');
    const card = el('button', 'overview-origin');
    card.type = 'button';
    card.dataset.mmKey = '0,0';
    card.title = '原点のマスへ';
    if (origin && !isEmptyRecord(origin)) {
      const cover = origin.cover ? imagesOf(origin).find((img) => img.id === origin.cover) : null;
      if (cover) {
        const pic = el('img', 'overview-origin-cover');
        pic.src = attUrl(cover.thumb || cover.file);
        pic.alt = '';
        pic.loading = 'lazy';
        card.append(pic);
      }
      card.append(el('span', `overview-origin-text${hasText(origin) ? '' : ' is-empty'}`, hasText(origin) ? origin.text : '（本文なし）'));
      const chips = stateChips(origin, { links: false });
      if (chips.length) {
        const row = el('span', 'overview-origin-states');
        row.append(...chips);
        card.append(row);
      }
    } else {
      card.classList.add('is-empty');
      card.append(el('span', 'overview-origin-text is-empty', '原点にはまだメモがありません。原点のマス（0, 0）に書くと、ノートのハニカムのセルに、このノートの説明として出ます。'));
    }
    frag.append(card);

    // ミニマップ
    frag.append(el('h3', 'side-day', 'ミニマップ（ノート直下・押すとそのマスへ）'));
    frag.append(buildMinimap(root));

    // 原点から近い順（周ごと、右上から時計回り）
    const list = [...root.memos].filter(([, r]) => !isEmptyRecord(r)).map(([k, r]) => {
      const pos = H.parseKey(k);
      const p = H.hexToPixel(pos.q, pos.r, 1);
      return { k, r, ring: H.hexDistance(pos, { q: 0, r: 0 }), angle: (Math.atan2(p.x, -p.y) + 2 * Math.PI) % (2 * Math.PI) };
    }).sort((a, b) => a.ring - b.ring || a.angle - b.angle);
    let ring = -1;
    let ul = null;
    let focused = null;
    for (const it of list.slice(0, side.limit)) {
      if (it.ring !== ring) {
        ring = it.ring;
        frag.append(el('h3', 'side-day', ring === 0 ? '原点' : `${ring} 周目`));
        ul = el('ul', 'side-list');
        frag.append(ul);
      }
      const li = buildSideItem(it.r, it.k, [], {
        label: it.ring === 0 ? '原点' : it.ring === 1 ? `${OV_RING_DIRS[it.k]}（${formatCoord(it.k)}）` : formatCoord(it.k),
        labelClass: 'side-dir', coord: false, board: own ? null : side.board,
      });
      if (side.focusLoc === historyLoc([], it.k)) {
        li.classList.add('is-current');
        focused = li;
      }
      ul.append(li);
    }
    $('sideListItems').replaceChildren(frag);
    const rest = list.length - side.limit;
    $('sideListMore').hidden = rest <= 0;
    $('sideListMore').textContent = `もっと見る（残り ${rest} 件）`;
    empty.hidden = list.length > 0;
    empty.textContent = 'このノートにはまだメモがありません。';
    if (side.scrollToFocus && focused) {
      side.scrollToFocus = false;
      const view = $('sideListView');
      const r = focused.getBoundingClientRect();
      const v = view.getBoundingClientRect();
      if (r.top < v.top + 40 || r.bottom > v.bottom) view.scrollTop += r.top - v.top - 48;
    }
  }

  // ミニマップ：ノート直下のメモを六角形の点で（いいねの段階の色・ブックマークの縁・原点の印）。押すとそのマスへ
  function buildMinimap(root) {
    const NS = 'http://www.w3.org/2000/svg';
    const cells = [...root.memos].filter(([, r]) => !isEmptyRecord(r)).slice(0, 3000);
    const pos = (k) => {
      const p = H.parseKey(k);
      return { x: H.SQRT3 * (p.q + p.r / 2), y: 1.5 * p.r };
    };
    const pts = [{ x: 0, y: 0 }, ...cells.map(([k]) => pos(k))];
    let minX = Math.min(...pts.map((p) => p.x)) - 1.2;
    let maxX = Math.max(...pts.map((p) => p.x)) + 1.2;
    let minY = Math.min(...pts.map((p) => p.y)) - 1.3;
    let maxY = Math.max(...pts.map((p) => p.y)) + 1.3;
    // メモが少ないときに六角形が大きくなりすぎないよう、見せる範囲に最小の広さを持たせる（真ん中に寄せる）
    const grow = (lo, hi, min) => (hi - lo >= min ? [lo, hi] : [(lo + hi) / 2 - min / 2, (lo + hi) / 2 + min / 2]);
    [minX, maxX] = grow(minX, maxX, 14);
    [minY, maxY] = grow(minY, maxY, 8);
    const svg = document.createElementNS(NS, 'svg');
    svg.setAttribute('class', 'overview-map');
    svg.setAttribute('viewBox', `${minX} ${minY} ${maxX - minX} ${maxY - minY}`);
    svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', `ミニマップ：ノート直下のメモ ${cells.length} 件`);
    const hexPoints = ({ x, y }, r = 0.94) => Array.from({ length: 6 }, (_, i) => {
      const a = (Math.PI / 180) * (60 * i - 90);
      return `${(x + r * Math.cos(a)).toFixed(3)},${(y + r * Math.sin(a)).toFixed(3)}`;
    }).join(' ');
    // 原点の印（メモが無くても出す）
    const originMark = document.createElementNS(NS, 'polygon');
    originMark.setAttribute('points', hexPoints({ x: 0, y: 0 }, 1));
    originMark.setAttribute('class', 'mm-origin');
    svg.append(originMark);
    for (const [k, r] of cells) {
      const poly = document.createElementNS(NS, 'polygon');
      poly.setAttribute('points', hexPoints(pos(k)));
      const cls = ['mm-cell'];
      if (r.likedLevel > 0) cls.push(`mm-like-${r.likedLevel}`);
      if (r.bookmarked) cls.push('mm-bookmark');
      if (childCount(r)) cls.push('mm-kids');
      poly.setAttribute('class', cls.join(' '));
      poly.dataset.mmKey = k;
      const title = document.createElementNS(NS, 'title');
      title.textContent = `${formatCoord(k)}｜${recordLabel(r, k, 30)}`;
      poly.append(title);
      svg.append(poly);
    }
    const wrap = el('div', 'overview-map-wrap');
    wrap.append(svg);
    return wrap;
  }

  // ノートの全体からマスへ（ほかのノートなら、そのノートを開いてから）
  function goOverviewKey(key) {
    if (side.board !== currentBoardId) {
      if (hive.open) closeHive();
      goToBoardMemo(side.board, key, []);
      return;
    }
    side.focusLoc = historyLoc([], key);
    renderSide();
    jumpTo(key, []);
  }

  // 日ごとの見出し：今日・昨日・M月D日（去年以前は年も）
  function dayLabel(iso) {
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return '日時不明';
    const now = new Date();
    const dayStart = (x) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
    const diff = Math.round((dayStart(now) - dayStart(d)) / 86400000);
    if (diff === 0) return '今日';
    if (diff === 1) return '昨日';
    const md = `${d.getMonth() + 1}月${d.getDate()}日`;
    return d.getFullYear() === now.getFullYear() ? md : `${d.getFullYear()}年${md}`;
  }

  function buildSideItem(rec, key, path, { label, labelClass = 'side-dir', coord = true, unlinkId = null, time: timeInfo = null, unmark = null, board = null, extra = null } = {}) {
    const li = el('li', 'side-item');
    const go = el('button', 'side-item-go');
    go.type = 'button';
    go.dataset.key = key;
    go.dataset.path = path.join('|');
    go.title = 'ハニカムでこのマスへ移動';
    if (board) {
      // ほかのノートのメモ：見る・そのノートを開いてマスへ移る、だけ
      go.dataset.board = board;
      go.title = 'このノートを開いて、このマスへ移動';
    }
    const meta = el('span', 'side-item-meta');
    meta.append(el('span', labelClass, label));
    if (coord) meta.append(el('span', 'card-coord', formatCoord(key)));
    const time = el('span', 'card-time', timeInfo ? timeInfo.text : formatRelative(rec.updatedAt));
    time.title = timeInfo ? timeInfo.title : `更新：${formatFull(rec.updatedAt)}`;
    meta.append(time);
    go.append(meta, el('span', `side-item-text${hasText(rec) ? '' : ' is-empty'}`, hasText(rec) ? rec.text : '（本文なし）'));

    const foot = el('div', 'side-item-foot');
    foot.append(...stateChips(rec, { links: false }));
    if (extra) foot.append(...extra);
    if (board) {
      li.append(go, foot);
      return li;
    }
    // このメモのコメント・周りのメモ・関連をサイドバーで見る
    const mini = (cls, icon, text, title, data) => {
      const b = el('button', `chip ${cls} side-mini`);
      b.type = 'button';
      b.title = title;
      Object.assign(b.dataset, data);
      b.append(svgIcon(icon), document.createTextNode(text));
      foot.append(b);
    };
    const open = (tab) => ({ key, path: path.join('|'), sideOpen: tab });
    const n = rec.comments.length;
    mini('chip-comment', 'comment', n ? `コメント ${n}` : 'コメント', 'このメモのコメントをサイドバーで見る', open('comments'));
    const kids = childCount(rec);
    if (kids) mini('chip-layer', 'hex', `周り ${kids}`, 'このメモの周りのメモをサイドバーで見る', open('layer'));
    const nLinks = linkCount(rec);
    if (nLinks) mini('chip-link', 'link', `関連 ${nLinks}`, 'このメモの関連をサイドバーで見る', open('links'));
    mini('chip-copy', 'copy', '', 'このメモをコピー（マスを選んで Ctrl+V で貼り付け。いいね・コメント・周りのメモごと）', { copy: '1', key, path: path.join('|') });
    if (unlinkId) mini('chip-unlink', 'close', '解除', '関連付けを解除（メモは消えません）', { unlink: unlinkId });
    if (unmark) {
      const what = unmark === 'like' ? 'いいね' : 'ブックマーク';
      mini('chip-unmark', 'close', '外す', `${what}を外す（メモは消えません）`, { unmark, key, path: path.join('|') });
    }
    li.append(go, foot);
    return li;
  }

  function setSideTab(tab) {
    if (!side || side.tab === tab) return;
    side.tab = tab;
    renderSide();
    refreshAllCells();
  }

  // サイドバーでの変更を、表示中のマス・件数・保存に反映する
  function afterSideChange(rec) {
    const key = keyInView(rec);
    if (key) afterRecordChange(key);
    else {
      updateTabCounts();
      scheduleSave();
    }
    renderSide();
  }

  function updateSideComposer() {
    const n = countChars(sideInput.value.trim());
    sideCounter.textContent = `${n} / ${TEXT_LIMIT}`;
    sideCounter.className = `counter${n > TEXT_LIMIT ? ' is-over' : n >= TEXT_WARN ? ' is-warn' : ''}`;
    sidePost.disabled = n === 0 || n > TEXT_LIMIT;
  }

  function postSideComment() {
    const text = sideInput.value.trim();
    if (!side || !text || countChars(text) > TEXT_LIMIT) return;
    let rec = sideRecord();
    if (!rec) {
      // まだメモのないマス：コメントを書いたらメモができる（その階層がまだあるときだけ）
      if (!locateLayer(side.layer)) return;
      rec = side.layer.memos.get(side.key);
      if (!rec) {
        rec = createRecord();
        side.layer.memos.set(side.key, rec);
      }
      side.rec = rec;
    }
    const parent = replyTo && replyTo.where === 'side' && rec.comments.some((c) => c.id === replyTo.id) ? replyTo.id : null;
    rec.comments.push({ id: uuid(), text, createdAt: nowIso(), ...(parent ? { parentId: parent } : {}) });
    if (parent) setReplyTo('side', null);
    sideInput.value = '';
    updateSideComposer();
    afterSideChange(rec);
    refreshAllCells();
    $('sideBody').scrollTop = $('sideBody').scrollHeight;
  }

  function goToSideMemo() {
    if (!sideWhere) return;
    jumpTo(sideWhere.key, sideWhere.keys);
  }

  // このメモを中心にした階層へ（まだ無ければ、六角形ボタンと同じく作る）
  function openSideLayer(layerIndex = 0) {
    if (!side || !sideWhere) return;
    let rec = sideRecord();
    if (!rec) {
      rec = side.layer.memos.get(side.key) || createRecord();
      side.layer.memos.set(side.key, rec);
      side.rec = rec;
    }
    if (sideWhere.keys.length + 1 > MAX_DEPTH) return;
    if (!rec.children) rec.children = newLayer();
    setTab('grid');
    if (setPath([...sideWhere.keys, stepOf(sideWhere.key, layerIndex)], 'in')) flashCell(CENTER_KEY);
    renderSide();
  }

  $('sideClose').addEventListener('click', closeSide);
  $('sideBack').addEventListener('click', () => {
    if (slipEdit) saveSlipEdit({ by: 'interrupt' }); // ← は showSide を通らないので、ここでも先に保存
    cancelPocketDrag();
    const prev = sideHistory.pop();
    if (!prev) return;
    side = prev;
    sideInput.value = prev.draft || '';
    delete prev.draft;
    updateSideComposer();
    renderSide();
    refreshAllCells();
  });
  $('sideGo').addEventListener('click', goToSideMemo);
  $('sideOpenLayer').addEventListener('click', () => openSideLayer(0));
  $('sideTabs').addEventListener('click', (e) => {
    const tab = e.target.closest('.side-tab');
    if (tab) setSideTab(tab.dataset.sideTab);
  });
  sideInput.addEventListener('input', updateSideComposer);
  sideInput.addEventListener('keydown', (e) => {
    if (e.isComposing || e.keyCode === 229) return;
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey || e.shiftKey)) {
      e.preventDefault();
      postSideComment();
    }
  });
  sidePost.addEventListener('click', postSideComment);
  $('sideReplyTo').querySelector('.reply-to-cancel').addEventListener('click', () => setReplyTo('side', null));

  sideThread.addEventListener('click', (e) => {
    const copy = e.target.closest('.comment-copy');
    const del = e.target.closest('.comment-delete');
    const reply = e.target.closest('.comment-reply');
    const fold = e.target.closest('.comment-fold');
    const item = e.target.closest('.comment');
    if (copy) copySideComments([copy.dataset.commentId]);
    else if (del) deleteSideComment(del.dataset.commentId);
    else if (reply) setReplyTo('side', replyTo && replyTo.where === 'side' && replyTo.id === reply.dataset.commentId ? null : reply.dataset.commentId);
    else if (fold) {
      if (collapsedComments.has(fold.dataset.commentId)) collapsedComments.delete(fold.dataset.commentId);
      else collapsedComments.add(fold.dataset.commentId);
      renderSide();
    } else if (item) pickSideComment(item.dataset.commentId);
  });
  sideThread.addEventListener('contextmenu', (e) => {
    const item = e.target.closest('.comment');
    if (!item) return;
    e.preventDefault();
    pickSideComment(item.dataset.commentId);
    openCommentMenu(e, 'side', sideRecord(), sideThread);
  });
  // ---- サイドバーの一覧のメモ（周りのメモ・関連・いいね・ブックマーク）をコピーする ----
  // マスごと（いいね・コメント・その周りのメモも）コピーする。貼り付けはマスのコピーと同じ
  const sideItemMenu = $('sideItemMenu');
  let sideMenuItem = null; // 右クリックした項目の .side-item-go

  // 周りのメモの一覧に並んでいる順（近い周から右上を起点に時計回り）のメモ
  function sideKids() {
    return [...sideLayerList.querySelectorAll('.side-item-go')].map(sideItemRecord).filter(Boolean);
  }

  async function copyMemos(recs) {
    if (!api || !recs.length) return;
    const records = recs.map(serializeRecord);
    const payload = { v: 1, nonce: uuid(), cut: false, record: records[0] };
    if (records.length > 1) {
      payload.records = records;
      payload.text = recs.map((r) => r.text).join('\n\n');
    }
    try {
      await ipc(api.writeClip(payload));
    } catch (err) {
      toast(`コピーできませんでした：${err.message}`, 'error', 5000);
      return;
    }
    if (cutSource) {
      cutSource = null;
      refreshAllCells();
    }
    toast(recs.length > 1
      ? `メモ ${recs.length} 件をコピーしました。マスを選んで Ctrl+V で、そのマスと周りの空いているマスに1件ずつ貼り付けます`
      : 'メモをコピーしました。貼り付けたいマスを選んで Ctrl+V（右クリック →「貼り付け」）', 'info', 4500);
  }

  // ほかのノートのメモの項目（作成履歴・ノートの全体・検索で、別のノートのメモが並んでいるとき）。クリックしたときと同じ見分け方
  const isOtherBoardItem = (go) => !!(go && go.dataset.board && go.dataset.board !== currentBoardId);
  const sideGoLabel = sideItemMenu.querySelector('[data-cmd="go"] span').textContent; // 「ハニカムでこのマスへ移動」

  for (const list of [sideLayerList, sideLinkList, $('sideListItems')]) {
    list.addEventListener('contextmenu', (e) => {
      const item = e.target.closest('.side-item');
      if (!item || item.classList.contains('shelf-item')) return; // 棚の項目は、棚のところでタグボタンのメニューを出す
      e.preventDefault();
      // 移動先のマスを持たない項目（順路のカード・ゴミ箱の項目）は、メニューを出さない
      const go = item.querySelector('.side-item-go');
      if (!go || !go.dataset.key) return;
      sideMenuItem = go;
      go.focus({ preventScroll: true });
      const other = isOtherBoardItem(go);
      // ほかのノートの項目は「このノートを開いて、このマスへ移動」だけ（今のノートの同じ場所の別のメモをコピーしないように）
      sideItemMenu.querySelector('[data-cmd="copy"]').hidden = other;
      sideItemMenu.querySelector('[data-cmd="go"] span').textContent = other ? 'このノートを開いて、このマスへ移動' : sideGoLabel;
      const kids = list === sideLayerList && !other ? sideKids().length : 0;
      const all = sideItemMenu.querySelector('[data-cmd="copy-all"]');
      all.hidden = kids < 2;
      all.querySelector('span').textContent = `すべての周りのメモをコピー（${kids}件）`;
      const pos = { x: e.clientX, y: e.clientY };
      afterRightRelease(e, () => showPopoverAt(sideItemMenu, pos));
    });
  }
  sideItemMenu.addEventListener('mousedown', (e) => e.preventDefault());
  sideItemMenu.addEventListener('click', (e) => {
    const btn = e.target.closest('button[data-cmd]');
    if (!btn || !sideMenuItem) return;
    sideItemMenu.hidePopover();
    const go = sideMenuItem;
    const keys = go.dataset.path ? go.dataset.path.split('|') : [];
    if (isOtherBoardItem(go)) {
      if (btn.dataset.cmd === 'go') goToBoardMemo(go.dataset.board, go.dataset.key, keys);
      return;
    }
    const target = sideItemRecord(go);
    if (btn.dataset.cmd === 'copy' && target) copyMemos([target]);
    else if (btn.dataset.cmd === 'copy-all') copyMemos(sideKids());
    else if (btn.dataset.cmd === 'go') jumpTo(go.dataset.key, keys);
  });
  $('sideCopyAllKids').addEventListener('click', () => copyMemos(sideKids()));

  $('sideCopyAll').addEventListener('click', () => {
    const rec = sideRecord();
    if (rec) copyComments(commentsInTreeOrder(rec.comments)); // 返信のツリーの順（棚の「すべてコピー」と同じ）
  });

  // サイドバーのコメントをコピー（貼り付けるとメモになる）・選ぶ・削除
  const commentMenu = $('commentMenu');
  let sidePicked = null; // クリックで選んだコメントの ID（Ctrl+C でコピー）
  let commentMenuFor = 'side'; // コメントのメニューを開いた場所：'side'（マスのコメント）・'shelf'（棚の項目のコメント）・'pocket'（区画の紙片の全文の中のコメント）
  let commentMenuText = ''; // 右クリックしたときに範囲選択していた文字（「選んだ文字をコピー」）

  // コメントのメニューを開く。root の中で文字を範囲選択していれば「選んだ文字をコピー」も出す
  function openCommentMenu(e, where, rec, root) {
    commentMenuFor = where;
    const sel = window.getSelection();
    commentMenuText = sel && !sel.isCollapsed && root.contains(sel.anchorNode) ? sel.toString().trim() : '';
    commentMenu.querySelector('[data-cmd="copy-text"]').hidden = !commentMenuText;
    const all = commentMenu.querySelector('[data-cmd="copy-all"]');
    all.hidden = !rec || rec.comments.length < 2;
    all.querySelector('span').textContent = `すべてのコメントをコピー（${rec ? rec.comments.length : 0}件）`;
    // 紙片の全文の中のコメントは「区画に写す」を出さない（紙片から紙片の写しは作らない）。削除は出す（07。消えるのは紙片の中だけ）
    const inPocket = where === 'pocket';
    const toPocket = commentMenu.querySelector('[data-cmd="pocket"]');
    toPocket.hidden = inPocket;
    toPocket.disabled = boardReadOnly;
    commentMenu.querySelector('hr').hidden = false;
    const del = commentMenu.querySelector('[data-cmd="delete"]');
    del.hidden = false;
    del.disabled = inPocket && boardReadOnly; // 開くたびに設定し直す（棚・サイドバーの見た目は今のまま）
    const pos = { x: e.clientX, y: e.clientY };
    afterRightRelease(e, () => showPopoverAt(commentMenu, pos));
  }

  function pickSideComment(id) {
    sidePicked = id;
    for (const li of sideThread.querySelectorAll('.comment')) li.classList.toggle('is-picked', li.dataset.commentId === id);
  }

  function unpickSideComment() {
    if (!sidePicked) return;
    sidePicked = null;
    for (const li of sideThread.querySelectorAll('.comment.is-picked')) li.classList.remove('is-picked');
  }

  // 渡した ID の順のまま、サイドバーのコメントをコピー
  function copySideComments(ids) {
    const rec = sideRecord();
    if (!rec) return;
    const byId = new Map(rec.comments.map((c) => [c.id, c]));
    copyComments(ids.map((id) => byId.get(id)).filter(Boolean));
  }

  async function deleteSideComment(id) {
    const rec = sideRecord();
    const replies = rec ? countReplies(id, commentChildren(rec.comments).kids) : 0;
    const ok = await confirmDeleteComment(replies);
    if (ok && rec && side && side.rec === rec) {
      removeComment(rec, id);
      afterSideChange(rec);
    }
  }

  // コメントのメニューの相手：{ where：'side'（マスのコメント）｜'shelf'（棚の項目のコメント）｜'pocket'（区画の紙片の中のコメント）,
  // rec：コメントを持つレコード（今の物。紙片なら紙片の中身）, key：棚の項目の番号札（棚のときだけ。それ以外は null）,
  // id：右クリックした（選んだ）コメントの ID }。相手が無ければ null
  function commentMenuTarget() {
    if (commentMenuFor === 'pocket') {
      const s = pocketPicked && slipById(pocketPicked.slipId);
      return s ? { where: 'pocket', rec: s.rec, key: null, id: pocketPicked.commentId, slipId: s.id } : null;
    }
    if (commentMenuFor === 'shelf') {
      if (!shelfPicked) return null;
      const rec = shelfRecByKey(shelfPicked.rec);
      return rec ? { where: 'shelf', rec, key: shelfPicked.rec, id: shelfPicked.id } : null;
    }
    if (!sidePicked) return null;
    const rec = sideRecord();
    return rec ? { where: 'side', rec, key: null, id: sidePicked } : null;
  }

  commentMenu.addEventListener('mousedown', (e) => e.preventDefault());
  commentMenu.addEventListener('click', (e) => {
    const btn = e.target.closest('button[data-cmd]');
    if (!btn || btn.disabled) return;
    if (btn.dataset.cmd === 'copy-text') {
      commentMenu.hidePopover();
      if (commentMenuText) copyPlainText(commentMenuText, '選んだ文字をコピーしました');
      return;
    }
    commentMenu.hidePopover();
    const t = commentMenuTarget();
    if (!t) {
      if (commentMenuFor === 'shelf' && shelfPicked) shelfGone(); // 棚の項目が別のウィンドウで消えていた
      if (commentMenuFor === 'pocket' && pocketPicked) slipGone();
      return;
    }
    if (btn.dataset.cmd === 'copy') copyComments(t.rec.comments.filter((c) => c.id === t.id));
    else if (btn.dataset.cmd === 'copy-all') copyComments(commentsInTreeOrder(t.rec.comments)); // 返信のツリーの順
    else if (btn.dataset.cmd === 'pocket') {
      if (t.where !== 'pocket') copyCommentToPocket(t);
    } else if (btn.dataset.cmd === 'delete') {
      if (t.where === 'shelf') deleteShelfComment(t.key, t.id);
      else if (t.where === 'side') deleteSideComment(t.id);
      else if (t.where === 'pocket') deletePocketComment(t.slipId, t.id);
    }
  });

  // サイドバーのコメント以外を押したら、選んだコメントを外す（Ctrl+C がマスのコピーに戻る）
  document.addEventListener('pointerdown', (e) => {
    if (sidePicked && !sideThread.contains(e.target) && !commentMenu.contains(e.target)) unpickSideComment();
  }, true);

  function sideItemRecord(el) {
    const layer = layerAt(el.dataset.path ? el.dataset.path.split('|') : []);
    return layer ? layer.memos.get(el.dataset.key) || null : null;
  }

  function onSideListClick(e) {
    const splitPath = (p) => (p ? p.split('|') : []);
    const openLayer = e.target.closest('[data-open-layer]');
    if (openLayer) {
      openSideLayer(Number(openLayer.dataset.openLayer));
      return;
    }
    const copy = e.target.closest('[data-copy]');
    if (copy) {
      const target = sideItemRecord(copy);
      if (target) copyMemos([target]);
      return;
    }
    const unmark = e.target.closest('[data-unmark]');
    if (unmark) {
      const layer = layerAt(splitPath(unmark.dataset.path));
      const target = layer && layer.memos.get(unmark.dataset.key);
      if (target) unmarkFromSide(target, unmark.dataset.unmark);
      return;
    }
    const unlink = e.target.closest('[data-unlink]');
    if (unlink) {
      unlinkFromSide(unlink.dataset.unlink);
      return;
    }
    const linkEdit = e.target.closest('[data-link-edit]');
    if (linkEdit) {
      const rec = sideRecord();
      const link = rec && rec.id ? findLink(rec.id, linkEdit.dataset.linkEdit) : null;
      const r = linkEdit.getBoundingClientRect();
      if (link) openLinkEditor(link, { x: r.left, y: r.bottom + 4 }, rec.id);
      return;
    }
    const open = e.target.closest('[data-side-open]');
    if (open) {
      const layer = layerAt(splitPath(open.dataset.path));
      const target = layer && layer.memos.get(open.dataset.key);
      if (target) showSide({ rec: target, layer, key: open.dataset.key, tab: open.dataset.sideOpen }, { push: true });
      return;
    }
    const series = e.target.closest('[data-series]');
    if (series) {
      openSeriesFromHistory(series.dataset.series, series.dataset.key, splitPath(series.dataset.path));
      return;
    }
    // ノートの全体：ミニマップ・原点のメモ・開く・メニュー
    const mm = e.target.closest('[data-mm-key]');
    if (mm && side && side.list === 'overview') {
      goOverviewKey(mm.dataset.mmKey);
      return;
    }
    const ovOpen = e.target.closest('[data-overview-open]');
    if (ovOpen && side && side.list === 'overview') {
      if (hive.open) closeHive();
      if (side.board !== currentBoardId) switchBoard(side.board);
      return;
    }
    const ovPocket = e.target.closest('[data-overview-pocket]');
    if (ovPocket && side && side.list === 'overview') {
      copyBoardFaceToPocket(side.board);
      return;
    }
    const ovMenu = e.target.closest('[data-overview-menu]');
    if (ovMenu && side && side.list === 'overview') {
      const r = ovMenu.getBoundingClientRect();
      openBoardMenu(side.board, { x: r.left, y: r.bottom + 4 });
      return;
    }
    const go = e.target.closest('.side-item-go');
    if (!go) return;
    const keys = splitPath(go.dataset.path);
    if (side && side.list === 'search' && go.dataset.board && go.dataset.board !== currentBoardId) {
      goToBoardMemo(go.dataset.board, go.dataset.key, keys);
      return;
    }
    if (side && (side.list === 'history' || side.list === 'overview')) {
      side.focusLoc = historyLoc(keys, go.dataset.key); // 押したメモを一覧でも示す
      if (go.dataset.board && go.dataset.board !== currentBoardId) {
        goToBoardMemo(go.dataset.board, go.dataset.key, keys);
        return;
      }
      renderSide();
    }
    jumpTo(go.dataset.key, keys);
  }
  sideLayerList.addEventListener('click', onSideListClick);
  sideLinkList.addEventListener('click', onSideListClick);
  $('sideListItems').addEventListener('click', onSideListClick);
  $('sideListMore').addEventListener('click', () => {
    if (!side || (side.list !== 'history' && side.list !== 'overview' && side.list !== 'search')) return;
    side.limit += side.list === 'search' ? SEARCH_PAGE : HISTORY_PAGE;
    renderSide();
  });
  $('sideHistoryBoard').addEventListener('change', (e) => {
    if (!side || side.list !== 'history') return;
    Object.assign(side, { board: e.target.value, limit: HISTORY_PAGE, focusLoc: null, peek: null });
    $('sideListView').scrollTop = 0;
    if (side.board === currentBoardId) renderSide();
    else loadHistoryBoard();
  });
  $('sideHistorySort').addEventListener('click', (e) => {
    const b = e.target.closest('button[data-sort]');
    if (!b || !side || side.list !== 'history' || side.sort === b.dataset.sort) return;
    Object.assign(side, { sort: b.dataset.sort, limit: HISTORY_PAGE });
    $('sideListView').scrollTop = 0;
    renderSide();
  });
  $('sideFilter').addEventListener('click', (e) => {
    const b = e.target.closest('button[data-filter]');
    if (!b || !side || !side.list) return;
    side.filter = Number(b.dataset.filter);
    renderSide();
  });

  // 一覧から、いいね・ブックマークを外す（メモは消えない）
  function unmarkFromSide(rec, kind) {
    if (kind === 'like') {
      rec.likedLevel = 0;
      rec.liked = false;
      delete rec.likedAt;
    } else {
      rec.bookmarked = false;
      delete rec.bookmarkedAt;
    }
    afterSideChange(rec);
    toast(kind === 'like' ? 'いいねを外しました' : 'ブックマークを外しました');
  }

  // 関連付けの解除（メモは消えない。関連のためだけに残っていた空のメモは片付ける）
  function unlinkFromSide(otherId) {
    const rec = sideRecord();
    if (!rec || !rec.id) return;
    const other = locateById(otherId);
    removeLink(rec.id, otherId);
    for (const r of [rec, other && other.rec]) {
      const k = r && keyInView(r);
      if (k) pruneIfEmpty(k);
    }
    refreshAllCells();
    renderLinks();
    updateTabCounts();
    scheduleSave();
    renderSide();
    toast('関連付けを解除しました');
  }

  // このメモから関連付けを始める（相手はハニカムでクリック。別の階層のメモでもよい）
  $('sideLinkGraph').addEventListener('click', () => openLinkGraph(sideRecord()));
  $('sideNewLink').addEventListener('click', () => {
    const rec = sideRecord();
    if (!rec || !sideWhere) return;
    setTab('grid');
    startLinking(sideWhere.key, rec);
  });

  // サイドバーの開閉でハニカムの見え方がずれないよう、表示位置を補正する（ResizeObserver から）
  let stageLeft = null;
  let stageRight = null;
  function compensateStageShift() {
    const r = stage.getBoundingClientRect();
    if (stageLeft !== null && r.left !== stageLeft && r.right === stageRight && view.w > 0) {
      // 右端はそのままで左端が d 動いた → 画面上の中心は d/2 右へ。同じ場所が同じ位置に見えるよう中心の座標をずらす
      // （ウィンドウの大きさを変えたときは、これまでどおり中心を保つ）
      camera.x += (r.left - stageLeft) / 2 / camera.zoom;
      stopCameraAnimation();
    }
    stageLeft = r.left;
    stageRight = r.right;
  }

  // サイドバーを開いたとき、そのマスが隠れる位置にあれば見えるところまで動かす
  function revealCell(key) {
    const pos = H.parseKey(key);
    if (!pos || activeTab !== 'grid') return;
    const p = H.hexToPixel(pos.q, pos.r, HEX_SIZE);
    const z = camera.zoom;
    const half = view.w / 2 / z;
    const margin = (HEX_W / 2 + 24 / z);
    let x = camera.x;
    if (p.x - margin < camera.x - half) x = p.x - margin + half;
    else if (p.x + margin > camera.x + half) x = p.x + margin - half;
    if (x !== camera.x) animateCameraTo(x, camera.y);
  }

  // ---- 添付：画像とリンク -------------------------------------------------------
  // 画像はデータフォルダの attachments/ に保存し（中身のハッシュが名前）、メモには名前だけを持つ。
  // 表示は専用の読み込み口 hm-att://file/<名前> から。リンクは URL と、取得できたタイトルなどを持つ。

  const COVERS_PREF = 'hexMemo.showCovers';
  const FETCH_PREF = 'hexMemo.fetchLinkInfo';
  const IMAGE_MAX = 25 * 1024 * 1024;
  const THUMB_SIZE = 480;
  // ブラウザ版は、保存領域から作った blob: の URL
  const attUrl = (file) => (api && api.attachmentUrl ? api.attachmentUrl(file) : `hm-att://file/${encodeURIComponent(file)}`);
  const readPref = (key, fallback = true) => {
    try {
      const v = localStorage.getItem(key);
      return v === null ? fallback : v === '1';
    } catch {
      return fallback;
    }
  };
  const writePref = (key, on) => {
    try {
      localStorage.setItem(key, on ? '1' : '0');
    } catch {
      // 覚えられなくても、この起動中は切り替わる
    }
  };
  let showCovers = readPref(COVERS_PREF);
  let fetchLinkInfo = !isWeb && readPref(FETCH_PREF); // ブラウザ版はリンク先の情報を取りに行けない
  const pendingUrls = new Set(); // 情報を取得中のリンク（ID）
  const snapshotting = new Set(); // ページを保存中のリンク（ID）
  let checkingLinks = false;

  const imagesOf = (rec) => (rec && Array.isArray(rec.images) ? rec.images : []);
  const urlsOf = (rec) => (rec && Array.isArray(rec.urls) ? rec.urls : []);
  const coverOf = (rec) => (rec && rec.cover ? imagesOf(rec).find((img) => img.id === rec.cover) || null : null);
  const formatBytes = (n) => (n >= 1024 * 1024 ? `${(n / 1024 / 1024).toFixed(1)}MB` : n >= 1024 ? `${Math.round(n / 1024)}KB` : `${n}B`);

  // 表示中の階層の key のマスのメモ。create なら空きマスにメモを作る（中心は親のメモ）
  function recordAtKey(key, { create = false } = {}) {
    let rec = getRecord(key);
    if (!rec && create && !isCenter(key)) {
      rec = createRecord();
      memos.set(key, rec);
    }
    return rec || null;
  }

  // ---- 画像を添付する ----

  const isImageFile = (f) => !!f && (/^image\/(png|jpeg|gif|webp)$/.test(f.type) || (!f.type && /\.(png|jpe?g|gif|webp)$/i.test(f.name || '')));

  // 縮小版（WebP）と元の大きさ。表示できない形式（HEIC など）なら例外
  async function makeThumb(blob) {
    const bmp = await createImageBitmap(blob);
    try {
      const scale = Math.min(1, THUMB_SIZE / Math.max(bmp.width, bmp.height));
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, Math.round(bmp.width * scale));
      canvas.height = Math.max(1, Math.round(bmp.height * scale));
      canvas.getContext('2d').drawImage(bmp, 0, 0, canvas.width, canvas.height);
      const out = await new Promise((resolve) => canvas.toBlob(resolve, 'image/webp', 0.82));
      return { thumb: out ? new Uint8Array(await out.arrayBuffer()) : null, width: bmp.width, height: bmp.height };
    } finally {
      bmp.close();
    }
  }

  // ファイルを保存して、メモに入れる形（id を除く）にする
  async function storeImages(files) {
    const out = [];
    let skipped = 0;
    for (const f of files) {
      if (!isImageFile(f)) {
        skipped++;
        continue;
      }
      if (f.size > IMAGE_MAX) {
        toast(`「${f.name || '画像'}」は大きすぎます（25MB まで）`, 'warn', 4000);
        continue;
      }
      try {
        const { thumb, width, height } = await makeThumb(f);
        const { image } = await ipc(api.putImage({ data: new Uint8Array(await f.arrayBuffer()), thumb }));
        out.push({ ...image, name: f.name || '画像', width, height });
      } catch (err) {
        console.warn(err);
        skipped++;
      }
    }
    if (skipped) toast(`${skipped} 件は添付できませんでした（PNG・JPEG・GIF・WebP の画像に対応）`, 'warn', 4500);
    return out;
  }

  function addImagesToRecord(rec, stored) {
    if (!stored.length) return;
    if (!Array.isArray(rec.images)) rec.images = [];
    const t = nowIso();
    const added = stored.map((s) => ({ id: uuid(), file: s.file, ...(s.thumb ? { thumb: s.thumb } : {}), name: s.name, type: s.type, size: s.size, width: s.width, height: s.height, addedAt: t }));
    rec.images.push(...added);
    // 本文のないメモに初めて貼った画像は、そのまま表紙にする（画像だけのメモ）
    if (!rec.cover && !hasText(rec)) rec.cover = added[0].id;
  }

  // 表示中の階層の key のマスに添付（空きマスならメモを作る）
  async function attachImagesToKey(key, files) {
    if (!api || !key) return;
    const layer = currentLayer();
    const stored = await storeImages(files);
    if (!stored.length) return;
    let rec = isCenter(key) && path.length ? path[path.length - 1].rec : layer.memos.get(key);
    if (!rec) {
      rec = createRecord();
      layer.memos.set(key, rec);
    }
    addImagesToRecord(rec, stored);
    afterSideChange(rec);
    refreshAllCells();
    if (layer === currentLayer()) flashCell(key);
    toast(`画像を ${stored.length} 枚添付しました`);
  }

  // サイドバーに出しているメモへ添付
  async function attachImagesToSide(files) {
    if (!side || side.list || side.series) return;
    const stored = await storeImages(files);
    if (!stored.length) return;
    const rec = ensureSideRecord();
    if (!rec) return;
    addImagesToRecord(rec, stored);
    afterSideChange(rec);
    refreshAllCells();
    toast(`画像を ${stored.length} 枚添付しました`);
  }

  // サイドバーのメモ（空きマスならメモを作る。その階層がもう無ければ null）
  function ensureSideRecord() {
    let rec = sideRecord();
    if (rec) return rec;
    if (!locateLayer(side.layer)) return null;
    rec = side.layer.memos.get(side.key) || createRecord();
    side.layer.memos.set(side.key, rec);
    side.rec = rec;
    return rec;
  }

  function removeImage(rec, id) {
    rec.images = imagesOf(rec).filter((img) => img.id !== id);
    if (!rec.images.length) delete rec.images;
    if (rec.cover === id) delete rec.cover;
    // この画像と組み合わせた層は、組み合わせだけ外す（セルに書いたメモは残る）
    for (const layer of recLayers(rec)) if (layer.combo && layer.combo.image === id) delete layer.combo;
    afterSideChange(rec);
    refreshAllCells();
    renderCrumbs();
  }

  function setCover(rec, id) {
    if (id) rec.cover = id;
    else delete rec.cover;
    afterSideChange(rec);
    refreshAllCells();
    if (id && !showCovers) toast('表紙にしました（表紙は隠しています。右上の「表紙」で表示）');
  }

  // ---- リンクを添付する ----

  function addUrlToRecord(rec, raw, { fillText = false } = {}) {
    const url = U.stripTracking(String(raw).trim());
    if (!U.isWebUrl(url)) {
      toast('http:// か https:// で始まる URL を入れてください', 'warn');
      return null;
    }
    if (urlsOf(rec).some((u) => u.url === url)) {
      toast('このリンクはすでに付いています');
      return null;
    }
    if (!Array.isArray(rec.urls)) rec.urls = [];
    const entry = { id: uuid(), url, addedAt: nowIso() };
    rec.urls.push(entry);
    afterSideChange(rec);
    refreshAllCells();
    renderLinks();
    if (fetchLinkInfo) fetchUrlInfo(rec, entry, { fillText });
    return entry;
  }

  // 空きマスに URL を貼ったら、そのページのタイトルを本文にしたメモを作る
  function addUrlToKey(key, raw) {
    const existed = !!getRecord(key) && !isEmptyRecord(getRecord(key));
    const rec = recordAtKey(key, { create: true });
    if (!rec) return;
    const entry = addUrlToRecord(rec, raw, { fillText: !existed });
    if (!entry) {
      pruneIfEmpty(key);
      return;
    }
    selectCell(key);
    flashCell(key);
    toast(fetchLinkInfo ? 'リンクを付けました（ページの情報を取得しています…）' : 'リンクを付けました');
  }

  async function fetchUrlInfo(rec, entry, { fillText = false } = {}) {
    pendingUrls.add(entry.id);
    requestSideRender();
    refreshAllCells();
    try {
      const { preview } = await ipc(api.previewLink(entry.url));
      for (const k of ['title', 'description', 'siteName', 'favicon', 'image']) {
        if (preview[k]) entry[k] = preview[k];
        else delete entry[k];
      }
      entry.fetchedAt = nowIso();
      if (fillText && !hasText(rec) && entry.title) {
        rec.text = entry.title;
        rec.updatedAt = nowIso();
      }
    } catch (err) {
      console.warn(err);
      entry.fetchedAt = nowIso(); // 取れなかった（URL だけで表示する）
    } finally {
      pendingUrls.delete(entry.id);
      afterSideChange(rec);
      refreshAllCells();
    }
  }

  function removeUrl(rec, id) {
    rec.urls = urlsOf(rec).filter((u) => u.id !== id);
    if (!rec.urls.length) delete rec.urls;
    afterSideChange(rec);
    refreshAllCells();
    renderLinks();
  }

  // ---- 同じページを含むメモ（自動の関連付け） ----

  // ノート全体の「ページ → メモ」。key は urls.js の pageKey
  function pageIndex() {
    const map = new Map();
    forEachMemo((rec, key, keys) => {
      const seen = new Set();
      for (const u of urlsOf(rec)) {
        const k = U.pageKey(u.url);
        if (!k || seen.has(k)) continue;
        seen.add(k);
        if (!map.has(k)) map.set(k, []);
        map.get(k).push({ rec, key, keys });
      }
    });
    return map;
  }

  // そのメモと同じページを含む、ほかのメモ（重なりなし）
  function samePageMemos(rec, index = pageIndex()) {
    const out = [];
    const seen = new Set([rec]);
    for (const u of urlsOf(rec)) {
      for (const it of index.get(U.pageKey(u.url)) || []) {
        if (seen.has(it.rec)) continue;
        seen.add(it.rec);
        out.push(it);
      }
    }
    return out;
  }

  // この階層で同じページを含むマスの組（線を引く）。同じページのマスは順につなぐ
  function autoPairsInLayer() {
    const groups = new Map();
    const add = (key, rec) => {
      const seen = new Set();
      for (const u of urlsOf(rec)) {
        const k = U.pageKey(u.url);
        if (!k || seen.has(k)) continue;
        seen.add(k);
        if (!groups.has(k)) groups.set(k, []);
        groups.get(k).push(key);
      }
    };
    for (const [key, rec] of memos) if (!isEmptyRecord(rec)) add(key, rec);
    if (path.length) add(CENTER_KEY, path[path.length - 1].rec);
    const pairs = new Set();
    for (const keys of groups.values()) {
      keys.sort();
      for (let i = 1; i < keys.length; i++) pairs.add(`${keys[i - 1]}|${keys[i]}`);
    }
    return [...pairs].map((p) => p.split('|'));
  }

  // ---- マスへのリンク（hexmemo://） ----

  async function copyMemoLink(key) {
    const rec = getRecord(key);
    if (!api || !rec || isEmptyRecord(rec)) return;
    ensureId(rec);
    scheduleSave();
    const url = U.makeInternalLink({ memoId: rec.id, boardId: currentBoardId, appId });
    try {
      await ipc(api.writeLink({ url, label: recordLabel(rec, key, 30) }));
      toast('このマスへのリンクをコピーしました。メモの本文に貼り付けると、押してこのマスへ移動できます', 'info', 4500);
    } catch (err) {
      toast(`コピーできませんでした：${err.message}`, 'error', 5000);
    }
  }

  // 選んだマスに貼ったマスへのリンク：空きマスならその本文に、メモがあれば本文の最後に足す
  function addMemoLinkToKey(key, url) {
    const rec = recordAtKey(key, { create: true });
    if (!rec) return;
    rec.text = hasText(rec) ? `${rec.text.replace(/\s+$/, '')}\n${url}` : url;
    rec.updatedAt = nowIso();
    afterSideChange(rec);
    refreshAllCells();
    selectCell(key);
    flashCell(key);
    toast('マスへのリンクを本文に入れました（押すとそのマスへ移動します）');
  }

  function memoLinkLabel(link) {
    if ((link.appId || null) !== (appId || null)) return 'ほかのメモアプリのメモ';
    if (link.boardId && link.boardId !== currentBoardId) {
      const b = boardById(link.boardId);
      return b ? `「${b.name}」のメモ` : '見つからないノートのメモ';
    }
    const found = locateById(link.memoId);
    return found ? recordLabel(found.rec, found.key, 18) : '見つからないメモ';
  }

  async function navigateMemoLink(url) {
    const link = U.parseInternalLink(url);
    if (!link) return;
    if ((link.appId || null) !== (appId || null)) {
      try {
        await ipc(api.openMemoLink(url));
        toast('リンク先のメモアプリを開きます…');
      } catch (err) {
        toast(`開けませんでした：${err.message}`, 'error', 5000);
      }
      return;
    }
    if (link.boardId && link.boardId !== currentBoardId) {
      if (!boardById(link.boardId)) {
        toast('リンク先のノートが見つかりません（削除された可能性があります）', 'warn', 4500);
        return;
      }
      await switchBoard(link.boardId);
    }
    const found = locateById(link.memoId);
    if (!found) {
      toast('リンク先のメモが見つかりません（削除された可能性があります）', 'warn', 4500);
      return;
    }
    jumpTo(found.key, found.keys);
  }

  // 本文・カード・サイドバーのリンクを開く（マスへのリンクはそのマスへ）
  async function openAnyUrl(url) {
    if (U.parseInternalLink(url)) {
      navigateMemoLink(url);
      return;
    }
    if (!U.isWebUrl(url)) return;
    if (U.isSuspiciousHost(url)) {
      const ok = await confirmAction({
        title: 'このリンクを開きますか？',
        message: `「${U.hostOf(url)}」は、見た目の似た文字を使える国際化ドメイン（xn--）を含みます。よく知っているサイトか確かめてから開いてください。${url}`,
        confirmLabel: '開く',
        danger: false,
      });
      if (!ok) return;
    }
    try {
      await ipc(api.openLink(url));
    } catch (err) {
      toast(`開けませんでした：${err.message}`, 'error', 5000);
    }
  }

  // ---- マスの表示（本文のリンク・印・表紙・リンクのカード） ----

  // 本文：URL の部分だけ押せるリンクにする（編集中はふつうの文字）
  function renderBodyText(target, text) {
    // マスへのリンクの表示名は開いているノートで変わるので、ノートも合わせて描き直しを判断する
    const sig = `${currentBoardId}\u0000${text}`;
    if (target._text === sig) return;
    target._text = sig;
    const found = U.findUrls(text);
    if (!found.length) {
      target.textContent = text;
      return;
    }
    const frag = document.createDocumentFragment();
    let pos = 0;
    for (const { index, url } of found) {
      if (index > pos) frag.append(text.slice(pos, index));
      const span = el('span', 'body-url');
      span.dataset.url = url;
      span.setAttribute('role', 'link');
      const internal = U.parseInternalLink(url);
      if (internal) {
        span.classList.add('is-memo');
        span.textContent = `⬡ ${memoLinkLabel(internal)}`;
        span.title = 'クリックでこのメモへ移動';
      } else {
        span.textContent = U.shortUrl(url);
        span.title = `${U.hostOf(url)}\n${url}\nクリックでブラウザで開く`;
      }
      frag.append(span);
      pos = index + url.length;
    }
    if (pos < text.length) frag.append(text.slice(pos));
    target.replaceChildren(frag);
  }

  function updateCellMedia(node, rec) {
    const refs = node._refs;
    const nImages = imagesOf(rec).length;
    const list = urlsOf(rec);
    refs.att.hidden = nImages === 0;
    refs.attN.textContent = nImages ? String(nImages) : '';
    refs.web.hidden = list.length === 0;
    refs.webN.textContent = list.length ? String(list.length) : '';
    const broken = list.some((u) => u.status === 'broken');
    refs.web.classList.toggle('is-broken', broken);
    const sideOn = isSideTarget(node._key, rec);
    refs.att.classList.toggle('is-side', sideOn && side.tab === 'images');
    refs.web.classList.toggle('is-side', sideOn && side.tab === 'web');
    refs.att.title = `画像（${nImages}枚）をサイドバーで見る`;
    refs.web.title = `リンク（${list.length}件）をサイドバーで見る${broken ? '（開けないリンクがあります）' : ''}`;
    syncMetaBadges(refs);

    // 表紙
    const cover = showCovers ? coverOf(rec) : null;
    const coverUrl = cover ? attUrl(cover.thumb || cover.file) : '';
    if (node._cover !== coverUrl) {
      node._cover = coverUrl;
      refs.cover.style.backgroundImage = coverUrl ? `url("${coverUrl}")` : '';
    }
    node.classList.toggle('has-cover', !!coverUrl);

    // リンクのカード（1件目。ほかにもあれば +N）
    const first = list[0];
    // 本文がページのタイトルと同じなら、カードにはタイトルを重ねて出さない
    const sameAsText = !!first && !!first.title && !!rec && rec.text.trim() === first.title;
    const sig = first ? [first.url, first.title, first.favicon, first.status, pendingUrls.has(first.id), list.length, sameAsText].join('|') : '';
    if (node._card !== sig) {
      node._card = sig;
      refs.card.hidden = !first;
      node.classList.toggle('has-card', !!first);
      if (first) fillCard(refs.card, first, list.length, sameAsText);
    }
  }

  function fillCard(card, u, total, sameAsText = false) {
    const yt = U.youtubeInfo(u.url);
    const icon = u.favicon ? Object.assign(el('img', 'body-card-icon'), { src: attUrl(u.favicon), alt: '' }) : svgIcon(yt ? 'play' : 'globe');
    if (!u.favicon) icon.classList.add('body-card-icon');
    const title = el('span', 'body-card-title', pendingUrls.has(u.id) ? '情報を取得中…' : sameAsText ? u.siteName || U.hostOf(u.url) : u.title || U.shortUrl(u.url, 30));
    const sub = el('span', 'body-card-sub', sameAsText ? U.shortUrl(u.url, 34) : U.hostOf(u.url));
    if (yt && yt.start) sub.textContent = `▶ ${U.formatTime(yt.start)} から · ${U.hostOf(u.url)}`;
    if (u.status === 'broken') sub.textContent = `⚠ 開けません · ${U.hostOf(u.url)}`;
    const text = el('span', 'body-card-text');
    text.append(title, sub);
    card.replaceChildren(icon, text);
    if (total > 1) card.append(el('span', 'body-card-more', `+${total - 1}`));
    card.classList.toggle('is-broken', u.status === 'broken');
    card.dataset.url = u.url;
    card.title = `${u.title ? `${u.title}\n` : ''}${u.url}\nクリックでブラウザで開く${total > 1 ? `（ほかに ${total - 1} 件。🌐 からサイドバーで見る）` : ''}`;
  }

  function updateCoverToggle() {
    const btn = $('coverToggle');
    btn.setAttribute('aria-pressed', String(showCovers));
    btn.title = `表紙の画像を${showCovers ? '隠す' : '表示する'}`;
  }

  function setShowCovers(on) {
    showCovers = on;
    writePref(COVERS_PREF, on);
    updateCoverToggle();
    refreshAllCells();
    toast(on ? '表紙の画像を表示しました' : '表紙の画像を隠しました（画像は 📎 から見られます）');
  }

  // ---- サイドバー：画像 ----

  // 「並べる」（縮小版を並べる）／「幅いっぱい」（サイドバーの左右いっぱいに元の画像）
  const IMAGE_VIEW_PREF = 'hexMemo.sideImageView';
  let sideImageView = (() => {
    try {
      return localStorage.getItem(IMAGE_VIEW_PREF) === 'wide' ? 'wide' : 'grid';
    } catch {
      return 'grid';
    }
  })();

  function setSideImageView(view) {
    sideImageView = view === 'wide' ? 'wide' : 'grid';
    try {
      localStorage.setItem(IMAGE_VIEW_PREF, sideImageView);
    } catch {
      // 覚えられなくても、この起動中は切り替わる
    }
    renderSide();
  }

  function renderSideImages(rec) {
    const list = imagesOf(rec);
    const grid = $('sideImageGrid');
    const wide = sideImageView === 'wide';
    for (const b of document.querySelectorAll('[data-image-view]')) b.setAttribute('aria-pressed', String(b.dataset.imageView === sideImageView));
    grid.classList.toggle('is-wide', wide);
    // 中身が同じなら作り直さない（本文の入力のたびに画像を読み直さないように）
    const sig = [sideImageView, rec && rec.cover, ...list.map((img) => `${img.id}:${img.file}:${img.caption || ''}:${img.name || ''}`)].join('|');
    if (grid._sig !== sig) {
      grid._sig = sig;
      grid.replaceChildren(...list.map((img) => {
        const li = el('li', 'side-image');
        li.dataset.id = img.id;
        const open = el('button', 'side-image-open');
        open.type = 'button';
        open.title = `${img.caption || img.name || '画像'}（クリックで大きく表示）`;
        const pic = el('img');
        // 幅いっぱいのときは、ぼやけないよう元の画像を使う
        pic.src = attUrl(wide ? img.file : img.thumb || img.file);
        pic.alt = img.caption || img.name || '';
        pic.loading = 'lazy';
        pic.decoding = 'async';
        if (wide && img.width && img.height) pic.style.aspectRatio = `${img.width} / ${img.height}`; // 読み込む前から高さを確保
        open.append(pic);
        if (rec.cover === img.id) {
          const star = el('span', 'side-image-cover');
          star.append(svgIcon('star'), document.createTextNode('表紙'));
          open.append(star);
        }
        li.append(open, el('span', 'side-image-cap', img.caption || img.name || ''));
        return li;
      }));
    }
    grid.hidden = list.length === 0;
    $('sideImageEmpty').hidden = list.length > 0;
  }

  // ---- サイドバー：リンク ----

  function renderSideWeb(rec) {
    const list = urlsOf(rec);
    const index = list.length ? pageIndex() : null;
    const ul = $('sideWebList');
    ul.replaceChildren(...list.map((u) => buildWebItem(rec, u, index)));
    ul.hidden = list.length === 0;
    $('sideWebEmpty').hidden = list.length > 0;
    $('sideFetchToggle').checked = fetchLinkInfo;
    $('sideCheckLinks').disabled = !list.length || checkingLinks;
    $('sideCheckLinks').lastChild.textContent = checkingLinks ? '確認しています…' : 'リンク切れを確認';
  }

  function buildWebItem(rec, u, index) {
    const li = el('li', `side-web${u.status === 'broken' ? ' is-broken' : ''}`);
    li.dataset.id = u.id;
    if (u.image) {
      const banner = el('img', 'side-web-image');
      banner.src = attUrl(u.image);
      banner.alt = '';
      banner.loading = 'lazy';
      li.append(banner);
    }
    const head = el('div', 'side-web-head');
    const icon = u.favicon ? Object.assign(el('img', 'side-web-icon'), { src: attUrl(u.favicon), alt: '' }) : svgIcon('globe');
    if (!u.favicon) icon.classList.add('side-web-icon');
    const title = el('button', 'side-web-title', pendingUrls.has(u.id) ? '情報を取得しています…' : u.title || U.shortUrl(u.url, 48));
    title.type = 'button';
    title.dataset.webAct = 'open';
    title.title = `${u.url}\nクリックでブラウザで開く`;
    head.append(icon, title);
    li.append(head);
    li.append(el('div', 'side-web-host', [u.siteName, U.hostOf(u.url)].filter(Boolean).join(' · ')));
    if (u.description) li.append(el('p', 'side-web-desc', u.description));

    // YouTube：再生位置
    const yt = U.youtubeInfo(u.url);
    if (yt) {
      const row = el('div', 'side-web-yt');
      row.append(svgIcon('play'), document.createTextNode('再生位置 '));
      const input = el('input', 'side-web-time');
      input.type = 'text';
      input.value = yt.start ? U.formatTime(yt.start) : '';
      input.placeholder = '0:00';
      input.setAttribute('aria-label', '再生位置（分:秒）');
      const set = el('button', 'btn side-mini-btn', '設定');
      set.type = 'button';
      set.dataset.webAct = 'yt-set';
      row.append(input, set);
      if (yt.start) {
        const clear = el('button', 'btn side-mini-btn', '外す');
        clear.type = 'button';
        clear.dataset.webAct = 'yt-clear';
        row.append(clear);
      }
      li.append(row);
    }

    // リンク切れの確認の結果
    if (u.status) {
      const when = u.checkedAt ? ` · ${formatRelative(u.checkedAt)}に確認` : '';
      const st = el('div', `side-web-status is-${u.status}`,
        u.status === 'ok' ? `✓ 開けます${when}` : u.status === 'broken' ? `⚠ 開けませんでした${u.statusCode ? `（${u.statusCode}）` : ''}${when}` : `？ 確かめられませんでした${u.statusCode ? `（${u.statusCode}）` : ''}${when}`);
      if (u.status !== 'ok') {
        const arch = el('button', 'side-link-btn', 'アーカイブを探す');
        arch.type = 'button';
        arch.dataset.webAct = 'archive';
        st.append(arch);
      }
      li.append(st);
    }

    // 同じページを含むほかのメモ（自動の関連付け）
    const key = U.pageKey(u.url);
    const same = (index && key ? index.get(key) || [] : []).filter((it) => it.rec !== rec);
    if (same.length) {
      const box = el('div', 'side-web-same');
      box.append(el('span', 'side-web-same-head', `同じページを含むメモ ${same.length} 件`));
      for (const it of same.slice(0, 8)) {
        const b = el('button', 'side-link-btn', `${recordLabel(it.rec, it.key, 16)}（${locationLabel(it.keys, it.key)}）`);
        b.type = 'button';
        b.dataset.webAct = 'go';
        b.dataset.key = it.key;
        b.dataset.path = it.keys.join('|');
        box.append(b);
      }
      li.append(box);
    }

    const actions = el('div', 'side-web-actions');
    const act = (name, icon, text, title, extra = {}) => {
      const b = el('button', 'chip side-mini');
      b.type = 'button';
      b.dataset.webAct = name;
      b.title = title;
      b.append(svgIcon(icon), document.createTextNode(text));
      Object.assign(b, extra);
      actions.append(b);
    };
    act('open', 'external', '開く', 'ブラウザで開く');
    act('copy', 'copy', 'コピー', 'URL をコピー');
    act('refresh', 'refresh', pendingUrls.has(u.id) ? '取得中…' : '取り直す', 'タイトル・説明・画像を取り直す', { disabled: pendingUrls.has(u.id) });
    if (snapshotting.has(u.id)) act('snapshot', 'file', '保存中…', 'ページを PDF に保存しています', { disabled: true });
    else if (u.snapshot) {
      act('snapshot-open', 'file', `保存したページ（${formatRelative(u.snapshot.savedAt)}）`, `保存したページ（PDF）を開く${u.snapshot.title ? `：${u.snapshot.title}` : ''}`);
      act('snapshot', 'refresh', '保存し直す', 'ページを PDF に保存し直す');
    } else act('snapshot', 'file', 'ページを保存', 'ページを PDF に保存する（元のページが消えても読めます）');
    act('remove', 'close', '外す', 'このリンクを外す');
    li.append(actions);
    return li;
  }

  async function snapshotUrl(rec, u) {
    if (snapshotting.has(u.id)) return;
    snapshotting.add(u.id);
    requestSideRender();
    try {
      const { snapshot } = await ipc(api.snapshotLink(u.url));
      u.snapshot = snapshot;
      afterSideChange(rec);
      toast('ページを PDF に保存しました（「保存したページ」から開けます）');
    } catch (err) {
      toast(`ページを保存できませんでした：${err.message}`, 'error', 5000);
    } finally {
      snapshotting.delete(u.id);
      requestSideRender();
    }
  }

  // リンク切れの確認（結果はリンクごとに残す）
  async function checkUrlEntries(entries) {
    const urls = [...new Set(entries.map((e) => e.u.url))];
    if (!urls.length) return null;
    const { results } = await ipc(api.checkLinks(urls));
    const byUrl = new Map(results.map((r) => [r.url, r]));
    const t = nowIso();
    const touched = new Set();
    for (const { rec, u } of entries) {
      const r = byUrl.get(u.url);
      if (!r) continue;
      u.status = r.status;
      if (r.code) u.statusCode = r.code;
      else delete u.statusCode;
      u.checkedAt = t;
      touched.add(rec);
    }
    for (const rec of touched) {
      const k = keyInView(rec);
      if (k) refreshCell(k);
    }
    scheduleSave();
    return { total: urls.length, broken: results.filter((r) => r.status === 'broken').length, unknown: results.filter((r) => r.status === 'error').length };
  }

  const checkSummary = (s) => `リンク ${s.total} 件を確認しました${s.broken ? `：開けないもの ${s.broken} 件（⚠ の付いたマス）` : '：すべて開けます'}${s.unknown ? `・確かめられないもの ${s.unknown} 件` : ''}`;

  async function checkSideLinks() {
    const rec = sideRecord();
    if (!rec || checkingLinks) return;
    checkingLinks = true;
    renderSide();
    try {
      const s = await checkUrlEntries(urlsOf(rec).map((u) => ({ rec, u })));
      if (s) toast(checkSummary(s), s.broken ? 'warn' : 'info', 5000);
    } catch (err) {
      toast(`確認できませんでした：${err.message}`, 'error', 5000);
    } finally {
      checkingLinks = false;
      renderSide();
    }
  }

  // ノート全体（下の階層も含む）のリンクを確認する
  async function checkBoardLinks(id) {
    if (checkingLinks) return;
    if (id !== currentBoardId) await switchBoard(id);
    const entries = [];
    forEachMemo((rec) => {
      for (const u of urlsOf(rec)) entries.push({ rec, u });
    });
    if (!entries.length) {
      toast('このノートにはリンクがありません');
      return;
    }
    checkingLinks = true;
    toast(`リンク ${entries.length} 件を確認しています…`, 'info', 10000);
    try {
      const s = await checkUrlEntries(entries);
      requestSideRender();
      toast(checkSummary(s), s.broken ? 'warn' : 'info', 6000);
    } catch (err) {
      toast(`確認できませんでした：${err.message}`, 'error', 5000);
    } finally {
      checkingLinks = false;
    }
  }

  // ---- 画像を大きく表示する画面 ----

  const viewer = $('imageViewer');
  const viewerImg = $('viewerImg');
  let viewing = null; // { rec, id }

  // 窓の位置と大きさ（画面上の px）。メモアプリごとに覚える
  const VIEWER_PREF = 'hexMemo.viewerRect';
  const VIEWER_MIN = { w: 360, h: 260 };
  let viewerRect = null;
  let viewerMaxed = false;
  try {
    const r = JSON.parse(localStorage.getItem(VIEWER_PREF) || 'null');
    if (r && [r.x, r.y, r.w, r.h].every(Number.isFinite)) viewerRect = r;
  } catch {
    viewerRect = null;
  }

  function defaultViewerRect() {
    const w = Math.min(1000, innerWidth - 64);
    const h = Math.min(760, innerHeight - 64);
    return { x: Math.round((innerWidth - w) / 2), y: Math.round((innerHeight - h) / 2), w, h };
  }

  // 画面からはみ出しても、見出し（つかんで動かす所）は画面に残るように収める
  function fitViewerRect(r) {
    const w = Math.round(Math.min(Math.max(r.w, VIEWER_MIN.w), innerWidth));
    const h = Math.round(Math.min(Math.max(r.h, VIEWER_MIN.h), innerHeight));
    return {
      x: Math.round(Math.min(Math.max(r.x, 120 - w), innerWidth - 120)),
      y: Math.round(Math.min(Math.max(r.y, 0), innerHeight - 48)),
      w,
      h,
    };
  }

  function placeViewer() {
    const r = viewerMaxed ? { x: 0, y: 0, w: innerWidth, h: innerHeight } : (viewerRect = fitViewerRect(viewerRect || defaultViewerRect()));
    viewer.style.left = `${r.x}px`;
    viewer.style.top = `${r.y}px`;
    viewer.style.width = `${r.w}px`;
    viewer.style.height = `${r.h}px`;
    viewer.classList.toggle('is-max', viewerMaxed);
    const max = $('viewerMax');
    max.setAttribute('aria-pressed', String(viewerMaxed));
    max.title = viewerMaxed ? '元の大きさに戻す（見出しをダブルクリック）' : '最大化（見出しをダブルクリック）';
  }

  function saveViewerRect() {
    try {
      localStorage.setItem(VIEWER_PREF, JSON.stringify(viewerRect));
    } catch {
      // 覚えられなくても、この起動中は使える
    }
  }

  function toggleViewerMax() {
    if (viewerPinned) return; // 固定中は大きさを変えない
    viewerMaxed = !viewerMaxed;
    placeViewer();
  }

  // この場所に固定：窓を動かせず・大きさも変えられなくし、画像の部分のクリック・ホイールは後ろのハニカムへ通す
  // （見出しの行だけは押せる）。画像の濃さは「そのまま」「半透明」「薄く」の3段階（濃さはメモアプリごとに覚える）
  const VIEWER_FADE_PREF = 'hexMemo.viewerFade';
  const VIEWER_FADES = ['full', 'half', 'faint'];
  let viewerPinned = false;
  let viewerFade = 'full';
  try {
    const f = localStorage.getItem(VIEWER_FADE_PREF);
    if (VIEWER_FADES.includes(f)) viewerFade = f;
  } catch {
    viewerFade = 'full';
  }

  function setViewerFade(fade) {
    if (!VIEWER_FADES.includes(fade)) return;
    viewerFade = fade;
    viewer.dataset.fade = fade;
    for (const b of $('viewerFade').querySelectorAll('[data-fade]')) b.setAttribute('aria-pressed', String(b.dataset.fade === fade));
    try {
      localStorage.setItem(VIEWER_FADE_PREF, fade);
    } catch {
      // 覚えられなくても、この起動中は使える
    }
  }

  function setViewerPinned(on) {
    viewerPinned = on;
    viewer.classList.toggle('is-pinned', on);
    const pin = $('viewerPin');
    pin.setAttribute('aria-pressed', String(on));
    pin.title = on ? '固定をやめる（窓を動かせるようにする）' : 'この場所に固定する（画像越しに、後ろのマスを選べる・書ける）';
    $('viewerMax').disabled = on;
    $('viewerHead').title = on ? '固定中：画像の部分は後ろのマスを押せます（見出しのボタンは使えます）' : 'ドラッグで動かす・ダブルクリックで最大化';
    if (on) {
      saveViewerCaption();
      if (viewer.contains(document.activeElement)) document.activeElement.blur(); // キーはハニカムへ
    }
  }

  // series を渡すと、その分けて貼り付けた文章のマスの画像を、読む順に ← → で見られる
  // readOnly：見るだけ（区画の紙片の画像。表紙・説明・外す・組み合わせるを出さない）
  function openViewer(rec, id, { series = null, readOnly = false } = {}) {
    viewing = { rec, id, series, readOnly };
    renderViewer();
    if (!viewer.open) {
      placeViewer();
      viewer.show(); // ほかの操作をふさがない窓として開く
    }
    if (!viewerPinned) $('viewerStage').focus({ preventScroll: true }); // 固定中は、キーをハニカムに残す
  }

  // 見出しをつかんで動かす・縁や角をつかんで大きさを変える
  let viewerGesture = null;
  $('viewerHead').addEventListener('pointerdown', (e) => {
    if (e.button !== 0 || e.target.closest('button, input') || viewerPinned) return; // 固定中は動かさない
    e.preventDefault();
    // 最大化中は、実際に動かし始めたときに元の大きさへ戻す（ダブルクリックで戻せるように）
    viewerGesture = { kind: 'move', id: e.pointerId, x: e.clientX, y: e.clientY, rect: viewerMaxed ? null : { ...viewerRect }, fromMax: viewerMaxed };
    $('viewerHead').setPointerCapture(e.pointerId);
    viewer.classList.add('is-moving');
  });
  for (const handle of viewer.querySelectorAll('.viewer-resize')) {
    handle.addEventListener('pointerdown', (e) => {
      if (e.button !== 0 || viewerMaxed || viewerPinned) return;
      e.preventDefault();
      viewerGesture = { kind: 'resize', dir: handle.dataset.dir, id: e.pointerId, x: e.clientX, y: e.clientY, rect: { ...viewerRect } };
      handle.setPointerCapture(e.pointerId);
      viewer.classList.add('is-resizing');
    });
  }
  viewer.addEventListener('pointermove', (e) => {
    const g = viewerGesture;
    if (!g || e.pointerId !== g.id) return;
    const dx = e.clientX - g.x;
    const dy = e.clientY - g.y;
    if (g.fromMax) {
      if (Math.hypot(dx, dy) < 5) return;
      // 元の大きさに戻し、つかんだ所が見出しの同じ辺りに来るようにして、そのまま動かす
      const r0 = viewerRect || defaultViewerRect();
      viewerRect = { ...r0, x: e.clientX - r0.w * (g.x / innerWidth), y: Math.max(0, e.clientY - 20) };
      viewerMaxed = false;
      Object.assign(g, { fromMax: false, x: e.clientX, y: e.clientY, rect: { ...viewerRect } });
      placeViewer();
      return;
    }
    const r = { ...g.rect };
    if (g.kind === 'move') {
      r.x += dx;
      r.y += dy;
    } else {
      if (g.dir.includes('e')) r.w = Math.max(VIEWER_MIN.w, g.rect.w + dx);
      if (g.dir.includes('s')) r.h = Math.max(VIEWER_MIN.h, g.rect.h + dy);
      if (g.dir.includes('w')) {
        r.w = Math.max(VIEWER_MIN.w, g.rect.w - dx);
        r.x = g.rect.x + g.rect.w - r.w;
      }
      if (g.dir.includes('n')) {
        r.h = Math.max(VIEWER_MIN.h, g.rect.h - dy);
        r.y = g.rect.y + g.rect.h - r.h;
      }
    }
    viewerRect = r;
    placeViewer();
  });
  const endViewerGesture = (e) => {
    if (!viewerGesture || e.pointerId !== viewerGesture.id) return;
    viewerGesture = null;
    viewer.classList.remove('is-moving', 'is-resizing');
    saveViewerRect();
  };
  viewer.addEventListener('pointerup', endViewerGesture);
  viewer.addEventListener('pointercancel', endViewerGesture);
  $('viewerHead').addEventListener('dblclick', (e) => {
    if (!e.target.closest('button, input')) toggleViewerMax();
  });
  $('viewerMax').addEventListener('click', toggleViewerMax);
  $('viewerPin').addEventListener('click', () => setViewerPinned(!viewerPinned));
  $('viewerFade').addEventListener('click', (e) => {
    const b = e.target.closest('[data-fade]');
    if (b) setViewerFade(b.dataset.fade);
  });
  setViewerFade(viewerFade);
  window.addEventListener('resize', () => {
    if (viewer.open) placeViewer();
  });

  // 窓で順に見る画像 [{ key, rec, img }]：文章の画像なら文章のマスの順に全部、そうでなければそのメモの画像
  function viewerList() {
    if (!viewing) return [];
    if (viewing.series) return seriesImageEntries(viewing.series);
    return imagesOf(viewing.rec).map((img) => ({ key: null, rec: viewing.rec, img }));
  }
  const viewerIndex = (list) => list.findIndex((x) => x.rec === viewing.rec && x.img.id === viewing.id);

  function renderViewer() {
    if (!viewing) return;
    const list = viewerList();
    const i = viewerIndex(list);
    if (i < 0) {
      viewer.close();
      return;
    }
    const img = list[i].img;
    viewerImg.src = attUrl(img.file);
    viewerImg.alt = img.caption || img.name || '';
    $('viewerStage').classList.remove('is-actual');
    $('viewerTitle').textContent = viewing.series && list[i].rec.seq ? `${list[i].rec.seq.n} 番目のマス｜${img.name || '画像'}` : img.name || '画像';
    $('viewerCount').textContent = list.length > 1 ? `${i + 1} / ${list.length}` : '';
    $('viewerPrev').disabled = i === 0;
    $('viewerNext').disabled = i === list.length - 1;
    const isCover = viewing.rec.cover === img.id;
    $('viewerCover').setAttribute('aria-pressed', String(isCover));
    $('viewerCover').lastChild.textContent = isCover ? '表紙を外す' : '表紙にする';
    // 今いる階層に、すでにこの画像を組み合わせてあれば出さない
    const top = path[path.length - 1];
    const combo = currentLayer().combo;
    const ro = !!viewing.readOnly;
    $('viewerCover').hidden = ro;
    $('viewerDelete').hidden = ro;
    $('viewerCombine').hidden = ro || (!!top && top.rec === viewing.rec && !!combo && combo.image === img.id);
    $('viewerCaption').value = img.caption || '';
    $('viewerCaption').readOnly = ro;
    $('viewerCaption').hidden = ro && !img.caption;
    $('viewerInfo').textContent = [img.width && img.height ? `${img.width}×${img.height}` : '', img.size ? formatBytes(img.size) : '', img.addedAt ? `${formatFull(img.addedAt)} に追加` : ''].filter(Boolean).join(' · ');
  }

  function viewerStep(step) {
    if (!viewing) return;
    saveViewerCaption();
    const list = viewerList();
    const i = viewerIndex(list) + step;
    if (i < 0 || i >= list.length) return;
    const moved = list[i].rec !== viewing.rec;
    viewing.rec = list[i].rec;
    viewing.id = list[i].img.id;
    renderViewer();
    // 文章の画像を順に見ているとき、別のマスの画像へ進んだら、ハニカムと全文もそのマスへ（読書モードならそこまで進む）
    if (moved && viewing.series && side && side.series === viewing.series && list[i].key) goSeriesSeg(list[i].key);
  }

  function viewerImage() {
    return viewing ? imagesOf(viewing.rec).find((img) => img.id === viewing.id) || null : null;
  }

  function saveViewerCaption() {
    const img = viewerImage();
    if (!img || viewing.readOnly) return;
    const v = $('viewerCaption').value.trim().slice(0, 1000);
    if ((img.caption || '') === v) return;
    if (v) img.caption = v;
    else delete img.caption;
    afterSideChange(viewing.rec);
  }

  viewer.addEventListener('close', () => {
    saveViewerCaption();
    if (viewerPinned) setViewerPinned(false); // 次に開いたときは、ふつうの窓から
    viewing = null;
    viewerImg.removeAttribute('src');
    if (editingKey) editor.focus({ preventScroll: true });
  });
  viewer.addEventListener('keydown', (e) => {
    if (e.isComposing || e.keyCode === 229) return;
    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      viewer.close();
      return;
    }
    // 窓の中のキーはハニカムの操作（矢印でのパン・Delete での削除など）に渡さない（Ctrl の組み合わせは全体へ）
    if (!e.ctrlKey && !e.metaKey) e.stopPropagation();
    const typing = e.target === $('viewerCaption');
    if (typing) {
      if (e.key === 'Enter') {
        e.preventDefault();
        saveViewerCaption();
        $('viewerStage').focus();
      }
      return;
    }
    if (e.key === 'ArrowLeft') viewerStep(-1);
    else if (e.key === 'ArrowRight') viewerStep(1);
    else if (e.key === 'Delete') $('viewerDelete').click();
  });
  $('viewerPrev').addEventListener('click', () => viewerStep(-1));
  $('viewerNext').addEventListener('click', () => viewerStep(1));
  $('viewerClose').addEventListener('click', () => viewer.close());
  $('viewerCaption').addEventListener('blur', saveViewerCaption);
  $('viewerStage').addEventListener('click', (e) => {
    if (e.target === viewerImg) $('viewerStage').classList.toggle('is-actual'); // 画面に合わせる ⇄ 原寸
  });
  $('viewerCover').addEventListener('click', () => {
    const img = viewerImage();
    if (!img || viewing.readOnly) return;
    setCover(viewing.rec, viewing.rec.cover === img.id ? null : img.id);
    renderViewer();
  });
  $('viewerOpen').addEventListener('click', async () => {
    const img = viewerImage();
    if (!img) return;
    try {
      await ipc(api.openAttachment(img.file));
    } catch (err) {
      toast(`開けませんでした：${err.message}`, 'error', 5000);
    }
  });
  $('viewerReveal').addEventListener('click', async () => {
    const img = viewerImage();
    if (!img) return;
    try {
      await ipc(api.revealAttachment(img.file));
    } catch (err) {
      toast(`開けませんでした：${err.message}`, 'error', 5000);
    }
  });
  $('viewerSave').addEventListener('click', async () => {
    const img = viewerImage();
    if (!img) return;
    try {
      const res = await ipc(api.saveAttachmentAs(img.file, img.name || '画像'));
      if (!res.canceled) toast('画像を保存しました');
    } catch (err) {
      toast(`保存できませんでした：${err.message}`, 'error', 5000);
    }
  });
  $('viewerDelete').addEventListener('click', async () => {
    const img = viewerImage();
    if (!img || viewing.readOnly) return;
    const rec = viewing.rec;
    const index = viewerIndex(viewerList());
    const ok = await confirmAction({ title: 'この画像を外しますか？', message: `「${img.caption || img.name || '画像'}」をこのメモから外します。` });
    if (!ok) return;
    removeImage(rec, img.id);
    toast('画像を外しました');
    const rest = viewing ? viewerList() : [];
    if (viewer.open && viewing && (viewing.series || viewing.rec === rec) && rest.length) {
      const next = rest[Math.min(index, rest.length - 1)];
      viewing.rec = next.rec;
      viewing.id = next.img.id;
      renderViewer();
      $('viewerStage').focus({ preventScroll: true });
    } else if (viewer.open) viewer.close();
  });
  $('viewerCombine').addEventListener('click', () => {
    const img = viewerImage();
    if (!img || viewing.readOnly) return;
    saveViewerCaption();
    const rec = viewing.rec;
    if (combineImage(rec, img.id, { replace: true })) viewer.close(); // 画像はハニカムの下に敷いたので、窓は閉じる
  });

  // ---- 画像とセルの組み合わせ ----
  // 画像のあるメモの下の階層（そのメモが中心の層）に、そのメモの画像を組み合わせる：画像をハニカムの下に敷き、
  // 上のセルにふつうのメモとして書く（画像のこの場所 ＝ このセル）。画像はハニカムと一緒に動き、拡大縮小する。
  // 層の combo = { image: 画像の ID, x, y: 画像の中心, w: 画像の幅（どれもワールド座標）, fade: 上のセルの濃さ }
  // 表示だけの状態（comboImg・comboHiddenFor・comboAdjust・comboGesture）は、上の「状態」に置いてある

  const COMBO_FADES = ['full', 'half', 'faint'];
  const COMBO_PITCH = H.SQRT3 * HEX_SIZE; // セル1個分の横幅（隙間を含む）
  const COMBO_MIN_W = HEX_W; // 画像の幅は、セル1個分から
  const COMBO_MAX_W = COMBO_PITCH * 400;
  const comboFrame = $('comboFrame');

  // 保存形式の combo を画面用に（store.js で確かめてあるが、クリップボードからも来るので形だけもう一度）
  function comboFromRaw(raw) {
    if (!raw || typeof raw !== 'object' || typeof raw.image !== 'string') return null;
    const num = (v, d) => (v !== null && v !== '' && Number.isFinite(Number(v)) ? Number(v) : d);
    const combo = { image: raw.image, x: num(raw.x, 0), y: num(raw.y, 0), w: Math.max(20, num(raw.w, 1600)) };
    if (['full', 'half', 'faint'].includes(raw.fade)) combo.fade = raw.fade;
    return combo;
  }

  function serializeCombo(c) {
    const round = (n) => Math.round(n * 100) / 100;
    return { image: c.image, x: round(c.x), y: round(c.y), w: round(c.w), ...(c.fade ? { fade: c.fade } : {}) };
  }

  const comboFade = (combo) => combo.fade || 'half';

  // 表示中の階層に組み合わせた画像 { combo, img, rec }（組み合わせていない・画像が外されていたら null）
  function currentCombo() {
    const top = path[path.length - 1];
    const layer = currentLayer();
    if (!top || !layer.combo) return null;
    const img = imagesOf(top.rec).find((x) => x.id === layer.combo.image);
    return img ? { combo: layer.combo, img, rec: top.rec } : null;
  }

  // 画像の縦横比（高さ ÷ 幅）
  function comboAspect(img) {
    if (img.width && img.height) return img.height / img.width;
    if (comboImg && comboImg.dataset.file === img.file && comboImg.naturalWidth) return comboImg.naturalHeight / comboImg.naturalWidth;
    return 0.75;
  }

  function comboRect({ combo, img }) {
    const h = combo.w * comboAspect(img);
    return { left: combo.x - combo.w / 2, top: combo.y - h / 2, w: combo.w, h };
  }

  // 初めて組み合わせるときの大きさ：横はセル6個分、縦は5段分までに収める（中心のメモが画像の真ん中）
  function defaultComboWidth(img) {
    const aspect = img.width && img.height ? img.height / img.width : 0.75;
    return Math.round(Math.min(COMBO_PITCH * 6, (HEX_SIZE * 1.5 * 5) / aspect));
  }

  function ensureComboImg() {
    if (comboImg) return comboImg;
    comboImg = el('img', 'combo-img');
    comboImg.alt = '';
    comboImg.draggable = false;
    comboImg.hidden = true;
    comboImg.addEventListener('load', () => placeCombo()); // 縦横比が分かったら、位置合わせの枠を合わせ直す
    comboImg.addEventListener('error', () => {
      if (currentCombo()) toast('組み合わせた画像を読み込めませんでした', 'warn');
    });
    cellLayer.prepend(comboImg); // 関連の線・セルより下
    return comboImg;
  }

  // 表示中の階層に合わせて、画像・セルの見え方・上のバーを整える（階層や表示が変わるたびに呼ぶ）
  function renderCombo() {
    const info = currentCombo();
    if (comboHiddenFor && comboHiddenFor !== currentLayer()) comboHiddenFor = null; // 階層を移ったら、隠していた画像は戻す
    if (comboAdjust && (!info || comboAdjust.layer !== currentLayer() || activeTab !== 'grid')) endComboAdjust();
    const on = !!info && !comboHiddenFor;
    stage.classList.toggle('has-combo', on);
    if (on) stage.dataset.comboFade = comboFade(info.combo);
    else delete stage.dataset.comboFade;
    if (on || comboImg) {
      const img = ensureComboImg();
      img.hidden = !on;
      if (on && img.dataset.file !== info.img.file) {
        img.dataset.file = info.img.file;
        img.src = attUrl(info.img.file);
      }
    }
    placeCombo();
    renderComboBar(info);
  }

  function placeCombo() {
    const info = comboImg && !comboImg.hidden ? currentCombo() : null;
    if (!info) return;
    const { combo } = info;
    comboImg.style.width = `${combo.w}px`;
    comboImg.style.transform = `translate(${combo.x - anchor.x}px, ${combo.y - anchor.y}px) translate(-50%, -50%)`;
    if (comboAdjust) placeComboFrame();
    updateComboSize(info);
  }

  // 位置合わせの枠：画面の座標で、ハニカムの表示（移動・拡大縮小）に合わせて動かす
  function placeComboFrame() {
    const info = currentCombo();
    if (!info || !comboAdjust) return;
    const r = comboRect(info);
    const z = camera.zoom;
    comboFrame.style.left = `${view.w / 2 + (r.left - camera.x) * z}px`;
    comboFrame.style.top = `${view.h / 2 + (r.top - camera.y) * z}px`;
    comboFrame.style.width = `${r.w * z}px`;
    comboFrame.style.height = `${r.h * z}px`;
  }

  function renderComboBar(info = currentCombo()) {
    const bar = $('comboBar');
    bar.hidden = !info || activeTab !== 'grid';
    if (bar.hidden) return;
    const hidden = !!comboHiddenFor;
    bar.classList.toggle('is-adjusting', !!comboAdjust);
    bar.classList.toggle('is-image-hidden', hidden);
    const name = info.img.caption || info.img.name || '画像';
    $('comboName').textContent = name;
    $('comboName').title = `組み合わせている画像：${name}`;
    const n = imagesOf(info.rec).length;
    $('comboPrev').hidden = n < 2;
    $('comboNext').hidden = n < 2;
    const fade = comboFade(info.combo);
    for (const b of $('comboFade').querySelectorAll('[data-fade]')) b.setAttribute('aria-pressed', String(b.dataset.fade === fade));
    const show = $('comboShow');
    show.setAttribute('aria-pressed', String(!hidden));
    show.title = hidden ? '画像を表示する' : '画像を一時的に隠す（セルだけを見る）';
    show.setAttribute('aria-label', show.title);
    $('comboAdjustBtn').disabled = hidden;
    updateComboSize(info);
  }

  function updateComboSize(info = currentCombo()) {
    if (!info) return;
    const n = info.combo.w / COMBO_PITCH;
    $('comboSize').textContent = `幅 セル ${n < 10 ? n.toFixed(1) : Math.round(n)} 個分`;
  }

  // レコードそのものが、どの階層（道筋 keys）のどのマスにあるか
  function locateRecordPath(target) {
    const walk = (layer, keys) => {
      for (const [key, rec] of layer.memos) {
        if (rec === target) return { keys, key };
        for (const [li, sub] of recLayers(rec).entries()) {
          const found = walk(sub, [...keys, stepOf(key, li)]);
          if (found) return found;
        }
      }
      return null;
    };
    return walk(rootLayer, []);
  }

  // rec の画像 imageId を、rec の下の階層（中心が rec）と組み合わせて、その階層へ入る。
  // すでに組み合わせた層があればその層へ（replace なら、その層の画像をこの画像に替える）
  function combineImage(rec, imageId, { replace = false } = {}) {
    const images = imagesOf(rec);
    const img = images.find((x) => x.id === imageId) || images.find((x) => x.id === rec.cover) || images[0];
    if (!img) return false;
    const top = path[path.length - 1];
    const here = !!top && top.rec === rec; // 今いる階層の中心のメモ → この層に組み合わせる
    let keys = null;
    let li = here ? top.li : 0;
    if (!here) {
      const loc = locateRecordPath(rec);
      if (!loc) {
        toast('このメモが見つかりません（削除されたか、別のノートにあります）', 'warn');
        return false;
      }
      if (loc.keys.length >= MAX_DEPTH) {
        toast(`これより深い階層は作れません（${MAX_DEPTH} 階層まで）`, 'warn');
        return false;
      }
      li = Math.max(0, recLayers(rec).findIndex((l) => l.combo));
      keys = [...loc.keys, stepOf(loc.key, li)];
    }
    if (!rec.children) rec.children = newLayer();
    const layer = layerOf(rec, li);
    const fresh = !layer.combo;
    if (fresh) layer.combo = { image: img.id, x: 0, y: 0, w: defaultComboWidth(img), fade: 'half' };
    else if (replace) layer.combo.image = img.id;
    if (keys) setPath(keys, 'in');
    else endEdit();
    comboHiddenFor = null;
    renderCrumbs();
    refreshAllCells();
    scheduleSave();
    if (fresh) {
      fitCombo({ writable: true });
      toast(`「${img.caption || img.name || '画像'}」とセルを組み合わせました。セルに書くと、画像のその場所へのメモになります（位置と大きさは上の「位置合わせ」で）`, 'info', 6000);
    }
    return true;
  }

  // 組み合わせた画像の全体が見えるように（上のバーの分だけ余白を取る）。
  // writable なら、セルに書ける倍率（全体表示にならない 50%）より小さくはしない
  function fitCombo({ writable = false } = {}) {
    const info = currentCombo();
    if (!info || activeTab !== 'grid') return;
    const r = comboRect(info);
    const top = 100;
    let z = Math.min(view.w / (r.w * 1.1), (view.h - top) / (r.h * 1.1), 1);
    if (writable) z = Math.max(z, OVERVIEW_BELOW);
    z = clampZoom(z);
    animateCameraTo(info.combo.x, info.combo.y - top / 2 / z, null, z);
  }

  async function removeCombo() {
    const layer = currentLayer();
    if (!layer.combo) return;
    const ok = await confirmAction({
      title: '組み合わせを外しますか？',
      message: 'ハニカムの下の画像を外します。画像（元のメモの添付）とセルに書いたメモは、そのまま残ります。',
      confirmLabel: '外す',
      danger: false,
    });
    if (!ok || !layer.combo) return;
    endComboAdjust();
    delete layer.combo;
    renderCrumbs();
    refreshAllCells();
    scheduleSave();
    toast('組み合わせを外しました');
  }

  // 同じメモのほかの画像に替える（位置と大きさはそのまま）
  function stepComboImage(step) {
    const info = currentCombo();
    if (!info) return;
    const list = imagesOf(info.rec);
    const i = list.findIndex((x) => x.id === info.img.id);
    const next = list[(i + step + list.length) % list.length];
    if (!next || next.id === info.img.id) return;
    info.combo.image = next.id;
    renderCombo();
    scheduleSave();
  }

  function setComboFade(fade) {
    const layer = currentLayer();
    if (!layer.combo || !COMBO_FADES.includes(fade)) return;
    layer.combo.fade = fade;
    renderCombo();
    scheduleSave();
  }

  function toggleComboShown() {
    if (!currentCombo()) return;
    endComboAdjust();
    comboHiddenFor = comboHiddenFor ? null : currentLayer();
    renderCombo();
  }

  // 位置合わせ：画像の中をドラッグで移動、四隅をドラッグで大きさ（縦横比はそのまま）。画像の外のドラッグ・ホイールはふだんどおり
  function startComboAdjust() {
    const info = currentCombo();
    if (!info || comboAdjust) return;
    endEdit();
    if (reading) stopReading({ quiet: true });
    resetMulti();
    comboHiddenFor = null;
    comboAdjust = { layer: currentLayer(), before: { x: info.combo.x, y: info.combo.y, w: info.combo.w } };
    stage.classList.add('is-combo-adjust');
    comboFrame.hidden = false;
    renderCombo();
    fitCombo();
  }

  // cancel なら、位置合わせを始める前の位置・大きさに戻す
  function endComboAdjust({ cancel = false } = {}) {
    if (!comboAdjust) return;
    const { layer, before } = comboAdjust;
    comboAdjust = null;
    comboGesture = null;
    stage.classList.remove('is-combo-adjust');
    comboFrame.hidden = true;
    comboFrame.classList.remove('is-moving', 'is-resizing');
    const c = layer.combo;
    if (cancel && c && (c.x !== before.x || c.y !== before.y || c.w !== before.w)) {
      Object.assign(c, before);
      if (layer === currentLayer()) scheduleSave();
    }
    renderCombo();
  }

  function scaleCombo(factor) {
    const info = currentCombo();
    if (!info) return;
    info.combo.w = Math.min(COMBO_MAX_W, Math.max(COMBO_MIN_W, info.combo.w * factor));
    placeCombo();
    scheduleSave();
  }

  comboFrame.addEventListener('pointerdown', (e) => {
    const info = currentCombo();
    if (e.button !== 0 || !comboAdjust || !info) return;
    e.preventDefault();
    e.stopPropagation();
    stopCameraAnimation();
    const handle = e.target.closest('[data-corner]');
    comboGesture = {
      kind: handle ? 'resize' : 'move',
      corner: handle ? handle.dataset.corner : '',
      id: e.pointerId,
      sx: e.clientX,
      sy: e.clientY,
      start: { ...info.combo },
      aspect: comboAspect(info.img),
    };
    comboFrame.setPointerCapture(e.pointerId);
    comboFrame.classList.add(handle ? 'is-resizing' : 'is-moving');
  });
  comboFrame.addEventListener('pointermove', (e) => {
    const g = comboGesture;
    const info = g && e.pointerId === g.id ? currentCombo() : null;
    if (!info) return;
    const z = camera.zoom;
    const dx = (e.clientX - g.sx) / z;
    const dy = (e.clientY - g.sy) / z;
    const c = info.combo;
    if (g.kind === 'move') {
      c.x = g.start.x + dx;
      c.y = g.start.y + dy;
    } else {
      // 反対側の角を動かさずに大きさを変える。つかんだ角の動きは、対角線の向きにならす（縦横比を保つ）
      const sx = g.corner.includes('e') ? 1 : -1;
      const sy = g.corner.includes('s') ? 1 : -1;
      const h0 = g.start.w * g.aspect;
      const fx = g.start.x - (sx * g.start.w) / 2;
      const fy = g.start.y - (sy * h0) / 2;
      const px = g.start.w + sx * dx;
      const py = h0 + sy * dy;
      const w = Math.min(COMBO_MAX_W, Math.max(COMBO_MIN_W, (px + py * g.aspect) / (1 + g.aspect * g.aspect)));
      c.w = w;
      c.x = fx + (sx * w) / 2;
      c.y = fy + (sy * w * g.aspect) / 2;
    }
    placeCombo();
  });
  const endComboGesture = (e) => {
    const g = comboGesture;
    if (!g || e.pointerId !== g.id) return;
    comboGesture = null;
    comboFrame.classList.remove('is-moving', 'is-resizing');
    scheduleSave();
  };
  comboFrame.addEventListener('pointerup', endComboGesture);
  comboFrame.addEventListener('pointercancel', endComboGesture);

  $('comboPrev').addEventListener('click', () => stepComboImage(-1));
  $('comboNext').addEventListener('click', () => stepComboImage(1));
  $('comboFade').addEventListener('click', (e) => {
    const b = e.target.closest('[data-fade]');
    if (b) setComboFade(b.dataset.fade);
  });
  $('comboAdjustBtn').addEventListener('click', () => (comboAdjust ? endComboAdjust() : startComboAdjust()));
  $('comboShow').addEventListener('click', toggleComboShown);
  $('comboFit').addEventListener('click', () => fitCombo());
  $('comboView').addEventListener('click', () => {
    const info = currentCombo();
    if (info) openViewer(info.rec, info.img.id);
  });
  $('comboRemove').addEventListener('click', removeCombo);
  $('comboSmaller').addEventListener('click', () => scaleCombo(1 / 1.1));
  $('comboBigger').addEventListener('click', () => scaleCombo(1.1));
  $('comboDone').addEventListener('click', () => endComboAdjust());
  $('comboCancel').addEventListener('click', () => endComboAdjust({ cancel: true }));


  // ---- コピーして送る ----
  // マスの写しを、登録した送り先（ノートの原点・マス）の下の階層の、中心に近い空いたマスに置く（今あるメモには重ねない）。
  // 送り先の登録は、すべてのメモアプリで共通。このウィンドウで開いているノートへは画面の中で置き、ほかのノートへは本体が置く。
  // ほかのメモアプリへは、相手のアプリが受け取って置く（相手が動いていなければ、画面を開かずに受け取って終わる）

  const sendMenu = $('sendMenu');
  const sendList = $('sendList');
  const sendDialog = $('sendTargetDialog');
  let sendTargets = []; // 登録した送り先（見出し付き。メニューを開くたびに読み直す）
  let sendCtx = null; // 送るもの { records, offsets, ids, rootOrigin, boardId, title, pos }
  let lastSent = null; // 最後に送った先 { targetId, placed }（「送り先を開く」で光らせる）
  let sendCatalogApps = [];

  const hasSendApi = () => !!(api && api.sendTargets);
  // 画面は新しいのに、本体（起動したときのまま）が古いと、送る機能の窓口が無い
  const isOldMain = (err) => /No handler registered/i.test(String(err && err.message));
  const SEND_RESTART = 'アプリの本体が更新前のままです。このメモアプリのウィンドウをすべて閉じてから起動し直すと使えます';
  const sendError = (err, what) => (isOldMain(err) ? SEND_RESTART : `${what}：${err.message}`);

  async function loadSendTargets() {
    if (!hasSendApi()) return sendTargets;
    const res = await ipc(api.sendTargets());
    sendTargets = res.targets || [];
    return sendTargets;
  }

  // 送り先の見出し：［ほかのメモアプリの名前］ノート › 子ノート（› 『メモの最初の行』）
  function targetLabel(t) {
    const app = t.self ? '' : `［${t.appName || 'メモアプリ'}］`;
    const board = t.boardPath && t.boardPath.length ? t.boardPath.join(' › ') : '';
    if (t.kind === 'board') return `${app}${board || '（ノート）'}`;
    return `${app}${board ? `${board} › ` : ''}『${t.memoText || '？'}』`;
  }
  const targetWhere = (t) => (!t.exists ? '見つかりません（削除された可能性があります）' : t.kind === 'board' ? 'ノートの原点の下へ' : 'このマスの下へ');

  // 送るマスそのものが送り先（自分の下へ写す）になっている
  function isSelfTarget(t, ctx) {
    if (!t.self || !ctx) return false;
    if (t.kind === 'memo') return ctx.ids.has(t.memoId);
    return t.boardId === ctx.boardId && ctx.rootOrigin;
  }

  // entries：[[キー, レコード]]（表示中の階層のマス）。送るものはメニューを開いたときの内容で決める
  async function openSendMenu(entries, pos) {
    if (!hasSendApi()) {
      toast('この版では、コピーして送るは使えません', 'warn');
      return;
    }
    const list = entries.filter(([, r]) => r && !isEmptyRecord(r));
    if (!list.length) return;
    if (list.length > HS.MAX_SEND) {
      toast(`一度に送れるのは ${HS.MAX_SEND} マスまでです`, 'warn');
      return;
    }
    let offsets = null;
    if (list.length > 1) {
      const a = H.parseKey(list.map(([k]) => k).sort(byPosition)[0]);
      offsets = list.map(([k]) => {
        const p = H.parseKey(k);
        return { dq: p.q - a.q, dr: p.r - a.r };
      });
    }
    sendCtx = {
      records: list.map(([, r]) => serializeRecord(r)),
      offsets,
      ids: new Set(list.map(([, r]) => r.id).filter(Boolean)),
      rootOrigin: list.some(([, r]) => r === rootLayer.memos.get(CENTER_KEY)), // ノートの原点のメモ（下の階層の中心として選んでも）
      boardId: currentBoardId,
      title: list.length > 1 ? `選んだ ${list.length} マス` : `『${recordLabel(list[0][1], list[0][0], 16)}』`,
      pos,
    };
    $('sendMenuHead').replaceChildren(el('strong', '', sendCtx.title), document.createTextNode(' の写しを送る'));
    sendList.replaceChildren(el('div', 'menu-empty', '読み込み中…'));
    showPopoverAt(sendMenu, pos);
    try {
      await flushAllSaves(); // 送り先の見出し（メモの最初の行）が新しいように
      await loadSendTargets();
    } catch (err) {
      sendList.replaceChildren(el('div', 'menu-empty', sendError(err, '送り先を読めませんでした')));
      return;
    }
    if (sendMenu.matches(':popover-open')) renderSendList();
  }

  function renderSendList() {
    const frag = document.createDocumentFragment();
    if (!sendTargets.length) {
      frag.append(el('div', 'menu-empty', '送り先がまだありません。下の「送り先を追加…」で、ノートやマスを登録できます（マスの右クリック →「このマスを送り先に登録」、ノートのタブの右クリックからも）'));
    }
    const mine = sendTargets.filter((t) => t.self);
    const others = sendTargets.filter((t) => !t.self);
    for (const [title, items] of [['このメモアプリ', mine], ['ほかのメモアプリ', others]]) {
      if (!items.length) continue;
      if (others.length) frag.append(el('div', 'menu-label', title));
      for (const t of items) frag.append(sendRow(t));
    }
    sendList.replaceChildren(frag);
    if (sendCtx && sendMenu.matches(':popover-open')) {
      sendMenu._size = null;
      showPopoverAt(sendMenu, sendCtx.pos); // 行が増えた分、画面に収まる位置へ
    }
  }

  function sendRow(t) {
    const row = el('div', 'send-row');
    const self = isSelfTarget(t, sendCtx);
    const go = el('button', 'send-to');
    go.type = 'button';
    go.setAttribute('role', 'menuitem');
    go.dataset.sendTo = t.id;
    go.disabled = !t.exists || self;
    const text = el('span', 'send-to-text');
    text.append(el('span', 'send-to-label', targetLabel(t)), el('span', 'send-to-where', self ? 'このマス自身なので送れません' : targetWhere(t)));
    go.append(svgIcon(t.kind === 'board' ? 'hex' : 'link'), text);
    go.title = `${targetLabel(t)}｜${targetWhere(t)}`;
    const open = el('button', 'icon-btn send-open');
    open.type = 'button';
    open.dataset.sendOpen = t.id;
    open.disabled = !t.exists;
    open.title = '送り先を開く（見に行く）';
    open.setAttribute('aria-label', open.title);
    open.append(svgIcon('arrow'));
    const rm = el('button', 'icon-btn send-remove');
    rm.type = 'button';
    rm.dataset.sendRemove = t.id;
    rm.title = '送り先の登録を外す';
    rm.setAttribute('aria-label', rm.title);
    rm.append(svgIcon('close'));
    row.append(go, open, rm);
    return row;
  }

  sendMenu.addEventListener('mousedown', (e) => e.preventDefault());
  sendMenu.addEventListener('click', async (e) => {
    const find = (id) => sendTargets.find((t) => t.id === id);
    const to = e.target.closest('[data-send-to]');
    const open = e.target.closest('[data-send-open]');
    const rm = e.target.closest('[data-send-remove]');
    const cmd = e.target.closest('button[data-cmd]');
    if (to) {
      if (to.disabled) return;
      sendMenu.hidePopover();
      const t = find(to.dataset.sendTo);
      if (t) sendTo(t);
    } else if (open) {
      if (open.disabled) return;
      sendMenu.hidePopover();
      const t = find(open.dataset.sendOpen);
      if (t) openSendTarget(t);
    } else if (rm) {
      try {
        await removeSendTargetById(rm.dataset.sendRemove);
        renderSendList();
      } catch (err) {
        toast(sendError(err, '外せませんでした'), 'error', 6000);
      }
    } else if (cmd && cmd.dataset.cmd === 'add-target') {
      sendMenu.hidePopover();
      openSendDialog();
    }
  });

  // 送る。このウィンドウで開いているノートへは画面の中で置く（書きかけ・まだ保存していない変更と重ならないように）
  async function sendTo(t) {
    const ctx = sendCtx;
    if (!ctx) return;
    const label = targetLabel(t);
    if (t.self && t.boardId === currentBoardId) {
      sendHere(t, ctx, label);
      return;
    }
    if (t.self && (unsettled.has(t.boardId) || failedBoards.has(t.boardId))) {
      toast('送り先のノートに、まだ保存できていない変更があるため送れません（少し待ってから、もう一度）', 'warn', 6000);
      return;
    }
    const target = { kind: t.kind, appId: t.appId || null, boardId: t.boardId || null, ...(t.kind === 'memo' ? { memoId: t.memoId } : {}) };
    toast(t.self ? `${label} に送っています…` : `［${t.appName}］に送っています…（受け取るまで少しかかります）`, 'info', 60000);
    let res;
    try {
      res = await ipc(api.sendRecords(target, { records: ctx.records, offsets: ctx.offsets }));
    } catch (err) {
      toast(sendError(err, '送れませんでした'), 'error', 7000);
      return;
    }
    if (res.pending) {
      toast(res.reason === 'old'
        ? `［${res.appName}］は、受け取れない古い版のまま動いています。そのアプリのウィンドウをすべて閉じてから起動し直すと届きます（送ったものは置いてあります）`
        : res.reason
          ? `［${res.appName}］がまだ受け取れていません：${res.reason}（受け取れるようになると届きます）`
          : `［${res.appName}］がまだ受け取っていません（起動に時間がかかっているのかもしれません。届いたらお知らせします）`, 'warn', 10000);
      return;
    }
    lastSent = { targetId: t.id, placed: res.placed || [] };
    const where = `${res.self ? '' : `［${res.appName}］`}${(res.boardPath || []).join(' › ')}${res.memoText ? `・『${res.memoText}』の下` : 'の原点の下'}`;
    const why = {
      'missing-memo': '送り先のマスが見つからなかったため', 'missing-board': '送り先のノートが見つからなかったため',
      'too-deep': '送り先のマスの下が深すぎるため', full: '送り先のマスの下に空きが無かったため',
    };
    const notes = [res.fellBack ? `${why[res.fellBackReason] || '送り先に置けなかったため'}、ノートの原点の下に置きました` : '', res.missing ? `画像 ${res.missing} 件は送れませんでした` : ''].filter(Boolean).join('。');
    toast(`「${where}」に ${(res.placed || []).length} マス送りました${notes ? `（${notes}）` : ''}`, notes ? 'warn' : 'info', 5000);
  }

  function sendHere(t, ctx, label) {
    if (!canSave()) {
      toast('このノートは保存を止めているため、送れません', 'error', 5000);
      return;
    }
    let parent;
    let depth;
    if (t.kind === 'memo') {
      const loc = locateById(t.memoId);
      if (!loc) {
        toast('送り先のマスが見つかりません（削除された可能性があります）', 'warn', 5000);
        return;
      }
      parent = loc.rec;
      depth = loc.keys.length;
    } else {
      parent = rootLayer.memos.get(CENTER_KEY);
      if (!parent) {
        parent = createRecord();
        rootLayer.memos.set(CENTER_KEY, parent);
      }
      depth = 0;
    }
    // 写しにすると空になるメモ（関連付けだけのメモなど）は除く（並びも合わせて）
    const keep = ctx.records.map((r) => !HS.isBlank(r));
    const raws = ctx.records.filter((_, i) => keep[i]);
    const offs = ctx.offsets ? ctx.offsets.filter((_, i) => keep[i]) : null;
    if (!raws.length) {
      toast('送るメモがありません', 'warn');
      return;
    }
    if (depth + 1 + Math.max(...raws.map(HS.subtreeHeight)) > MAX_DEPTH) {
      toast(`送り先の階層が深すぎるため送れません（${MAX_DEPTH} 階層まで）`, 'warn', 5000);
      return;
    }
    if (!parent.children) parent.children = newLayer();
    const layer = parent.children;
    const shown = currentLayer() === layer;
    const spots = HS.pickSpots((k) => {
      const r = layer.memos.get(k);
      return !(r && !isEmptyRecord(r)) && !(shown && k === editingKey);
    }, raws.length, offs);
    if (!spots) {
      toast('送り先に空いたマスが見つかりません', 'warn');
      return;
    }
    spots.forEach((k, i) => layer.memos.set(k, recordFromClip(JSON.parse(JSON.stringify(raws[i])))));
    lastSent = { targetId: t.id, placed: spots };
    refreshAllCells();
    renderLinks();
    updateTabCounts();
    renderCrumbs();
    if (side) renderSide();
    scheduleSave();
    flushSave(); // すぐ保存へ（このあとノートを切り替えても、送ったものが残るように）
    if (shown) flashCell(spots[0]);
    toast(`「${label}」の${t.kind === 'board' ? '原点の' : ''}下に ${spots.length} マス送りました`);
  }

  // 送り先を開く（見に行く）。最後にそこへ送ったマスがあれば、そこへ寄って光らせる
  async function openSendTarget(t) {
    if (!t.self) {
      try {
        const memoId = t.kind === 'memo' ? t.memoId : t.originId;
        if (memoId) {
          await ipc(api.openMemoLink(U.makeInternalLink({ memoId, boardId: t.boardId, appId: t.appId })));
          toast(`［${t.appName}］の送り先を開きます…`);
        } else {
          await ipc(api.openApp(t.appId || null));
          toast(`［${t.appName}］を開きます…（ノート「${(t.boardPath || []).join(' › ')}」に切り替えて、原点の下を見てください）`, 'info', 6000);
        }
      } catch (err) {
        toast(`開けませんでした：${err.message}`, 'error', 5000);
      }
      return;
    }
    if (t.boardId && t.boardId !== currentBoardId) await switchBoard(t.boardId);
    if (t.boardId && t.boardId !== currentBoardId) return;
    if (hive.open) closeHive();
    setTab('grid');
    let steps = null;
    if (t.kind === 'memo') {
      const loc = locateById(t.memoId);
      if (!loc) {
        toast('送り先のマスが見つかりません（削除された可能性があります）', 'warn', 5000);
        return;
      }
      if (!loc.rec.children) {
        jumpTo(loc.key, loc.keys);
        return;
      }
      steps = [...loc.keys, stepOf(loc.key, 0)];
    } else {
      const origin = rootLayer.memos.get(CENTER_KEY);
      if (!origin || !origin.children) {
        jumpTo(CENTER_KEY, []);
        return;
      }
      steps = [CENTER_KEY];
    }
    if (!setPath(steps, 'in')) return;
    const placed = lastSent && lastSent.targetId === t.id ? lastSent.placed.filter((k) => getRecord(k)) : [];
    if (placed.length) {
      const p = H.parseKey(placed[0]);
      const px = H.hexToPixel(p.q, p.r, HEX_SIZE);
      animateCameraTo(px.x, px.y, () => flashCell(placed[0]));
    }
  }

  // ---- 送り先の登録 ----

  // このメモアプリの、登録してある送り先（ノートはノートの ID、マスはメモの ID で）
  let sendRegistry = []; // 登録の一覧（見出しなし。右クリックのたびに軽く読み直す）
  const isMine = (t) => (t.appId || null) === (appId || null);
  const findIn = (list, kind, id) => list.find((t) => isMine(t) && t.kind === kind && (kind === 'board' ? t.boardId === id : t.memoId === id)) || null;
  async function loadSendRegistry() {
    if (!api || !api.sendRegistered) return loadSendTargets();
    const res = await ipc(api.sendRegistered());
    sendRegistry = res.targets || [];
    return sendRegistry;
  }

  async function addSendTarget(raw) {
    const res = await ipc(api.addSendTarget(raw));
    sendTargets = res.targets || sendTargets;
    sendRegistry = sendTargets;
    const t = sendTargets.find((x) => x.id === res.id);
    const message = res.existed ? `すでに送り先に登録してあります：${t ? targetLabel(t) : ''}`
      : `送り先に登録しました：${t ? targetLabel(t) : ''}（マスの右クリック →「コピーして送る…」で送れます）`;
    // 「送り先を追加」を開いているときは、その中に出す（トーストは窓の後ろに隠れるため）
    if (sendDialog.open) {
      setSendDialogMessage('status', message);
    } else {
      toast(message, 'info', 5000);
    }
    return res;
  }

  async function removeSendTargetById(id) {
    const res = await ipc(api.removeSendTarget(id));
    sendTargets = res.targets || [];
    sendRegistry = sendTargets;
  }

  // マスの右クリック →「このマスを送り先に登録」（もう一度で外す）。そのマスの下の階層へ送れるようになる
  async function toggleSendCell(key) {
    const rec0 = getRecord(key);
    if (!rec0 || isEmptyRecord(rec0) || !hasSendApi()) return;
    const boardId = currentBoardId;
    const layer = currentLayer();
    const knownId = rec0.id || null;
    try {
      await loadSendRegistry();
      // 読み込みを待つ間に、ノートを切り替えた・ほかのウィンドウの変更で読み直した：今のメモを探し直す
      if (currentBoardId !== boardId) return;
      const rec = knownId ? (locateById(knownId) || {}).rec : currentLayer() === layer ? getRecord(key) : null;
      if (!rec || isEmptyRecord(rec)) {
        toast('マスが変わったため、登録できませんでした（もう一度試してください）', 'warn');
        return;
      }
      const found = rec.id ? findIn(sendRegistry, 'memo', rec.id) : null;
      if (found) {
        await removeSendTargetById(found.id);
        toast('送り先の登録を外しました');
        return;
      }
      // メモの ID で覚えるので、ID を付けて保存してから（ほかのウィンドウ・ほかのメモアプリからも見つかるように）
      ensureId(rec);
      scheduleSave();
      await flushAllSaves();
      if (dirty || unsettled.size) await flushAllSaves();
      if (currentBoardId !== boardId) return;
      await addSendTarget({ kind: 'memo', appId, boardId, memoId: rec.id });
    } catch (err) {
      toast(sendError(err, '登録できませんでした'), 'error', 6000);
    }
  }

  // ノートのタブの右クリック →「このノートを送り先に登録」（もう一度で外す）。ノートの原点の下へ送れるようになる
  async function toggleSendBoard(id) {
    if (!hasSendApi() || !boardById(id)) return;
    try {
      await loadSendRegistry();
      const found = findIn(sendRegistry, 'board', id);
      if (found) {
        await removeSendTargetById(found.id);
        toast('送り先の登録を外しました');
        return;
      }
      await addSendTarget({ kind: 'board', appId, boardId: id });
    } catch (err) {
      toast(sendError(err, '登録できませんでした'), 'error', 6000);
    }
  }

  // メニューを開くとき：登録しているかで「登録」「外す」を出し分ける（覚えている一覧で。読み直したら合わせ直す）
  function syncSendItem(item, kind, id, labels) {
    if (!item) return;
    item.hidden = !hasSendApi();
    const found = () => (id ? findIn(sendRegistry, kind, id) || findIn(sendTargets, kind, id) : null);
    item.querySelector('span').textContent = found() ? labels[1] : labels[0];
    if (hasSendApi()) {
      const token = {};
      item._sendSync = token; // 読み直している間に、別のマスでメニューを開き直したら、古い結果で書き換えない
      loadSendRegistry().then(() => {
        if (item._sendSync === token) item.querySelector('span').textContent = id && findIn(sendRegistry, kind, id) ? labels[1] : labels[0];
      }).catch(() => {});
    }
  }

  // 「送り先を追加」の中の知らせ（kind：'status'・'error'・null）。前の知らせは消してから出す
  function setSendDialogMessage(kind, text = '') {
    const status = $('sendTargetStatus');
    const error = $('sendTargetError');
    status.hidden = kind !== 'status';
    error.hidden = kind !== 'error';
    if (kind) (kind === 'status' ? status : error).textContent = text;
  }

  // 「送り先を追加」：メモアプリごとのノートを選ぶ（もう一度で外す）、またはマスへのリンクを貼り付ける
  async function openSendDialog() {
    if (!hasSendApi()) return;
    setSendDialogMessage(null);
    $('sendLinkInput').value = '';
    $('sendCatalog').replaceChildren(el('div', 'menu-empty', '読み込み中…'));
    sendDialog.showModal();
    try {
      await loadSendTargets();
      const res = await ipc(api.sendCatalog());
      sendCatalogApps = res.apps || [];
      renderSendCatalog();
    } catch (err) {
      $('sendCatalog').replaceChildren(el('div', 'menu-empty', sendError(err, '読み込めませんでした')));
    }
  }

  function renderSendCatalog() {
    const frag = document.createDocumentFragment();
    const registered = (a, b) => sendTargets.find((t) => t.kind === 'board' && (t.appId || null) === (a.id || null) && t.boardId === b.id);
    for (const a of sendCatalogApps) {
      frag.append(el('div', 'send-cat-app', a.self ? `${a.name}（このメモアプリ）` : a.name));
      if (!a.available) {
        frag.append(el('div', 'send-cat-empty', 'ノートの一覧を読めませんでした'));
        continue;
      }
      for (const b of a.boards) {
        const on = registered(a, b);
        const btn = el('button', 'send-cat-item');
        btn.type = 'button';
        btn.dataset.catApp = a.id || '';
        btn.dataset.catBoard = b.id;
        btn.setAttribute('aria-pressed', String(!!on));
        btn.style.paddingLeft = `${10 + b.depth * 16}px`;
        btn.append(svgIcon(b.depth ? 'layers' : 'hex'), el('span', 'send-cat-name', b.name), el('span', 'send-cat-state', on ? '✓ 登録済み（押すと外す）' : '原点の下へ送る'));
        btn.title = on ? '送り先の登録を外す' : 'このノートを送り先に登録（ノートの原点の下の階層へ送る）';
        frag.append(btn);
      }
    }
    // マス（リンク）の送り先：ここで見て外せるように
    const cells = sendTargets.filter((t) => t.kind === 'memo');
    if (cells.length) {
      frag.append(el('div', 'send-cat-app', 'マスの送り先（そのマスの下へ送る）'));
      for (const t of cells) {
        const row = el('div', 'send-cat-memo');
        row.append(svgIcon('link'), el('span', 'send-cat-name', targetLabel(t)), el('span', 'send-cat-state', t.exists ? '' : '見つかりません'));
        const rm = el('button', 'icon-btn send-cat-remove');
        rm.type = 'button';
        rm.dataset.catRemove = t.id;
        rm.title = '送り先の登録を外す';
        rm.setAttribute('aria-label', rm.title);
        rm.append(svgIcon('close'));
        row.append(rm);
        frag.append(row);
      }
    }
    $('sendCatalog').replaceChildren(frag);
  }

  $('sendCatalog').addEventListener('click', async (e) => {
    const rmBtn = e.target.closest('[data-cat-remove]');
    if (rmBtn) {
      try {
        await removeSendTargetById(rmBtn.dataset.catRemove);
        setSendDialogMessage('status', '送り先の登録を外しました');
        renderSendCatalog();
      } catch (err) {
        setSendDialogMessage('error', sendError(err, '外せませんでした'));
      }
      return;
    }
    const btn = e.target.closest('.send-cat-item');
    if (!btn) return;
    const target = { kind: 'board', appId: btn.dataset.catApp || null, boardId: btn.dataset.catBoard };
    try {
      const on = sendTargets.find((t) => t.kind === 'board' && (t.appId || null) === target.appId && t.boardId === target.boardId);
      if (on) {
        await removeSendTargetById(on.id);
        setSendDialogMessage('status', '送り先の登録を外しました');
      } else {
        await addSendTarget(target);
      }
      renderSendCatalog();
    } catch (err) {
      setSendDialogMessage('error', sendError(err, '登録できませんでした'));
    }
  });

  async function addSendLink() {
    const text = $('sendLinkInput').value.trim();
    const link = U.parseInternalLink(text);
    const error = (msg) => setSendDialogMessage('error', msg);
    if (!link) {
      error('マスへのリンク（hexmemo://memo/… で始まるもの）を貼り付けてください');
      return;
    }
    if (isWeb && link.appId) {
      error('ほかのメモアプリのマスへのリンクは、ブラウザ版（iPad など）では使えません');
      return;
    }
    setSendDialogMessage(null);
    try {
      await addSendTarget({ kind: 'memo', appId: link.appId || null, boardId: link.boardId || null, memoId: link.memoId });
      $('sendLinkInput').value = '';
      renderSendCatalog();
    } catch (err) {
      error(sendError(err, '登録できませんでした'));
    }
  }
  $('sendLinkAdd').addEventListener('click', addSendLink);
  $('sendLinkInput').addEventListener('keydown', (e) => {
    if (e.isComposing || e.keyCode === 229) return;
    if (e.key === 'Enter') {
      e.preventDefault();
      addSendLink();
    }
  });
  $('sendTargetClose').addEventListener('click', () => sendDialog.close());
  closeOnBackdrop(sendDialog);
  sendDialog.addEventListener('close', () => {
    if (editingKey) editor.focus({ preventScroll: true });
  });

  // ほかのメモアプリから届いた・届けたお知らせ
  if (api && api.onAppNotice) api.onAppNotice((n) => showNotices([n]));

  // ---- サイドバーの操作 ----

  $('sideAddImage').addEventListener('click', () => $('sideImageInput').click());
  $('sideImageView').addEventListener('click', (e) => {
    const b = e.target.closest('[data-image-view]');
    if (b) setSideImageView(b.dataset.imageView);
  });
  $('sideImageInput').addEventListener('change', async (e) => {
    const files = [...e.target.files];
    e.target.value = '';
    if (files.length) await attachImagesToSide(files);
  });
  $('sideImageGrid').addEventListener('click', (e) => {
    const item = e.target.closest('.side-image');
    const rec = sideRecord();
    if (item && rec) openViewer(rec, item.dataset.id);
  });
  $('sideUrlForm').addEventListener('submit', (e) => {
    e.preventDefault();
    const input = $('sideUrlInput');
    const raw = input.value.trim();
    if (!raw) return;
    const rec = ensureSideRecord();
    if (!rec) return;
    if (addUrlToRecord(rec, raw)) input.value = '';
  });
  $('sideUrlInput').addEventListener('keydown', (e) => {
    if (e.isComposing || e.keyCode === 229 || e.key !== 'Enter') return;
    e.preventDefault();
    $('sideUrlForm').requestSubmit();
  });
  $('sideFetchToggle').addEventListener('change', (e) => {
    fetchLinkInfo = e.target.checked;
    writePref(FETCH_PREF, fetchLinkInfo);
    toast(fetchLinkInfo ? 'リンクを付けたとき、ページのタイトル・説明・画像を取得します' : 'リンク先の情報は取得しません（URL だけ保存します）');
  });
  $('sideCheckLinks').addEventListener('click', checkSideLinks);
  $('sideWebList').addEventListener('click', async (e) => {
    const b = e.target.closest('[data-web-act]');
    const item = e.target.closest('.side-web');
    const rec = sideRecord();
    if (!b || !item || !rec || b.disabled) return;
    const u = urlsOf(rec).find((x) => x.id === item.dataset.id);
    if (!u) return;
    const act = b.dataset.webAct;
    if (act === 'open') openAnyUrl(u.url);
    else if (act === 'copy') {
      try {
        await ipc(api.writeLink({ url: u.url, label: u.title || u.url }));
        toast('URL をコピーしました');
      } catch (err) {
        toast(`コピーできませんでした：${err.message}`, 'error', 5000);
      }
    } else if (act === 'refresh') fetchUrlInfo(rec, u);
    else if (act === 'snapshot') snapshotUrl(rec, u);
    else if (act === 'snapshot-open') {
      try {
        await ipc(api.openAttachment(u.snapshot.file));
      } catch (err) {
        toast(`開けませんでした：${err.message}`, 'error', 5000);
      }
    } else if (act === 'remove') {
      removeUrl(rec, u.id);
      toast('リンクを外しました');
    } else if (act === 'archive') openAnyUrl(`https://web.archive.org/web/*/${u.url}`);
    else if (act === 'go') jumpTo(b.dataset.key, b.dataset.path ? b.dataset.path.split('|') : []);
    else if (act === 'yt-set' || act === 'yt-clear') {
      const input = item.querySelector('.side-web-time');
      const sec = act === 'yt-clear' ? null : U.parseTime(input.value);
      if (act === 'yt-set' && sec === null) {
        toast('再生位置は「12:34」や「1:02:03」の形で入れてください', 'warn');
        return;
      }
      u.url = U.withYoutubeStart(u.url, sec);
      afterSideChange(rec);
      refreshAllCells();
      toast(sec ? `再生位置を ${U.formatTime(sec)} にしました` : '再生位置を外しました');
    }
  });
  $('sideWebList').addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && e.target.classList.contains('side-web-time')) {
      e.preventDefault();
      e.target.closest('.side-web').querySelector('[data-web-act="yt-set"]').click();
    }
  });

  // 関連タブの「同じページを含むメモ（自動）」
  // ---- つながりの候補（共通のタグ・言葉から） ----
  // 本文の2文字ずつのかたまり（日本語でも語に切らずに比べられる）の重なり・共通の語（漢字・カタカナの続き、英数字の語）・共通のタグで点を付け、
  // まだ関連付けていないメモから上位を出す。「つなぐ」で関連付け、「×」で候補から外す（この組はもう出さない）
  const textFeat = new WeakMap(); // rec → { text, grams, words }
  const WORD_RE = /[一-龯々〆ヵヶ]{2,}|[ァ-ヴー]{2,}|[A-Za-z][A-Za-z0-9]{2,}/g;
  const SUGGEST_PREF = 'hexMemo.suggestHidden';
  const pairKey = (a, b) => (a < b ? `${a}|${b}` : `${b}|${a}`);
  let suggestHiddenSet = null;
  function suggestHidden() {
    if (!suggestHiddenSet) {
      try {
        suggestHiddenSet = new Set(JSON.parse(localStorage.getItem(SUGGEST_PREF) || '[]'));
      } catch {
        suggestHiddenSet = new Set();
      }
    }
    return suggestHiddenSet;
  }
  function hideSuggestion(a, b) {
    const set = suggestHidden();
    set.add(pairKey(a, b));
    try {
      localStorage.setItem(SUGGEST_PREF, JSON.stringify([...set].slice(-3000)));
    } catch {
      // 覚えられなくても、この起動中は出さない
    }
  }

  function featOf(rec) {
    const text = rec.text || '';
    let f = textFeat.get(rec);
    if (f && f.text === text) return f;
    // ひらがな（助詞・送り仮名）・記号・空白で区切り、中身の語（漢字・カタカナ・英数字）の中だけで2文字ずつ
    const norm = text.toLowerCase().replace(/https?:\/\/\S+/g, ' ').replace(/[\s\p{P}\p{S}ぁ-ゖ]+/gu, ' ');
    const grams = new Set();
    for (const part of norm.split(' ')) {
      const ch = [...part];
      for (let i = 0; i + 1 < ch.length; i++) grams.add(ch[i] + ch[i + 1]);
    }
    const words = new Set((text.match(WORD_RE) || []).map((w) => w.toLowerCase()));
    f = { text, grams, words };
    textFeat.set(rec, f);
    return f;
  }

  function linkSuggestions(rec, limit = 5) {
    if (!rec || (!hasText(rec) && !tagsOf(rec).length)) return [];
    const me = featOf(rec);
    const myTags = new Set(tagsOf(rec));
    const linked = rec.id ? linkIndex.get(rec.id) || new Set() : new Set();
    const hidden = suggestHidden();
    const out = [];
    forEachMemo((r, key, keys) => {
      if (r === rec || (r.id && linked.has(r.id))) return;
      if (rec.id && r.id && hidden.has(pairKey(rec.id, r.id))) return;
      const f = featOf(r);
      let common = 0;
      for (const g of me.grams) if (f.grams.has(g)) common++;
      const cos = me.grams.size && f.grams.size ? common / Math.sqrt(me.grams.size * f.grams.size) : 0;
      const words = [];
      for (const w of me.words) { // 同じ語か、片方がもう片方を含む語（集中 と 集中力）。見せるのは短いほう
        const x = f.words.has(w) ? w : [...f.words].find((v) => v.includes(w) || w.includes(v));
        if (x) words.push(x.length < w.length ? x : w);
      }
      const tags = tagsOf(r).filter((t) => myTags.has(t));
      const score = cos * 0.7 + Math.min(words.length, 4) * 0.08 + Math.min(tags.length, 3) * 0.25;
      if (score < 0.2) return;
      out.push({ rec: r, key, keys, score, words: words.slice(0, 3), tags });
    });
    out.sort((a, b) => b.score - a.score);
    return out.slice(0, limit);
  }

  let sideSuggestItems = [];
  function renderSideSuggest(rec) {
    sideSuggestItems = rec && !isEmptyRecord(rec) ? linkSuggestions(rec) : [];
    $('sideSuggestList').replaceChildren(...sideSuggestItems.map((it, i) => {
      const why = el('span', 'chip chip-why');
      why.textContent = [it.tags.length ? it.tags.map((t) => `#${t}`).join(' ') : '', it.words.length ? it.words.map((w) => `「${w}」`).join('') : ''].filter(Boolean).join('　') || '本文が似ている';
      why.title = '候補に出たわけ（共通のタグ・言葉）';
      const link = el('button', 'chip chip-edit side-mini');
      link.type = 'button';
      link.dataset.suggestLink = String(i);
      link.title = 'このメモと関連付ける（線の種類はあとで「線」から変えられます）';
      link.append(svgIcon('link'), document.createTextNode('つなぐ'));
      const hide = el('button', 'chip side-mini');
      hide.type = 'button';
      hide.dataset.suggestHide = String(i);
      hide.title = '候補から外す（この組はもう出しません）';
      hide.append(svgIcon('close'));
      return buildSideItem(it.rec, it.key, it.keys, {
        label: locationLabel(it.keys, it.key), labelClass: 'side-dir is-suggest', coord: false, extra: [why, link, hide],
      });
    }));
    $('sideSuggest').hidden = sideSuggestItems.length === 0;
  }
  $('sideSuggestList').addEventListener('click', (e) => {
    const link = e.target.closest('[data-suggest-link]');
    const hide = e.target.closest('[data-suggest-hide]');
    const rec = sideRecord();
    if (!rec || (!link && !hide)) {
      if (!link && !hide) onSideListClick(e);
      return;
    }
    const it = sideSuggestItems[Number((link || hide).dataset.suggestLink ?? (link || hide).dataset.suggestHide)];
    if (!it) return;
    const a = ensureId(rec);
    const b = ensureId(it.rec);
    if (hide) {
      hideSuggestion(a, b);
      renderSide();
      return;
    }
    if (!isLinked(a, b)) addLink(a, b);
    refreshAllCells();
    renderLinks();
    scheduleSave();
    toast('関連付けました（線の種類は「線」から変えられます）', 'info', 2500);
  });

  function renderSideAuto(rec) {
    const items = rec ? samePageMemos(rec) : [];
    $('sideAutoList').replaceChildren(...items.map((it) => buildSideItem(it.rec, it.key, it.keys, {
      label: locationLabel(it.keys, it.key), labelClass: 'side-dir is-link', coord: false,
    })));
    $('sideAuto').hidden = items.length === 0;
  }
  $('sideAutoList').addEventListener('click', onSideListClick);

  // ---- ドラッグ＆ドロップ（画像ファイル・ブラウザからのリンク） ----

  const hasDropPayload = (dt) => !!dt && [...dt.types].some((t) => t === 'Files' || t === 'text/uri-list' || t === 'application/x-hexmemo-shelf');
  function droppedUrl(dt) {
    const list = (dt.getData('text/uri-list') || '').split(/\r?\n/).map((s) => s.trim()).filter((s) => s && !s.startsWith('#'));
    const url = list[0] || (dt.getData('text/plain') || '').trim();
    return U.classifyPasted(url) === 'web' ? url : null;
  }
  let fileDropKey = null;
  function markFileDrop(key) {
    if (fileDropKey === key) return;
    if (fileDropKey) activeCells.get(fileDropKey)?.classList.remove('is-file-drop');
    fileDropKey = key;
    if (key) activeCells.get(key)?.classList.add('is-file-drop');
  }

  stage.addEventListener('dragover', (e) => {
    if (!hasDropPayload(e.dataTransfer) || activeTab !== 'grid') return;
    e.preventDefault();
    const shelf = e.dataTransfer.types.includes('application/x-hexmemo-shelf');
    e.dataTransfer.dropEffect = shelf ? 'move' : 'copy';
    if (shelf && isOverview) {
      // 空のマスは DOM に無いので、紙片と同じ影を1枚出す（見るだけのときは影も出さない）
      if (overviewWrites()) {
        const land = overviewDropKey(e.clientX, e.clientY);
        showOvMark(land, 'drop', land ? `ここに置く（${formatCoord(land)}）` : '');
      } else hideOvMark();
      markFileDrop(null);
      return;
    }
    if (ovMark && ovMark.mode === 'drop') hideOvMark();
    markFileDrop(keyAt(e.clientX, e.clientY));
  });
  stage.addEventListener('dragleave', (e) => {
    if (!stage.contains(e.relatedTarget)) {
      markFileDrop(null);
      if (ovMark && ovMark.mode === 'drop' && !(pocketDrag && pocketDrag.honey) && !(shelfPlacing && overviewWrites())) hideOvMark();
    }
  });
  stage.addEventListener('drop', (e) => {
    if (!hasDropPayload(e.dataTransfer)) return;
    e.preventDefault();
    const key = keyAt(e.clientX, e.clientY);
    markFileDrop(null);
    if (ovMark && ovMark.mode === 'drop' && !(shelfPlacing && overviewWrites())) hideOvMark();
    const shelfKey = e.dataTransfer.getData('application/x-hexmemo-shelf');
    if (shelfKey !== '') {
      const act = shelfDropAction({ overview: isOverview, viewOnly: settings.overviewViewOnly === true, key });
      if (act.kind === 'ignore') return; // 見るだけの全体表示では、今までどおり何もしない
      const rec = shelfRecByKey(shelfKey);
      if (rec) placeShelfRec(rec, act.key);
      else shelfGone(); // 別のウィンドウで消えた・別のノートの棚から落とした
      return;
    }
    const files = [...e.dataTransfer.files];
    const images = files.filter(isImageFile);
    if (images.length) attachImagesToKey(key, images);
    else if (files.length) toast('画像ファイル（PNG・JPEG・GIF・WebP）をドロップしてください', 'warn');
    else {
      const url = droppedUrl(e.dataTransfer);
      if (url) addUrlToKey(key, url);
    }
  });
  sidePanel.addEventListener('dragover', (e) => {
    if (!hasDropPayload(e.dataTransfer) || !side || side.list || side.series) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
    sidePanel.classList.add('is-file-drop');
  });
  sidePanel.addEventListener('dragleave', (e) => {
    if (!sidePanel.contains(e.relatedTarget)) sidePanel.classList.remove('is-file-drop');
  });
  sidePanel.addEventListener('drop', (e) => {
    sidePanel.classList.remove('is-file-drop');
    if (!hasDropPayload(e.dataTransfer) || !side || side.list || side.series || e.target.closest('input, textarea')) return;
    e.preventDefault();
    const images = [...e.dataTransfer.files].filter(isImageFile);
    if (images.length) {
      setSideTab('images');
      attachImagesToSide(images);
      return;
    }
    const url = droppedUrl(e.dataTransfer);
    const rec = url && ensureSideRecord();
    if (rec) {
      setSideTab('web');
      addUrlToRecord(rec, url);
    }
  });
  // そのほかの場所に落としたファイルで、画面がファイルに切り替わらないように
  document.addEventListener('dragover', (e) => {
    if (e.dataTransfer && [...e.dataTransfer.types].includes('Files')) e.preventDefault();
  });
  document.addEventListener('drop', (e) => {
    if (e.dataTransfer && [...e.dataTransfer.types].includes('Files') && !e.defaultPrevented) e.preventDefault();
  });

  // 本文の入力中に画像を貼り付けたら、そのマスに添付する（文字の貼り付けはそのまま）
  editor.addEventListener('paste', (e) => {
    const files = [...(e.clipboardData ? e.clipboardData.files : [])].filter(isImageFile);
    if (!files.length || !editingKey) return;
    e.preventDefault();
    attachImagesToKey(editingKey, files);
  });

  // ---- メニューからの操作 ----

  async function flushAllSaves() {
    flushSave();
    await saveChain;
  }

  // メモアプリ全体（すべてのノート・ツリー・添付ファイル）を1つの zip に書き出す。
  // デスクトップ版では保存先を選び、ブラウザ版（iPad など）では共有（「ファイル」・Google Drive など）かダウンロード
  async function exportApp() {
    if (!api) return;
    try {
      await flushAllSaves();
      const res = await ipc(api.exportApp());
      if (res.canceled) return;
      toast(`${isWeb ? 'データ' : 'メモアプリ全体'}（ノート ${res.boards} 冊・画像など ${res.files} 件）を書き出しました：${res.path}`
        + `${res.missing ? `（見つからないファイル ${res.missing} 件）` : ''}`, 'info', 7000);
    } catch (err) {
      toast(`書き出せませんでした：${err.message}`, 'error', 6000);
    }
  }

  // ---- ブラウザ版：書き出した zip を読み込む ----
  // メモアプリ全体の zip なら、このブラウザ版のデータをそっくり入れ替える（確認あり）。ノート1冊の zip なら新しいタブとして加える
  let importing = false;

  function chooseImportFile() {
    if (!api || !api.importData) return;
    const input = $('importDataInput');
    input.value = '';
    input.click();
  }

  $('importDataInput').addEventListener('change', async (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file || !api || !api.importData || importing) return;
    let info;
    try {
      info = await ipc(api.inspectImport(file));
    } catch (err) {
      toast(`読み込めませんでした：${err.message}`, 'error', 7000);
      return;
    }
    const ok = await confirmAction(info.kind === 'app' ? {
      title: `「${info.name}」を読み込みますか？`,
      message: `ノート ${info.boards} 冊・画像など ${info.attachments} 件を読み込みます。今このブラウザにあるデータ（「${info.current.name}」ノート ${info.current.boards} 冊）は、すべて入れ替わります。`
        + '残しておきたいときは、先にメニューの「データを書き出す」で保存してください。',
      confirmLabel: '入れ替えて読み込む',
    } : {
      title: `ノート「${info.name}」を加えますか？`,
      message: `ノート1冊の書き出しです。新しいタブとして加えます（画像など ${info.attachments} 件）。今のノートはそのまま残ります。`,
      confirmLabel: 'タブとして加える',
      danger: false,
    });
    if (!ok) return;
    importing = true;
    try {
      await flushAllSaves();
      boardReadOnly = true; // 読み込み中・読み込み後に、古い内容を保存しないように
      const res = await ipc(api.importData(file));
      toast(res.kind === 'app' ? `「${res.name}」を読み込みました（ノート ${res.boards} 冊）。開き直します…` : `ノート「${res.name}」を加えました。開き直します…`, 'info', 4000);
      setTimeout(() => location.reload(), 600);
    } catch (err) {
      importing = false;
      boardReadOnly = false;
      toast(`読み込めませんでした：${err.message}`, 'error', 7000);
    }
  });

  async function importBookmarks() {
    if (!api) return;
    if (boardsReadOnly) {
      toast('ノート一覧を保存できない状態のため、読み込めません', 'error');
      return;
    }
    try {
      await flushAllSaves();
      const res = await ipc(api.importBookmarks());
      if (res.canceled) return;
      boards = res.boards;
      renderBoardTabs();
      await switchBoard(res.rootId, { force: true });
      toast(`ブックマーク ${res.bookmarks} 件を読み込みました（ノート ${res.notebooks} 冊・フォルダごとに子ノート）`, 'info', 5000);
    } catch (err) {
      toast(`読み込めませんでした：${err.message}`, 'error', 6000);
    }
  }

  async function sweepAttachments() {
    if (!api) return;
    try {
      await flushAllSaves();
      const res = await ipc(api.sweepAttachments({ graceMs: 60 * 1000 }));
      toast(res.removed ? `使われていない画像など ${res.removed} 件（${formatBytes(res.bytes)}）を片付けました` : '片付けるファイルはありませんでした');
    } catch (err) {
      toast(`片付けられませんでした：${err.message}`, 'error', 5000);
    }
  }

  async function registerProtocol() {
    if (!api) return;
    const ok = await confirmAction({
      title: 'hexmemo:// のリンクを有効にしますか？',
      message: 'メールやほかのメモアプリに貼った「マスへのリンク」を押したときに、六角メモが開いてそのマスへ移動するよう、Windows に登録します（このユーザーの設定だけが変わります）。',
      confirmLabel: '登録する',
      danger: false,
    });
    if (!ok) return;
    try {
      const res = await ipc(api.registerProtocol());
      toast(res.registered ? 'hexmemo:// のリンクをほかのアプリから開けるようにしました' : '登録できませんでした', res.registered ? 'info' : 'warn');
    } catch (err) {
      toast(`登録できませんでした：${err.message}`, 'error', 5000);
    }
  }

  async function exportBoard(id) {
    if (!api) return;
    try {
      await flushAllSaves();
      const res = await ipc(api.exportBoard(id));
      if (res.canceled) return;
      toast(`書き出しました（画像など ${res.files} 件を含む）：${res.path}${res.missing ? `（見つからないファイル ${res.missing} 件）` : ''}`, 'info', 6000);
    } catch (err) {
      toast(`書き出せませんでした：${err.message}`, 'error', 5000);
    }
  }

  $('coverToggle').addEventListener('click', () => setShowCovers(!showCovers));
  updateCoverToggle();

  // マスの右クリックメニュー「画像を添付…」
  let cellImageKey = null;
  $('cellImageInput').addEventListener('change', async (e) => {
    const files = [...e.target.files];
    e.target.value = '';
    const key = cellImageKey;
    cellImageKey = null;
    if (files.length && key) await attachImagesToKey(key, files);
  });

  // ---- タブ・一覧 ------------------------------------------------------------

  function setTab(tab) {
    if (!TABS[tab]) return;
    hidePeek();
    hideGraphPeek(); // グラフの一覧の全文の吹き出しも（タブを離れる・開き直すとき）
    hideGraphHover(); // グラフのノードのカードも
    queueMicrotask(updateMultiBar);
    if (tab !== 'grid') {
      if (reading) stopReading({ quiet: true });
      endDrag();
      endEdit();
      if (linking) cancelLinking();
    }
    if (tab !== 'graph') closeGraphBundle(); // つながりの束はグラフのタブの中だけ
    if (tab !== 'graph' && document.body.classList.contains('graph-maxed')) setGraphMax(false); // グラフのタブを離れたら最大化は戻す
    activeTab = tab;
    for (const btn of tabButtons) {
      const selected = btn.dataset.tab === tab;
      btn.setAttribute('aria-selected', String(selected));
      btn.tabIndex = selected ? 0 : -1;
    }
    const grid = tab === 'grid';
    const isGraph = tab === 'graph';
    stage.hidden = !grid;
    listView.hidden = grid || isGraph;
    graphView.hidden = !isGraph;
    if (grid) {
      measureView();
      enforceGridZoomLock(); // グラフを見ている間にほかのウィンドウで固定された倍率に、戻ったときに合わせる
      lastSignature = '';
      render();
    } else if (isGraph) {
      stopCameraAnimation();
      // 戻るたびに全体表示にする。固定中は、はじめの一度だけ（はっきり頼んだ並べ直し（この関係線のグラフ・並びを開く）はそのまま）
      if (gCamFree()) graph.fitPending = true;
      renderGraphView();
      // ほかのウィンドウでグラフの倍率を固定した後など：固定した倍率に合わせる（位置は真ん中のまま）
      const lk = gZoomLocked();
      if (lk != null && Math.round(graph.cam.k * 100) !== Math.round(lk * 100)) gZoomTo(lk);
    } else {
      stopCameraAnimation();
      renderList();
      listView.scrollTop = 0;
    }
    renderCrumbs();
    zoomUiKey = '';
    updateZoomUi(); // 右上の倍率を、見ている画面（ハニカム・グラフ）の倍率に
  }

  // 件数と一覧は、ノート全体（周りに書いた下の階層も含む）が対象
  function updateTabCounts() {
    const counts = { like1: 0, like2: 0, like3: 0, bookmark: 0 };
    forEachMemo((rec) => {
      if (rec.likedLevel > 0) counts[`like${rec.likedLevel}`]++;
      if (rec.bookmarked) counts.bookmark++;
    });
    for (const [id, n] of Object.entries(counts)) tabCountEls[id].textContent = `(${n})`;
    updateDueCount();
    updateShelfCount();
  }

  function renderList() {
    const def = TABS[activeTab];
    if (!def || !def.match) return;
    const items = [];
    forEachMemo((rec, key, keys) => {
      if (def.match(rec)) items.push([key, rec, keys]);
    });
    items.sort((a, b) => Date.parse(b[1].updatedAt) - Date.parse(a[1].updatedAt));

    const head = el('div', 'list-head');
    head.append(el('h2', '', def.label));
    if (items.length) head.append(el('p', '', `${items.length} 件 · 更新が新しい順 · クリックでハニカムの該当マスへ移動`));

    if (!items.length) {
      const empty = el('div', 'empty-state');
      empty.append(svgIcon(activeTab === 'bookmark' ? 'bookmark' : 'heart'), el('strong', '', `「${def.label}」のメモはまだありません`), el('p', '', def.hint));
      listView.replaceChildren(head, empty);
      return;
    }

    const grid = el('ul', 'card-grid');
    for (const [key, rec, keys] of items) grid.append(buildCard(key, rec, keys));
    listView.replaceChildren(head, grid);
  }

  // 道筋 keys の各メモの見出し（ノート直下から順に）
  function pathLabels(keys, root = rootLayer) {
    const labels = [];
    let layer = root;
    for (const step of keys) {
      const { key, li } = parseStep(step);
      const rec = layer && layer.memos.get(key);
      if (!rec) break;
      // 重ねた層（第2層以降）にあるときは、層の名前も添える
      labels.push(li > 0 ? `${recordLabel(rec, key, 12)}（${layerName(rec, li)}）` : recordLabel(rec, key, 12));
      layer = layerOf(rec, li);
    }
    return labels;
  }

  function buildCard(key, rec, keys = []) {
    const li = el('li');
    const card = el('button', 'card');
    card.type = 'button';
    card.dataset.key = key;
    card.dataset.path = keys.join('|');

    const meta = el('span', 'card-meta');
    const coord = el('span', 'card-coord');
    coord.append(svgIcon('hex'), document.createTextNode(formatCoord(key)));
    const time = el('span', 'card-time', `更新 ${formatRelative(rec.updatedAt)}`);
    time.title = formatFull(rec.updatedAt);
    const go = el('span', 'card-go');
    go.title = 'ハニカムで開く';
    go.append(svgIcon('arrow'));
    meta.append(coord, time, go);

    const text = el('span', `card-text${hasText(rec) ? '' : ' is-empty'}`, hasText(rec) ? rec.text : '（本文なし）');

    const states = el('span', 'card-states');
    if (rec.likedLevel > 0) {
      const chip = el('span', `chip chip-like-${rec.likedLevel}`);
      chip.append(svgIcon('heart'), document.createTextNode(LIKE_LABELS[rec.likedLevel]));
      states.append(chip);
    }
    if (rec.bookmarked) {
      const chip = el('span', 'chip chip-bookmark');
      chip.append(svgIcon('bookmark'), document.createTextNode('ブックマーク'));
      states.append(chip);
    }
    if (rec.comments.length) {
      const chip = el('span', 'chip chip-comment');
      chip.append(svgIcon('comment'), document.createTextNode(`コメント ${rec.comments.length}`));
      states.append(chip);
    }
    if (linkCount(rec)) {
      const chip = el('span', 'chip chip-link');
      chip.append(svgIcon('link'), document.createTextNode(`関連 ${linkCount(rec)}`));
      states.append(chip);
    }
    for (const [n, cls, icon, word] of [[imagesOf(rec).length, 'chip-image', 'clip', '画像'], [urlsOf(rec).length, 'chip-web', 'globe', 'リンク']]) {
      if (!n) continue;
      const chip = el('span', `chip ${cls}`);
      chip.append(svgIcon(icon), document.createTextNode(`${word} ${n}`));
      states.append(chip);
    }
    card.title = 'クリックでハニカムの該当マスへ移動';
    card.append(meta);
    if (keys.length) {
      // 下の階層にあるメモは、どのメモの周りに書いたものかを示す
      const where = el('span', 'card-path');
      where.append(svgIcon('layers'), document.createTextNode(`${pathLabels(keys).join(' › ')} の周り`));
      card.append(where);
    }
    card.append(text, states);
    li.append(card);
    return li;
  }

  document.querySelector('.tabs').addEventListener('click', (e) => {
    const btn = e.target.closest('.tab');
    if (btn) setTab(btn.dataset.tab);
  });
  listView.addEventListener('click', (e) => {
    const card = e.target.closest('.card');
    if (card) jumpTo(card.dataset.key, card.dataset.path ? card.dataset.path.split('|') : []);
  });

  // ---- ノート（上段のタブ） ------------------------------------------------------

  async function ipc(promise) {
    const res = await promise;
    if (!res || !res.ok) throw new Error((res && res.error) || '不明なエラー');
    return res;
  }

  const currentBoard = () => boards.find((b) => b.id === currentBoardId);

  // ---- ノートのツリー ----
  // 上段のタブ = 親を持たないノート。タブの中に子ノート（さらにその子ノート…）を作れる。
  // どのノートも別々のハニカム（別の保存ファイル）を持つ。兄弟の並びは boards の中の順番

  const MAX_BOARD_DEPTH = 10; // boards.js と同じ上限（タブを 1 段目として数える）
  const boardById = (id) => boards.find((b) => b.id === id);
  const parentOfBoard = (id) => {
    const b = boardById(id);
    return b && b.parentId ? b.parentId : null;
  };
  const rootBoards = () => boards.filter((b) => !b.parentId);
  const siblingBoards = (parentId) => boards.filter((b) => (b.parentId || null) === (parentId || null));

  function rootOfBoard(id) {
    let cur = id;
    for (let p = parentOfBoard(cur); p; p = parentOfBoard(cur)) cur = p;
    return cur;
  }

  // タブから、そのノートまでの道筋
  function boardPath(id) {
    const out = [];
    for (let cur = id; cur; cur = parentOfBoard(cur)) {
      const b = boardById(cur);
      if (!b) break;
      out.unshift(b);
    }
    return out;
  }

  // そのノートと子孫（子ノート・孫ノート…）の ID。親が先に並ぶ
  function boardSubtree(id) {
    const ids = [id];
    for (let i = 0; i < ids.length; i++) for (const b of boards) if (b.parentId === ids[i]) ids.push(b.id);
    return ids;
  }

  // タブを押したときに開くノート：そのタブで最後に開いていたノート
  function tabTarget(rootId) {
    const root = boardById(rootId);
    const open = root && root.openId;
    return open && boardById(open) && rootOfBoard(open) === rootId ? open : rootId;
  }

  // そのタブで最後に開いたノートとして覚える（本体の boards.json と同じ規則）
  function rememberOpen(id) {
    const root = boardById(rootOfBoard(id));
    if (!root) return;
    if (root.id === id) delete root.openId;
    else root.openId = id;
  }

  function updateTitle() {
    const names = boardPath(currentBoardId).map((b) => b.name);
    document.title = names.length ? `${names.join(' › ')} - ${appName}` : appName;
  }

  function renderBoardTabs() {
    const frag = document.createDocumentFragment();
    for (const b of rootBoards()) {
      const tab = el('div', 'board-tab');
      tab.dataset.id = b.id;
      tab.setAttribute('role', 'tab');
      const target = tabTarget(b.id);
      const kids = boardSubtree(b.id).length - 1;
      tab.title = `${boardPath(target).map((x) => x.name).join(' › ')}（ダブルクリックで名前を変更${kids ? '・⌄ でタブの中のノート' : ''}）`;
      tab.append(el('span', 'board-name', b.name));
      // タブの中で開いている（最後に開いた）子ノート
      if (target !== b.id) tab.append(el('span', 'board-sub', `› ${boardById(target).name}`));
      if (kids) {
        const pill = el('span', 'board-kids', String(kids));
        pill.title = `このタブの中の子ノート ${kids} 冊`;
        tab.append(pill);
      }
      const more = el('button', 'board-more');
      more.type = 'button';
      more.tabIndex = -1;
      more.title = 'このタブの中のノート（子ノートの作成・並べ替え）';
      more.setAttribute('aria-label', `「${b.name}」タブの中のノート`);
      more.setAttribute('aria-haspopup', 'tree');
      more.setAttribute('aria-expanded', String(treeIsOpen() && treeRootId === b.id));
      more.append(svgIcon('chevron'));
      tab.append(more);
      frag.append(tab);
    }
    boardTabsEl.replaceChildren(frag);
    syncBoardSelection();
  }

  // 切り替えでは選択表示だけ更新する（名前の入力中にタブを作り直さないため）
  function syncBoardSelection() {
    const root = currentBoardId ? rootOfBoard(currentBoardId) : null;
    for (const tab of boardTabsEl.children) {
      const selected = tab.dataset.id === root;
      tab.setAttribute('aria-selected', String(selected));
      tab.tabIndex = selected ? 0 : -1;
      if (selected) revealBoardTab(tab);
    }
    updateTabOverflow();
    if (hive.open) renderHive(); // ノートのハニカムも（開いているノート・名前・ノートの増減）
  }

  // 選択中のタブが見えるよう、タブの列の中だけをスクロールする
  // （scrollIntoView は画面全体までずらしてしまうことがあるので使わない）
  function revealBoardTab(tab) {
    const t = tab.getBoundingClientRect();
    const s = boardTabsEl.getBoundingClientRect();
    const pad = 32; // 端の薄くなる部分に掛からないように
    if (t.left < s.left + pad) boardTabsEl.scrollLeft -= s.left + pad - t.left;
    else if (t.right > s.right - pad) boardTabsEl.scrollLeft += t.right - (s.right - pad);
  }

  function updateTabOverflow() {
    const max = boardTabsEl.scrollWidth - boardTabsEl.clientWidth;
    boardTabsEl.classList.toggle('is-scroll-left', boardTabsEl.scrollLeft > 1);
    boardTabsEl.classList.toggle('is-scroll-right', boardTabsEl.scrollLeft < max - 1);
  }

  // タブ（中で開いているノート名など）とツリーを今の状態に。名前の入力中は作り直さない
  function refreshBoardTabs() {
    if (boardTabsEl.querySelector('.board-rename')) syncBoardSelection();
    else renderBoardTabs();
    if (treeIsOpen() && !boardTreeList.querySelector('.board-rename')) renderBoardTree();
  }

  function applyBoard(id, payload) {
    hidePeek();
    currentBoardId = id;
    boardReadOnly = !!payload.readOnly;
    stopCameraAnimation();
    clearTimeout(saveTimer);
    saveTimer = 0;
    dirty = false;
    dataDirty = false;
    firstDirtyAt = 0;
    clearTimeout(flashTimer);
    flashKey = null;

    endDrag();
    if (linking) cancelLinking(); // 関連付けは同じノートの中だけ
    closeSide();
    if (reading) stopReading({ quiet: true });
    if (viewer.open) viewer.close();
    selectedKey = null;
    resetMulti();
    links = Array.isArray(payload.store.links) ? payload.store.links.map(serializeLink) : [];
    rebuildLinkIndex();
    rootLayer = toLayer(payload.store);
    attachRootExtras(rootLayer, payload.store);
    activePocketId = null;
    rebuildCopyIndex();
    lastVisit = null;
    activeDend = null;
    if (shelfPlacing) cancelShelfPlacing();
    if (tplPlacing) cancelTemplatePlacing();
    graph.pos.clear();
    graph.selected = null;
    graph.camReady = false; // 別のノート：固定中でも一度は全体表示にする
    graph.lockPos = null;
    if (graph.locked) graph.fitPending = true; // グラフのタブのまま切り替えたときも、並べ直して全体表示に
    path = []; // ノートを開いたらノート直下から
    memos = rootLayer.memos;
    camera = rootLayer.camera;
    enforceGridZoomLock();
    anchor.x = Math.round(camera.x);
    anchor.y = Math.round(camera.y);
    for (const node of activeCells.values()) {
      placeCell(node);
      updateCellContent(node);
    }
    lastSignature = '';
    ready = true;

    rememberOpen(id);
    refreshBoardTabs();
    updateTitle();
    updateTabCounts();
    renderCrumbs();
    if (activeTab === 'grid') {
      measureView();
      render();
    } else {
      renderList();
      listView.scrollTop = 0;
    }
    renderLinks();
    if (payload.rev !== undefined) {
      setSync(id, payload.rev, serialize());
      ownNext.delete(id);
    }
    if (boardReadOnly) setSaveStatus('disabled', 'このノートは読み込みに失敗したため保存を停止しています');
    else if (!failedBoards.size) setSaveStatus('saved');
    showNotices(payload.notices);
    resetUndo({ keep: true }); // 前に開いていたときと同じ内容なら、元に戻す履歴も続けて使える
    updateTrashCount();
    updateTodayBadge();
    maybeOpenTodayOnStart();
  }

  async function switchBoard(id, { force = false } = {}) {
    if (!api || !id || (!force && id === currentBoardId)) return;
    if (sendMenu.matches(':popover-open')) sendMenu.hidePopover(); // 送るものは、そのノートのマス
    const seq = ++switchSeq;
    // 作成履歴を出していたら、切り替えた後も出したままに（開いていたノートの履歴なら、切り替えたノートの履歴へ）
    const history = side && (side.list === 'history' || side.list === 'overview')
      ? { list: side.list, board: side.board === currentBoardId ? id : side.board, sort: side.sort } : null;
    endEdit();
    if (slipEdit) saveSlipEdit({ by: 'interrupt' }); // 区画の紙片の書きかけも、切り替える前のノートに保存
    cancelPocketDrag();
    if (undoTimer) undoCheckpoint(); // 切り替え前のノートの最後の変更も、元に戻せるように覚える
    flushSave(); // 切り替え前のノートの変更を、そのノート宛てに送る
    document.body.classList.add('is-switching');
    try {
      const payload = await ipc(api.loadBoard(id));
      if (seq !== switchSeq) return; // もっと新しい切り替えが走っている
      applyBoard(id, payload);
      if (history && history.list === 'overview') openOverview(history.board);
      else if (history) openHistory(history.board, { sort: history.sort });
      api.activateBoard(id).catch(() => {});
    } catch (err) {
      if (seq === switchSeq) toast(`ノートを開けませんでした：${err.message}`, 'error', 5000);
    } finally {
      if (seq === switchSeq) document.body.classList.remove('is-switching');
    }
  }

  // Ctrl+Tab：隣のタブへ（そのタブで最後に開いていたノート）
  function cycleBoard(step) {
    const roots = rootBoards();
    if (roots.length < 2) return;
    const i = roots.findIndex((b) => b.id === rootOfBoard(currentBoardId));
    switchBoard(tabTarget(roots[(i + step + roots.length) % roots.length].id));
  }

  // parentId を指定すると、そのノートの子ノートを作る（ツリーを開いて、すぐに名前を付けられる）
  async function createBoard(parentId = null) {
    if (!api) return;
    if (boardsReadOnly) {
      toast('ノート一覧を保存できない状態のため、ノートを追加できません', 'error');
      return;
    }
    try {
      const res = await ipc(api.createBoard(parentId));
      boards = res.boards;
      if (parentId) expandBoardPath(res.board.id);
      renderBoardTabs();
      await switchBoard(res.board.id);
      if (parentId) startRename(res.board.id, { inTree: true });
      else startRename(res.board.id); // すぐに名前を付けられるように
    } catch (err) {
      toast(`${parentId ? '子ノート' : 'ノート'}を作成できませんでした：${err.message}`, 'error', 5000);
    }
  }

  // タブのノートはタブの上で、子ノート（または inTree のとき）はツリーの行の上で名前を入力する
  function startRename(id, { inTree = false } = {}) {
    if (!id || boardsReadOnly) return;
    const board = boardById(id);
    if (!board) return;
    let host;
    let nameEl;
    if (inTree || board.parentId) {
      const rootId = rootOfBoard(id);
      expandBoardPath(id);
      if (!treeIsOpen() || treeRootId !== rootId) openBoardTree(rootId, { focus: false });
      else renderBoardTree();
      host = boardTreeList.querySelector(`.tree-row[data-id="${id}"]`);
      nameEl = host && host.querySelector('.tree-name');
    } else {
      host = boardTabsEl.querySelector(`.board-tab[data-id="${id}"]`);
      nameEl = host && host.querySelector('.board-name');
    }
    if (!host || !nameEl || host.querySelector('.board-rename')) return;

    const input = document.createElement('input');
    input.className = 'board-rename';
    input.value = board.name;
    input.maxLength = 40;
    input.spellcheck = false;
    input.setAttribute('aria-label', 'ノート名');
    nameEl.replaceWith(input);
    input.focus();
    input.select();

    const inRow = host.classList.contains('tree-row');
    let finished = false;
    const finish = async (commit) => {
      if (finished) return;
      finished = true;
      const name = input.value.replace(/\s+/g, ' ').trim();
      if (commit && name && name !== board.name) {
        try {
          boards = (await ipc(api.renameBoard(id, name))).boards;
        } catch (err) {
          toast(`名前を変更できませんでした：${err.message}`, 'error', 5000);
        }
      }
      renderBoardTabs();
      if (treeIsOpen()) renderBoardTree();
      updateTitle();
      if (inRow && treeIsOpen()) focusTreeRow(id);
      else if (editingKey) editor.focus({ preventScroll: true });
    };
    input.addEventListener('keydown', (e) => {
      e.stopPropagation(); // Space・Esc などを全体のショートカットに渡さない
      if (e.isComposing || e.keyCode === 229) return;
      if (e.key === 'Enter') {
        e.preventDefault();
        finish(true);
      } else if (e.key === 'Escape') {
        e.preventDefault();
        finish(false);
      }
    });
    input.addEventListener('blur', () => finish(true));
    for (const type of ['click', 'dblclick', 'contextmenu', 'pointerdown']) input.addEventListener(type, (e) => e.stopPropagation());
  }

  // 子ノートも一緒に削除する（メモの件数は子ノートの分も合わせて確認に出す）
  async function deleteBoard(id) {
    const board = boardById(id);
    if (!board || boardsReadOnly) return;
    const ids = boardSubtree(id);
    if (ids.length >= boards.length) return; // ノートが1冊も残らなくなる
    const includesCurrent = ids.includes(currentBoardId);

    let count = 0;
    let unknown = false;
    await Promise.all(ids.map(async (bid) => {
      if (bid === currentBoardId) {
        forEachMemo(() => count++);
        return;
      }
      try {
        count += (await ipc(api.boardStats(bid))).memoCount;
      } catch {
        unknown = true;
      }
    }));
    const kids = ids.length - 1;
    const scope = kids ? `このノートと子ノート ${kids} 冊` : 'このノート';
    const detail = unknown ? `${scope}のメモがすべて削除されます。`
      : count > 0 ? `${scope}のメモ ${count} 件（いいね・ブックマーク・コメントを含む）がすべて削除されます。`
        : `${scope}にはメモがありません。`;
    const ok = await confirmAction({ title: `「${board.name}」を削除しますか？`, message: `${detail}この操作は取り消せません。`, confirmLabel: 'ノートを削除' });
    if (!ok) return;

    const hadChanges = includesCurrent && dirty;
    if (includesCurrent) {
      endEdit();
      clearTimeout(saveTimer); // これから消すノートには保存しない
      saveTimer = 0;
      dirty = false;
      dataDirty = false;
      firstDirtyAt = 0;
    }
    try {
      const res = await ipc(api.deleteBoard(id));
      boards = res.boards;
      for (const bid of ids) {
        unsettled.delete(bid);
        failedBoards.delete(bid);
        collapsedBoards.delete(bid);
      }
      if (treeIsOpen() && !boardById(treeRootId)) closeBoardTree();
      renderBoardTabs();
      if (treeIsOpen()) renderBoardTree();
      if (includesCurrent) await switchBoard(res.activeId, { force: true });
      toast(`「${board.name}」${kids ? `と子ノート ${kids} 冊` : ''}を削除しました`);
    } catch (err) {
      if (hadChanges) scheduleSave();
      toast(`ノートを削除できませんでした：${err.message}`, 'error', 5000);
    }
  }

  // 並べ替え・親の付け替え（parentId が null ならタブに。beforeId の兄弟の直前、null なら最後）
  async function moveBoard(id, parentId, beforeId) {
    if (!api || boardsReadOnly) return;
    try {
      const res = await ipc(api.moveBoard(id, parentId, beforeId));
      boards = res.boards;
      expandBoardPath(id);
      // ツリーを開いていたタブが別のノートの中へ移ったら、移った先のタブのツリーを見せる
      if (treeRootId && boardById(treeRootId) && parentOfBoard(treeRootId)) treeRootId = rootOfBoard(treeRootId);
      renderBoardTabs();
      if (treeIsOpen()) {
        renderBoardTree();
        positionBoardTree();
        focusTreeRow(id);
      }
      updateTitle();
    } catch (err) {
      toast(`ノートを移動できませんでした：${err.message}`, 'error', 5000);
    }
  }

  function moveBoardBy(cmd, id) {
    const board = boardById(id);
    if (!board) return;
    const parent = board.parentId || null;
    const sibs = siblingBoards(parent);
    const i = sibs.findIndex((b) => b.id === id);
    if (cmd === 'up' && i > 0) moveBoard(id, parent, sibs[i - 1].id);
    else if (cmd === 'down' && i < sibs.length - 1) moveBoard(id, parent, sibs[i + 2] ? sibs[i + 2].id : null);
    else if (cmd === 'indent' && i > 0) moveBoard(id, sibs[i - 1].id, null); // 上（左）のノートの子の最後へ
    else if (cmd === 'outdent' && parent) {
      // 親のすぐ後ろへ
      const gp = parentOfBoard(parent);
      const psibs = siblingBoards(gp);
      const next = psibs[psibs.findIndex((b) => b.id === parent) + 1];
      moveBoard(id, gp, next ? next.id : null);
    } else if (cmd === 'to-tab' && parent) moveBoard(id, null, null);
  }

  let menuBoardId = null;
  let menuFromTree = false;

  // メニュー（popover）を pos の位置に開く。画面からはみ出さないよう寄せる
  // 右クリックのメニューを出す。macOS・Linux では右ボタンを押した時点で contextmenu が来るので、そのまま出すと
  // 離したときにメニューの外とみなされて閉じる。ボタンを押したままなら、離してから出す
  function afterRightRelease(e, open) {
    if (!(e.buttons & 2)) {
      open();
      return;
    }
    const released = () => {
      window.removeEventListener('pointerup', released, true);
      window.removeEventListener('pointercancel', released, true);
      setTimeout(open, 0);
    };
    window.addEventListener('pointerup', released, true);
    window.addEventListener('pointercancel', released, true);
  }

  function showPopoverAt(menu, pos) {
    if (!menu._size) menu._size = { w: 240, h: 150 }; // 実寸は最初に開いたときに測る
    if (menu.matches(':popover-open')) menu.hidePopover();
    const place = () => {
      menu.style.left = `${Math.max(8, Math.min(pos.x, innerWidth - menu._size.w - 8))}px`;
      menu.style.top = `${Math.max(8, Math.min(pos.y, innerHeight - menu._size.h - 8))}px`;
    };
    // 表示する前に位置を決める（表示してから動かすと、一瞬前回の位置に出てしまう）
    place();
    menu.showPopover();
    const r = menu.getBoundingClientRect();
    if (r.width && (Math.abs(r.width - menu._size.w) > 1 || Math.abs(r.height - menu._size.h) > 1)) {
      menu._size = { w: r.width, h: r.height };
      place();
    }
  }

  // ノートのメニュー（タブの右クリック、ツリーの行の … ・右クリック）
  function openBoardMenu(id, pos, { fromTree = false } = {}) {
    const board = boardById(id);
    if (!board) return;
    menuBoardId = id;
    menuFromTree = fromTree;
    const isRoot = !board.parentId;
    const sibs = siblingBoards(board.parentId);
    const i = sibs.findIndex((b) => b.id === id);
    const ro = boardsReadOnly;
    const item = (cmd) => boardMenu.querySelector(`[data-cmd="${cmd}"]`);
    const label = (cmd, text) => {
      item(cmd).querySelector('span').textContent = text;
    };
    item('rename').disabled = ro;
    item('new').disabled = ro;
    item('new-child').disabled = ro || boardPath(id).length >= MAX_BOARD_DEPTH;
    item('up').disabled = ro || i <= 0;
    item('down').disabled = ro || i >= sibs.length - 1;
    item('indent').disabled = ro || i <= 0;
    item('outdent').disabled = ro || isRoot;
    item('to-tab').disabled = ro || isRoot;
    item('delete').disabled = ro || boardSubtree(id).length >= boards.length;
    item('export').disabled = false;
    item('check-links').disabled = false;
    label('up', isRoot ? '左へ移動（タブの並び）' : '上へ移動');
    label('down', isRoot ? '右へ移動（タブの並び）' : '下へ移動');
    label('indent', isRoot ? '左のタブの中へ入れる' : '上のノートの中へ入れる');
    const kids = boardSubtree(id).length - 1;
    label('delete', kids ? `このノートを削除（子ノート ${kids} 冊も）…` : 'このノートを削除…');
    syncSendItem(item('send-register'), 'board', id, ['このノートを送り先に登録（原点の下へ送れるように）', '送り先の登録を外す']);
    showPopoverAt(boardMenu, pos);
  }

  boardMenu.addEventListener('mousedown', (e) => e.preventDefault()); // 本文のフォーカスを保つ
  boardMenu.addEventListener('click', (e) => {
    const btn = e.target.closest('button[data-cmd]');
    if (!btn || btn.disabled) return;
    const id = menuBoardId;
    const fromTree = menuFromTree;
    boardMenu.hidePopover();
    const cmd = btn.dataset.cmd;
    if (cmd === 'send-register') toggleSendBoard(id);
    if (cmd === 'rename') startRename(id, { inTree: fromTree });
    else if (cmd === 'new') createBoard();
    else if (cmd === 'new-child') {
      if (hive.open) createChildFromHive(id); // ノートのハニカムから：そのノートを中心にした並びで見せる
      else createBoard(id);
    }
    else if (cmd === 'delete') deleteBoard(id);
    else if (cmd === 'export') exportBoard(id);
    else if (cmd === 'check-links') checkBoardLinks(id);
    else if (cmd === 'history') openHistory(id);
    else if (cmd === 'overview') openOverview(id);
    else moveBoardBy(cmd, id);
  });

  // ---- タブの中のノート（ツリー） ----
  // タブの ⌄ で開く。行を押すとそのノートを開く。＋で子ノート、… でメニュー、ドラッグで並べ替え・入れ子

  const boardTree = $('boardTree');
  const boardTreeList = $('boardTreeList');
  const TREE_PREF = 'hexMemo.collapsedBoards';
  let treeRootId = null;
  let treeDrag = null;
  let treeSuppressClick = false;
  const collapsedBoards = new Set(readCollapsedBoards());

  function readCollapsedBoards() {
    try {
      const v = JSON.parse(localStorage.getItem(TREE_PREF) || '[]');
      return Array.isArray(v) ? v.filter((x) => typeof x === 'string') : [];
    } catch {
      return [];
    }
  }

  function saveCollapsedBoards() {
    try {
      localStorage.setItem(TREE_PREF, JSON.stringify([...collapsedBoards].filter((id) => boardById(id))));
    } catch {
      // 折りたたみを覚えられなくても使える
    }
  }

  function treeIsOpen() {
    return boardTree.matches(':popover-open');
  }

  // そのノートが見えるよう、上の段を開く
  function expandBoardPath(id) {
    let changed = false;
    for (let p = parentOfBoard(id); p; p = parentOfBoard(p)) if (collapsedBoards.delete(p)) changed = true;
    if (changed) saveCollapsedBoards();
  }

  function openBoardTree(rootId, { focus = true } = {}) {
    if (!boardById(rootId)) return;
    treeRootId = rootId;
    if (currentBoardId && rootOfBoard(currentBoardId) === rootId) expandBoardPath(currentBoardId);
    renderBoardTree();
    positionBoardTree();
    renderBoardTabs(); // ⌄ の開閉の表示
    if (focus) focusTreeRow(currentBoardId && rootOfBoard(currentBoardId) === rootId ? currentBoardId : rootId);
  }

  function positionBoardTree() {
    const tab = boardTabsEl.querySelector(`.board-tab[data-id="${treeRootId}"]`);
    const r = tab ? tab.getBoundingClientRect() : { left: 8, bottom: 48 };
    showPopoverAt(boardTree, { x: r.left, y: r.bottom + 4 });
  }

  function closeBoardTree() {
    if (!treeIsOpen()) return;
    const input = boardTreeList.querySelector('.board-rename');
    if (input) input.blur(); // 入力中の名前は確定させる
    cancelTreeDrag();
    boardTree.hidePopover();
  }

  boardTree.addEventListener('toggle', (e) => {
    if (e.newState !== 'closed') return;
    treeRootId = null;
    for (const b of boardTabsEl.querySelectorAll('.board-more[aria-expanded="true"]')) b.setAttribute('aria-expanded', 'false');
  });

  function renderBoardTree() {
    const root = boardById(treeRootId);
    if (!root) {
      closeBoardTree();
      return;
    }
    $('boardTreeHead').replaceChildren(document.createTextNode('タブの中のノート'), el('strong', '', root.name));
    const frag = document.createDocumentFragment();
    const walk = (b, depth) => {
      const kids = boards.filter((x) => x.parentId === b.id);
      frag.append(buildTreeRow(b, depth, kids.length));
      if (kids.length && !collapsedBoards.has(b.id)) for (const k of kids) walk(k, depth + 1);
    };
    walk(root, 0);
    boardTreeList.replaceChildren(frag);
    boardTree.querySelector('[data-cmd="tree-add"]').disabled = boardsReadOnly;
  }

  function buildTreeRow(b, depth, nKids) {
    const row = el('div', 'tree-row');
    row.dataset.id = b.id;
    row.setAttribute('role', 'treeitem');
    row.setAttribute('aria-level', String(depth + 1));
    row.setAttribute('aria-selected', String(b.id === currentBoardId));
    row.style.setProperty('--depth', String(Math.min(depth, 8)));
    row.tabIndex = -1;
    row.title = boardPath(b.id).map((x) => x.name).join(' › ');
    const btn = (act, icon, title, cls = 'tree-act') => {
      const x = el('button', cls);
      x.type = 'button';
      x.tabIndex = -1;
      x.dataset.act = act;
      x.title = title;
      x.setAttribute('aria-label', title);
      x.append(svgIcon(icon));
      return x;
    };
    if (nKids) {
      const open = !collapsedBoards.has(b.id);
      row.setAttribute('aria-expanded', String(open));
      row.append(btn('toggle', 'chevron', open ? '折りたたむ' : '開く', 'tree-twisty'));
    } else {
      row.append(el('span', 'tree-twisty'));
    }
    row.append(svgIcon(depth === 0 ? 'layers' : 'hex'), el('span', 'tree-name', b.name));
    if (nKids && collapsedBoards.has(b.id)) row.append(el('span', 'tree-count', `+${boardSubtree(b.id).length - 1}`));
    if (!boardsReadOnly) {
      if (depth + 1 < MAX_BOARD_DEPTH) row.append(btn('add', 'plus', `「${b.name}」の中に子ノートを作成`));
      row.append(btn('menu', 'more', 'メニュー（名前・並べ替え・移動・削除）'));
    }
    return row;
  }

  function treeRows() {
    return [...boardTreeList.querySelectorAll('.tree-row')];
  }

  function focusTreeRow(id) {
    const row = boardTreeList.querySelector(`.tree-row[data-id="${id}"]`) || treeRows()[0];
    if (row) row.focus({ preventScroll: false });
  }

  function toggleBoardCollapsed(id, open = collapsedBoards.has(id)) {
    if (open) collapsedBoards.delete(id);
    else collapsedBoards.add(id);
    saveCollapsedBoards();
    renderBoardTree();
    focusTreeRow(id);
  }

  boardTreeList.addEventListener('click', (e) => {
    if (treeSuppressClick) {
      treeSuppressClick = false;
      return;
    }
    const row = e.target.closest('.tree-row');
    if (!row) return;
    const id = row.dataset.id;
    const act = e.target.closest('button[data-act]');
    if (act) {
      const r = act.getBoundingClientRect();
      if (act.dataset.act === 'toggle') toggleBoardCollapsed(id);
      else if (act.dataset.act === 'add') createBoard(id);
      else if (act.dataset.act === 'menu') openBoardMenu(id, { x: r.left, y: r.bottom + 4 }, { fromTree: true });
      return;
    }
    closeBoardTree();
    switchBoard(id);
  });
  boardTreeList.addEventListener('contextmenu', (e) => {
    const row = e.target.closest('.tree-row');
    if (!row) return;
    e.preventDefault();
    openBoardMenu(row.dataset.id, { x: e.clientX, y: e.clientY }, { fromTree: true });
  });
  boardTree.addEventListener('mousedown', (e) => {
    if (e.target.closest('button')) e.preventDefault(); // 本文のフォーカスを保つ
  });
  boardTree.addEventListener('click', (e) => {
    const btn = e.target.closest('button[data-cmd="tree-add"]');
    if (btn && !btn.disabled && treeRootId) createBoard(treeRootId);
  });

  // キー操作：↑↓ で移動、→← で開閉、Enter で開く、F2 で名前、Esc で閉じる
  boardTree.addEventListener('keydown', (e) => {
    if (e.isComposing || e.keyCode === 229) return;
    if ((e.ctrlKey || e.metaKey) && !e.altKey) return; // Ctrl+T などは全体のショートカットへ
    e.stopPropagation(); // Delete・Space などをハニカムの操作に渡さない
    const row = e.target.closest && e.target.closest('.tree-row');
    const rows = treeRows();
    const i = row ? rows.indexOf(row) : -1;
    const id = row && row.dataset.id;
    if (e.key === 'Escape') {
      e.preventDefault();
      closeBoardTree();
      const tab = boardTabsEl.querySelector('.board-tab[aria-selected="true"]');
      if (editingKey) editor.focus({ preventScroll: true });
      else if (tab) tab.focus();
    } else if (!row) {
      return;
    } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      const next = rows[Math.max(0, Math.min(rows.length - 1, i + (e.key === 'ArrowDown' ? 1 : -1)))];
      if (next) next.focus();
    } else if (e.key === 'ArrowRight') {
      e.preventDefault();
      if (row.getAttribute('aria-expanded') === 'false') toggleBoardCollapsed(id, true);
      else if (row.getAttribute('aria-expanded') === 'true' && rows[i + 1]) rows[i + 1].focus();
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      if (row.getAttribute('aria-expanded') === 'true') toggleBoardCollapsed(id, false);
      else if (parentOfBoard(id)) focusTreeRow(parentOfBoard(id));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      closeBoardTree();
      switchBoard(id);
    } else if (e.key === 'F2') {
      e.preventDefault();
      startRename(id, { inTree: true });
    }
  });

  // ツリーの外を押したら閉じる（メニュー・確認ダイアログ・タブの ⌄ は除く）
  document.addEventListener('pointerdown', (e) => {
    if (!treeIsOpen() || confirmDialog.open) return;
    const t = e.target;
    if (boardTree.contains(t) || boardMenu.contains(t) || (t.closest && t.closest('.board-more'))) return;
    closeBoardTree();
  }, true);

  // ---- ツリーのドラッグ：行の上半分・下半分なら前後へ、真ん中ならその中へ。タブの上ならそのタブの中へ ----

  function treeDropAt(x, y) {
    const hit = document.elementFromPoint(x, y);
    if (!hit || !treeDrag) return null;
    const moving = boardSubtree(treeDrag.id);
    const row = hit.closest('#boardTreeList .tree-row');
    if (row) {
      const id = row.dataset.id;
      if (moving.includes(id)) return null; // 自分の中へは入れられない
      const r = row.getBoundingClientRect();
      const f = (y - r.top) / r.height;
      return { el: row, id, zone: f < 0.3 ? 'before' : f > 0.7 ? 'after' : 'inside' };
    }
    const tab = hit.closest('.board-tab');
    if (tab && !moving.includes(tab.dataset.id)) return { el: tab, id: tab.dataset.id, zone: 'tab' };
    return null;
  }

  function clearTreeDropMarks() {
    for (const n of document.querySelectorAll('.drop-before, .drop-after, .drop-inside, .board-tab.is-drop')) {
      n.classList.remove('drop-before', 'drop-after', 'drop-inside', 'is-drop');
    }
  }

  function cancelTreeDrag() {
    if (!treeDrag) return;
    clearTreeDropMarks();
    for (const n of document.querySelectorAll('.tree-row.is-drag-src')) n.classList.remove('is-drag-src');
    document.body.classList.remove('is-tree-dragging');
    treeDrag = null;
  }

  boardTreeList.addEventListener('pointerdown', (e) => {
    if (e.button !== 0 || boardsReadOnly) return;
    const row = e.target.closest('.tree-row');
    if (!row || e.target.closest('button, input')) return;
    treeDrag = { id: row.dataset.id, x: e.clientX, y: e.clientY, active: false, drop: null };
  });
  window.addEventListener('pointermove', (e) => {
    if (!treeDrag) return;
    if (!treeDrag.active) {
      if (Math.hypot(e.clientX - treeDrag.x, e.clientY - treeDrag.y) < 5) return;
      treeDrag.active = true;
      const src = boardTreeList.querySelector(`.tree-row[data-id="${treeDrag.id}"]`);
      if (src) src.classList.add('is-drag-src');
      document.body.classList.add('is-tree-dragging');
    }
    clearTreeDropMarks();
    treeDrag.drop = treeDropAt(e.clientX, e.clientY);
    const d = treeDrag.drop;
    if (d) d.el.classList.add(d.zone === 'tab' ? 'is-drop' : `drop-${d.zone}`);
  });
  window.addEventListener('pointerup', () => {
    if (!treeDrag) return;
    const { id, active, drop } = treeDrag;
    cancelTreeDrag();
    if (!active) return;
    treeSuppressClick = true;
    setTimeout(() => {
      treeSuppressClick = false;
    }, 0);
    if (!drop) return;
    if (drop.zone === 'inside' || drop.zone === 'tab') {
      moveBoard(id, drop.id, null);
    } else {
      const parent = parentOfBoard(drop.id);
      if (drop.zone === 'before') moveBoard(id, parent, drop.id);
      else {
        const sibs = siblingBoards(parent).filter((b) => b.id !== id);
        const next = sibs[sibs.findIndex((b) => b.id === drop.id) + 1];
        moveBoard(id, parent, next ? next.id : null);
      }
    }
  });
  window.addEventListener('blur', cancelTreeDrag);

  // ---- 上段のタブ ----

  boardTabsEl.addEventListener('mousedown', (e) => {
    if (e.target.closest('.board-more')) e.preventDefault();
  });
  boardTabsEl.addEventListener('click', (e) => {
    const tab = e.target.closest('.board-tab');
    if (!tab || e.target.closest('.board-rename')) return;
    if (e.target.closest('.board-more')) {
      if (treeIsOpen() && treeRootId === tab.dataset.id) closeBoardTree();
      else openBoardTree(tab.dataset.id);
      return;
    }
    switchBoard(tabTarget(tab.dataset.id));
  });
  boardTabsEl.addEventListener('dblclick', (e) => {
    const tab = e.target.closest('.board-tab');
    if (tab && !e.target.closest('.board-more')) startRename(tab.dataset.id);
  });
  boardTabsEl.addEventListener('contextmenu', (e) => {
    const tab = e.target.closest('.board-tab');
    if (!tab) return;
    e.preventDefault();
    openBoardMenu(tab.dataset.id, { x: e.clientX, y: e.clientY });
  });
  boardTabsEl.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && e.target.classList.contains('board-tab')) {
      e.preventDefault();
      switchBoard(tabTarget(e.target.dataset.id));
    }
  });
  boardTabsEl.addEventListener('scroll', updateTabOverflow, { passive: true });
  new ResizeObserver(updateTabOverflow).observe(boardTabsEl);
  // タブが多いときは縦ホイールで横にスクロール
  boardTabsEl.addEventListener('wheel', (e) => {
    if (Math.abs(e.deltaY) <= Math.abs(e.deltaX)) return;
    e.preventDefault();
    boardTabsEl.scrollLeft += e.deltaY;
  }, { passive: false });
  $('boardAdd').addEventListener('click', () => createBoard());

  // ---- ノートのハニカム：タブ（ノート）の題名を六角セルに並べて見る区画 ----
  // 中心にこのメモアプリ（子ノートの中では親のノート）、周りに右上から時計回りでノートをタブの順に並べる。
  // セルを押すとそのノートを開き、「子ノート N」でその中へ（中心がそのノートになる）。最後のセルで新しいノートを作る
  const HIVE_SIZE = 78; // 六角形の外接円半径（px）
  const HIVE_GAP = 1.07; // セルの間のすき間（倍率）

  function openHive() {
    hive.open = true;
    hive.parent = null;
    hive.stats = new Map();
    hidePeek();
    $('boardHive').hidden = false;
    $('boardHiveBtn').setAttribute('aria-pressed', 'true');
    renderHive();
  }

  function closeHive() {
    if (!hive.open) return;
    hive.open = false;
    $('boardHive').hidden = true;
    $('boardHiveBtn').setAttribute('aria-pressed', 'false');
  }

  const toggleHive = () => (hive.open ? closeHive() : openHive());

  // 中心のまわりを、内側の周から右上を起点に時計回りで埋める位置（中心は含まない）
  function hiveSpiral(n) {
    const out = [];
    for (let ring = 1; out.length < n; ring++) {
      const cells = [];
      for (let q = -ring; q <= ring; q++) {
        for (let r = Math.max(-ring, -q - ring); r <= Math.min(ring, -q + ring); r++) {
          if (H.hexDistance({ q: 0, r: 0 }, { q, r }) !== ring) continue;
          const p = H.hexToPixel(q, r, 1);
          cells.push({ q, r, angle: (Math.atan2(p.x, -p.y) + 2 * Math.PI) % (2 * Math.PI) });
        }
      }
      cells.sort((a, b) => a.angle - b.angle);
      out.push(...cells);
    }
    return out.slice(0, n);
  }

  // メモの数：開いているノートは今の内容で、ほかは保存されている内容から（読み込み中は null、読めなければ undefined）
  // メモの数と原点のメモ { count, origin: { text, cover? } | null }：開いているノートは今の内容で、
  // ほかは保存されている内容から（読み込み中は null、読めなければ undefined）
  function hiveInfo(id) {
    if (id === currentBoardId) {
      let count = 0;
      forEachMemo(() => { count++; });
      const o = rootLayer.memos.get('0,0');
      let origin = null;
      if (o && !isEmptyRecord(o)) {
        const cover = o.cover ? imagesOf(o).find((img) => img.id === o.cover) : null;
        origin = { text: (o.text.split('\n').find((l) => l.trim()) || '').trim().slice(0, 80), ...(cover ? { cover: cover.thumb || cover.file } : {}) };
      }
      return { count, origin };
    }
    return hive.stats.has(id) ? hive.stats.get(id) : null;
  }

  async function loadHiveStats() {
    if (hive.loading) return;
    hive.loading = true;
    try {
      for (const b of [...boards]) {
        if (!hive.open) return;
        if (b.id === currentBoardId || hive.stats.has(b.id)) continue;
        try {
          const st = await ipc(api.boardStats(b.id));
          hive.stats.set(b.id, { count: st.memoCount, origin: st.origin || null });
        } catch {
          hive.stats.set(b.id, undefined);
        }
      }
    } finally {
      hive.loading = false;
    }
    renderHive();
  }

  function hiveShell(cls) {
    const cell = el('div', `hive-cell ${cls}`);
    const hex = el('div', 'hive-hex');
    hex.append(el('div', 'hive-fill'));
    cell.append(hex);
    return { cell, hex };
  }

  function hiveBoardCell(b, { center = false } = {}) {
    const current = b.id === currentBoardId;
    const { cell, hex } = hiveShell(`is-board${center ? ' is-center' : ''}${current ? ' is-current' : ''}`);
    cell.dataset.id = b.id;
    const open = el('button', 'hive-open');
    open.type = 'button';
    open.dataset.hiveOpen = b.id;
    open.title = current ? `「${b.name}」（開いているノート）に戻る` : `「${b.name}」を開く`;
    if (current) open.append(el('span', 'hive-flag', '開いているノート'));
    open.append(el('span', 'hive-name', b.name));
    const info = hiveInfo(b.id);
    // 原点のメモ：ノートの説明（1行目）と表紙
    if (info && info.origin && info.origin.text) open.append(el('span', 'hive-origin', info.origin.text));
    if (info && info.origin && info.origin.cover) {
      cell.classList.add('has-cover');
      hex.querySelector('.hive-fill').style.backgroundImage = `url("${attUrl(info.origin.cover)}")`;
    }
    if (info !== undefined) open.append(el('span', 'hive-count', info === null ? 'メモ …' : `メモ ${info.count}`));
    if (side && side.list === 'overview' && side.board === b.id) cell.classList.add('is-overview');
    open.title += '｜右クリックで、このノートの全体をサイドバーに';
    hex.append(open);
    const chip = (cls, icon, text, title, parent) => {
      const c = el('button', `hive-chip ${cls}`);
      c.type = 'button';
      c.title = title;
      c.dataset.hiveParent = parent || '';
      c.append(svgIcon(icon), document.createTextNode(text));
      hex.append(c);
    };
    const kids = siblingBoards(b.id).length;
    if (center) chip('hive-up', 'up', '上へ', 'ひとつ上の階層のノートへ', b.parentId);
    else if (kids) chip('hive-kids', 'layers', `子ノート ${kids}`, `「${b.name}」の中の子ノートを六角セルで見る`, b.id);
    else if (!boardsReadOnly && boardPath(b.id).length < MAX_BOARD_DEPTH) {
      // 子ノートがまだ無いノート：その中に子ノートを作る（作ると、そのノートを中心にした並びへ）
      const c = el('button', 'hive-chip hive-new-kid');
      c.type = 'button';
      c.title = `「${b.name}」の中に子ノートを作る`;
      c.dataset.hiveNewChild = b.id;
      c.append(svgIcon('plus'), document.createTextNode('子ノート'));
      hex.append(c);
    }
    return cell;
  }

  // そのノートの中に子ノートを作り、区画はそのノートを中心にした並びにする（作った子ノートは開いた状態で、名前を入力できる）
  function createChildFromHive(parentId) {
    hive.parent = parentId;
    $('hiveScroll').scrollTop = 0;
    createBoard(parentId);
  }

  function hiveAppCell(nTabs) {
    const { cell, hex } = hiveShell('is-app is-center');
    const body = el('div', 'hive-open');
    body.append(svgIcon('hex'), el('span', 'hive-name', $('appName').textContent || '六角メモ'),
      el('span', 'hive-count', `タブ ${nTabs}・ノート ${boards.length}`));
    hex.append(body);
    return cell;
  }

  function hiveAddCell(parent) {
    const { cell, hex } = hiveShell('is-add');
    const add = el('button', 'hive-open');
    add.type = 'button';
    add.dataset.hiveAdd = parent ? parent.id : '';
    add.title = parent ? `「${parent.name}」の中に子ノートを作る` : '新しいノート（タブ）を作る';
    add.disabled = boardsReadOnly || (!!parent && boardPath(parent.id).length >= MAX_BOARD_DEPTH);
    add.append(svgIcon('plus'), el('span', 'hive-name', parent ? '子ノートを作る' : '新しいノート'));
    hex.append(add);
    return cell;
  }

  function renderHive() {
    if (!hive.open) return;
    if (hiveDrag && hiveDrag.dragging) return; // ドラッグ中は作り直さない（離したときに描き直す）
    if (hive.parent && !boardById(hive.parent)) hive.parent = null;
    const parent = hive.parent ? boardById(hive.parent) : null;
    const list = siblingBoards(hive.parent);

    // パンくず：すべてのタブ › 親 › …
    const crumb = (label, id, here) => {
      const b = el('button', `hive-crumb${here ? ' is-here' : ''}`, label);
      b.type = 'button';
      b.dataset.hiveParent = id || '';
      b.disabled = here;
      return b;
    };
    const trail = parent ? boardPath(parent.id) : [];
    $('hiveCrumbs').replaceChildren(crumb('すべてのタブ', null, !parent),
      ...trail.flatMap((b, i) => [el('span', 'hive-sep', '›'), crumb(b.name, b.id, i === trail.length - 1)]));

    const cells = [{ q: 0, r: 0, node: parent ? hiveBoardCell(parent, { center: true }) : hiveAppCell(list.length) }];
    const pos = hiveSpiral(list.length + 1);
    list.forEach((b, i) => cells.push({ ...pos[i], node: hiveBoardCell(b) }));
    cells.push({ ...pos[list.length], node: hiveAddCell(parent) });

    // 六角形（とがった方が上）の位置。全体の外枠に合わせて並べる
    const w = HIVE_SIZE * H.SQRT3;
    const h = HIVE_SIZE * 2;
    const s = HIVE_SIZE * HIVE_GAP;
    const pts = cells.map((c) => ({ x: s * H.SQRT3 * (c.q + c.r / 2), y: s * 1.5 * c.r }));
    const minX = Math.min(...pts.map((p) => p.x)) - w / 2;
    const minY = Math.min(...pts.map((p) => p.y)) - h / 2;
    const canvas = $('hiveCanvas');
    canvas.style.setProperty('--hive-w', `${w}px`);
    canvas.style.setProperty('--hive-h', `${h}px`);
    canvas.style.width = `${Math.max(...pts.map((p) => p.x)) + w / 2 - minX}px`;
    canvas.style.height = `${Math.max(...pts.map((p) => p.y)) + h / 2 - minY}px`;
    cells.forEach((c, i) => {
      c.node.style.left = `${pts[i].x - w / 2 - minX}px`;
      c.node.style.top = `${pts[i].y - h / 2 - minY}px`;
    });
    canvas.replaceChildren(...cells.map((c) => c.node));
    // 並べ替えのための、ノートのセルの位置（タブの順＝i 番目の位置）
    hive.layout = {
      ids: list.map((b) => b.id),
      slots: list.map((_, i) => {
        const p = pts[i + 1];
        return { left: p.x - w / 2 - minX, top: p.y - h / 2 - minY, cx: p.x - minX, cy: p.y - minY };
      }),
    };
    if (boards.some((b) => b.id !== currentBoardId && !hive.stats.has(b.id))) loadHiveStats();
  }

  // ノートを開いて区画を閉じる（開いているノートなら閉じるだけ）
  async function openBoardFromHive(id) {
    closeHive();
    if (id !== currentBoardId) await switchBoard(id);
  }

  $('boardHiveBtn').addEventListener('click', toggleHive);
  $('hiveClose').addEventListener('click', closeHive);
  $('boardHive').addEventListener('click', (e) => {
    if (hiveClickBlocked) {
      hiveClickBlocked = false; // ドラッグを離したときのクリックでは開かない
      return;
    }
    const nav = e.target.closest('[data-hive-parent]');
    if (nav) {
      if (nav.disabled) return;
      hive.parent = nav.dataset.hiveParent || null;
      $('hiveScroll').scrollTop = 0;
      renderHive();
      return;
    }
    const newKid = e.target.closest('[data-hive-new-child]');
    if (newKid) {
      createChildFromHive(newKid.dataset.hiveNewChild);
      return;
    }
    const add = e.target.closest('[data-hive-add]');
    if (add) {
      if (!add.disabled) createBoard(add.dataset.hiveAdd || null); // 作ったノートは開いた状態で区画に加わり、名前を入力できる
      return;
    }
    const open = e.target.closest('[data-hive-open]');
    if (open) openBoardFromHive(open.dataset.hiveOpen);
  });
  // セルの右クリック：ノートのメニュー（名前の変更・子ノートの作成・並べ替え・削除など）
  $('hiveCanvas').addEventListener('contextmenu', (e) => {
    const cell = e.target.closest('.hive-cell.is-board');
    if (!cell) return;
    e.preventDefault();
    if (hiveDrag) cancelHiveDrag();
    toggleOverview(cell.dataset.id); // そのノートの全体を左のサイドバーに（もう一度で閉じる）
  });

  // ---- ノートのハニカム：ドラッグで並べ替え（同じ階層の中で） ----
  // セルをつかんで動かすと、ほかのセルが新しい並びの位置へ寄り、落とす位置に枠が出る。離すとその順番に並べ替える
  // （タブ・ツリーの順も同じに変わる）。Esc で取りやめ
  let hiveDrag = null; // { id, cell, from, to, sx, sy, dx, dy, dragging, pointerId, ghost }
  let hiveClickBlocked = false;

  function hiveCanvasPoint(e) {
    const r = $('hiveCanvas').getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  }

  // つかんだノートを to 番目に入れたときの並び
  function hiveDragOrder(d) {
    const ids = hive.layout.ids.filter((id) => id !== d.id);
    ids.splice(d.to, 0, d.id);
    return ids;
  }

  function layoutHiveDrag() {
    const d = hiveDrag;
    const cells = new Map([...$('hiveCanvas').querySelectorAll('.hive-cell.is-board:not(.is-center)')].map((c) => [c.dataset.id, c]));
    hiveDragOrder(d).forEach((id, i) => {
      if (id === d.id) return;
      const c = cells.get(id);
      const s = hive.layout.slots[i];
      if (!c || !s) return;
      c.style.left = `${s.left}px`;
      c.style.top = `${s.top}px`;
    });
    const g = hive.layout.slots[d.to];
    d.ghost.style.left = `${g.left}px`;
    d.ghost.style.top = `${g.top}px`;
  }

  function endHiveDragLook(d) {
    d.cell.classList.remove('is-dragging');
    if (d.ghost) d.ghost.remove();
    $('hiveCanvas').classList.remove('is-sorting');
    document.body.classList.remove('is-hive-sorting');
  }

  function cancelHiveDrag() {
    const d = hiveDrag;
    hiveDrag = null;
    if (!d || !d.dragging) return;
    hiveClickBlocked = true; // まだ押したままなので、離したときのクリックで開かないように
    endHiveDragLook(d);
    renderHive();
  }

  $('hiveCanvas').addEventListener('pointerdown', (e) => {
    hiveClickBlocked = false;
    if (e.button !== 0 || boardsReadOnly || !hive.layout || e.target.closest('.hive-chip')) return;
    const cell = e.target.closest('.hive-cell.is-board:not(.is-center)');
    const from = cell ? hive.layout.ids.indexOf(cell.dataset.id) : -1;
    if (from < 0) return;
    const p = hiveCanvasPoint(e);
    const s = hive.layout.slots[from];
    hiveDrag = { id: cell.dataset.id, cell, from, to: from, sx: e.clientX, sy: e.clientY, dx: p.x - s.left, dy: p.y - s.top, dragging: false, pointerId: e.pointerId, ghost: null };
  });

  document.addEventListener('pointermove', (e) => {
    const d = hiveDrag;
    if (!d || e.pointerId !== d.pointerId) return;
    if (!d.dragging) {
      if (Math.hypot(e.clientX - d.sx, e.clientY - d.sy) < 6) return; // 少し動いただけならクリック
      d.dragging = true;
      d.cell.classList.add('is-dragging');
      $('hiveCanvas').classList.add('is-sorting');
      document.body.classList.add('is-hive-sorting');
      d.ghost = hiveShell('is-ghost').cell;
      $('hiveCanvas').append(d.ghost);
      layoutHiveDrag();
    }
    e.preventDefault();
    const p = hiveCanvasPoint(e);
    d.cell.style.left = `${p.x - d.dx}px`;
    d.cell.style.top = `${p.y - d.dy}px`;
    // いちばん近い位置へ（どの位置からも離れているときは、今の位置のまま）
    let best = d.to;
    let bestDist = Infinity;
    hive.layout.slots.forEach((s, i) => {
      const dist = Math.hypot(p.x - s.cx, p.y - s.cy);
      if (dist < bestDist) {
        bestDist = dist;
        best = i;
      }
    });
    if (bestDist < HIVE_SIZE * 1.6 && best !== d.to) {
      d.to = best;
      layoutHiveDrag();
    }
  });

  async function finishHiveDrag(e, drop) {
    const d = hiveDrag;
    if (!d || e.pointerId !== d.pointerId) return;
    hiveDrag = null;
    if (!d.dragging) return; // ただのクリック（ノートを開く）
    hiveClickBlocked = true;
    const s = hive.layout.slots[d.to];
    d.cell.style.left = `${s.left}px`; // 落とした位置へ収める
    d.cell.style.top = `${s.top}px`;
    endHiveDragLook(d);
    if (!drop || d.to === d.from) {
      renderHive();
      return;
    }
    const order = hiveDragOrder(d);
    await moveBoard(d.id, hive.parent, order[d.to + 1] || null); // 次のノートの前へ（最後なら末尾）
    renderHive();
  }
  document.addEventListener('pointerup', (e) => finishHiveDrag(e, true));
  document.addEventListener('pointercancel', (e) => finishHiveDrag(e, false));

  // ---- メモアプリ（左上のアプリ名のメニュー） ------------------------------------------
  // 「別のメモアプリ」は、データを分けた六角メモ。起動ファイル「名前.cmd」から開く

  const appMenuBtn = $('appMenuBtn');
  const appMenu = $('appMenu');
  const appMenuList = $('appMenuList');
  const newAppDialog = $('newAppDialog');
  const newAppName = $('newAppName');
  const newAppError = $('newAppError');
  const newAppOk = $('newAppOk');
  let appMenuClosedAt = 0;

  function setAppName(name, id) {
    appName = name || '六角メモ';
    appId = id || null;
    $('appName').textContent = appName;
    updateTitle();
  }

  // ---- 六角形の文字量：選ぶ・当てる ----
  function syncTextLinesMenu() {
    for (const b of appMenu.querySelectorAll('button[data-text-lines]')) b.setAttribute('aria-checked', String(Number(b.dataset.lines) === textLines[b.dataset.textLines]));
  }
  function applyTextLines() {
    stage.dataset.bodyLines = String(textLines.honey); // ハニカム：CSS の行数を切り替える
    graphSvg.classList.toggle('is-lines-3', textLines.graph === 3); // グラフ：3 行は少し小さい文字
    if (typeof lastZoom === 'number') applyZoomStyles(lastZoom); // 全体表示の行数も合わせる
    if (activeTab === 'graph') drawGraph();
    syncTextLinesMenu();
  }
  function setTextLines(kind, n) {
    if (!TEXT_LINES_CHOICES[kind] || !TEXT_LINES_CHOICES[kind].includes(n)) return;
    textLines[kind] = n;
    try { localStorage.setItem(TEXT_LINES_PREF[kind], String(n)); } catch { /* 覚えられなくても、この起動中は使える */ }
    applyTextLines();
  }
  async function openAppMenu() {
    syncTextLinesMenu();
    if (!api) return;
    const head = $('appMenuHead');
    head.replaceChildren(document.createTextNode('このメモアプリ'), el('strong', '', appName));
    updateTrashCount();
    appMenuList.replaceChildren(el('div', 'menu-empty', '読み込み中…'));
    const r = appMenuBtn.getBoundingClientRect();
    showPopoverAt(appMenu, { x: r.left, y: r.bottom + 4 });
    appMenuBtn.setAttribute('aria-expanded', 'true');
    try {
      const { apps } = await ipc(api.listApps());
      const others = apps.filter((a) => (a.id || null) !== appId);
      if (!others.length) {
        appMenuList.replaceChildren(el('div', 'menu-empty', 'まだありません（上の「新しいメモアプリを作成」から作れます）'));
        return;
      }
      appMenuList.replaceChildren(...others.map((a) => {
        const b = el('button');
        b.type = 'button';
        b.setAttribute('role', 'menuitem');
        b.dataset.appId = a.id || '';
        b.append(svgIcon('hex'), el('span', '', a.name));
        return b;
      }));
    } catch (err) {
      appMenuList.replaceChildren(el('div', 'menu-empty', `一覧を読み込めませんでした：${err.message}`));
    }
  }

  appMenuBtn.addEventListener('mousedown', (e) => e.preventDefault()); // 本文のフォーカスを保つ
  appMenuBtn.addEventListener('click', () => {
    // 開いていたメニューを外側クリックで閉じた直後なら、開き直さない
    if (performance.now() - appMenuClosedAt < 250) return;
    openAppMenu();
  });
  appMenu.addEventListener('toggle', (e) => {
    if (e.newState === 'open') syncAppMenuGraph();
    if (e.newState !== 'closed') return;
    appMenuClosedAt = performance.now();
    appMenuBtn.setAttribute('aria-expanded', 'false');
  });
  appMenu.addEventListener('mousedown', (e) => e.preventDefault());
  appMenu.addEventListener('click', async (e) => {
    const btn = e.target.closest('button');
    if (!btn) return;
    if (btn.dataset.textLines) { // 文字量：メニューは開いたまま（その場で見比べられる）
      setTextLines(btn.dataset.textLines, Number(btn.dataset.lines));
      return;
    }
    appMenu.hidePopover();
    try {
      if (btn.dataset.cmd === 'new-window') {
        await openNewWindow();
      } else if (btn.dataset.cmd === 'quick-input') {
        quickInput();
      } else if (btn.dataset.cmd === 'quick-settings') {
        openQuickDialog();
      } else if (btn.dataset.cmd === 'capture') {
        startCapture();
      } else if (btn.dataset.cmd === 'capture-settings') {
        openCaptureDialog();
      } else if (btn.dataset.cmd === 'search') {
        openSearch();
      } else if (btn.dataset.cmd === 'tag-settings') {
        openTagDialog();
      } else if (btn.dataset.cmd === 'tag-sets') {
        openTagSetDialog();
      } else if (btn.dataset.cmd === 'link-kinds') {
        openLinkKindDialog();
      } else if (btn.dataset.cmd === 'templates') {
        openTplDialog();
      } else if (btn.dataset.cmd === 'graph-open') {
        openGraphFromAppMenu();
      } else if (btn.dataset.cmd === 'dendrites') {
        openDendrites();
      } else if (btn.dataset.cmd === 'due-list') {
        openDueList();
      } else if (btn.dataset.cmd === 'shelf') {
        openShelf();
      } else if (btn.dataset.cmd === 'trash') {
        openTrash();
      } else if (btn.dataset.cmd === 'today') {
        openToday();
      } else if (btn.dataset.cmd === 'voice') {
        openVoice();
      } else if (btn.dataset.cmd === 'export') {
        openExportHere();
      } else if (btn.dataset.cmd === 'line-tips') {
        openTipsMenu();
      } else if (btn.dataset.cmd === 'zoom-menu') {
        if (!miniMode) openZoomMenu();
      } else if (btn.dataset.cmd === 'undo' || btn.dataset.cmd === 'redo') {
        applyUndo(btn.dataset.cmd);
      } else if (btn.dataset.cmd === 'stats') {
        openStats();
      } else if (btn.dataset.cmd === 'pocket') {
        togglePocket();
      } else if (btn.dataset.cmd === 'new-app') {
        openNewAppDialog();
      } else if (btn.dataset.cmd === 'data-folder') {
        await ipc(api.openDataFolder());
      } else if (btn.dataset.cmd === 'import-bookmarks') {
        await importBookmarks();
      } else if (btn.dataset.cmd === 'sweep') {
        await sweepAttachments();
      } else if (btn.dataset.cmd === 'register-protocol') {
        await registerProtocol();
      } else if (btn.dataset.cmd === 'export-app') {
        await exportApp();
      } else if (btn.dataset.cmd === 'import-data') {
        chooseImportFile();
      } else if ('appId' in btn.dataset) {
        const name = btn.textContent;
        await ipc(api.openApp(btn.dataset.appId || null));
        toast(`「${name}」を開いています…`);
      }
    } catch (err) {
      toast(`開けませんでした：${err.message}`, 'error', 5000);
    }
  });

  // 画面側でも同じ規則で先に知らせる（最終的な判定はメインプロセス）
  function checkAppName(raw) {
    const name = raw.replace(/\s+/g, ' ').trim();
    if (!name) return { name, error: '' };
    if ([...name].length > 60) return { name, error: '名前は 60 文字までです' };
    if (/[\\/:*?"<>|%^&!]/.test(name)) return { name, error: '次の文字は使えません：\\ / : * ? " < > | % ^ & !' };
    if (name.endsWith('.')) return { name, error: '名前の最後に「.」は使えません' };
    if (name === '六角メモ') return { name, error: '「六角メモ」は元のアプリの名前です。別の名前にしてください' };
    return { name, error: '' };
  }

  function updateNewAppForm() {
    const { name, error } = checkAppName(newAppName.value);
    $('newAppFile').textContent = name && !error ? `作成されるファイル：${name}.cmd（アプリのフォルダ）` : 'アプリのフォルダに「名前.cmd」ができます';
    newAppError.textContent = error;
    newAppError.hidden = !error;
    newAppName.setAttribute('aria-invalid', String(!!error));
    newAppOk.disabled = !name || !!error;
  }

  function openNewAppDialog() {
    if (!api) return;
    newAppName.value = '';
    updateNewAppForm();
    newAppDialog.showModal();
    newAppName.focus();
  }

  async function submitNewApp() {
    const { name, error } = checkAppName(newAppName.value);
    if (!name || error || newAppOk.disabled) return;
    newAppOk.disabled = true;
    try {
      const res = await ipc(api.createApp(name));
      newAppDialog.close();
      const where = res.launcher ? `次からはアプリのフォルダの「${res.launcher}」をダブルクリックで開けます。` : '';
      toast(`「${res.app.name}」を作成して開きました。${where}`, 'info', 7000);
    } catch (err) {
      newAppError.textContent = err.message;
      newAppError.hidden = false;
      newAppName.setAttribute('aria-invalid', 'true');
      newAppName.focus();
    } finally {
      if (newAppDialog.open) newAppOk.disabled = false;
    }
  }

  newAppName.addEventListener('input', updateNewAppForm);
  newAppName.addEventListener('keydown', (e) => {
    if (e.isComposing || e.keyCode === 229) return;
    if (e.key === 'Enter') {
      e.preventDefault();
      submitNewApp();
    }
  });
  newAppOk.addEventListener('click', submitNewApp);
  $('newAppCancel').addEventListener('click', () => newAppDialog.close());
  closeOnBackdrop(newAppDialog);
  newAppDialog.addEventListener('close', () => {
    if (editingKey) editor.focus({ preventScroll: true });
  });

  // ---- 保存 ----------------------------------------------------------------

  // 保存は「どのノートの・どの時点のデータか」を組にして順番に送る。
  // ノートを切り替えても、切り替え前の変更が別のノートに書き込まれることはない。
  const SAVE_LABELS = { saved: '保存済み', saving: '保存中…', error: '保存に失敗', disabled: '保存停止中' };
  let saveTimer = 0;
  let retryTimer = 0;
  let dirty = false; // 表示中のノートにまだ送っていない変更がある
  let dataDirty = false; // そのうちカメラ以外の変更がある
  let firstDirtyAt = 0;
  let lastSavedAt = '';
  let saveChain = Promise.resolve();
  const unsettled = new Map(); // ノートID → 送ったがまだ保存を確認できていないデータ
  const failedBoards = new Set(); // 直近の保存に失敗したノート

  const canSave = () => !!api && !!currentBoardId && !boardReadOnly;
  const boardExists = (id) => boards.some((b) => b.id === id);

  function setSaveStatus(state, detail = '') {
    saveStatusEl.dataset.state = state;
    saveStatusEl.textContent = SAVE_LABELS[state];
    saveStatusEl.title = detail || (state === 'saved' && lastSavedAt ? `最終保存：${formatFull(lastSavedAt)}` : '');
  }

  // ノート全体（下の階層も含む）を保存形式にする
  function serialize() {
    return serializeFrom(rootLayer, links);
  }

  function serializeFrom(root, linkList) {
    const out = {};
    for (const [key, rec] of root.memos) if (!isEmptyRecord(rec)) out[key] = serializeRecord(rec);
    const data = { version: 2, camera: serializeCamera(root.camera), memos: out };
    if (linkList && linkList.length) data.links = linkList.map(serializeLink);
    if (root.regions && root.regions.length) data.regions = root.regions.map(serializeRegion);
    if (root.footprints && Object.keys(root.footprints).length) data.footprints = { ...root.footprints };
    if (root.trails && Object.keys(root.trails).length) data.trails = { ...root.trails };
    if (root.shelf && root.shelf.length) data.shelf = root.shelf.map(serializeRecord);
    if (root.dendrites && root.dendrites.length) data.dendrites = root.dendrites.map(serializeDendrite);
    if (root.activity && Object.keys(root.activity).length) data.activity = { ...root.activity };
    if (root.trash && root.trash.length) data.trash = root.trash.slice(); // 1件ずつは書き換えないので、そのまま
    if (root.graphLayouts && root.graphLayouts.length) data.graphLayouts = root.graphLayouts.map((g) => structuredClone(g));
    if (root.layoutHints) data.layoutHints = structuredClone(root.layoutHints); // 画面からの保存で消えないように（store.js の正規化で ID を確かめる）
    // 区画：紙片の無い既定の区画は書かない（最初に写したときに作るもの。開いただけで保存や元に戻すの1手が増えないように）
    const ps = (root.pockets || []).filter((x) => !HP.isBlankPocket(x));
    if (ps.length) data.pockets = ps.map((x) => structuredClone(x)); // map(structuredClone) と書かない（番号が2つ目の引数に入る）
    return data;
  }

  // ---- ほかのウィンドウとの内容の合わせ方 ----
  // ノートごとに「本体（保存ファイル）と最後に同じだった内容」と、その版の番号を覚えておく（この画面の保存形式で）。
  // 保存が「その間にほかのウィンドウが保存した」と断られたら、共通の内容・こちら・あちらの3つを比べて合わせる：
  // 片方だけが変えたマスはその変更を、両方が変えたマスはこちら（入力しているウィンドウ）を採る。周りの層も同じように合わせる
  const syncs = new Map(); // ノートの ID → { rev, store }
  const ownNext = new Map(); // ノートの ID → Map（こちらの保存で進んだ版：もとの版 → 新しい版）

  function setSync(id, rev, store) {
    syncs.set(id, { rev, store });
  }

  // 本体から届いた内容を、この画面の保存形式に揃える（比べるとき、形の違いを変更と取り違えないように）。
  // ノート直下だけが持つもの（棚・ゴミ箱・順路・グラフの並び・区画・活動）も通す。通さないと、合わせた結果から
  // あちらで足した分と、どちらも触っていない分が落ちる
  function rendererForm(store) {
    const copy = structuredClone(store);
    const root = toLayer(copy);
    attachRootExtras(root, copy);
    return serializeFrom(root, Array.isArray(store.links) ? store.links : []);
  }

  // 表示位置（camera）は比べない。キーの順番も揃える
  function canon(v) {
    return JSON.stringify(v, (k, val) => {
      if (k === 'camera') return undefined;
      if (val && typeof val === 'object' && !Array.isArray(val)) return Object.fromEntries(Object.keys(val).sort().map((x) => [x, val[x]]));
      return val;
    });
  }

  const sameContent = (a, b) => (!a || !b ? !a && !b : canon(a) === canon(b));
  // 未配置の棚の項目の見分け（番号札）：ID があればそれ、無ければ作った時刻＋本文（棚にある間は本文を直せないので変わらない）。
  // 2つのウィンドウの合わせ方と、棚の画面（ボタン・ドラッグ・コメントの開閉・書きかけ）の両方がこれを使う。
  // 棚のメモに ID を付けると見分けが変わるので、付けない（区画の紙片の「元の場所」もこの値で棚の項目を探す）
  const shelfKeyOf = (r) => r.id || `${r.createdAt}|${r.text}`;

  function mergeStores(base, local, remote) {
    const out = { version: 2, camera: local.camera, memos: mergeMemos(base.memos, local.memos, remote.memos) };
    const l = mergeLinks(base.links, local.links, remote.links);
    if (l.length) out.links = l;
    const rg = mergeRegions(base.regions, local.regions, remote.regions);
    if (rg.length) out.regions = rg;
    const sh = mergeById(base.shelf, local.shelf, remote.shelf, shelfKeyOf);
    if (sh.length) out.shelf = sh;
    const dd = mergeById(base.dendrites, local.dendrites, remote.dendrites, (d) => d.id);
    if (dd.length) out.dendrites = dd;
    const fp = mergeCounts(base.footprints, local.footprints, remote.footprints, (x) => (x && x.n) || 0);
    if (fp) out.footprints = fp;
    const tr = mergeCounts(base.trails, local.trails, remote.trails, (x) => Number(x) || 0);
    if (tr) out.trails = tr;
    const ac = mergeCounts(base.activity, local.activity, remote.activity, (x) => (x ? (x.v || 0) + (x.e || 0) : 0));
    if (ac) out.activity = ac;
    const tr2 = mergeById(base.trash, local.trash, remote.trash, (t) => t.id);
    if (tr2.length) out.trash = tr2;
    const gl = mergeById(base.graphLayouts, local.graphLayouts, remote.graphLayouts, (g) => g.id);
    if (gl.length) out.graphLayouts = gl;
    // 配置ヒントは1かたまり：こちらが基準から変えていればこちら、でなければあちら（項目ごとには合わせない）
    const lh = sameContent(local.layoutHints, base.layoutHints) ? remote.layoutHints : local.layoutHints;
    if (lh) out.layoutHints = structuredClone(lh);
    const pk = mergePockets(base.pockets, local.pockets, remote.pockets);
    if (pk.length) out.pockets = pk;
    return out;
  }

  // ID（または見分ける鍵）ごとに：こちらが変えたものはこちら、そうでなければあちら。こちらで消したものは消す
  function mergeById(b = [], l = [], r = [], keyOf) {
    const base = new Map(b.map((x) => [keyOf(x), x]));
    const mine = new Map(l.map((x) => [keyOf(x), x]));
    const out = new Map(r.map((x) => [keyOf(x), x]));
    for (const [id, x] of mine) if (!base.has(id) || !sameContent(x, base.get(id))) out.set(id, x);
    for (const id of base.keys()) if (!mine.has(id)) out.delete(id);
    return [...out.values()];
  }

  // 区画（写しの作業台）：区画ごとに、名前・色などは こちらが変えていればこちら、でなければあちら。
  // 紙片は ID ごとに「こちらが変えた・足したものはこちら、こちらで外したものは消す」。ただし置いた記録（placed）は3つの和。
  // 両方にある紙片は、位置（q, r）と中身（本文など）とコメント（番号札ごと）を別々に合わせる（片方で本文を直し、もう片方で動かす・
  // 両方でコメントを足すと、どれも残る）。
  // 線は両端の組ごと（関連付けと同じ）。両方が同じセルに足した紙片は、写した時刻の遅いほうを空いたセルへずらす。
  // 紙片を全部外した区画は保存に書かれない（空の区画は書かない）ので、片方に無い区画は「紙片を全部外した」と見て紙片ごとに合わせる
  function mergePockets(b = [], l = [], r = []) {
    if (!b.length && !l.length && !r.length) return [];
    // 両方のウィンドウが同時に「最初の区画」を作った：2枚にせず1枚にまとめる
    if (!b.length && l.length === 1 && r.length === 1 && l[0].id !== r[0].id && HP.isPlainPocket(l[0]) && HP.isPlainPocket(r[0])) {
      return [joinFirstPockets(l[0], r[0])];
    }
    const base = new Map(b.map((p) => [p.id, p]));
    const mine = new Map(l.map((p) => [p.id, p]));
    const theirs = new Map(r.map((p) => [p.id, p]));
    const emptied = (p) => ({ ...p, slips: [], lines: [] });
    const out = [];
    for (const id of new Set([...theirs.keys(), ...mine.keys()])) {
      const bp = base.get(id);
      const lp = mine.get(id);
      const rp = theirs.get(id);
      if (!lp && !bp) out.push(rp); // あちらが新しく作った
      else if (!rp && !bp) out.push(lp); // こちらが新しく作った
      else out.push(mergePocket(bp, lp || emptied(bp), rp || emptied(bp)));
    }
    const list = out.filter((p) => !HP.isBlankPocket(p)).sort((x, y) => (x.createdAt < y.createdAt ? -1 : x.createdAt > y.createdAt ? 1 : x.id < y.id ? -1 : 1));
    // 段階1は区画を1枚しか作れない。二重をまとめた直後に、まとめられた側のウィンドウが紙片を足していた、などで
    // 既定の区画（名前・色が既定）が2枚以上になったら、早く作ったほうへ1枚にまとめる（もう1枚の紙片に画面から届かなくならないように）
    if (list.length > 1 && b.length <= 1 && list.every((p) => HP.isPlainPocket(p))) return [list.reduce((acc, p) => joinFirstPockets(acc, p))];
    return list;
  }

  // 紙片のコメント（07）：番号札ごとに、こちらが足した・変えたものはこちら、こちらで消したものは消え、あちらが足したものは残る。
  // 親が無くなった返信は親を外す（読み込みの整えと同じ）。並びは「あちらの並びのあとに、こちらが足した分」
  function mergeSlipComments(b, l, r) {
    const list = (x) => (Array.isArray(x) ? x : []);
    const out = mergeById(list(b), list(l), list(r), (c) => c.id);
    const ids = new Set(out.map((c) => c.id));
    return out.map((c) => {
      if (!c.parentId || ids.has(c.parentId)) return c;
      const { parentId, ...rest } = c;
      return rest;
    });
  }

  function mergePocket(bp, lp, rp) {
    const pick = (k) => (bp && sameContent(lp[k], bp[k]) ? rp[k] : lp[k]);
    const base = new Map((bp ? bp.slips : []).map((s) => [s.id, s]));
    const mine = new Map(lp.slips.map((s) => [s.id, s]));
    const theirs = new Map(rp.slips.map((s) => [s.id, s]));
    const body = (s) => ({ ...s, placed: undefined }); // 置いた記録は別に（和で）合わせる
    const spot = (s) => ({ q: s.q, r: s.r });
    const inner = (s) => ({ ...s, q: undefined, r: undefined, placed: undefined, rec: s.rec ? { ...s.rec, comments: undefined } : s.rec }); // コメントは別に（番号札ごと）
    const merged = new Map(theirs);
    for (const [id, s] of mine) {
      const b = base.get(id);
      const r = theirs.get(id);
      if (!b || !r) {
        if (!b || !sameContent(body(s), body(b))) merged.set(id, s); // こちらが足した・あちらが外したがこちらが変えた
        continue;
      }
      // 3つにある紙片：位置と中身を別々に「こちらが変えていればこちら、でなければあちら」（両方が本文を直したら、こちら）
      const pos = sameContent(spot(s), spot(b)) ? r : s;
      const src = sameContent(inner(s), inner(b)) ? r : s;
      const comments = mergeSlipComments(b.rec && b.rec.comments, s.rec && s.rec.comments, r.rec && r.rec.comments);
      merged.set(id, { ...src, q: pos.q, r: pos.r, rec: { ...src.rec, comments } });
    }
    for (const id of base.keys()) if (!mine.has(id)) merged.delete(id);
    const slips = HP.settleSlips(HP.capSlips([...merged.values()].map((s) => withPlaced(s, base.get(s.id), mine.get(s.id), theirs.get(s.id)))));
    const ids = new Set(slips.map((s) => s.id));
    const p = { id: lp.id, name: pick('name') || HP.DEFAULT_NAME };
    const color = pick('color');
    if (color) p.color = color;
    p.createdAt = lp.createdAt < rp.createdAt ? lp.createdAt : rp.createdAt;
    p.updatedAt = lp.updatedAt > rp.updatedAt ? lp.updatedAt : rp.updatedAt;
    const size = pick('size');
    if (size) p.size = size;
    const layout = pick('layout');
    const kept = layout ? Object.fromEntries(Object.entries(layout).filter(([id]) => ids.has(id))) : null;
    if (kept && Object.keys(kept).length) p.layout = kept;
    p.slips = slips;
    p.lines = mergeLinks(bp ? bp.lines : [], lp.lines, rp.lines).filter((x) => ids.has(x.a) && ids.has(x.b));
    return p;
  }

  // 紙片に、base・こちら・あちらの置いた記録の和を付ける（メモの番号札ごとに1件。上限 50）
  function withPlaced(s, ...from) {
    const placed = HP.mergePlaced(...from.map((x) => x && x.placed));
    const out = { ...s };
    delete out.placed;
    if (placed.length) out.placed = placed;
    return out;
  }

  // 2枚の「最初の区画」を1枚に：早く作ったほう（同じなら番号の小さいほう）の番号と作った時刻を残し、紙片・線は和（同じ番号はこちら）
  function joinFirstPockets(lp, rp) {
    const first = lp.createdAt < rp.createdAt || (lp.createdAt === rp.createdAt && lp.id < rp.id) ? lp : rp;
    const mine = new Map(lp.slips.map((s) => [s.id, s]));
    const theirs = new Map(rp.slips.map((s) => [s.id, s]));
    const all = new Map([...theirs, ...mine]);
    const slips = HP.settleSlips(HP.capSlips([...all.values()].map((s) => withPlaced(s, mine.get(s.id), theirs.get(s.id)))));
    const ids = new Set(slips.map((s) => s.id));
    return {
      id: first.id, name: HP.DEFAULT_NAME, createdAt: first.createdAt,
      updatedAt: lp.updatedAt > rp.updatedAt ? lp.updatedAt : rp.updatedAt,
      slips, lines: mergeLinks([], lp.lines, rp.lines).filter((x) => ids.has(x.a) && ids.has(x.b)),
    };
  }

  // 回数の記録（足あと・道・活動）：鍵ごとに多いほうを採る
  function mergeCounts(b, l, r, countOf) {
    if (!l && !r) return null;
    const out = { ...(r || {}) };
    for (const [k, v] of Object.entries(l || {})) {
      if (!(k in out) || countOf(v) >= countOf(out[k])) out[k] = v;
    }
    return Object.keys(out).length ? out : null;
  }

  // 領域：ID ごとに、こちらが変えたものはこちら、そうでなければあちら。こちらで消したものは消す
  function mergeRegions(b = [], l = [], r = []) {
    const base = new Map(b.map((x) => [x.id, x]));
    const mine = new Map(l.map((x) => [x.id, x]));
    const out = new Map(r.map((x) => [x.id, x]));
    for (const [id, x] of mine) if (!base.has(id) || !sameContent(x, base.get(id))) out.set(id, x);
    for (const id of base.keys()) if (!mine.has(id)) out.delete(id);
    return [...out.values()];
  }

  // 保存形式のメモで、そのメモ自身の中身（本文・いいね・ブックマーク・コメント・画像・リンク・ID）が無い（下の階層だけ）
  const ownEmptyRecord = (x) => !!x && !(x.text || '').trim() && !(x.likedLevel > 0) && !x.bookmarked
    && !(x.comments || []).length && !(x.images || []).length && !(x.urls || []).length && !x.id;

  // 同じメモか（作った時刻と ID で見分ける。ずらして置かれても分かるように）
  const sameIdentity = (x, y) => !!x && !!y && !!x.createdAt && x.createdAt === y.createdAt && (x.id || null) === (y.id || null);

  // inLayer：下の階層の中（中心 (0,0) は親のメモなので、メモを置かない）
  function mergeMemos(b = {}, l = {}, r = {}, inLayer = false) {
    const out = {};
    const moved = [];
    const done = new Set();
    // 前に、ぶつかったメモを隣へずらした側がある（下の「別々の新しいメモ」）：ずらされた元のメモを、同じメモとして合わせる
    // （こちらもあちらも書き続けていても、どちらかが消えたり二重になったりしないように）
    for (const k of Object.keys(b)) {
      const base = b[k];
      if (!l[k] || !r[k]) continue;
      if (sameIdentity(l[k], base) && !sameIdentity(r[k], base)) {
        // あちらが base を k2 へずらし、k に別のメモを置いた：こちらの k はそのまま（あちらの変更も合わせる）、あちらの k のメモをずらす
        const k2 = Object.keys(r).find((x) => x !== k && !b[x] && !l[x] && sameIdentity(r[x], base));
        if (k2) {
          const m = mergeRecord(base, l[k], r[k2]);
          if (m) out[k] = m;
          moved.push([k, r[k]]);
          done.add(k);
          done.add(k2);
        }
      } else if (sameIdentity(r[k], base) && !sameIdentity(l[k], base)) {
        // こちらが base を k2 へずらした（まだ保存していない）：ずらした先で、あちらの変更も合わせる
        const k2 = Object.keys(l).find((x) => x !== k && !b[x] && !r[x] && sameIdentity(l[x], base));
        if (k2) {
          out[k] = l[k];
          const m = mergeRecord(base, l[k2], r[k]);
          if (m) out[k2] = m;
          done.add(k);
          done.add(k2);
        }
      }
    }
    for (const k of new Set([...Object.keys(b), ...Object.keys(l), ...Object.keys(r)])) {
      if (done.has(k)) continue;
      // 同じ空きマスに、こちらとあちらが別々の新しいメモを置いた（こちらの書きかけと、ほかのウィンドウ・ほかの
      // メモアプリから送られてきたメモなど）：こちらはそのまま、あちらのメモは近くの空いたマスへ移す（どちらも消さない）
      if (!b[k] && l[k] && r[k] && !sameContent(l[k], r[k])) {
        // 片方が中身の無い入れ物（送られてきた写しを入れるために作った、本文の無い原点など）なら、ずらさずに
        // 1つにまとめる（下の階層は層ごとに合わせる）。写しがノートの原点の下から外れないように
        const container = ownEmptyRecord(r[k]) ? r[k] : ownEmptyRecord(l[k]) ? l[k] : null;
        if (container) {
          const base = { ...container };
          delete base.children;
          delete base.moreLayers;
          const m = mergeRecord(base, l[k], r[k]);
          if (m) out[k] = m;
          continue;
        }
        out[k] = l[k];
        moved.push([k, r[k]]);
        continue;
      }
      const m = mergeRecord(b[k], l[k], r[k]);
      if (m) out[k] = m;
    }
    for (const [k, rec] of moved) {
      const at = HS.parseKey(k);
      const abs = (rel) => {
        const p = HS.parseKey(rel);
        return HS.keyOf(at.q + p.q, at.r + p.r);
      };
      const spot = HS.pickSpots((rel) => {
        const key = abs(rel);
        return !(key in out) && !(inLayer && key === CENTER_KEY);
      }, 1);
      if (spot) out[abs(spot[0])] = rec;
    }
    return out;
  }

  function mergeRecord(b, l, r) {
    if (sameContent(l, b)) return r; // こちらは変えていない → あちらの内容
    if (sameContent(r, b)) return l; // あちらは変えていない → こちらの内容
    if (!l || !r) return l || r; // 片方が消し、もう片方が書き換えた → 書き換えたほうを残す
    // 両方が変えた：本文・いいね等は、こちらが変えていればこちら。周りの層は層ごとに合わせる
    const own = (x) => {
      const o = { ...x };
      delete o.children;
      delete o.moreLayers;
      return o;
    };
    const out = sameContent(own(l), own(b)) ? own(r) : own(l);
    const layersOf = (x) => (x && x.children ? [x.children, ...(x.moreLayers || [])] : []);
    const lb = layersOf(b);
    const ll = layersOf(l);
    const lr = layersOf(r);
    const merged = [];
    for (let i = 0; i < Math.max(ll.length, lr.length); i++) {
      const lo = ll[i];
      const re = lr[i];
      const ba = lb[i];
      const nameOf = (x) => (x && x.name) || '';
      const name = nameOf(lo) !== nameOf(ba) ? nameOf(lo) : nameOf(re);
      // 組み合わせた画像（位置・大きさ・濃さ）も、こちらが変えていればこちら
      const comboOf = (x) => (x && x.combo) || null;
      const combo = !sameContent(comboOf(lo), comboOf(ba)) ? comboOf(lo) : comboOf(re);
      const layer = { camera: (lo || re).camera, memos: mergeMemos(ba ? ba.memos : {}, lo ? lo.memos : {}, re ? re.memos : {}, true) };
      if (name) layer.name = name;
      if (combo) layer.combo = combo;
      const regions = mergeRegions(ba ? ba.regions : [], lo ? lo.regions : [], re ? re.regions : []);
      if (regions.length) layer.regions = regions;
      const fp = mergeCounts(ba && ba.footprints, lo && lo.footprints, re && re.footprints, (x) => (x && x.n) || 0);
      if (fp) layer.footprints = fp;
      const tr = mergeCounts(ba && ba.trails, lo && lo.trails, re && re.trails, (x) => Number(x) || 0);
      if (tr) layer.trails = tr;
      merged.push(layer);
    }
    const filled = (x) => Object.keys(x.memos).length > 0 || !!x.combo || !!(x.regions && x.regions.length);
    while (merged.length > 1 && !filled(merged[merged.length - 1])) merged.pop();
    if (merged.length > 1 || (merged.length === 1 && filled(merged[0]))) {
      out.children = merged[0];
      if (merged.length > 1) out.moreLayers = merged.slice(1);
    }
    return out;
  }

  // 関連付け：あちらの一覧に、こちらで足したものを足し、こちらで外したものを外す
  function mergeLinks(b = [], l = [], r = []) {
    const key = (x) => (x.a < x.b ? `${x.a}|${x.b}` : `${x.b}|${x.a}`);
    const base = new Map(b.map((x) => [key(x), x]));
    const mine = new Map(l.map((x) => [key(x), x]));
    const out = new Map(r.map((x) => [key(x), x]));
    // 種類・ラベルは、こちらが変えていればこちら
    const sameKind = (x, y) => (x.kind || '') === (y.kind || '') && (x.label || '') === (y.label || '');
    for (const [k, x] of mine) if (!base.has(k) || (out.has(k) && !sameKind(x, base.get(k)))) out.set(k, x);
    for (const k of base.keys()) if (!mine.has(k)) out.delete(k);
    return [...out.values()];
  }

  // 保存を断られた（その間にほかのウィンドウが保存していた）：合わせて保存し直す
  function resolveConflict(boardId, sent, res) {
    const sync = syncs.get(boardId);
    const remote = rendererForm(res.store);
    if (boardId === currentBoardId && !boardReadOnly) {
      const merged = sync ? mergeStores(sync.store, serialize(), remote) : serialize();
      applyRemoteStore(merged);
      setSync(boardId, res.rev, remote);
      dirty = true;
      dataDirty = true;
      scheduleSave();
      resetUndo(); // ほかのウィンドウの変更と合わせた：それより前には戻さない
    } else {
      const merged = sync ? mergeStores(sync.store, sent, remote) : sent;
      setSync(boardId, res.rev, remote);
      enqueueSave(boardId, merged, true);
    }
  }

  // 連続した変更はまとめて保存（最後の変更から少し待つ。ただし最大 MAX_SAVE_WAIT まで）
  function scheduleSave(kind = 'data') {
    if (kind === 'data') requestSideRender();
    if (kind === 'data') scheduleUndoCheckpoint();
    if (kind === 'data' && activeTab === 'graph') requestGraphRender();
    if (kind === 'data' && reading) updateReadActions(); // 読書モードの いいね・ブックマーク・コメントのボタン
    if (kind === 'data' && multi.length) updateMultiBar();
    if (!canSave()) return;
    dirty = true;
    if (kind === 'data') {
      dataDirty = true;
      setSaveStatus('saving');
    }
    const now = performance.now();
    if (!firstDirtyAt) firstDirtyAt = now;
    const due = Math.min(now + (kind === 'data' ? SAVE_DELAY : CAMERA_SAVE_DELAY), firstDirtyAt + MAX_SAVE_WAIT);
    clearTimeout(saveTimer);
    saveTimer = setTimeout(flushSave, Math.max(0, due - now));
  }

  // 表示中のノートの未送信分を、今の内容で保存キューに積む
  function flushSave() {
    clearTimeout(saveTimer);
    saveTimer = 0;
    if (!dirty || !canSave()) return saveChain;
    const boardId = currentBoardId;
    const data = serialize();
    const wasData = dataDirty;
    dirty = false;
    dataDirty = false;
    firstDirtyAt = 0;
    return enqueueSave(boardId, data, wasData);
  }

  function enqueueSave(boardId, data, wasData) {
    unsettled.set(boardId, data);
    const sync = syncs.get(boardId);
    const baseRev = sync ? sync.rev : undefined; // この内容がもとにした版（作った時点で決まる）
    saveChain = saveChain.then(() => sendSave(boardId, data, wasData, baseRev));
    return saveChain;
  }

  async function sendSave(boardId, data, wasData, baseRev) {
    // 前の保存（こちら）で進んだ版なら、その続きとして送る
    const next = ownNext.get(boardId);
    while (next && baseRev !== undefined && next.has(baseRev)) baseRev = next.get(baseRev);
    if (!boardExists(boardId)) {
      unsettled.delete(boardId); // 削除済みのノート
      return;
    }
    try {
      const res = await api.saveBoard(boardId, data, { data: !!wasData, ...(baseRev !== undefined ? { baseRev } : {}) });
      if (res && res.conflict) {
        if (unsettled.get(boardId) === data) unsettled.delete(boardId);
        resolveConflict(boardId, data, res);
        return;
      }
      if (!res || !res.ok) throw new Error((res && res.error) || '不明なエラー');
      if (res.rev !== undefined) {
        if (baseRev !== undefined) {
          if (!ownNext.has(boardId)) ownNext.set(boardId, new Map());
          ownNext.get(boardId).set(baseRev, res.rev);
        }
        setSync(boardId, res.rev, data);
      }
      if (unsettled.get(boardId) === data) unsettled.delete(boardId);
      failedBoards.delete(boardId);
      if (boardId === currentBoardId) lastSavedAt = res.savedAt;
      if (!dataDirty && !failedBoards.size && !boardReadOnly) setSaveStatus('saved'); // 保存中に本文が変わっていたら「保存中」のまま
    } catch (err) {
      console.error('[hex-memo] 保存に失敗しました', err);
      if (!boardExists(boardId)) {
        unsettled.delete(boardId);
        return;
      }
      failedBoards.add(boardId);
      if (boardId === currentBoardId) {
        // 表示中のノートは、再試行のときに最新の内容で送り直す
        dirty = true;
        dataDirty = dataDirty || wasData;
      }
      setSaveStatus('error', `保存に失敗しました：${err.message}（自動で再試行します）`);
      clearTimeout(retryTimer);
      retryTimer = setTimeout(retrySaves, SAVE_RETRY_DELAY);
    }
  }

  function retrySaves() {
    for (const id of [...failedBoards]) {
      if (id === currentBoardId) continue;
      const data = unsettled.get(id);
      if (data) enqueueSave(id, data, true);
      else failedBoards.delete(id);
    }
    flushSave();
  }

  // ウィンドウを閉じる・再読み込みする直前に、未保存分（ほかのノートの送信待ちも含む）を同期的に書き出す
  window.addEventListener('beforeunload', () => {
    if (slipEdit) saveSlipEdit({ by: 'interrupt' }); // 区画の紙片の書きかけも保存して書き出す（空なら前の文のまま）
    if (ovEditKey) closeOvEdit({ commit: true });
    if (!api) return;
    const snapshots = new Map(unsettled);
    if (canSave() && (dirty || unsettled.has(currentBoardId))) snapshots.set(currentBoardId, serialize());
    if (!snapshots.size) return;
    try {
      api.saveSync([...snapshots].map(([id, data]) => ({ id, data })));
    } catch (err) {
      console.error(err);
    }
  });

  // ---- 入力：パン・クリック -------------------------------------------------

  function setSpaceHeld(on) {
    spaceHeld = on;
    stage.classList.toggle('is-space', on);
  }

  stage.addEventListener('pointerdown', (e) => {
    if (e.pointerType === 'touch') return; // 指の操作は下の「タッチ」で
    if (e.target.closest('.combo-frame, .ov-write, .ov-edit')) return; // 位置合わせの枠と、全体表示の入力は、それぞれのほうで扱う
    if (!linking && !e.ctrlKey && !e.metaKey && !e.shiftKey && (e.button === 2 || (e.button === 0 && e.altKey))) {
      const cell = e.target.closest && e.target.closest('.cell');
      const rec = cell && getRecord(cell._key);
      const gesture = overviewLinkGesture({
        overview: isOverview,
        viewOnly: settings.overviewViewOnly === true || boardReadOnly,
        button: e.button,
        alt: !!(e.altKey || altHeld),
        fromMemo: !!(cell && rec && !isEmptyRecord(rec) && overviewWrites()),
      });
      if (gesture !== 'none') {
        // 左の Alt は画面を動かさない。右は、動かさなければ今までのメニュー（離してから出す）
        ovLinkDrag = { pointerId: e.pointerId, key: cell._key, x: e.clientX, y: e.clientY, active: false, button: e.button };
        if (e.button === 0) e.preventDefault();
        return;
      }
    }
    const middle = e.button === 1;
    const spaceDrag = e.button === 0 && spaceHeld;
    // 全体表示では左ドラッグでも動かせる（クリックは拡大）。画像の位置合わせ中も、画像の外のドラッグはハニカムを動かす。
    // ただし全体表示でもメモのマスを押したときは、ふつうの倍率と同じく、少し動かすとメモのドラッグ移動にする
    const ovMemo = e.button === 0 && isOverview && !spaceHeld && overviewMemoCell(e.target);
    const overviewDrag = e.button === 0 && ((isOverview && !ovMemo) || !!comboAdjust);
    if (!middle && !spaceDrag && !overviewDrag) {
      suppressClick = false;
      // メモのあるマスを左ボタンで押したら、少し動かしたところでドラッグ移動にする（動かさなければ編集）
      const cell = e.button === 0 && !drag && !linking ? e.target.closest('.cell') : null;
      const rec = cell && getRecord(cell._key);
      const onControl = e.target.closest('.act, .editor, .meta-link, .meta-badge, .body-url, .body-card, button');
      if (selectMode && cell && rec && !isEmptyRecord(rec) && !isCenter(cell._key) && !onControl && !e.shiftKey) {
        // 選択モード：メモの上からなぞると、通ったメモを選ぶ（選んであるメモから始めると外す）
        paint = { pointerId: e.pointerId, x: e.clientX, y: e.clientY, start: cell._key, remove: multiSet.has(rec), active: false, seen: new Set() };
      } else if (cell && rec && !isEmptyRecord(rec) && !isCenter(cell._key) && !onControl && !e.shiftKey) {
        dragCandidate = { key: cell._key, pointerId: e.pointerId, x: e.clientX, y: e.clientY };
      } else if (e.button === 0 && !drag && !linking && !reading && !onControl && (e.shiftKey || !rec || isEmptyRecord(rec))) {
        // 空いているところ（または Shift を押して）からドラッグすると、四角で囲んだメモを選ぶ
        marquee = { pointerId: e.pointerId, x: e.clientX, y: e.clientY, additive: selectMode || e.ctrlKey || e.metaKey || e.shiftKey, active: false };
      }
      return;
    }
    e.preventDefault();
    stopCameraAnimation();
    pan = { id: e.pointerId, x: e.clientX, y: e.clientY, moved: 0, clickable: overviewDrag && !spaceDrag && !comboAdjust };
    stage.setPointerCapture(e.pointerId);
    stage.classList.add('is-panning');
    suppressClick = spaceDrag; // Space+クリックで編集が始まらないように
  }, true);

  // 全体表示：メモからメモへ線を引く（Alt+左ドラッグ、または右ドラッグ）。種類は離す前に 1〜9、または上の案内
  document.addEventListener('pointermove', (e) => {
    const d = ovLinkDrag;
    if (!d || e.pointerId !== d.pointerId || d.active) return;
    if (Math.hypot(e.clientX - d.x, e.clientY - d.y) <= DRAG_THRESHOLD) return;
    d.active = true;
    suppressClick = true;
    ovLinkSuppressMenu = true;
    if (ovWriteKey) closeOvWrite({ commit: true });
    startLinking(d.key);
  }, true);
  document.addEventListener('pointerup', (e) => {
    const d = ovLinkDrag;
    if (!d || e.pointerId !== d.pointerId) return;
    ovLinkDrag = null;
    if (!d.active) {
      if (d.button === 2) {
        suppressClick = true;
        ovLinkSuppressMenu = true;
        const key = d.key;
        const x = d.x;
        const y = d.y;
        setTimeout(() => {
          ovLinkSuppressMenu = false;
          if (!linking) openCellMenu(key, { x, y });
        }, 0);
      } else {
        suppressClick = true;
        startLinking(d.key); // 動かさずに離した Alt+クリックも、線を引き始める
      }
      return;
    }
    suppressClick = true;
    ovLinkSuppressMenu = true;
    setTimeout(() => { ovLinkSuppressMenu = false; }, 0);
    if (!linking) return;
    const hit = document.elementFromPoint(e.clientX, e.clientY);
    if (hit && hit.closest('#linkBanner, .kind-btn')) return; // 種類を押しただけ。線はまだ引かない
    const key = keyAt(e.clientX, e.clientY);
    const rec = getRecord(key);
    if (rec && !isEmptyRecord(rec) && key !== d.key) completeLinking(key);
    else if (key !== d.key) beginLinkedWrite(key); // 空いたマス：一行入力。Enter でメモと線
  }, true);
  document.addEventListener('pointercancel', (e) => {
    if (!ovLinkDrag || e.pointerId !== ovLinkDrag.pointerId) return;
    ovLinkDrag = null;
  }, true);

  stage.addEventListener('pointermove', (e) => {
    if (!pan || e.pointerId !== pan.id) return;
    const dx = e.clientX - pan.x;
    const dy = e.clientY - pan.y;
    pan.x = e.clientX;
    pan.y = e.clientY;
    pan.moved += Math.abs(dx) + Math.abs(dy);
    if (pan.clickable && pan.moved > 4) suppressClick = true; // 動かしたらクリック（拡大）にしない
    panBy(-dx, -dy);
  });

  // ---- 全体表示：マスにマウスを重ねると、そのマスを読める大きさ（100%）で浮かび上がらせる ----
  // 表示中のマスを複製して、全体表示の縮小のスタイルが効かない場所に置く（本文・いいね・件数・表紙がそのまま見える）。
  // マウスの動きは遮らないので、動かすと隣のマスに付いていき、クリックはこれまでどおりそのマスを 100% で表示
  function peekBox() {
    if (!peek) {
      peek = el('div', 'hex-peek');
      peek.hidden = true;
      peek.setAttribute('aria-hidden', 'true');
      peek.addEventListener('click', onPinnedPeekClick);
      peek.addEventListener('contextmenu', (e) => {
        if (peekPinned) e.preventDefault();
      });
      // 固定中の写しの上の押し下げは、ステージ（パン・ドラッグ）に渡さない
      peek.addEventListener('pointerdown', (e) => {
        if (peekPinned) e.stopPropagation();
      });
      stage.parentElement.append(peek);
    }
    return peek;
  }
  const PEEK_DELAY = 160; // 通り過ぎるだけのマスでは出さない
  const PEEK_STATES = ['is-multi', 'is-selected', 'is-editing', 'is-flash', 'is-cut', 'is-drop-target', 'is-drop-swap', 'is-drag-source', 'is-side-target', 'is-link-source'];

  function showPeek(node, force = false) {
    clearTimeout(peekHideTimer);
    if (!isOverview || !node.isConnected) return;
    if (peekPinned && !force) return; // 固定中は、ほかのマスに付いていかない
    const box = peekBox();
    if (peekKey === node._key && !box.hidden && !force) return;
    peekKey = node._key;
    const clone = node.cloneNode(true);
    clone.classList.remove(...PEEK_STATES);
    clone.style.transform = '';
    const ed = clone.querySelector('.editor');
    if (ed) ed.remove();
    // マスの中心から浮かび上がる。画面からはみ出さないよう寄せる
    const vr = box.parentElement.getBoundingClientRect();
    const hr = node.querySelector('.hex').getBoundingClientRect();
    const cx = hr.left + hr.width / 2 - vr.left;
    const cy = hr.top + hr.height / 2 - vr.top;
    const pad = 12;
    const x = Math.max(pad, Math.min(cx - HEX_W / 2, vr.width - HEX_W - pad));
    const y = Math.max(pad, Math.min(cy - HEX_H / 2, vr.height - HEX_H - pad));
    box.style.transform = `translate(${Math.round(x)}px, ${Math.round(y)}px)`;
    box.style.setProperty('--peek-origin', `${Math.round(cx - x)}px ${Math.round(cy - y)}px`);
    box.dataset.key = node._key;
    box.replaceChildren(clone);
    if (peekPinned === node._key) box.append(...peekPinControls());
    box.hidden = false;
  }

  function hidePeek() {
    clearTimeout(peekTimer);
    clearTimeout(peekHideTimer);
    peekKey = null;
    if (peekPinned) setPeekPinned(null);
    if (!peek || peek.hidden) return;
    peek.hidden = true;
    peek.replaceChildren();
  }

  // ---- 浮かび上がりの固定（縮小中のクリックが「浮かせて固定」のとき）----
  // 固定すると、写しの上でマウスを使える（.is-pinned）。写しはステージの外なので、押したものは写しの上で受けて、
  // 本物のマスと同じ handleAction に回し、そのあと写しを作り直す。外す：×・Esc・外のクリック・動かす・拡大縮小・全体表示を出る
  function setPeekPinned(key) {
    peekPinned = key;
    peekPinCam = key ? { x: camera.x, y: camera.y, zoom: camera.zoom } : null;
    if (!peek) return;
    peek.classList.toggle('is-pinned', !!key);
    if (key) peek.removeAttribute('aria-hidden');
    else peek.setAttribute('aria-hidden', 'true');
  }

  function pinPeek(node) {
    clearTimeout(peekTimer);
    clearTimeout(peekHideTimer);
    peekHideTimer = 0;
    setPeekPinned(node._key);
    showPeek(node, true);
    if (!peek || peek.hidden) setPeekPinned(null); // 出せなかった
  }

  function unpinPeek() {
    if (!peekPinned) return false;
    hidePeek();
    return true;
  }

  // 固定中のマスの中身が変わった（♡・タグ・別のウィンドウなど）：写しを作り直す。マスが無くなったら外す
  function refreshPinnedPeek(key) {
    if (!peekPinned || key !== peekPinned) return;
    const node = activeCells.get(key);
    const rec = getRecord(key);
    if (!node || !rec || isEmptyRecord(rec)) unpinPeek();
    else showPeek(node, true);
  }

  // カメラが固定したときから動いたか（動かした・拡大縮小した・全体表示を出た）
  function peekCameraMoved(cam, pin) {
    return !!pin && (cam.x !== pin.x || cam.y !== pin.y || cam.zoom !== pin.zoom);
  }

  function peekPinControls() {
    const close = el('button', 'peek-pin-btn peek-pin-close', '×');
    close.type = 'button';
    close.dataset.peek = 'close';
    close.title = '固定を外す（Esc・外をクリック）';
    close.setAttribute('aria-label', '固定を外す');
    const edit = el('button', 'peek-pin-btn peek-pin-edit', '✎');
    edit.type = 'button';
    edit.dataset.peek = 'edit';
    edit.title = '100% に拡大して書く（本文をクリックしても同じ）';
    edit.setAttribute('aria-label', '拡大して書く');
    return [close, edit];
  }

  // 固定した写しの上で押したもの。返り値：何をしたか（テスト用）
  const PEEK_SKIP_ACTIONS = new Set(['select']); // 選択モード（縮小中は使わない）
  function onPinnedPeekClick(e) {
    const key = peekPinned;
    if (!key) return null;
    e.stopPropagation();
    e.preventDefault();
    const ctl = e.target.closest('[data-peek]');
    if (ctl && ctl.dataset.peek === 'close') {
      unpinPeek();
      return 'close';
    }
    if (ctl && ctl.dataset.peek === 'edit') {
      unpinPeek();
      editFromOverview(key);
      return 'edit';
    }
    const urlEl = e.target.closest('.body-url');
    if (urlEl) {
      openAnyUrl(urlEl.dataset.url);
      return 'url';
    }
    const btn = e.target.closest('button[data-action]');
    if (btn) {
      const action = btn.dataset.action;
      if (PEEK_SKIP_ACTIONS.has(action)) return null;
      handleAction(action, key, btn);
      refreshPinnedPeek(key); // 写しを今の中身に（変わらない操作でも作り直して害は無い）
      return action;
    }
    if (e.target.closest('.zone-body, .body-text, .cover')) {
      unpinPeek();
      editFromOverview(key);
      return 'edit';
    }
    return null;
  }

  stage.addEventListener('pointermove', (e) => {
    const hidePlus = () => { if (ovMark && ovMark.mode === 'plus') hideOvMark(); };
    if (peekPinned) {
      if (!isOverview || pan || drag) hidePeek(); // 固定中は、マウスを動かすだけでは外さない
      return;
    }
    if (!isOverview || pan || drag || e.buttons || linking || shelfPlacing || pocketDrag || ovWriteKey || ovEditKey) {
      hidePeek();
      hidePlus();
      return;
    }
    const cell = e.target.closest && e.target.closest('.cell');
    const rec = cell && getRecord(cell._key);
    if (!rec || isEmptyRecord(rec)) {
      // 空いたマス・隙間：少し待って消す（マスの間を通るときにちらつかないように）
      clearTimeout(peekTimer);
      if (peek && !peek.hidden && !peekHideTimer) peekHideTimer = setTimeout(() => { peekHideTimer = 0; hidePeek(); }, 120);
      if (overviewWrites()) {
        const key = keyAt(e.clientX, e.clientY);
        const at = getRecord(key);
        if (!isCenter(key) && (!at || isEmptyRecord(at))) {
          if (!ovMark || ovMark.mode !== 'plus' || ovMark.key !== key) showOvMark(key, 'plus');
        } else hidePlus();
      } else hidePlus();
      return;
    }
    hidePlus();
    clearTimeout(peekHideTimer);
    peekHideTimer = 0;
    if (peek && !peek.hidden) {
      showPeek(cell); // 出ている間は、重ねたマスにすぐ付いていく
      return;
    }
    clearTimeout(peekTimer);
    peekTimer = setTimeout(() => showPeek(cell), PEEK_DELAY);
  });
  // 固定中は、写しの上へ出た（pointerleave）・ステージを押した（外のクリックは click で外す）だけでは消さない
  stage.addEventListener('pointerleave', () => {
    if (!peekPinned) hidePeek();
    if (ovMark && ovMark.mode === 'plus') hideOvMark();
  });
  stage.addEventListener('pointerdown', () => {
    if (!peekPinned) hidePeek();
  }, true);
  stage.addEventListener('pointerdown', () => {
    if (ovMark && ovMark.mode === 'plus') hideOvMark();
  }, true);
  stage.addEventListener('wheel', () => {
    hidePeek();
    if (ovMark && ovMark.mode === 'plus') hideOvMark();
  }, { passive: true, capture: true });

  // ---- 小さく表示しているとき：マスのコメント（または本文）の1行目を、吹き出しで出す ----
  // マウスを重ねなくても、どのマスに何があるかが見えるように。吹き出しは倍率によらず同じ大きさで、
  // ほかの吹き出しに重ならない場所を、マスの上の端・下の端・上の外・下の外・右・左の順に探す（ほかのマスの文字に
  // かぶる場所は後回し）。置けないものは隠す（設定で、薄くして重ねて出すことも）。選んだマス → いいね・ブックマーク →
  // 新しい順に場所を取る。マウスの操作は遮らない（下のマスをそのまま押せる。全体表示ではマウスを重ねると大きく浮かぶ）
  const TIP_SHOWS = ['off', 'comment-new', 'comment-old', 'text'];
  const TIP_WHENS = ['overview', 'small', 'always'];
  const TIP_OVERLAPS = ['avoid', 'dim'];
  const TIP_LENS = [0, 12, 20, 32]; // 0：自動（マスの大きさに合わせて切る）
  const TIP_H = 22; // 吹き出しの高さ（画面の px）
  const TIP_GAP = 5; // マスの外に出すときの間（しっぽの分）
  const TIP_MAX_W = 340;
  const TIP_MARGIN = 160; // 画面の外でも、この幅までのマスは並べておく（少し動かしてもすぐ見えるように）
  const TIP_SPACE = 4; // 吹き出しどうしの間（重ならないものだけ出すとき）
  const TIP_COVER_MAX = 0.75; // 重ならないものだけ出すとき：ほかのマスの文字をこれ以上（マス何個分）隠す場所しか無ければ出さない

  function readTipsPref() {
    try {
      const v = JSON.parse(localStorage.getItem(TIPS_PREF) || 'null') || {};
      return {
        show: TIP_SHOWS.includes(v.show) ? v.show : TIPS_DEFAULT.show,
        last: TIP_SHOWS.includes(v.last) && v.last !== 'off' ? v.last : TIPS_DEFAULT.last,
        when: TIP_WHENS.includes(v.when) ? v.when : TIPS_DEFAULT.when,
        overlap: TIP_OVERLAPS.includes(v.overlap) ? v.overlap : TIPS_DEFAULT.overlap,
        len: TIP_LENS.includes(v.len) ? v.len : TIPS_DEFAULT.len,
      };
    } catch {
      return { ...TIPS_DEFAULT };
    }
  }
  tipsPref = readTipsPref();

  function setTipsPref(patch) {
    tipsPref = { ...tipsPref, ...patch };
    if (tipsPref.show !== 'off') tipsPref.last = tipsPref.show;
    try {
      localStorage.setItem(TIPS_PREF, JSON.stringify(tipsPref));
    } catch {
      // 覚えられなくても、この起動中は切り替わる
    }
    tipsLaidZ = null;
    tipsDirty = true;
    updateTipsUi();
    if (activeTab === 'grid') render();
  }

  // 出す・出さないを切り替える（出すときは前に選んでいたもの）
  function toggleTips() {
    const on = tipsPref.show === 'off';
    setTipsPref({ show: on ? tipsPref.last : 'off' });
    if (on && !tipsActive() && activeTab === 'grid') {
      toast(`1行の吹き出しは${tipsPref.when === 'small' ? '100%' : '50%'} 未満に縮小したときに出ます（倍率の右の吹き出しのボタンで、いつも出すようにもできます）`, 'info', 4000);
    }
  }

  function tipsActive() {
    if (tipsPref.show === 'off' || !ready || activeTab !== 'grid' || reading || view.w === 0) return false;
    const z = camera.zoom;
    return tipsPref.when === 'always' || z < (tipsPref.when === 'small' ? 1 : OVERVIEW_BELOW);
  }

  function tipLayerEl() {
    if (!tipLayer) {
      tipLayer = el('div', 'line-tips');
      tipLayer.setAttribute('aria-hidden', 'true');
      stage.insertBefore(tipLayer, $('comboFrame'));
    }
    return tipLayer;
  }

  function clearTips() {
    clearTimeout(tipsTimer);
    tipsTimer = 0;
    tipsLaidZ = null;
    tipsSeenZ = null;
    tipEls.clear();
    if (tipLayer) {
      tipLayer.replaceChildren();
      tipLayer.hidden = true;
    }
    tipsStat = { shown: 0, hidden: 0 };
  }

  function markTipsDirty() {
    if (tipsPref.show === 'off') return;
    tipsDirty = true;
    if (tipsLaidZ !== null && !tipsTimer) queueTips();
  }

  // 次の描画で並べ直す。メモが多くて並べるのに時間がかかるときは、動かしている間は間を空ける
  function queueTips() {
    if (tipsQueued) return;
    tipsQueued = true;
    const run = () => requestAnimationFrame(() => {
      tipsQueued = false;
      if (tipsTimer) return; // 拡大・縮小の途中（止まってから並べる）
      layoutTips();
    });
    const wait = tipsCost > 8 ? tipsLastAt + 150 - performance.now() : 0;
    if (wait > 0) setTimeout(run, wait);
    else run();
  }

  // 描くたびに（render から）：層を画面に合わせて動かす。倍率が変わったら、止まるまで隠して待ってから並べ直す
  function syncTips(ox, oy, z) {
    if (!tipsActive()) {
      if (tipLayer && !tipLayer.hidden) clearTips();
      return;
    }
    const layer = tipLayerEl();
    layer.hidden = false;
    layer.style.transform = `translate(${Math.round(ox)}px, ${Math.round(oy)}px)`;
    if (tipsLaidZ !== null && z !== tipsLaidZ) {
      layer.classList.add('is-moving');
      if (z !== tipsSeenZ || !tipsTimer) {
        clearTimeout(tipsTimer);
        tipsTimer = setTimeout(() => {
          tipsTimer = 0;
          layoutTips();
        }, 180);
      }
      tipsSeenZ = z;
      return;
    }
    if (tipsDirty || tipsLaidZ === null) queueTips();
  }

  // 吹き出しに出す1行（無ければ null）。コメントは、いちばん新しい（または最初の）1件
  function tipContent(rec) {
    let src = '';
    let at = rec.updatedAt || rec.createdAt || '';
    let n = 0;
    if (tipsPref.show === 'text') src = rec.text || '';
    else {
      const list = Array.isArray(rec.comments) ? rec.comments : [];
      if (!list.length) return null;
      const c = tipsPref.show === 'comment-old' ? list[0] : list.reduce((a, b) => (String(b.createdAt) >= String(a.createdAt) ? b : a));
      src = c.text || '';
      at = c.createdAt || '';
      n = list.length;
    }
    const line = (String(src).split('\n').find((l) => l.trim()) || '').trim();
    if (!line) return null;
    const chars = [...line];
    const max = tipsPref.len || 60; // 自動のときは、並べるときに幅で切る
    return { line: chars.length > max ? `${chars.slice(0, max).join('')}…` : line, at, n };
  }

  // 幅 maxW（px）に収まるように、後ろを … にして切る
  function fitTipText(line, maxW, size) {
    if (tipTextWidth(line, size) <= maxW) return line;
    const chars = [...line.replace(/…$/, '')];
    let lo = 1;
    let hi = chars.length;
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if (tipTextWidth(`${chars.slice(0, mid).join('')}…`, size) <= maxW) lo = mid;
      else hi = mid - 1;
    }
    return `${chars.slice(0, lo).join('')}…`;
  }

  // 文字の幅（画面の px）。吹き出しと同じ字で測る
  let tipCtx = null;
  let tipFamily = '';
  const tipWidths = new Map();
  function tipTextWidth(text, size) {
    const k = `${size}|${text}`;
    let w = tipWidths.get(k);
    if (w !== undefined) return w;
    if (!tipCtx) {
      tipCtx = document.createElement('canvas').getContext('2d');
      tipFamily = getComputedStyle(stage).fontFamily;
    }
    const font = `600 ${size}px ${tipFamily}`;
    if (tipCtx.font !== font) tipCtx.font = font;
    w = tipCtx.measureText(text).width;
    if (tipWidths.size > 4000) tipWidths.clear();
    tipWidths.set(k, w);
    return w;
  }

  // 置いた四角を、ます目に分けて覚える（重なりを速く調べる）
  function tipGrid(size = 96) {
    const cells = new Map();
    const span = (a, b) => [Math.floor(a / size), Math.floor(b / size)];
    const each = (r, fn) => {
      const [x0, x1] = span(r.x, r.x + r.w);
      const [y0, y1] = span(r.y, r.y + r.h);
      for (let gx = x0; gx <= x1; gx++) for (let gy = y0; gy <= y1; gy++) if (fn(`${gx},${gy}`) === false) return false;
      return true;
    };
    return {
      add(r) {
        each(r, (k) => {
          if (!cells.has(k)) cells.set(k, []);
          cells.get(k).push(r);
        });
      },
      // r と重なる四角（同じものは1回だけ）
      hits(r, pad = 0) {
        const out = new Set();
        each(r, (k) => {
          for (const o of cells.get(k) || []) {
            if (r.x < o.x + o.w - pad && o.x < r.x + r.w - pad && r.y < o.y + o.h - pad && o.y < r.y + r.h - pad) out.add(o);
          }
        });
        return out;
      },
    };
  }
  // 重ならない場所が先。どちらも重ならなければ「かぶり」の少ないほう、どちらも重なるなら重なりの小さいほう
  function tipBetter(c, b) {
    if (!b) return true;
    if ((c.crowd === 0) !== (b.crowd === 0)) return c.crowd === 0;
    if (c.crowd === 0) return c.cost < b.cost;
    return c.crowd < b.crowd || (c.crowd === b.crowd && c.cost < b.cost);
  }
  const overlapArea = (a, b) => Math.max(0, Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x)) * Math.max(0, Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y));

  function layoutTips() {
    clearTimeout(tipsTimer);
    tipsTimer = 0;
    tipsDirty = false;
    if (!tipsActive()) {
      clearTips();
      return;
    }
    const t0 = performance.now();
    const layer = tipLayerEl();
    const z = camera.zoom;
    tipsLaidZ = z;
    tipsSeenZ = z;
    const hw = (HEX_W / 2) * z;
    const hh = (HEX_H / 2) * z;
    const showBody = z >= TINY_BELOW; // さらに小さいとマスの文字は出ない（かぶっても困らない）
    // 画面に映る範囲（層の座標。層は ox, oy だけ動かしてある）
    const ox = view.w / 2 - (camera.x - anchor.x) * z;
    const oy = view.h / 2 - (camera.y - anchor.y) * z;
    const vis = { x: -ox - TIP_MARGIN, y: -oy - TIP_MARGIN, w: view.w + TIP_MARGIN * 2, h: view.h + TIP_MARGIN * 2 };
    const font = 12;
    const comment = tipsPref.show !== 'text';
    const autoW = Math.max(96, Math.min(TIP_MAX_W, HEX_W * z * 2.2));
    const items = [];
    const bodies = tipGrid();
    for (const [key, node] of activeCells) {
      const rec = getRecord(key);
      if (!rec || isEmptyRecord(rec)) continue;
      const cx = (node._wx - anchor.x) * z;
      const cy = (node._wy - anchor.y) * z;
      if (cx < vis.x || cx > vis.x + vis.w || cy < vis.y || cy > vis.y + vis.h) continue;
      // マスの文字のあたり（ほかの吹き出しは、なるべくここにかぶせない）
      if (showBody) bodies.add({ key, x: cx - hw * 0.76, y: cy - hh * 0.62, w: hw * 1.52, h: hh * 1.24, area: hw * 1.52 * hh * 1.24 });
      if (key === editingKey || (path.length && key === CENTER_KEY)) continue;
      const tip = tipContent(rec);
      if (!tip) continue;
      const chrome = 18 + (comment ? 16 : 0) + (tip.n > 1 ? tipTextWidth(String(tip.n), 10.5) + 14 : 0);
      if (!tipsPref.len) tip.line = fitTipText(tip.line, autoW - chrome, font); // 自動：マス2つ分ほどの幅まで
      const w = Math.min(TIP_MAX_W, Math.ceil(chrome + tipTextWidth(tip.line, font)));
      let rank = (rec.likedLevel || 0) * 10 + (rec.bookmarked ? 5 : 0);
      if (multiSet.has(rec)) rank += 1000;
      if (key === selectedKey) rank += 10000;
      items.push({ key, rec, cx, cy, w, rank, ...tip });
    }
    items.sort((a, b) => b.rank - a.rank || (a.at < b.at ? 1 : a.at > b.at ? -1 : 0) || (a.key < b.key ? -1 : 1));

    const placed = tipGrid();
    const avoid = tipsPref.overlap === 'avoid';
    const out = [];
    let hidden = 0;
    for (const it of items) {
      const { w, cx, cy } = it;
      const h = TIP_H;
      const cands = [
        ['top', cx - w / 2, cy - hh * 0.72 - h / 2],
        ['bottom', cx - w / 2, cy + hh * 0.72 - h / 2],
        ['above', cx - w / 2, cy - hh - TIP_GAP - h],
        ['below', cx - w / 2, cy + hh + TIP_GAP],
        ['right', cx + hw + TIP_GAP, cy - h / 2],
        ['left', cx - hw - TIP_GAP - w, cy - h / 2],
      ];
      let best = null;
      cands.forEach(([side, x, y], order) => {
        const r = { x, y, w, h };
        const clash = placed.hits(avoid ? { x: x - TIP_SPACE, y: y - TIP_SPACE, w: w + TIP_SPACE * 2, h: h + TIP_SPACE * 2 } : r);
        let crowd = 0;
        for (const o of clash) crowd += overlapArea(r, o);
        // ほかのマスの文字にかぶる量（マス何個分か。自分のマスは数えない）
        let cover = 0;
        for (const b of bodies.hits(r, 2)) if (b.key !== it.key) cover += overlapArea(r, b) / b.area;
        // 画面の外にはみ出す分も、少しだけ後回しに
        const outside = r.x < -ox || r.x + w > view.w - ox || r.y < -oy || r.y + h > view.h - oy ? 1 : 0;
        const cost = order + cover * 12 + outside * 3;
        const c = { side, x, y, crowd: crowd || (clash.size ? 1 : 0), cost, cover };
        if (tipBetter(c, best)) best = c;
      });
      if (avoid && (best.crowd > 0 || best.cover > TIP_COVER_MAX)) {
        hidden++;
        continue;
      }
      placed.add({ x: best.x, y: best.y, w, h });
      out.push({ ...it, ...best });
    }

    // 要素を作り直さずに、出す・動かす・消す
    const keep = new Set();
    for (const t of out) {
      keep.add(t.key);
      let node = tipEls.get(t.key);
      if (!node) {
        node = el('div', 'line-tip');
        node.dataset.key = t.key;
        layer.append(node);
        tipEls.set(t.key, node);
      }
      const sig = `${tipsPref.show}|${t.line}|${t.n}`;
      if (node._sig !== sig) {
        node._sig = sig;
        const parts = [];
        if (comment) parts.push(svgIcon('comment'));
        parts.push(el('span', 'line-tip-text', t.line));
        if (t.n > 1) parts.push(el('span', 'line-tip-n', String(t.n)));
        node.replaceChildren(...parts);
      }
      node.style.transform = `translate(${Math.round(t.x)}px, ${Math.round(t.y)}px)`;
      node.style.width = `${t.w}px`;
      node.dataset.side = t.side;
      node.dataset.like = String(t.rec.likedLevel || 0);
      node.classList.toggle('is-comment', comment);
      node.classList.toggle('is-crowded', t.crowd > 0);
      node.classList.toggle('is-selected', t.key === selectedKey);
    }
    for (const [k, node] of tipEls) {
      if (keep.has(k)) continue;
      node.remove();
      tipEls.delete(k);
    }
    layer.classList.remove('is-moving');
    tipsStat = { shown: out.length, hidden };
    updateTipsStatus();
    tipsLastAt = performance.now();
    tipsCost = tipsLastAt - t0;
  }

  // ---- 1行の吹き出しの設定（ツールバーの「1行」） ----
  const tipsMenu = $('tipsMenu');

  function updateTipsUi() {
    const btn = $('tipsBtn');
    const on = tipsPref.show !== 'off';
    btn.setAttribute('aria-pressed', String(on));
    btn.title = on
      ? `1行の吹き出し：${{ 'comment-new': 'コメント（新しい1件）', 'comment-old': 'コメント（最初の1件）', text: '本文' }[tipsPref.show]}の1行目を出しています（押すと設定）`
      : '縮小したときに、マスのコメント（または本文）の1行目を吹き出しで出す（押すと設定）';
    for (const b of tipsMenu.querySelectorAll('[data-tips-show]')) b.setAttribute('aria-pressed', String(b.dataset.tipsShow === tipsPref.show));
    for (const b of tipsMenu.querySelectorAll('[data-tips-when]')) b.setAttribute('aria-pressed', String(b.dataset.tipsWhen === tipsPref.when));
    for (const b of tipsMenu.querySelectorAll('[data-tips-overlap]')) b.setAttribute('aria-pressed', String(b.dataset.tipsOverlap === tipsPref.overlap));
    for (const b of tipsMenu.querySelectorAll('[data-tips-len]')) b.setAttribute('aria-pressed', String(Number(b.dataset.tipsLen) === tipsPref.len));
    tipsMenu.classList.toggle('is-off', !on);
    updateTipsStatus();
  }

  function updateTipsStatus() {
    if (!tipsMenu.matches(':popover-open')) return;
    const st = $('tipsStatus');
    if (tipsPref.show === 'off') st.textContent = '';
    else if (!tipsActive()) {
      st.textContent = activeTab === 'grid'
        ? `いまは ${Math.round(camera.zoom * 100)}% なので出していません（${tipsPref.when === 'small' ? '100%' : '50%'} 未満で出ます）`
        : 'ハニカムの画面で出ます';
    } else {
      st.textContent = `いま ${tipsStat.shown} 件を表示${tipsStat.hidden ? `。重なる ${tipsStat.hidden} 件は隠しています（拡大する・マウスを重ねると見えます）` : ''}`;
    }
  }

  function openTipsMenu(anchorEl = $('tipsBtn')) {
    updateTipsUi();
    const r = anchorEl.getBoundingClientRect();
    const visible = r.width > 0 && r.bottom > 0;
    showPopoverAt(tipsMenu, visible ? { x: r.left + r.width / 2 - 220, y: r.bottom + 8 } : { x: innerWidth / 2 - 220, y: 90 });
    updateTipsStatus();
  }

  $('tipsBtn').addEventListener('click', () => {
    if (tipsMenu.matches(':popover-open')) tipsMenu.hidePopover();
    else openTipsMenu();
  });
  tipsMenu.addEventListener('click', (e) => {
    const b = e.target.closest('button');
    if (!b) return;
    if (b.dataset.tipsShow) setTipsPref({ show: b.dataset.tipsShow });
    else if (b.dataset.tipsWhen) setTipsPref({ when: b.dataset.tipsWhen });
    else if (b.dataset.tipsOverlap) setTipsPref({ overlap: b.dataset.tipsOverlap });
    else if (b.dataset.tipsLen) setTipsPref({ len: Number(b.dataset.tipsLen) });
    else if (b.id === 'tipsClose') tipsMenu.hidePopover();
    // 並べ終わってから件数を出し直す
    requestAnimationFrame(() => requestAnimationFrame(updateTipsStatus));
  });
  updateTipsUi();

  // 全体表示でクリック：その場所（メモのマスならその中心）を 100% で表示
  // 全体表示で、押した要素がつかめるメモのマスならそのマス（中心・選択モード・関連付けや貼り付けの途中は除く）
  function overviewMemoCell(target) {
    if (!isOverview || comboAdjust || linking || selectMode || tplPlacing || shelfPlacing || reading || drag) return null;
    const cell = target && target.closest && target.closest('.cell');
    if (!cell || cell.classList.contains('drag-ghost')) return null;
    const rec = getRecord(cell._key);
    return rec && !isEmptyRecord(rec) && !isCenter(cell._key) ? cell : null;
  }

  // 縮小中に「編集する」を選んでいるとき：そのマスへ 100% で寄ってから書き始める（倍率を 50% 未満で固定中は知らせて、寄るだけ）
  function editFromOverview(key) {
    const { q, r } = H.parseKey(key);
    const p = H.hexToPixel(q, r, HEX_SIZE);
    if (warnOverviewLocked()) {
      animateCameraTo(p.x, p.y, () => flashCell(key), 1);
      return;
    }
    animateCameraTo(p.x, p.y, () => {
      if (!isOverview && getRecord(key)) startEdit(key);
    }, 1);
  }

  function zoomInAt(clientX, clientY) {
    const r = stage.getBoundingClientRect();
    const z = camera.zoom;
    const wx = camera.x + (clientX - r.left - view.w / 2) / z;
    const wy = camera.y + (clientY - r.top - view.h / 2) / z;
    const h = H.pixelToHex(wx, wy, HEX_SIZE);
    const key = H.keyOf(h.q, h.r);
    const rec = getRecord(key);
    if (rec && !isEmptyRecord(rec)) {
      const p = H.hexToPixel(h.q, h.r, HEX_SIZE);
      animateCameraTo(p.x, p.y, () => flashCell(key), 1);
    } else {
      animateCameraTo(wx, wy, null, 1);
    }
  }

  function endPan(e) {
    if (!pan || e.pointerId !== pan.id) return;
    pan = null;
    stage.classList.remove('is-panning');
    if (stage.hasPointerCapture(e.pointerId)) stage.releasePointerCapture(e.pointerId);
  }
  stage.addEventListener('pointerup', endPan);
  stage.addEventListener('pointercancel', endPan);

  // ---- タッチ（iPad・タッチ画面）----
  // ハニカム：1本指でなぞると移動、2本指でピンチ（拡大縮小・移動）、長押しして離すと右クリックと同じメニュー、
  // メモのマスを長押ししたまま動かすとメモの移動（ドラッグ）。タップはこれまでのクリックと同じ（本文の編集など）。
  // 画面のほかの場所（タブ・ツリー・サイドバー・ノートのハニカムなど）も、長押しして離すと右クリックと同じメニューになる。
  // メニューは指を離したときに開く（押したままのときに開くと、指を離したときに「外側を押した」ことになって閉じてしまうため）。
  // 長押しが成立したところで、その場所を光らせて知らせる
  const LONG_PRESS_MS = 500;
  const TOUCH_SLOP = 10; // これより動いたら長押しではなく移動
  const touchPoints = new Map(); // ハニカムに触れている指 pointerId → { x, y }
  let touchPan = null; // { id, x, y, startX, startY, moved, longFired, dragged, holdEl, target, timer }
  let pinch = null; // { d, mx, my }
  let otherPress = null; // ハニカムの外の長押し { id, x, y, target, holdEl, timer, fired, moved }
  let swallowClick = null; // 長押しで指を離したときのクリック（タブの切り替えなど）は無視する { target, until }
  let lastTouchAt = -Infinity; // 最後に指が離れた時刻（ブラウザ自身の長押しメニューと重ならないように）

  // 長押しの位置に、右クリックと同じ合図を出す（それぞれの右クリックの処理がそのまま動く）。
  // 指を離したときの処理（ポップアップの「外側を押したら閉じる」）が済んでから出す
  function fireContextMenu(target, x, y) {
    setTimeout(() => {
      const el0 = target && target.isConnected ? target : document.elementFromPoint(x, y);
      if (el0) el0.dispatchEvent(new MouseEvent('contextmenu', { bubbles: true, cancelable: true, clientX: x, clientY: y, button: 2, view: window }));
    }, 0);
  }

  // ブラウザ（タッチ画面の Chrome など）が長押しで出す右クリックの合図は止める（自前の合図と二重にならないように）
  window.addEventListener('contextmenu', (e) => {
    if (!e.isTrusted) return;
    const touchy = e.pointerType === 'touch' || (e.sourceCapabilities && e.sourceCapabilities.firesTouchEvents);
    if (touchy || touchPoints.size || touchPan || otherPress || performance.now() - lastTouchAt < 1500) {
      e.preventDefault();
      e.stopImmediatePropagation();
    }
  }, true);

  // 長押しが成立した場所を光らせる（離すとメニュー）
  function holdMark(target) {
    const el0 = target && target.closest ? target.closest('.cell, button, [role="tab"], [role="treeitem"], li, .seg, .hive-cell') || target : null;
    if (el0) el0.classList.add('is-touch-hold');
    return el0;
  }
  const holdUnmark = (el0) => el0 && el0.classList.remove('is-touch-hold');

  function cancelTouchPress() {
    if (touchPan) {
      clearTimeout(touchPan.timer);
      holdUnmark(touchPan.holdEl);
    }
    touchPan = null;
  }

  function touchLongPress() {
    const t = touchPan;
    if (!t || t.moved || pinch) return;
    t.longFired = true;
    suppressClick = true; // 指を離したときのタップ（本文の編集）にしない
    t.holdEl = holdMark(t.target);
    // メモのあるマスなら、このまま指を動かすとドラッグで移動
    const cell = t.target.closest && t.target.closest('.cell');
    const rec = cell && getRecord(cell._key);
    if (cell && rec && !isEmptyRecord(rec) && !isCenter(cell._key) && !linking
      && !t.target.closest('.act, .editor, .meta-link, .meta-badge, .body-url, .body-card')) {
      dragCandidate = { key: cell._key, pointerId: t.id, x: t.x, y: t.y };
    }
  }

  const midpoint = () => {
    const [a, b] = [...touchPoints.values()];
    return { d: Math.hypot(a.x - b.x, a.y - b.y), mx: (a.x + b.x) / 2, my: (a.y + b.y) / 2 };
  };

  stage.addEventListener('pointerdown', (e) => {
    if (e.pointerType !== 'touch' || e.target.closest('.editor, .combo-frame, .ov-write, .ov-edit')) return; // 本文の入力欄は、ふつうの操作（文字の選択など）。位置合わせの枠と全体表示の入力は枠のほうで
    touchPoints.set(e.pointerId, { x: e.clientX, y: e.clientY });
    stopCameraAnimation();
    if (touchPoints.size === 1) {
      suppressClick = false;
      touchPan = { id: e.pointerId, x: e.clientX, y: e.clientY, startX: e.clientX, startY: e.clientY, moved: false, longFired: false, dragged: false, holdEl: null, target: e.target, timer: 0 };
      touchPan.timer = setTimeout(touchLongPress, LONG_PRESS_MS);
    } else if (touchPoints.size === 2) {
      // 2本目の指：長押し・移動・ドラッグをやめてピンチへ
      cancelTouchPress();
      dragCandidate = null;
      if (drag) endDrag();
      pinch = midpoint();
      suppressClick = true;
    }
  }, true);

  stage.addEventListener('pointermove', (e) => {
    if (e.pointerType !== 'touch' || !touchPoints.has(e.pointerId)) return;
    touchPoints.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pinch && touchPoints.size >= 2) {
      const now = midpoint();
      if (pinch.d > 0 && now.d > 0) zoomAt(now.mx, now.my, now.d / pinch.d);
      panBy(-(now.mx - pinch.mx), -(now.my - pinch.my));
      pinch = now;
      return;
    }
    const t = touchPan;
    if (!t || e.pointerId !== t.id) return;
    if (drag) {
      // 長押しのまま動かして、メモの移動（ドラッグ）が始まった：移動は移動の処理で
      t.dragged = true;
      holdUnmark(t.holdEl);
      return;
    }
    const far = Math.hypot(e.clientX - t.startX, e.clientY - t.startY) >= TOUCH_SLOP;
    if (t.longFired) {
      // 長押しの後に動かした（ドラッグにならない場所）：メニューは出さない
      if (far && !dragCandidate) {
        t.moved = true;
        holdUnmark(t.holdEl);
      }
      return;
    }
    if (!t.moved && !far) return;
    if (!t.moved) {
      t.moved = true;
      clearTimeout(t.timer);
      suppressClick = true;
      hidePeek();
    }
    panBy(-(e.clientX - t.x), -(e.clientY - t.y));
    t.x = e.clientX;
    t.y = e.clientY;
  });

  function touchUp(e) {
    if (e.pointerType !== 'touch') return;
    touchPoints.delete(e.pointerId);
    lastTouchAt = performance.now();
    const t = touchPan;
    if (t && e.pointerId === t.id) {
      clearTimeout(t.timer);
      holdUnmark(t.holdEl);
      touchPan = null;
      // 長押しして、動かさずに離した：右クリックと同じメニュー
      if (e.type === 'pointerup' && t.longFired && !t.dragged && !t.moved) fireContextMenu(t.target, t.startX, t.startY);
    }
    if (touchPoints.size < 2) pinch = null;
    if (touchPoints.size === 1 && !drag) {
      // ピンチの後に残った1本の指：そのまま移動に使う（長押しにはしない）
      const [id, p] = [...touchPoints.entries()][0];
      touchPan = { id, x: p.x, y: p.y, startX: p.x, startY: p.y, moved: true, longFired: false, dragged: false, holdEl: null, target: stage, timer: 0 };
    }
  }
  stage.addEventListener('pointerup', touchUp);
  stage.addEventListener('pointercancel', touchUp);

  // ハニカムの外（タブ・ツリー・サイドバーの一覧・メニュー・ノートのハニカムなど）：長押しして離すと右クリックと同じ
  document.addEventListener('pointerdown', (e) => {
    if (e.pointerType !== 'touch' || stage.contains(e.target) || e.target.closest('input, textarea, select, [contenteditable="true"]')) return;
    if (otherPress) {
      clearTimeout(otherPress.timer);
      holdUnmark(otherPress.holdEl);
    }
    const press = { id: e.pointerId, x: e.clientX, y: e.clientY, target: e.target, holdEl: null, timer: 0, fired: false, moved: false };
    press.timer = setTimeout(() => {
      press.fired = true;
      press.holdEl = holdMark(press.target);
    }, LONG_PRESS_MS);
    otherPress = press;
  }, true);
  document.addEventListener('pointermove', (e) => {
    const p = otherPress;
    if (!p || e.pointerId !== p.id || Math.hypot(e.clientX - p.x, e.clientY - p.y) <= TOUCH_SLOP) return;
    clearTimeout(p.timer); // なぞった（スクロール・並べ替えなど）：長押しにしない
    holdUnmark(p.holdEl);
    p.moved = true;
  }, true);
  const endOtherPress = (e) => {
    const p = otherPress;
    if (!p || e.pointerId !== p.id) return;
    clearTimeout(p.timer);
    holdUnmark(p.holdEl);
    otherPress = null;
    lastTouchAt = performance.now();
    if (e.type === 'pointerup' && p.fired && !p.moved) {
      swallowClick = { target: p.target, until: performance.now() + 1500 };
      fireContextMenu(p.target, p.x, p.y);
    }
  };
  document.addEventListener('pointerup', endOtherPress, true);
  document.addEventListener('pointercancel', endOtherPress, true);
  document.addEventListener('click', (e) => {
    const s = swallowClick;
    if (!s) return;
    swallowClick = null;
    if (performance.now() < s.until && s.target.isConnected && s.target.contains(e.target)) {
      e.preventDefault();
      e.stopPropagation();
    }
  }, true);

  stage.addEventListener('pointermove', (e) => {
    if (drag && e.pointerId === drag.pointerId) {
      drag.x = e.clientX;
      drag.y = e.clientY;
      updateDrag();
    } else if (dragCandidate && e.pointerId === dragCandidate.pointerId && (e.buttons & 1)
      && Math.hypot(e.clientX - dragCandidate.x, e.clientY - dragCandidate.y) > DRAG_THRESHOLD) {
      startDrag(e);
    }
  });
  stage.addEventListener('pointerup', (e) => {
    if (drag && e.pointerId === drag.pointerId) finishDrag();
    dragCandidate = null;
  });
  stage.addEventListener('pointercancel', () => {
    endDrag();
    dragCandidate = null;
  });
  stage.addEventListener('lostpointercapture', (e) => {
    // ウィンドウ外でボタンを離した等：移動しない。タッチでは、指を置いたマスの要素が持っていた捕捉が
    // ステージへ移るときにもこの合図が（その要素から）届くので、ステージ自身が失ったときだけにする
    if (drag && e.target === stage && e.pointerId === drag.pointerId) endDrag();
  });

  // 中ボタンの既定動作（オートスクロール・Linux の貼り付け）を止める
  for (const type of ['mousedown', 'mouseup', 'auxclick']) {
    stage.addEventListener(type, (e) => {
      if (e.button === 1) e.preventDefault();
    });
  }

  // ボタンを押しても本文のフォーカスを奪わない
  stage.addEventListener('mousedown', (e) => {
    if (e.button === 0 && e.target.closest('.act, .meta-link, .meta-badge, .body-url, .body-card, .cell-check')) e.preventDefault();
  });

  stage.addEventListener('click', (e) => {
    if (suppressClick) {
      suppressClick = false;
      return;
    }
    if (tplPlacing) {
      // 定型を貼る場所を選んでいる途中
      if (isOverview) {
        toast('全体表示では貼れません。拡大してからマスをクリックしてください', 'warn');
        return;
      }
      const p = tplPlacing;
      const key = keyAt(e.clientX, e.clientY);
      cancelTemplatePlacing();
      pasteTemplate(p.tpl, key, { rot: p.rot, mirror: p.mirror, avoidRegions: p.avoidRegions });
      return;
    }
    if (shelfPlacing) {
      // 棚のメモ（または区画の紙片の写し）を置くマスを選んでいる途中
      const p = shelfPlacing;
      cancelShelfPlacing();
      const key = keyAt(e.clientX, e.clientY);
      if (p.kind === 'pocket') {
        // 紙片の写しは全体表示でも置ける（「見るだけ」のときは今までどおり止める）
        if (isOverview && !overviewWrites()) toast('全体表示では置けません。拡大してからマスをクリックしてください', 'warn');
        else placePocketSlip(p.pocketId, p.slipId, key);
      } else if (isOverview && !overviewWrites()) toast('全体表示では置けません。拡大してからマスをクリックしてください', 'warn');
      else placeShelfRec(p.rec, key);
      return;
    }
    if (comboAdjust) return; // 画像の位置合わせ中は、マスを押しても何もしない（終わるのは上の「完了」か Enter）
    if (reading) {
      const c = e.target.closest('.cell');
      const at = c && !e.target.closest('button') ? readingList().findIndex(([k]) => k === c._key) : -1;
      if (at >= 0) {
        goReadingAt(at);
        return;
      }
      stopReading();
    }
    if (linking) {
      // 関連付け先を選んでいる途中：六角形ボタンで階層を移動しながら選べる。それ以外のクリックは「選ぶ」
      const layerBtn = e.target.closest('button[data-action="layer"]');
      const layerCell = layerBtn && e.target.closest('.cell');
      if (layerCell) {
        enterLayer(layerCell._key);
        return;
      }
      const key = keyAt(e.clientX, e.clientY);
      const rec = getRecord(key);
      if (linking.create) {
        if (isOverview) {
          zoomInAt(e.clientX, e.clientY); // 全体表示では、拡大してから置く
          warnOverviewLocked(); // 倍率を固定中は拡大できない
        } else completeNewLinked(key);
      } else if (isOverview && !(rec && !isEmptyRecord(rec))) {
        if (!beginLinkedWrite(key)) zoomInAt(e.clientX, e.clientY); // 見るだけ・中心は、今までどおり拡大
      } else completeLinking(key);
      return;
    }
    if (isOverview) {
      if (e.target.closest && e.target.closest('.ov-write, .ov-edit')) return;
      if (unpinPeek()) return; // 固定中に外をクリック：外すだけ（拡大しない）
      const key = keyAt(e.clientX, e.clientY);
      const rec = getRecord(key);
      const filled = !!(rec && !isEmptyRecord(rec));
      const act = emptyOverviewClick({
        overview: true,
        viewOnly: settings.overviewViewOnly === true || boardReadOnly,
        filled,
        center: isCenter(key),
      });
      if (act === 'write') {
        cancelOvZoom();
        if (ovEditKey) closeOvEdit({ commit: true });
        if (ovWriteKey !== key) {
          if (ovWriteKey) closeOvWrite({ commit: true });
          openOvWrite(key);
        }
        return;
      }
      const filledAct = overviewFilledAction({
        overview: true,
        viewOnly: settings.overviewViewOnly === true,
        filled,
        center: isCenter(key),
        readOnly: boardReadOnly,
        gesture: e.detail > 1 ? 'dblclick' : 'click',
      });
      if (filledAct === 'edit') {
        cancelOvZoom();
        if (ovWriteKey) closeOvWrite({ commit: true });
        openOvEdit(key);
        return;
      }
      if (filledAct === 'wait') {
        if (ovWriteKey) closeOvWrite({ commit: true });
        if (ovEditKey) closeOvEdit({ commit: true });
        scheduleOvZoom(e.clientX, e.clientY, e.target); // 1回のクリックは「メモのクリック」。2回押しは上で欄を開く
        return;
      }
      cancelOvZoom();
      if (ovWriteKey) closeOvWrite({ commit: true });
      if (ovEditKey) closeOvEdit({ commit: true });
      const mode = overviewClickMode();
      const ovCell = mode !== 'zoom' && overviewMemoCell(e.target);
      if (ovCell && mode === 'pin') pinPeek(ovCell);
      else if (ovCell) editFromOverview(ovCell._key);
      else zoomInAt(e.clientX, e.clientY);
      return;
    }
    // 本文の中のリンク：押すと開く（編集は始めない）
    const urlEl = e.target.closest('.body-url');
    if (urlEl && !e.target.closest('.editor')) {
      e.stopPropagation();
      openAnyUrl(urlEl.dataset.url);
      return;
    }
    const cell = e.target.closest('.cell');
    const btn = e.target.closest('button[data-action]');
    if (selectMode && cell && (!btn || btn.dataset.action === 'select')) {
      // 選択モード：メモのマスはクリックで選ぶ・外す（編集は始めない。空いたマスでは何もしない）
      e.stopPropagation();
      if (e.shiftKey) rangeMulti(cell._key);
      else if (selectableRec(cell._key)) toggleMulti(cell._key);
      else if (!selectHinted) {
        selectHinted = true;
        toast('いまはマスを選んでいます。書くときは、下の「完了」で選ぶのを終えてから', 'info', 3500);
      }
      return;
    }
    if (cell && !btn && e.altKey && !e.ctrlKey && !e.metaKey && !e.shiftKey) {
      // Alt+クリック：そのマスから関連線を引き始める（続けて相手をクリック）
      e.stopPropagation();
      const rec = getRecord(cell._key);
      if (rec && !isEmptyRecord(rec)) startLinking(cell._key);
      return;
    }
    if (cell && !btn && (e.ctrlKey || e.metaKey || e.shiftKey)) {
      // Ctrl+クリックで1つずつ足す（外す）、Shift+クリックで範囲を選ぶ（編集は始めない）
      e.stopPropagation();
      if (editingKey) endEdit();
      if (e.shiftKey) rangeMulti(cell._key);
      else toggleMulti(cell._key);
      return;
    }
    if (cell && btn) {
      // アクションは本文の編集を開始しない
      e.stopPropagation();
      handleAction(btn.dataset.action, cell._key, btn);
    } else if (cell) {
      clearMulti(); // ふつうのクリックは1つだけ選ぶ
      multiAnchor = null;
      startEdit(cell._key);
    } else if (selectMode) {
      // 選択モードでは、隙間をクリックしても選んだものは消さない（「完了」か Esc で終わる）
    } else {
      endEdit(); // 隙間（ステージ）をクリック
      clearSelection();
    }
  });

  stage.addEventListener('dblclick', (e) => {
    if (!isOverview || (e.target.closest && e.target.closest('.ov-write, .ov-edit, button'))) return;
    const key = keyAt(e.clientX, e.clientY);
    const rec = getRecord(key);
    const act = overviewFilledAction({
      overview: true,
      viewOnly: settings.overviewViewOnly === true,
      filled: !!(rec && !isEmptyRecord(rec)),
      center: isCenter(key),
      readOnly: boardReadOnly,
      gesture: 'dblclick',
    });
    if (act !== 'edit') return;
    e.preventDefault();
    cancelOvZoom();
    if (ovWriteKey) closeOvWrite({ commit: true });
    openOvEdit(key);
  });

  cellLayer.addEventListener('animationend', (e) => {
    const btn = e.target.closest && e.target.closest('.act.is-pop');
    if (btn) btn.classList.remove('is-pop');
  });

  stage.addEventListener('wheel', (e) => {
    const scroller = e.target.closest && e.target.closest('.editor');
    if (scroller && !e.ctrlKey && canScrollY(scroller, e.deltaY)) return; // 本文のスクロールを優先
    e.preventDefault();
    if (e.ctrlKey) {
      // Ctrl+ホイール・トラックパッドのピンチ：ポインターの位置を中心に拡大縮小
      const dz = e.deltaMode === 1 ? e.deltaY * 40 : e.deltaMode === 2 ? e.deltaY * view.h : e.deltaY;
      zoomAt(e.clientX, e.clientY, Math.exp(-dz * 0.0022));
      return;
    }
    let dx = e.deltaX;
    let dy = e.deltaY;
    if (e.deltaMode === 1) {
      dx *= 40;
      dy *= 40;
    } else if (e.deltaMode === 2) {
      dx *= view.w;
      dy *= view.h;
    }
    if (e.shiftKey && dx === 0) {
      dx = dy;
      dy = 0;
    }
    panBy(dx, dy);
  }, { passive: false });

  function canScrollY(node, dy) {
    if (node.scrollHeight <= node.clientHeight + 1 || dy === 0) return false;
    return dy < 0 ? node.scrollTop > 0 : node.scrollTop + node.clientHeight < node.scrollHeight - 1;
  }

  // フォーカス移動でステージ自体がスクロールしてしまうのを打ち消す
  stage.addEventListener('scroll', () => {
    stage.scrollTop = 0;
    stage.scrollLeft = 0;
  });

  // ---- 入力：キーボード ------------------------------------------------------

  document.addEventListener('keyup', (e) => {
    if (e.key === 'Alt') altHeld = false;
  });
  window.addEventListener('blur', () => { altHeld = false; });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Alt' && !e.repeat) {
      altHeld = true;
      // 全体表示で線を引くとき、Alt をブラウザのメニューに取られないようにする
      if (overviewWrites() && !isTypingTarget(e.target)) e.preventDefault();
    }
    if (e.isComposing || e.keyCode === 229) return; // IME 変換中の Esc / Enter は触らない
    // クイック入力（設定したキー。本文の入力中でも効く）。デスクトップ版は本体に任せる：
    // キーで呼び出したところなら、もう一度のキーで最小化する。最小化する別のキーも
    if (!e.repeat && matchesAccelerator(e, settings.quickInput.shortcut)) {
      e.preventDefault();
      if (api && api.quickKey) ipc(api.quickKey()).catch(() => {});
      else if (!anyDialogOpen()) quickInput();
      return;
    }
    if (!e.repeat && settings.quickInput.hideShortcut && api && api.minimizeApp && matchesAccelerator(e, settings.quickInput.hideShortcut)) {
      e.preventDefault();
      ipc(api.minimizeApp()).catch(() => {});
      return;
    }
    if (anyDialogOpen()) return; // ダイアログ側で処理（Esc で閉じる）
    // 区画の紙片を並べ替えている間：Esc でやめるだけ（ノートのハニカム・ツリーの Esc より先。Ctrl+Z などほかのキーも効かせない）
    if (pocketDrag && pocketDrag.dragging) {
      if (e.key === 'Escape') {
        e.preventDefault();
        cancelPocketDrag();
      }
      return;
    }
    // 六角形スクショ（アプリの中でも。ほかのアプリの前からは本体のグローバルなキーで）
    if (!e.repeat && captureSupported() && settings.capture && matchesAccelerator(e, settings.capture.shortcut)) {
      e.preventDefault();
      startCapture();
      return;
    }
    if ((e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey && e.code === 'KeyF') {
      e.preventDefault();
      openSearch();
      return;
    }
    // タブの中のノート（ツリー）は手動で開閉するので、Esc もここで閉じる（上に重なったメニューが先）
    if (e.key === 'Escape' && treeIsOpen() && !boardMenu.matches(':popover-open')) {
      e.preventDefault();
      closeBoardTree();
      return;
    }
    if (e.key === 'Escape' && document.querySelector('.menu:popover-open')) return; // メニューは自分で閉じる
    if (hive.open && !isTypingTarget(e.target)) {
      // ノートのハニカムを出している間：Esc で閉じる。後ろのハニカム（マス）向けのキーは効かせない
      if (e.key === 'Escape') {
        e.preventDefault();
        if (hiveDrag && hiveDrag.dragging) cancelHiveDrag(); // ドラッグ中なら取りやめだけ
        else closeHive();
        return;
      }
      if (!(e.ctrlKey || e.metaKey) || ['KeyA', 'KeyC', 'KeyX', 'KeyV', 'KeyL', 'KeyZ', 'KeyY'].includes(e.code)) return;
    }
    // 音声で入力（本文を書いている途中でも）
    if ((e.ctrlKey || e.metaKey) && e.shiftKey && !e.altKey && e.code === 'KeyM') {
      e.preventDefault();
      openVoice();
      return;
    }
    // 元に戻す・やり直す（文字の入力欄の中では、その文字の取り消し）
    if ((e.ctrlKey || e.metaKey) && !e.altKey && !isTypingTarget(e.target) && (e.code === 'KeyZ' || e.code === 'KeyY')) {
      e.preventDefault();
      if (drag || comboAdjust) return;
      applyUndo(e.code === 'KeyY' || e.shiftKey ? 'redo' : 'undo');
      return;
    }
    // 画像の位置合わせ中：Enter で完了、Esc で始める前の位置・大きさに戻して終わる
    if (comboAdjust && !isTypingTarget(e.target) && (e.key === 'Enter' || e.key === 'Escape')) {
      e.preventDefault();
      endComboAdjust({ cancel: e.key === 'Escape' });
      return;
    }
    if (drag) {
      if (e.key === 'Escape') {
        e.preventDefault();
        endDrag(); // ドラッグを取り消す（移動しない）
      }
      return;
    }
    if (e.key === 'Escape' && ovLinkDrag) {
      ovLinkDrag = null;
      ovLinkSuppressMenu = true;
      setTimeout(() => { ovLinkSuppressMenu = false; }, 0);
    }
    if (linking && e.key === 'Escape') {
      e.preventDefault();
      cancelLinking();
      return;
    }
    if (shelfPlacing && e.key === 'Escape') {
      e.preventDefault();
      cancelShelfPlacing();
      return;
    }
    // 定型を貼る場所を選んでいる途中：Esc でやめる、R で回転（Shift+R で逆）、M で反転、G で領域の中も可
    if (tplPlacing && !isTypingTarget(e.target)) {
      if (e.key === 'Escape') {
        e.preventDefault();
        cancelTemplatePlacing();
        return;
      }
      if (!e.ctrlKey && !e.metaKey && !e.altKey && ['KeyR', 'KeyM', 'KeyG'].includes(e.code)) {
        e.preventDefault();
        if (e.code === 'KeyR') tplPlacing.rot = (tplPlacing.rot + (e.shiftKey ? 5 : 1)) % 6;
        else if (e.code === 'KeyM') tplPlacing.mirror = !tplPlacing.mirror;
        else tplPlacing.avoidRegions = !tplPlacing.avoidRegions;
        refreshTemplatePlacing();
        return;
      }
    }
    // 関連付けの途中：1〜9 で線の種類を選ぶ（0 で指定なし）
    if (linking && !isTypingTarget(e.target) && !e.ctrlKey && !e.metaKey && !e.altKey && /^Digit[0-9]$/.test(e.code)) {
      const n = Number(e.code.slice(5));
      const k = n === 0 ? null : settings.linkKinds[n - 1];
      if (n === 0 || k) {
        e.preventDefault();
        linking.kind = k ? k.id : null;
        renderLinkKindPalette();
        renderLinks();
      }
      return;
    }
    if (reading && activeTab === 'grid' && !isTypingTarget(e.target) && handleReadingKey(e)) return;

    // ノートの操作・拡大縮小（本文の編集中でも効く）
    const mod = (e.ctrlKey || e.metaKey) && !e.altKey;
    if (mod && (['+', '=', ';'].includes(e.key) || e.code === 'NumpadAdd')) {
      e.preventDefault();
      zoomBy(1.25);
      return;
    }
    if (mod && (e.key === '-' || e.code === 'Minus' || e.code === 'NumpadSubtract')) {
      e.preventDefault();
      zoomBy(0.8);
      return;
    }
    if (mod && !e.shiftKey && (e.code === 'Digit0' || e.code === 'Numpad0')) {
      e.preventDefault();
      zoomReset();
      return;
    }
    if (mod && !e.shiftKey && e.code === 'KeyN') {
      e.preventDefault();
      openNewWindow();
      return;
    }
    if ((e.ctrlKey || e.metaKey) && e.altKey && !e.shiftKey && e.code === 'KeyT') {
      e.preventDefault();
      toggleOnTop();
      return;
    }
    if (mod && e.shiftKey && e.code === 'KeyN') {
      e.preventDefault();
      openNewAppDialog();
      return;
    }
    if (mod && e.shiftKey && e.code === 'KeyL') {
      e.preventDefault();
      setShowLinkLines(!showLinkLines);
      return;
    }
    if (mod && !e.shiftKey && e.code === 'KeyH') {
      e.preventDefault();
      toggleHistory();
      return;
    }
    if (mod && !e.shiftKey && e.code === 'KeyL' && activeTab === 'grid') {
      e.preventDefault();
      if (selectedKey) startLinking(selectedKey);
      else toast('先にメモのマスを選んでください（クリックしてから Esc）', 'warn');
      return;
    }
    if (mod && e.code === 'KeyT' && !e.shiftKey) {
      e.preventDefault();
      createBoard();
      return;
    }
    if (mod && e.code === 'KeyT' && e.shiftKey) {
      e.preventDefault();
      if (currentBoardId) createBoard(currentBoardId); // 開いているノートの中に子ノート
      return;
    }
    if (mod && (e.key === 'Tab' || e.key === 'PageDown' || e.key === 'PageUp')) {
      e.preventDefault();
      cycleBoard(e.key === 'PageUp' || (e.key === 'Tab' && e.shiftKey) ? -1 : 1);
      return;
    }
    if (mod && !e.shiftKey && /^Digit[1-9]$/.test(e.code)) {
      e.preventDefault();
      const n = Number(e.code.slice(5));
      const roots = rootBoards();
      const tab = n === 9 ? roots[roots.length - 1] : roots[n - 1]; // Ctrl+9 は最後のタブ
      if (tab) switchBoard(tabTarget(tab.id));
      return;
    }
    // Ctrl+Shift+1〜6：登録した倍率（固定中なら固定し直す。固定中の倍率をもう一度で解除）。
    // ⌘ は使わない（macOS の ⌘+Shift+3/4/5 は画面の撮影）。Shift で記号になるので e.code で見る
    if (e.ctrlKey && e.shiftKey && !e.metaKey && !e.altKey && /^Digit[1-6]$/.test(e.code)) {
      e.preventDefault();
      applyZoomPreset(Number(e.code.slice(5)) - 1, { toggle: true }); // 小窓では固定を付けも外しもせず、倍率だけ合わせる（zoomLockPct が null）
      return;
    }
    if (e.key === 'F2') {
      if (e.target && e.target.id === 'ovEditInput') return; // 本文を直している途中の F2 は、ノートの名前に取らない
      e.preventDefault();
      if (tryOverviewEditKey()) return; // 全体表示で選んでいるメモの本文
      startRename(currentBoardId);
      return;
    }
    // 上の階層へ
    if (e.altKey && !e.ctrlKey && !e.metaKey && e.key === 'ArrowUp' && path.length && activeTab === 'grid') {
      e.preventDefault();
      goToDepth(path.length - 1);
      return;
    }

    if (e.key === 'Escape' && sidePanel.contains(e.target) && e.target !== document.body) {
      e.preventDefault();
      e.target.blur();
      return;
    }
    // Esc：まず固定した浮かび上がりを外す
    if (e.key === 'Escape' && peekPinned) {
      e.preventDefault();
      unpinPeek();
      return;
    }
    // Esc：編集を終える（マスは選択したまま）→ 切り取りをやめる → 選択を外す
    if (e.key === 'Escape') {
      if (editingKey) {
        e.preventDefault();
        endEdit();
      } else if (selectMode) {
        setSelectMode(false);
      } else if (multi.length) {
        clearMulti();
      } else if (cutSource) {
        clearCut();
      } else if (selectedKey) {
        clearSelection();
      }
      return;
    }
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey) && e.target === editor) {
      e.preventDefault();
      endEdit();
      return;
    }
    // 関連付けのある新しいメモを書いているとき：Tab でこのメモから続けて作る（Shift+Tab で同じ元から）
    if (e.key === 'Tab' && !e.ctrlKey && !e.metaKey && !e.altKey && e.target === editor && chainCreate && editingKey && getRecord(editingKey) === chainCreate.rec) {
      e.preventDefault();
      continueLinkedChain(e.shiftKey);
      return;
    }
    // タグ：Alt+1〜6 で、よく使うタグを選択中（編集中）のマスに付け外し
    if (e.altKey && !e.ctrlKey && !e.metaKey && !e.shiftKey && /^Digit[1-6]$/.test(e.code) && activeTab === 'grid' && (editingKey || selectedKey)) {
      e.preventDefault();
      toggleTopTag(Number(e.code.slice(5)) - 1);
      return;
    }
    if (isTypingTarget(e.target)) return;

    if (e.key === 'Enter' && !e.ctrlKey && !e.metaKey && !e.altKey && !e.shiftKey && !e.repeat && tryOverviewEditKey()) {
      e.preventDefault(); // 全体表示で選んでいるメモの本文（改行は入力欄の中）
      return;
    }

    // Space はハニカムのパン用に押下を止める。グラフ上段の「線の種類」のボタンは、Space でも押せるように通す
    const spaceOnKinds = e.target instanceof Element && !!e.target.closest('#graphKinds');
    if ((e.code === 'Space' || e.key === ' ') && !spaceOnKinds) {
      e.preventDefault();
      if (!e.repeat && activeTab === 'grid') setSpaceHeld(true);
      return;
    }
    if (mod && !e.shiftKey && e.code === 'KeyC') {
      // 範囲選択した文字（サイドバーのコメントなど）は、ふつうの文字のコピー
      const sel = window.getSelection();
      if (sel && !sel.isCollapsed && sel.toString().trim() && !stage.contains(sel.anchorNode)) return;
      // サイドバーでクリックして選んだコメント（貼り付けるとメモになる）
      if (sidePicked && side) {
        e.preventDefault();
        copySideComments([sidePicked]);
        return;
      }
      // 未配置の棚でクリックして選んだコメント
      if (shelfPicked && side && side.list === 'shelf') {
        e.preventDefault();
        copyShelfComments(shelfPicked.rec, shelfPicked.id);
        return;
      }
      // 区画の紙片の全文の中でクリックして選んだコメント
      if (pocketPicked && side && side.list === 'pocket') {
        const slip = slipById(pocketPicked.slipId);
        const c = slip && slip.rec.comments.find((x) => x.id === pocketPicked.commentId);
        if (c) {
          e.preventDefault();
          copyComments([c]);
          return;
        }
      }
      // サイドバーの一覧でクリックした（フォーカスのある）メモ。移動先のマスを持たない項目（順路のカード・棚・ゴミ箱）は、下の「選んだマスのコピー」へ
      const item = side && document.activeElement && document.activeElement.closest && document.activeElement.closest('#sidePanel .side-item');
      const go = item && item.querySelector('.side-item-go');
      if (isOtherBoardItem(go)) {
        e.preventDefault(); // ほかのノートの項目：何もしない（今のノートの選んだマスをコピーすると紛らわしいため）
        return;
      }
      const target = go && go.dataset.key ? sideItemRecord(go) : null;
      if (target) {
        e.preventDefault();
        copyMemos([target]);
        return;
      }
    }
    // 長文を分けて並べる（本文の入力中は、ふつうの「書式なしで貼り付け」）
    if (activeTab === 'grid' && mod && e.shiftKey && e.code === 'KeyV') {
      e.preventDefault();
      if (!selectedKey) toast('先に並べ始めるマスを選んでください（クリックしてから Esc）', 'warn');
      else splitPasteAt(selectedKey);
      return;
    }
    // 選択中のマスのコピー・切り取り・貼り付け・削除（本文の入力中は、ふつうの文字のコピー等になる）
    if (activeTab === 'grid' && mod && !e.shiftKey && e.code === 'KeyA' && !isOverview) {
      e.preventDefault();
      selectAllMemos(); // この階層のメモをすべて選ぶ
      return;
    }
    if (activeTab === 'grid' && mod && !e.shiftKey && ['KeyC', 'KeyX'].includes(e.code) && multiEntries().length > (selectMode ? 0 : 1)) {
      e.preventDefault();
      copyMulti({ cut: e.code === 'KeyX' });
      return;
    }
    if (activeTab === 'grid' && e.key === 'Delete' && multiEntries().length > (selectMode ? 0 : 1)) {
      e.preventDefault();
      deleteMulti();
      return;
    }
    if (activeTab === 'grid' && mod && !e.shiftKey && ['KeyC', 'KeyX', 'KeyV'].includes(e.code)) {
      e.preventDefault();
      if (!selectedKey) {
        toast('先にマスを選んでください（クリックしてから Esc）', 'warn');
      } else if (e.code === 'KeyV') {
        pasteAt(selectedKey);
      } else {
        copyCell(selectedKey, { cut: e.code === 'KeyX' });
      }
      return;
    }
    if (activeTab === 'grid' && e.key === 'Delete' && selectedKey && !isCenter(selectedKey) && memos.has(selectedKey)) {
      e.preventDefault();
      deleteMemo(selectedKey);
      return;
    }
    // T：選んだマス（複数なら全部）にタグボタン（セットの 1〜6）
    if (activeTab === 'grid' && e.code === 'KeyT' && !e.ctrlKey && !e.metaKey && !e.altKey && !e.shiftKey && !isTypingTarget(e.target) && !editingKey && !isOverview) {
      const entries = multiEntries().length ? multiEntries() : selectedKey && !isCenter(selectedKey) ? [[selectedKey, getRecord(selectedKey)]] : [];
      if (entries.length) {
        e.preventDefault();
        openCellTagButtons(entries, tagButtonsPos(entries[0][0]));
        return;
      }
    }
    if (e.shiftKey && !e.ctrlKey && !e.metaKey && !e.altKey && e.code === 'Digit1') {
      e.preventDefault();
      fitAll(); // 全体を表示
      return;
    }
    if (activeTab !== 'grid' || e.ctrlKey || e.metaKey || e.altKey) return;
    const step = e.shiftKey ? KEY_PAN_STEP * 3 : KEY_PAN_STEP;
    const moves = { ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, -step], ArrowDown: [0, step] };
    if (moves[e.key]) {
      e.preventDefault();
      panBy(...moves[e.key]);
    } else if (e.key === 'Home') {
      e.preventDefault();
      goToOrigin();
    }
  });

  document.addEventListener('keyup', (e) => {
    if (e.code === 'Space' || e.key === ' ') {
      if (spaceHeld) e.preventDefault();
      setSpaceHeld(false);
    }
  });
  window.addEventListener('blur', () => setSpaceHeld(false));

  $('originBtn').addEventListener('click', goToOrigin);
  $('zoomIn').addEventListener('click', () => zoomBy(1.25));
  $('zoomOut').addEventListener('click', () => zoomBy(0.8));
  // 倍率を押す：倍率の登録と固定のメニュー（100% に戻すのはメニューの中か Ctrl+0）
  // 開いているときに押したら閉じるだけ（外側を押したとみなされて、指を離したときにもう閉じている）
  let zoomMenuWasOpen = false;
  zoomLabelEl.addEventListener('pointerdown', () => {
    zoomMenuWasOpen = zoomMenu.matches(':popover-open');
  });
  zoomLabelEl.addEventListener('click', (e) => {
    const wasOpen = e.detail ? zoomMenuWasOpen : zoomMenu.matches(':popover-open'); // キー（Enter・Space）で押したときは今の状態で
    zoomMenuWasOpen = false;
    if (wasOpen) {
      if (zoomMenu.matches(':popover-open')) zoomMenu.hidePopover();
    } else openZoomMenu();
  });
  zoomMenu.addEventListener('click', (e) => {
    const b = e.target.closest('button');
    if (!b) return;
    if (b.dataset.zoomPreset) applyZoomPreset(Number(b.dataset.zoomPreset));
    else if (b.dataset.zoomNow) {
      const i = Number(b.dataset.zoomNow);
      const presets = zoomPrefs().presets;
      presets[i] = zoomClampPct(currentZoom() * 100, 'grid'); // 登録は 4〜150%
      setZoomPresets(presets);
      toast(`登録 ${i + 1} を ${presets[i]}% にしました`, 'info', 1500);
    } else if (b.id === 'zoomPresetReset') {
      setZoomPresets(ZOOM_DEFAULT.presets.slice());
      toast('登録した倍率を既定（25・50・75・100・125・150%）に戻しました', 'info', 2000);
    } else if (b.id === 'zoomMenu100') {
      zoomReset();
    } else if (b.id === 'zoomMenuClose') zoomMenu.hidePopover();
  });
  $('zoomLock').addEventListener('change', (e) => toggleZoomLock(e.target.checked));
  $('zoomOverviewClick').addEventListener('change', (e) => {
    setOverviewClickMode(e.target.value);
    toast({ edit: '縮小中にメモをクリックすると、拡大して編集します', pin: '縮小中にメモをクリックすると、浮かび上がりを固定します（× か Esc・外のクリックで外す）' }[e.target.value] || '縮小中にメモをクリックすると、そこを拡大します');
  });
  $('overviewViewOnly').addEventListener('change', (e) => {
    settings = { ...settings, overviewViewOnly: e.target.checked };
    syncOverviewEditClass();
    if (ovWriteKey) closeOvWrite({ commit: true });
    if (ovEditKey) closeOvEdit({ commit: true });
    cancelOvZoom();
    if (e.target.checked && isOverview && linking) cancelLinking();
    if (!overviewWrites()) hideOvMark();
    saveSettings({ overviewViewOnly: e.target.checked }, { quiet: true });
    if (zoomMenu.matches(':popover-open')) renderZoomMenu();
  });
  zoomMenu.addEventListener('change', (e) => {
    const input = e.target.closest('[data-zoom-slot]');
    if (!input) return;
    const i = Number(input.dataset.zoomSlot);
    const presets = zoomPrefs().presets;
    const v = Number(input.value);
    if (input.value.trim() === '' || !Number.isFinite(v) || v < 4 || v > 150) {
      input.value = String(presets[i]);
      toast('4〜150 の数で入れてください', 'warn');
      return;
    }
    presets[i] = Math.round(v);
    input.value = String(presets[i]);
    setZoomPresets(presets);
  });
  $('zoomFit').addEventListener('click', fitAll);
  $('linkToggle').addEventListener('click', () => setShowLinkLines(!showLinkLines));
  $('historyBtn').addEventListener('click', toggleHistory);
  updateLinkToggle();
  if (api && api.onCommand) {
    // メニューバー「表示」から
    api.onCommand((cmd) => {
      if (cmd === 'zoom-in') zoomBy(1.25);
      else if (cmd === 'zoom-out') zoomBy(0.8);
      else if (cmd === 'zoom-reset') zoomReset();
      else if (cmd === 'zoom-fit') fitAll();
      else if (cmd === 'zoom-menu') { if (!miniMode) openZoomMenu(); } // 小窓は倍率の固定に従わないので、メニューも出さない
      else if (cmd === 'toggle-links') setShowLinkLines(!showLinkLines);
      else if (cmd === 'toggle-covers') setShowCovers(!showCovers);
      else if (cmd === 'toggle-tips') toggleTips();
      else if (cmd === 'line-tips') openTipsMenu();
      else if (cmd === 'import-bookmarks') importBookmarks();
      else if (cmd === 'sweep-attachments') sweepAttachments();
      else if (cmd === 'register-protocol') registerProtocol();
      else if (cmd === 'new-window') openNewWindow();
      else if (cmd === 'quick-input') quickInput();
      else if (cmd === 'quick-done') finishQuickInput();
      else if (cmd === 'quick-settings') openQuickDialog();
      else if (cmd === 'capture') startCapture();
      else if (cmd === 'capture-settings') openCaptureDialog();
      else if (cmd === 'search') openSearch();
      else if (cmd === 'tag-settings') openTagDialog();
      else if (cmd === 'tag-sets') openTagSetDialog();
      else if (cmd === 'link-kinds') openLinkKindDialog();
      else if (cmd === 'templates') openTplDialog();
      else if (cmd === 'due-list') openDueList();
      else if (cmd === 'shelf') openShelf();
      else if (cmd === 'trash') openTrash();
      else if (cmd === 'today') openToday();
      else if (cmd === 'voice') openVoice();
      else if (cmd === 'export') openExportHere();
      else if (cmd === 'undo' || cmd === 'redo') {
        // メニューバーから：文字の入力欄にいれば、その文字を。そうでなければメモの操作を
        if (isTypingTarget(document.activeElement)) document.execCommand(cmd);
        else applyUndo(cmd);
      }
      else if (cmd === 'dendrites') openDendrites();
      else if (cmd === 'stats') openStats();
    });
  }
  if (api && api.onSettingsChanged) api.onSettingsChanged((s) => applySettings(s));
  // ほかのプロセス（リンクを押したとき）から渡されたマスへのリンク
  if (api && api.onNavigate) api.onNavigate((url) => navigateMemoLink(url));

  // ---- ウィンドウ（同じメモアプリを複数のウィンドウで開く・常に最前面） ---------------------
  // どのウィンドウも同じノートのファイルを扱う。あるウィンドウが保存すると、同じノートを開いているほかのウィンドウに
  // 新しい内容が届くので、表示位置・今いる階層・選択・編集中の文字はそのままに読み直す

  const ON_TOP_PREF = 'hexMemo.alwaysOnTop';
  let onTop = false;

  async function openNewWindow() {
    if (!api || !api.newWindow) return;
    flushSave(); // 新しいウィンドウが最新の内容で開くように
    try {
      await ipc(api.newWindow(currentBoardId));
    } catch (err) {
      toast(`新しいウィンドウを開けませんでした：${err.message}`, 'error', 5000);
    }
  }

  // ---- 小窓：このウィンドウを複製して、常に最前面・セル1個分よりやや広い小さなウィンドウで開く ----
  // 小窓ではタブ・ツールバー・下の案内を隠してハニカムだけを見せ、今のマス（書いている・選んでいるマス、
  // なければ画面の真ん中のマス）を 100% で真ん中に置く。右上の小さなボタンで、ふつうのウィンドウに戻せる
  // （ウィンドウを大きく広げても戻る）。小窓で最前面を切り替えても、次に開くウィンドウの設定には残さない
  const MINI_EXIT = { width: 720, height: 480 }; // これより広げたら、ふつうの画面に戻す（main.js のふつうの最小の大きさ）
  let miniMode = false;

  async function openMiniWindow() {
    if (!api || !api.newWindow) return;
    flushSave();
    let key = editingKey || selectedKey;
    if (!key) {
      const c = H.pixelToHex(camera.x, camera.y, HEX_SIZE);
      key = H.keyOf(c.q, c.r);
    }
    try {
      const res = await ipc(api.newWindow(currentBoardId, { mini: true, keys: path.map((p) => p.step), key }));
      if (res.mini) toast('小窓（常に最前面）で開きました。小窓の右上のボタンで、ふつうのウィンドウに戻せます');
      // 画面は新しいのに、ウィンドウを作る本体（起動したときのまま）が古いと、ふつうの大きさで開いてしまう
      else toast('アプリの本体が更新前のままのため、ふつうのウィンドウで開きました。このメモアプリのウィンドウをすべて閉じてから起動し直すと、小窓で開けます', 'warn', 9000);
    } catch (err) {
      toast(`小窓を開けませんでした：${err.message}`, 'error', 5000);
    }
  }

  function setMiniMode(on) {
    miniMode = on;
    if (!on) enforceGridZoomLock(); // 小窓は倍率の固定に従わない。ふつうの画面に戻したら固定した倍率へ
    zoomUiKey = '';
    updateZoomUi();
    document.body.classList.toggle('is-mini', on);
    $('miniBar').hidden = !on;
    if (on && hive.open) closeHive();
    if (activeTab === 'grid') {
      measureView();
      invalidateLayout();
    }
  }

  // 小窓として開いたとき：道筋 keys の階層の、マス key を 100% で真ん中に（表示位置は保存しない）
  function startMini({ keys = [], key = null } = {}) {
    setMiniMode(true);
    if (keys.length && !setPath(keys)) key = null; // その階層が見つからなければ、ノート直下のまま
    const pos = key ? H.parseKey(key) : null;
    const p = pos ? H.hexToPixel(pos.q, pos.r, HEX_SIZE) : { x: camera.x, y: camera.y };
    stopCameraAnimation();
    camera.x = p.x;
    camera.y = p.y;
    camera.zoom = 1;
    if (pos && getRecord(key)) selectedKey = key;
    refreshAllCells();
    measureView();
    invalidateLayout();
  }

  async function exitMini({ resize = true } = {}) {
    if (!miniMode) return;
    setMiniMode(false);
    try {
      if (api && api.exitMini) await ipc(api.exitMini({ resize }));
    } catch (err) {
      toast(`ふつうのウィンドウに戻せませんでした：${err.message}`, 'error', 5000);
    }
  }

  // 小窓を大きく広げた（最大化したときも）ら、タブやツールバーのあるふつうの画面に戻す
  window.addEventListener('resize', () => {
    if (miniMode && innerWidth >= MINI_EXIT.width && innerHeight >= MINI_EXIT.height) exitMini({ resize: false });
  });

  function showOnTop(on) {
    onTop = on;
    const btn = $('onTopBtn');
    btn.setAttribute('aria-pressed', String(on));
    btn.title = on ? '常に最前面に表示をやめる（Ctrl+Alt+T）' : '常に最前面に表示（Ctrl+Alt+T）';
    const pin = $('miniPin');
    pin.setAttribute('aria-pressed', String(on));
    pin.title = on ? '常に最前面をやめる' : '常に最前面に表示';
    pin.setAttribute('aria-label', pin.title);
  }

  // remember：次に開くウィンドウも同じにする（小窓での切り替えは覚えない）
  async function setOnTop(on, { announce = true, remember = !miniMode } = {}) {
    if (!api || !api.setOnTop) return;
    try {
      const res = await ipc(api.setOnTop(on));
      showOnTop(res.onTop);
      try {
        if (remember) localStorage.setItem(ON_TOP_PREF, res.onTop ? '1' : '0'); // 次に開くウィンドウも同じに
      } catch {
        // 覚えられなくてもこのウィンドウは切り替わる
      }
      if (announce) toast(res.onTop ? 'このウィンドウを常に最前面に表示します' : '常に最前面に表示をやめました');
    } catch (err) {
      toast(`切り替えられませんでした：${err.message}`, 'error', 5000);
    }
  }

  const toggleOnTop = () => setOnTop(!onTop);

  $('newWindowBtn').addEventListener('click', openNewWindow);
  $('onTopBtn').addEventListener('click', toggleOnTop);
  $('miniWindowBtn').addEventListener('click', openMiniWindow);
  $('miniPin').addEventListener('click', toggleOnTop);
  $('miniExit').addEventListener('click', () => exitMini());
  if (api && api.onOnTop) api.onOnTop(showOnTop); // メニューバーから切り替えたとき

  // ほかのウィンドウへ移る前に、まだ送っていない変更を保存する（あちらが最新の内容を受け取れるように）
  window.addEventListener('blur', () => {
    if (dirty) flushSave();
  });
  // 画面が隠れるとき（iPad でほかのアプリへ移る・最小化など）も
  document.addEventListener('visibilitychange', () => {
    if (document.hidden && dirty) flushSave();
  });
  // ページを離れるとき：iPad（Safari など）は beforeunload を出さないことが多いので、区画の紙片の書きかけもここで保存して書き出す
  //（visibilitychange で保存すると、最小化しただけで欄が閉じてしまうので、離れるときだけ）
  window.addEventListener('pagehide', () => {
    if (slipEdit) saveSlipEdit({ by: 'interrupt' });
    if (dirty) flushSave();
  });
  // ブラウザ版：保存領域に書けなかった（空き容量が足りないなど）
  let storageErrorShown = 0;
  window.addEventListener('hexmemo-storage-error', (e) => {
    if (performance.now() - storageErrorShown < 30000) return;
    storageErrorShown = performance.now();
    toast(`ブラウザの保存領域に保存できませんでした：${e.detail}（空き容量を確かめて、メニューの「データを書き出す」で保存してください）`, 'error', 9000);
  });

  // ほかのウィンドウで保存された、表示中のノートの新しい内容を読み直す
  function applyRemoteStore(store) {
    hidePeek();
    const steps = path.map((p) => p.step);
    const cam = { ...camera };
    const editingRec = editingKey ? getRecord(editingKey) : null;
    // 書いているメモの見分け（作った時刻と ID）。読み直した後も同じメモか確かめるのに使う
    const editing = editingKey ? {
      key: editingKey, text: editor.value, start: editor.selectionStart, end: editor.selectionEnd,
      createdAt: editingRec ? editingRec.createdAt : null, id: editingRec ? editingRec.id || null : null,
    } : null;
    const sideLoc = side && !side.list && !side.series && sideWhere ? { keys: sideWhere.keys, key: sideWhere.key, tab: side.tab } : null;
    // 一覧（区画・棚など）を出しているときの ← の戻り先のうち、メモの詳細は、作り直す前の場所で覚えておいて後で引き直す
    //（古いレコードを指したまま ← で戻ると「このメモは削除されました」になるため。見つからなくなった戻り先は捨てる）
    const backLocs = sideLoc ? null : sideHistory.map((h) => {
      if (h.list || h.series) return { keep: h };
      const loc = h.rec ? locatePath(h.rec) : null;
      const keys = loc ? loc.keys : h.layer ? locateLayer(h.layer) : null;
      return keys ? { h, keys, key: loc ? loc.key : h.key } : null;
    });
    if (editing) {
      editingKey = null;
      editor.remove();
    }
    endDrag();
    cancelPocketDrag(); // 紙片の並べ替えはやめる（元の場所のまま。紙片を直している途中の欄は、描き直しても文とカーソルを戻す）
    if (linking) cancelLinking();
    cutSource = null;
    links = Array.isArray(store.links) ? store.links.map(serializeLink) : [];
    rebuildLinkIndex();
    rootLayer = toLayer(structuredClone(store));
    attachRootExtras(rootLayer, store);
    rebuildCopyIndex();
    lastVisit = null;
    // 固定中は、作り直すメモの位置を ID ごとに控えて、読み直したあとも同じ位置に置く（gPosOf）
    //（続けて読み直したり、別のタブで元に戻したりしても消えないように、前の控えに足す）
    if (graph.locked) {
      const keep = new Map(graph.lockPos || []);
      for (const [r, p] of graph.pos) if (r.id) keep.set(r.id, [p.x, p.y]);
      graph.lockPos = keep;
    } else graph.lockPos = null;
    graph.pos.clear();
    graph.selected = null;
    if (shelfPlacing) cancelShelfPlacing();
    if (tplPlacing) cancelTemplatePlacing();
    // タグボタンのメニュー（棚の項目・マス）は読み直す前のレコードを持っているので閉じる（Ctrl+Z のときと同じ。開いたままタグを押すと、付けたタグが黙って消える）
    if (shelfTagMenu.matches(':popover-open')) shelfTagMenu.hidePopover();
    // 今いる階層を新しい内容でたどり直す（無くなっていたら、たどれるところまで）
    const next = [];
    let layer = rootLayer;
    for (const step of steps) {
      const { key, li } = parseStep(step);
      const rec = layer.memos.get(key);
      const sub = rec && layerOf(rec, li);
      if (!sub) break;
      next.push({ key, li, rec, layer: sub, step });
      layer = sub;
    }
    path = next;
    memos = currentLayer().memos;
    camera = currentLayer().camera;
    if (next.length === steps.length) Object.assign(camera, cam); // このウィンドウの表示位置はそのまま
    else {
      enforceGridZoomLock();
      stopCameraAnimation();
      anchor.x = Math.round(camera.x);
      anchor.y = Math.round(camera.y);
    }
    if (selectedKey && !getRecord(selectedKey)) selectedKey = null;
    resetMulti(); // 読み直したメモは別のレコードになる
    for (const node of activeCells.values()) {
      placeCell(node);
      updateCellContent(node);
    }
    lastSignature = '';
    if (activeTab === 'grid') render();
    else renderList();
    renderLinks();
    renderCrumbs();
    updateTabCounts();
    // 書きかけの本文は、そのまま書き続けられるように。ただし、何も書いていない空のマスに、ほかのウィンドウ・ほかの
    // メモアプリから新しいメモが届いたときは、空の書きかけで上書きしない（編集を終えて、届いたメモを残す）
    // 書いていたのと同じ階層・同じメモ（または、まだメモの無いマス）のときだけ、書きかけを戻す。
    // 階層が消えて上の階層に戻った・そのマスに別のメモが届いた（空のマスに、ほかのウィンドウ・ほかのメモアプリから
    // 送られてきたなど）ときは、編集を終える（書きかけで別のメモを上書きしないように）
    const there = editing ? getRecord(editing.key) : null;
    const sameMemo = !!there && !!editing.createdAt && there.createdAt === editing.createdAt
      && (!editing.id || !there.id || editing.id === there.id);
    const restore = editing && next.length === steps.length && (sameMemo || !there || isEmptyRecord(there));
    if (restore && activeTab === 'grid' && activeCells.get(editing.key)) {
      startEdit(editing.key);
      if (editor.value !== editing.text) {
        editor.value = editing.text;
        editor.dispatchEvent(new Event('input'));
      }
      editor.setSelectionRange(editing.start, editing.end);
    }
    // サイドバーは同じ場所のメモを表示し続ける
    if (sideLoc) {
      const l = layerAt(sideLoc.keys);
      const r = l && l.memos.get(sideLoc.key);
      if (r) side = { rec: r, layer: l, key: sideLoc.key, tab: sideLoc.tab };
      sideHistory.length = 0;
    } else if (backLocs) {
      const next = [];
      for (const b of backLocs) {
        if (!b) continue;
        if (b.keep) {
          next.push(b.keep);
          continue;
        }
        const l = layerAt(b.keys);
        const r = l ? l.memos.get(b.key) || null : null;
        if (!l || (b.h.rec && !r)) continue;
        next.push({ ...b.h, rec: b.h.rec ? r : null, layer: l, key: b.key });
      }
      sideHistory.splice(0, sideHistory.length, ...next);
    }
    if (side) renderSide();
    if (reading) updateReadActions();
    if (searchMap) applySearchMap({ keepCamera: true });
  }

  if (api && api.onBoardChanged) {
    api.onBoardChanged((payload) => {
      if (!payload || payload.id !== currentBoardId || !payload.store || boardReadOnly) return;
      const sync = syncs.get(payload.id);
      if (sync && payload.rev !== undefined && payload.rev <= sync.rev) return; // もう知っている版
      const pending = dirty || unsettled.has(payload.id);
      if (payload.data === false) {
        // 表示位置だけの保存：中身は同じなので読み直さない（保存待ちがあれば、その保存のときに合わせる）
        if (!pending) setSync(payload.id, payload.rev, serialize());
        return;
      }
      if (pending && sync) {
        const remote = rendererForm(payload.store);
        applyRemoteStore(mergeStores(sync.store, serialize(), remote));
        setSync(payload.id, payload.rev, remote);
        dirty = true;
        dataDirty = true;
        scheduleSave();
      } else {
        applyRemoteStore(payload.store);
        setSync(payload.id, payload.rev, serialize());
      }
      resetUndo(); // ほかのウィンドウの変更より前には戻さない（あちらの変更を消さないように）
      updateTrashCount();
    });
  }

  // ほかのウィンドウでノートを作った・名前を変えた・移動した・削除した
  if (api && api.onBoardsChanged) {
    api.onBoardsChanged((list) => {
      if (!list || !Array.isArray(list.boards)) return;
      boards = list.boards;
      boardsReadOnly = !!list.readOnly;
      if (currentBoardId && !boardById(currentBoardId)) {
        // 開いていたノートが別のウィンドウで削除された：保存を取りやめて、ほかのノートへ
        clearTimeout(saveTimer);
        saveTimer = 0;
        dirty = false;
        dataDirty = false;
        unsettled.delete(currentBoardId);
        failedBoards.delete(currentBoardId);
        const next = boardById(list.activeId) ? list.activeId : tabTarget(rootBoards()[0].id);
        toast('開いていたノートは別のウィンドウで削除されました', 'warn', 5000);
        switchBoard(next, { force: true });
        return;
      }
      refreshBoardTabs();
      updateTitle();
    });
  }


  // ---- 期限と進み具合（六角形の辺） ------------------------------------------------------
  // マスに期限（日付）を付けられる。進み具合は六角形の印で、クリックするたびに辺が1つ明るくなり、6つで完了（チェック）。
  // 右クリックで一度に完了、もう一度右クリックで全部消す。印は、期限の一覧・サイドバー・マスの上の三角形に出る

  const DAY_MS = 86400000;
  const pad2 = (n) => String(n).padStart(2, '0');
  const localDay = (d = new Date()) => `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
  function dayAfter(days, from = new Date()) {
    const d = new Date(from.getFullYear(), from.getMonth(), from.getDate() + days);
    return localDay(d);
  }
  const dueOf = (rec) => (rec && rec.due) || null;
  const progressOf = (rec) => (rec && rec.progress > 0 ? Math.min(6, rec.progress) : 0);
  const isDone = (rec) => progressOf(rec) >= 6;
  // 今日からの日数（負なら過ぎている）
  function daysUntil(due, today = localDay()) {
    const a = new Date(`${due}T00:00:00`);
    const b = new Date(`${today}T00:00:00`);
    return Math.round((a - b) / DAY_MS);
  }
  function dueLabel(due, { withDate = true } = {}) {
    const n = daysUntil(due);
    const date = `${Number(due.slice(5, 7))}/${Number(due.slice(8, 10))}`;
    const rel = n === 0 ? '今日' : n === 1 ? '明日' : n > 1 ? `あと ${n} 日` : n === -1 ? '昨日' : `${-n} 日前`;
    return withDate ? `${date}（${rel}）` : rel;
  }

  // 六角形の進み具合の印（SVG）。p：明るい辺の数（0〜6）。6 ならチェック
  function hexProgressSvg(p, size = 18) {
    const s = svgEl('svg', { class: 'hexp-svg', viewBox: '0 0 24 24', width: String(size), height: String(size), 'aria-hidden': 'true' });
    const pts = Array.from({ length: 6 }, (_, i) => {
      const a = (Math.PI / 180) * (60 * i - 90);
      return [12 + 10 * Math.cos(a), 12 + 10 * Math.sin(a)];
    });
    for (let i = 0; i < 6; i++) {
      const [x1, y1] = pts[i];
      const [x2, y2] = pts[(i + 1) % 6];
      s.append(svgEl('line', { class: `hexp-edge${i < p ? ' is-on' : ''}`, x1: x1.toFixed(2), y1: y1.toFixed(2), x2: x2.toFixed(2), y2: y2.toFixed(2) }));
    }
    if (p >= 6) s.append(svgEl('path', { class: 'hexp-check', d: 'M7.5 12.5l3 3 6-6.5' }));
    return s;
  }

  // 印のボタン。rec を覚えておき、クリック・右クリックで進める（下の document の受け口で扱う）
  function hexProgressEl(rec, { size = 18, cls = '' } = {}) {
    const b = el('button', `hexp${cls ? ` ${cls}` : ''}`);
    b.type = 'button';
    b._rec = rec;
    renderHexProgress(b, rec, size);
    return b;
  }
  function renderHexProgress(b, rec, size = 18) {
    const p = progressOf(rec);
    const sig = `${p}|${size}`;
    b.dataset.progress = String(p);
    b.classList.toggle('is-done', p >= 6);
    b.title = p >= 6 ? '完了｜クリックで最初から・右クリックで全部消す' : `進み具合 ${p}/6｜クリックで辺を1つ進める・右クリックで一度に完了`;
    b.setAttribute('aria-label', `進み具合 ${p}/6`);
    if (b._sig === sig) return;
    b._sig = sig;
    const keep = b.querySelector('.meta-badge-n'); // マスの印は、日付の文字も持つ
    if (keep) {
      for (const c of [...b.childNodes]) if (c !== keep) c.remove();
      b.prepend(hexProgressSvg(p, size));
    } else b.replaceChildren(hexProgressSvg(p, size));
  }

  // そのメモがどの階層にあっても、変更を反映して保存する
  function afterRecordChangeAnywhere(rec) {
    const k = keyInView(rec);
    if (k) afterRecordChange(k);
    else {
      pruneRecordAnywhere(rec);
      updateTabCounts();
      scheduleSave();
    }
    if (side) requestSideRender();
  }

  function setProgress(rec, p, { quiet = false } = {}) {
    const next = Math.max(0, Math.min(6, p));
    if (progressOf(rec) === next) return;
    if (next > 0) rec.progress = next;
    else delete rec.progress;
    afterRecordChangeAnywhere(rec);
    for (const b of document.querySelectorAll('.hexp')) if (b._rec === rec) renderHexProgress(b, rec, Number(b.dataset.size) || 18);
    if (!quiet && next === 6) toast('完了にしました', 'info', 1500);
  }
  const stepProgress = (rec) => setProgress(rec, (progressOf(rec) + 1) % 7);
  const toggleDone = (rec) => setProgress(rec, isDone(rec) ? 0 : 6);
  document.addEventListener('click', (e) => {
    const b = e.target.closest('.hexp');
    if (!b || !b._rec) return;
    e.preventDefault();
    e.stopPropagation();
    stepProgress(b._rec);
  }, true);
  document.addEventListener('contextmenu', (e) => {
    const b = e.target.closest('.hexp');
    if (!b || !b._rec) return;
    e.preventDefault();
    e.stopPropagation();
    toggleDone(b._rec);
  }, true);

  function setDue(rec, due) {
    if ((rec.due || null) === (due || null)) return;
    if (due) rec.due = due;
    else {
      delete rec.due;
    }
    afterRecordChangeAnywhere(rec);
    refreshAllCells();
  }

  // マスの上の三角形の印（期限があるとき）
  function renderCellDue(node, rec) {
    const refs = node._refs;
    const due = dueOf(rec);
    refs.due.hidden = !due;
    node.classList.toggle('has-due', !!due);
    if (!due) {
      refs.due._rec = null;
      return;
    }
    refs.due._rec = rec;
    refs.due.dataset.size = '14';
    renderHexProgress(refs.due, rec, 14);
    const n = daysUntil(due);
    refs.dueN.textContent = n === 0 ? '今日' : n === 1 ? '明日' : `${Number(due.slice(5, 7))}/${Number(due.slice(8, 10))}`;
    refs.due.classList.toggle('is-overdue', n < 0 && !isDone(rec));
    refs.due.classList.toggle('is-today', n === 0 && !isDone(rec));
    refs.due.title = `期限 ${dueLabel(due)}${isDone(rec) ? '・完了' : `・進み具合 ${progressOf(rec)}/6`}｜クリックで辺を1つ進める・右クリックで一度に完了（右クリック →「期限…」で日付）`;
  }

  // 期限の窓（日付・進み具合）
  const dueMenu = $('dueMenu');
  let dueTarget = null; // { rec, key }
  function openDueMenu(key, pos, rec = getRecord(key)) {
    if (!rec) {
      if (isCenter(key)) return;
      rec = ensureRecord(key);
    }
    dueTarget = { rec, key: key || keyInView(rec) };
    renderDueMenu();
    showPopoverAt(dueMenu, pos);
  }
  function openDueMenuFor(rec, pos) {
    dueTarget = { rec, key: keyInView(rec) };
    renderDueMenu();
    showPopoverAt(dueMenu, pos);
  }
  function renderDueMenu() {
    if (!dueTarget) return;
    const { rec, key } = dueTarget;
    $('dueMenuHead').replaceChildren(document.createTextNode('期限'), el('strong', '', recordLabel(rec, key || keyInView(rec) || '?', 20)));
    $('dueDate').value = rec.due || '';
    const hexWrap = $('dueMenuHex');
    hexWrap.replaceChildren(hexProgressEl(rec, { size: 30, cls: 'hexp-big' }));
    hexWrap.firstChild.dataset.size = '30';
    $('dueMenuProgress').textContent = isDone(rec) ? '完了' : `進み具合 ${progressOf(rec)}/6（クリックで辺を1つ・右クリックで一度に完了）`;
    $('dueMenuSub').textContent = rec.due ? `期限 ${dueLabel(rec.due)}` : '期限はありません';
    dueMenu.querySelector('[data-cmd="clear"]').disabled = !rec.due;
    dueMenu.querySelector('[data-cmd="done"] span').textContent = isDone(rec) ? '完了を取り消す' : '完了にする';
  }
  dueMenu.addEventListener('mousedown', (e) => {
    if (!e.target.closest('input')) e.preventDefault();
  });
  dueMenu.addEventListener('click', (e) => {
    const btn = e.target.closest('button[data-cmd]');
    if (!btn || !dueTarget || btn.disabled) return;
    const { rec } = dueTarget;
    const cmd = btn.dataset.cmd;
    if (cmd === 'today') setDue(rec, dayAfter(0));
    else if (cmd === 'tomorrow') setDue(rec, dayAfter(1));
    else if (cmd === 'days3') setDue(rec, dayAfter(3));
    else if (cmd === 'week') setDue(rec, dayAfter(7));
    else if (cmd === 'clear') setDue(rec, null);
    else if (cmd === 'done') toggleDone(rec);
    renderDueMenu();
    updateDueCount();
  });
  $('dueDate').addEventListener('change', (e) => {
    if (!dueTarget) return;
    const v = e.target.value;
    setDue(dueTarget.rec, /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : null);
    renderDueMenu();
    updateDueCount();
  });
  dueMenu.addEventListener('toggle', (e) => {
    if (e.newState === 'open' || !dueTarget) return;
    const { rec, key } = dueTarget;
    dueTarget = null;
    if (key && !isCenter(key) && memos.get(key) === rec && isEmptyRecord(rec) && key !== editingKey) {
      memos.delete(key);
      refreshCell(key);
    }
  });

  // サイドバー（メモの詳細）の期限の行
  function renderSideDue(rec) {
    const row = $('sideDue');
    row.replaceChildren();
    if (!rec) {
      row.hidden = true;
      return;
    }
    row.hidden = false;
    if (rec.due) {
      const hex = hexProgressEl(rec, { size: 20 });
      hex.dataset.size = '20';
      const n = daysUntil(rec.due);
      const text = el('span', `side-due-text${n < 0 && !isDone(rec) ? ' is-overdue' : ''}${isDone(rec) ? ' is-done' : ''}`, `期限 ${dueLabel(rec.due)}${isDone(rec) ? '・完了' : ''}`);
      const change = el('button', 'chip chip-due-edit');
      change.type = 'button';
      change.dataset.dueEdit = '1';
      change.textContent = '変更…';
      row.append(hex, text, change);
    } else {
      const add = el('button', 'chip chip-add-tag');
      add.type = 'button';
      add.dataset.dueEdit = '1';
      add.append(svgIcon('clock'), document.createTextNode('期限を付ける'));
      row.append(add);
    }
  }
  $('sideDue').addEventListener('click', (e) => {
    const b = e.target.closest('[data-due-edit]');
    if (!b) return;
    const rec = sideRecord() || ensureSideRecord();
    if (!rec) return;
    const r = b.getBoundingClientRect();
    openDueMenuFor(rec, { x: r.left, y: r.bottom + 4 });
  });

  // ---- 期限の一覧（サイドバー）----
  function openDueList() {
    showSide({ list: 'due', showDone: false });
    $('dueBtn').setAttribute('aria-pressed', 'true');
  }
  function toggleDueList() {
    if (side && side.list === 'due') closeSide();
    else openDueList();
  }
  // 期限が今日まで（過ぎたものを含む）で、完了していないメモの数
  function dueCount() {
    const today = localDay();
    let n = 0;
    forEachMemo((rec) => {
      if (rec.due && rec.due <= today && !isDone(rec)) n++;
    });
    return n;
  }
  function updateDueCount() {
    const n = dueCount();
    const b = $('dueBtn');
    b.querySelector('.btn-badge').textContent = n ? String(n) : '';
    b.classList.toggle('has-due', n > 0);
    b.title = n ? `期限：今日までのメモが ${n} 件（サイドバーで一覧）` : '期限の一覧（サイドバー）';
  }

  function renderSideDueList() {
    $('sideFilter').hidden = true;
    $('sideHistoryCtl').hidden = true;
    const ctl = $('sideDueCtl');
    ctl.hidden = false;
    $('sideDueShowDone').checked = !!side.showDone;
    $('sideNotify').checked = settings.notify.enabled !== false;
    $('sideNotifyTime').value = settings.notify.time || '09:00';
    $('sideNotifyWeb').hidden = !isWeb;
    if (isWeb && 'Notification' in window) {
      $('sideNotifyWeb').textContent = Notification.permission === 'granted' ? 'このブラウザの通知：許可済み（開いているときに知らせます）' : Notification.permission === 'denied' ? 'このブラウザの通知：拒否されています（ブラウザの設定で変えられます）' : 'このブラウザの通知：「通知を試す」で許可を求めます';
    }
    const today = localDay();
    const items = [];
    forEachMemo((rec, key, keys) => {
      if (rec.due) items.push({ rec, key, keys, due: rec.due, n: daysUntil(rec.due, today), done: isDone(rec) });
    });
    for (const r of rootLayer.shelf || []) if (r.due) items.push({ rec: r, key: null, keys: null, due: r.due, n: daysUntil(r.due, today), done: isDone(r), shelf: true });
    items.sort((a, b) => (a.due < b.due ? -1 : a.due > b.due ? 1 : 0));
    const groups = [
      ['期限切れ', (x) => !x.done && x.n < 0],
      ['今日', (x) => !x.done && x.n === 0],
      ['明日', (x) => !x.done && x.n === 1],
      ['7日以内', (x) => !x.done && x.n > 1 && x.n <= 7],
      ['それ以降', (x) => !x.done && x.n > 7],
      ['完了', (x) => x.done],
    ];
    const open = items.filter((x) => !x.done).length;
    $('sideListSub').textContent = items.length ? `期限のあるメモ ${items.length} 件（未完了 ${open}・今日まで ${items.filter((x) => !x.done && x.n <= 0).length}）` : '';
    const frag = document.createDocumentFragment();
    for (const [label, test] of groups) {
      const list = items.filter(test);
      if (!list.length || (label === '完了' && !side.showDone)) continue;
      frag.append(el('h3', `side-day${label === '期限切れ' ? ' is-overdue' : label === '今日' ? ' is-today' : ''}`, `${label}（${list.length}）`));
      const ul = el('ul', 'side-list due-list');
      for (const it of list) {
        const row = el('li', `due-row${it.done ? ' is-done' : it.n < 0 ? ' is-overdue' : ''}`);
        const hex = hexProgressEl(it.rec, { size: 22, cls: 'due-row-hex' });
        hex.dataset.size = '22';
        const body = el('div', 'due-row-body');
        if (it.shelf) {
          const text = el('span', `side-item-text${hasText(it.rec) ? '' : ' is-empty'}`, hasText(it.rec) ? it.rec.text : '（本文なし）');
          const meta = el('span', 'side-item-meta');
          meta.append(el('span', 'side-dir is-where', '未配置の棚'), el('span', 'card-time', `期限 ${dueLabel(it.due)}`));
          body.append(meta, text);
        } else {
          const item = buildSideItem(it.rec, it.key, it.keys, {
            label: locationLabel(it.keys, it.key), labelClass: 'side-dir is-where', coord: false,
            time: { text: `期限 ${dueLabel(it.due)}`, title: it.due },
          });
          const inner = el('div', 'side-item');
          inner.append(...item.childNodes);
          body.append(inner);
        }
        const edit = el('button', 'chip chip-due-edit');
        edit.type = 'button';
        edit.dataset.dueRow = '1';
        edit.textContent = '日付…';
        edit._rec = it.rec;
        body.append(edit);
        row.append(hex, body);
        ul.append(row);
      }
      frag.append(ul);
    }
    $('sideListItems').replaceChildren(frag);
    const empty = $('sideListEmpty');
    empty.hidden = items.length > 0 && (open > 0 || side.showDone);
    empty.textContent = items.length ? '未完了のメモはありません（「完了も見る」で完了したものを表示）。' : 'まだ期限のあるメモはありません。マスの右クリック →「期限…」で付けられます。';
  }
  $('sideDueShowDone').addEventListener('change', (e) => {
    if (!side || side.list !== 'due') return;
    side.showDone = e.target.checked;
    renderSide();
  });
  $('sideNotify').addEventListener('change', (e) => saveSettings({ notify: { enabled: e.target.checked } }, { quiet: true }));
  $('sideNotifyTime').addEventListener('change', (e) => {
    if (/^([01]\d|2[0-3]):[0-5]\d$/.test(e.target.value)) saveSettings({ notify: { time: e.target.value } }, { quiet: true });
  });
  $('sideNotifyTest').addEventListener('click', async () => {
    if (isWeb) {
      if (!('Notification' in window)) {
        toast('このブラウザは通知に対応していません', 'warn');
        return;
      }
      const perm = Notification.permission === 'granted' ? 'granted' : await Notification.requestPermission();
      if (perm !== 'granted') {
        toast('通知が許可されませんでした', 'warn');
        renderSide();
        return;
      }
      webNotifyDue({ force: true });
      renderSide();
      return;
    }
    try {
      await ipc(api.notifyDue());
      toast(dueCount() ? '通知を出しました' : '今日までの期限のメモが無いので、通知はありません', 'info', 3000);
    } catch (err) {
      toast(`通知を出せませんでした：${err.message}`, 'error', 5000);
    }
  });
  $('sideListItems').addEventListener('click', (e) => {
    const b = e.target.closest('[data-due-row]');
    if (!b || !b._rec) return;
    e.stopPropagation();
    const r = b.getBoundingClientRect();
    openDueMenuFor(b._rec, { x: r.left, y: r.bottom + 4 });
  }, true);
  $('dueBtn').addEventListener('click', toggleDueList);

  // ブラウザ版の通知（開いているときだけ。1日に1回）
  const WEB_NOTIFY_PREF = 'hexMemo.webNotifiedDay';
  function webNotifyDue({ force = false } = {}) {
    if (!isWeb || !('Notification' in window) || Notification.permission !== 'granted' || settings.notify.enabled === false) return;
    const today = localDay();
    try {
      if (!force && localStorage.getItem(WEB_NOTIFY_PREF) === today) return;
    } catch {
      // 覚えられなくても出す
    }
    const list = [];
    forEachMemo((rec) => {
      if (rec.due && rec.due <= today && !isDone(rec)) list.push(rec);
    });
    if (!list.length) {
      if (force) toast('今日までの期限のメモはありません', 'info', 2500);
      return;
    }
    try {
      localStorage.setItem(WEB_NOTIFY_PREF, today);
    } catch {
      // 続ける
    }
    const n = new Notification(`${appName}：期限のメモ ${list.length} 件`, { body: list.slice(0, 3).map((r) => `・${recordLabel(r, '?', 30)}（${r.due}）`).join('\n') });
    n.onclick = () => {
      window.focus();
      openDueList();
    };
  }

  // ---- 関連グラフ（グラフの見方） ---------------------------------------------------------
  // ハニカムの「場所」とは別に、関連線だけを取り出して「つながり」で並べる見方（上段のタブ「グラフ」）。
  // メモは六角形のノード、線は種類の色（向きのある種類は矢印）。力学配置と、有向の線で層を作る「流れ」配置。
  // ノードをクリックでサイドバー（関連）、ダブルクリックでハニカムのそのマスへ、Alt+クリックで線を引き始める

  const graphView = $('graphView');
  const graphSvg = $('graphSvg');
  queueMicrotask(applyTextLines); // 覚えた文字量を、起動のあと（全部の準備ができてから）当てる
