    const same = (a, b) => Math.abs((a ?? 0) - (b ?? 0)) < 0.5;
    let { x, y } = cam;
    if (!same(prev.left, next.left) && same(prev.right, next.right)) x -= next.left - prev.left;
    if (!same(prev.top, next.top) && same(prev.bottom, next.bottom)) y -= next.top - prev.top;
