    if (nodes.length <= HINT_SMALL_N) return;
    const hs = hintInherit(nodes.map((n) => ({ id: n.rec.id, h: hintOf(hints, n.rec) })));
    const ids = new Set(nodes.map((n) => n.rec.id).filter(Boolean));
