    const pw = !panel.hidden ? panel.offsetWidth + 24 : 0;
    const panelW = r.width - pw >= 200 ? pw : 0;
    const pad = gFitPad(r.width - panelW);
    const w = maxX - minX + 2 * GR + pad.x;
    const h = maxY - minY + 2 * GR + pad.y;
