        g.append(svgEl('path', { class: 'g-hit' }), svgEl('path', { class: 'g-line' }), svgEl('text', { class: 'g-label' }));
        g.addEventListener('click', (ev) => {
          ev.stopPropagation();
          const link = links.find((l) => l.a === g.__a && l.b === g.__b);
          if (link) openLinkEditor(link, { x: ev.clientX, y: ev.clientY });
        });
        g.addEventListener('pointerenter', () => { graph.hoverEdge = key; drawGraph(); });
        g.addEventListener('pointerleave', () => { graph.hoverEdge = null; drawGraph(); });
        gEdgeEls.set(key, g);
