      hit.setAttribute('d', d);
      line.setAttribute('d', d);
      if (graph.arrows && isDirected(e)) line.setAttribute('marker-end', `url(#g-arrow-${e.kind || 'none'})`);
      else line.removeAttribute('marker-end');
